describe('security review 2026-10-08', () => {
  const section = (body: string, id: number) => {
    const at = body.indexOf(`id="R${id}"`);
    return at < 0 ? '' : body.slice(at, body.indexOf('</section>', at));
  };

  test('hidden report columns cannot be shown, searched, filtered, sorted or aggregated through URL parameters', async () => {
    const pid = (await owner.one(`select id from meta.page where app_id = $1 and page_no = 11`, [appId])).id;
    const rid = (await owner.one(
      `insert into meta.region (page_id, seq, title, type, source, config) values ($1, 999, 'Review hidden', 'report',
        'select empno, ename, sal as secret_sal from hr.emp', '{"hidden": ["secret_sal"]}') returning id`, [pid])).id as number;
    try {
      const king = await as('king');
      const rows = (body: string) => (section(body, rid).match(/<tr[ >]/g) ?? []).length;
      const all = rows((await king.get('/a/hr/11')).body);
      const get = async (k: string, v: string) => (await king.get(`/a/hr/11?${new URLSearchParams({ [`r${rid}_${k}`]: v })}`)).body;
      // a computed column over a hidden one is refused (shown as an error chip, no values)
      const computed = section(await get('c', 'LEAK|secret_sal'), rid);
      assert.doesNotMatch(computed, /5000|5,000|5\.000/, 'no hidden values through a computation');
      assert.equal(rows(await get('f', 'secret_sal|gt|4999')), all, 'a filter on a hidden column is ignored');
      assert.equal(rows(await get('q', '5000')), rows(await get('q', 'no-such-text-zz')), 'the search does not look into hidden columns');
      const tbody = (body: string) => /<tbody>([\s\S]*?)<\/tbody>/.exec(section(body, rid))?.[1] ?? '';
      assert.equal(tbody(await get('s', '3')), tbody((await king.get('/a/hr/11')).body), 'sorting by a hidden column is ignored');
      assert.doesNotMatch(section(await get('a', 'max|secret_sal'), rid), /5000|5,000|5\.000/, 'no aggregate of a hidden column');
      const group = (await king.get(`/a/hr/11?r${rid}_v=group&r${rid}_g=ename&r${rid}_ga=${encodeURIComponent('max|secret_sal')}`)).body;
      assert.doesNotMatch(section(group, rid), /5000|5,000|5\.000/, 'no group-by aggregate of a hidden column');
      const pivot = (await king.get(`/a/hr/11?r${rid}_v=pivot&r${rid}_pv=${encodeURIComponent('ename|secret_sal|count|empno')}`)).body;
      assert.doesNotMatch(section(pivot, rid), /5000|5,000|5\.000/, 'no pivot on a hidden column');
      const brk = (await king.get(`/a/hr/11?r${rid}_b=secret_sal`)).body;
      assert.doesNotMatch(section(brk, rid), /5000|5,000|5\.000/, 'no control break on a hidden column');
      // shown columns still work
      assert.match(section(await get('c', 'TWICE|empno * 2'), rid), /15678/, 'computations over shown columns work');
    } finally {
      await owner.query('delete from meta.region where id = $1', [rid]);
    }
  });

  test('REST modules: the caller cannot set :APP_USER or other built-in binds', async () => {
    const { issueApiToken } = await import('../src/api.ts');
    await owner.query(`insert into meta.rest_module (app_id, name, title, handlers) values ($1, 'review_binds', 'Review', $2)`,
      [appId, JSON.stringify([{ method: 'GET', path: 'me', type: 'item', source: 'select :APP_USER as u, :APP_ID as a, :APP_SESSION as s' }])]);
    try {
      const token = (await issueApiToken(appId, 'allen', 1)).token;
      const res = await app.inject({ method: 'GET', url: '/a/hr/rest/review_binds/me?app_user=KING&APP_ID=1&app_session=x', headers: { authorization: `Bearer ${token}` } });
      assert.equal(res.statusCode, 200, res.body);
      assert.deepEqual(res.json(), { u: 'allen', a: String(appId), s: null });
      const { handlerProblems } = await import('../src/runtime/rest.ts');
      assert.ok(handlerProblems([{ method: 'GET', path: 'x/:app_user', type: 'item', source: 'select 1' }]).some((p) => /set by the server/.test(p)));
    } finally {
      await owner.query(`delete from meta.rest_module where app_id = $1 and name = 'review_binds'`, [appId]);
    }
  });

  test('select lists only accept values their list of values offers', async () => {
    const king = await as('king');
    await king.get(link('king', 3, { P3_EMPNO: '7934' }));
    const before = await owner.one('select deptno, job from hr.emp where empno = 7934');
    const form = { __csrf: king.lastCsrf, __request: 'SAVE', P3_ENAME: 'MILLER', P3_MGR: '7782', P3_HIREDATE: '1982-01-23', P3_SAL: '1300', P3_ACTIVE: 'true' };
    const forged = await king.post('/a/hr/3', { ...form, P3_JOB: 'CLERK', P3_DEPTNO: '99' });
    assert.equal(forged.statusCode, 422, 'a department the list does not offer is refused');
    assert.match(forged.body, /choose a value from the list/);
    const job = await king.post('/a/hr/3', { ...form, __csrf: king.lastCsrf, P3_JOB: 'EMPEROR', P3_DEPTNO: String(before.deptno) });
    assert.equal(job.statusCode, 422, 'a job the list does not offer is refused');
    assert.deepEqual(await owner.one('select deptno, job from hr.emp where empno = 7934'), before, 'nothing was saved');
    const ok = await king.post('/a/hr/3', { ...form, __csrf: king.lastCsrf, P3_JOB: before.job, P3_DEPTNO: String(before.deptno) });
    assert.equal(ok.statusCode, 303, 'values from the list are accepted');
  });

  test('My account: guessing the current password is throttled like sign-ins', async () => {
    const user = `pwthrottle_${Date.now()}`;
    await owner.query(`insert into meta.account (username, password_hash) values ($1, meta.hash_password('Correct-horse-9'))`, [user]);
    await owner.query(`insert into meta.app_access (app_id, account_id) select $1, id from meta.account where username = $2`, [appId, user]);
    try {
      const b = new Browser();
      assert.equal((await b.login(user, 'Correct-horse-9')).statusCode, 303);
      await b.get('/a/hr/account');
      const codes: number[] = [];
      for (let i = 0; i < 7; i++)
        codes.push((await b.post('/a/hr/account/password', { __csrf: b.lastCsrf, password: `wrong${i}`, new_password: 'Another-pass-77', confirm_password: 'Another-pass-77' })).statusCode);
      assert.deepEqual(codes.slice(0, 5), [401, 401, 401, 401, 401]);
      assert.equal(codes[6], 429, 'locked after the sign-in limit');
      const right = await b.post('/a/hr/account/password', { __csrf: b.lastCsrf, password: 'Correct-horse-9', new_password: 'Another-pass-77', confirm_password: 'Another-pass-77' });
      assert.equal(right.statusCode, 429, 'even the right password waits while locked');
    } finally {
      await owner.query('delete from meta.activity_log where lower(username) = lower($1)', [user]);
      await owner.query('delete from meta.account where username = $1', [user]);
    }
  });

  test('a DELETE runs the validations made for DELETE (and only those)', async () => {
    const pid = (await owner.one(`select id from meta.page where app_id = $1 and page_no = 3`, [appId])).id;
    const emp = (await owner.one(`insert into hr.emp (empno, ename, job, deptno, hiredate, sal) values (7990, 'DELTEST', 'CLERK', 10, current_date, 1000) returning empno`)).empno;
    const v = (await owner.one(
      `insert into meta.validation (page_id, name, type, expression, message, when_button) values ($1, 'review no delete', 'sql', 'false', 'Review: this employee cannot be deleted', 'DELETE') returning id`, [pid])).id;
    try {
      const king = await as('king');
      await king.get(link('king', 3, { P3_EMPNO: String(emp) }));
      // a required item left empty doesn't stop a delete, the DELETE validation does
      const res = await king.post('/a/hr/3', { __csrf: king.lastCsrf, __request: 'DELETE', P3_ENAME: '' });
      assert.equal(res.statusCode, 422);
      assert.match(res.body, /this employee cannot be deleted/);
      assert.equal((await owner.one('select count(*)::int as n from hr.emp where empno = $1', [emp])).n, 1, 'the row is still there');
      await owner.query('delete from meta.validation where id = $1', [v]);
      const ok = await king.post('/a/hr/3', { __csrf: king.lastCsrf, __request: 'DELETE', P3_ENAME: '' });
      assert.equal(ok.statusCode, 303, 'without it the delete goes through (item checks are skipped)');
    } finally {
      await owner.query('delete from meta.validation where id = $1', [v]);
      await owner.query('delete from hr.emp where empno = $1', [emp]);
    }
  });

  test('TRUST_PROXY believes only the configured proxies, not addresses a client puts in X-Forwarded-For', async () => {
    const { default: Fastify } = await import('fastify');
    const { trustProxySetting } = await import('../src/security.ts');
    const ipFor = async (setting: string | undefined) => {
      const f = Fastify({ trustProxy: trustProxySetting(setting) as never });
      f.get('/', async (req) => req.ip);
      const res = await f.inject({ url: '/', remoteAddress: '10.0.0.5', headers: { 'x-forwarded-for': '6.6.6.6, 203.0.113.9' } } as never);
      await f.close();
      return res.body;
    };
    assert.equal(await ipFor('true'), '203.0.113.9', 'one proxy: the address it saw, not the forged first entry');
    assert.equal(await ipFor('2'), '6.6.6.6', 'two proxies in a row');
    assert.equal(await ipFor('10.0.0.0/8'), '203.0.113.9', 'a trusted subnet');
    assert.equal(await ipFor(undefined), '10.0.0.5', 'unset: the socket');
    assert.equal(await ipFor('false'), '10.0.0.5');
  });

  test('without signing in, ?doc= only gives the documents the public page offers', async () => {
    const pid = (await owner.one(`select id from meta.page where app_id = $1 and page_no = 11`, [appId])).id;
    await owner.query('update meta.page set requires_auth = false where id = $1', [pid]);
    let button: number | null = null;
    try {
      const anon = new Browser();
      const refused = await anon.get('/a/hr/11?doc=EMPLOYEE_SHEET');
      assert.equal(refused.statusCode, 403, 'a public page does not hand out any template');
      assert.doesNotMatch(String(refused.headers['content-type']), /pdf/);
      const king = await as('king');
      assert.match(String((await king.get('/a/hr/11?doc=EMPLOYEE_SHEET')).headers['content-type']), /application\/pdf/, 'signed-in users keep ?doc=');
      button = (await owner.one(`insert into meta.button (page_id, seq, name, label, action, document, target_items) values ($1, 99, 'REVIEW_PRINT', 'Print', 'document', 'EMPLOYEE_SHEET', '{}') returning id`, [pid])).id;
      assert.match(String((await anon.get('/a/hr/11?doc=EMPLOYEE_SHEET')).headers['content-type']), /application\/pdf/, 'offered by a visible button: allowed');
    } finally {
      if (button) await owner.query('delete from meta.button where id = $1', [button]);
      await owner.query('update meta.page set requires_auth = true where id = $1', [pid]);
    }
  });

  test('bind values stay values in SQL that PostgreSQL lexes unusually', async () => {
    const { applyBinds } = await import('../src/binds.ts');
    const evil = "$ä$, 'pwned' as x -- ' \\' \r\n; select 1 as x; --";
    for (const sql of ['select $ä$ :A $ä$ as t, :A as v', 'select 1 as a$b$, :A as v', 'select 1 -- note\r, :A as v', "select :A as v where'\\' <> :A"]) {
      const row = (await runtime.query(applyBinds(sql, { A: evil }))).rows[0];
      assert.equal(row.v, evil, sql);
      assert.equal(Object.keys(row).includes('x'), false, sql);
    }
  });

  test('a URL checksum covers names and values unambiguously (no "&NAME=" inside a value)', async () => {
    assert.notEqual(urlChecksum(appId, 3, 'u', { P3_ID: 'x&P3_OWNER=me' }), urlChecksum(appId, 3, 'u', { P3_ID: 'x', P3_OWNER: 'me' }));
    assert.notEqual(urlChecksum(appId, 3, 'u', { A: '1=2' }), urlChecksum(appId, 3, 'u', { 'A=1': '2' }));
    // the database computes the same checksum (meta.page_url, notifications)
    for (const items of [{ P3_EMPNO: '7839' }, { P3_ID: 'x&P3_OWNER=me', P3_B: 'ä€😀' }, { P3_E: '' }] as Record<string, string>[]) {
      const db = await owner.one('select meta.url_checksum($1, 3, $2, $3) as cs', [appId, 'King', JSON.stringify(items)]);
      assert.equal(db.cs, urlChecksum(appId, 3, 'King', items), JSON.stringify(items));
    }
  });
});

describe('sprint 42 MCP server for AI agents', () => {
  test('run_query cannot change anything: one statement, in a read-only transaction', async () => {
    const { readOnlyQuery } = await import('../src/cli/mcp.ts');
    const { withDb } = await import('../src/cli/apps.ts');
    await owner.query('create table if not exists public.mcp_probe (n int)');
    try {
      await withDb(async (db) => {
        for (const sql of [
          'insert into public.mcp_probe values (1)',
          // a second statement after ending the transaction (the simple query protocol would run it)
          'commit; insert into public.mcp_probe values (2)',
          'rollback; insert into public.mcp_probe values (3)',
          'set transaction read write',
          `do $$ begin insert into public.mcp_probe values (4); end $$`,
          'select 1; insert into public.mcp_probe values (5)',
          `with x as (insert into public.mcp_probe values (6) returning n) select * from x`,
        ]) await assert.rejects(readOnlyQuery(db, sql, 10), Error, sql);
        // still usable afterwards, and still read-only
        assert.equal((await readOnlyQuery(db, 'select 1 as one', 10)).rows[0].one, 1);
      });
      assert.equal((await owner.one('select count(*)::int as n from public.mcp_probe')).n, 0);
    } finally {
      await owner.query('drop table public.mcp_probe');
    }
  });

  test('run_query hides password hashes, secrets and tokens by column name', async () => {
    const { readOnlyQuery } = await import('../src/cli/mcp.ts');
    const { withDb } = await import('../src/cli/apps.ts');
    const r = await withDb((db) =>
      readOnlyQuery(db, `select 'x' as password_hash, 'y' as client_secret, 'z' as token, 'w' as api_key, 'ok' as name`, 10));
    assert.deepEqual(r.rows[0], { password_hash: '(hidden)', client_secret: '(hidden)', token: '(hidden)', api_key: '(hidden)', name: 'ok' });
  });
});

describe('sprint 50 forms lost update', () => {
  test('meta.row_version runs with the caller\'s rights and takes the key as a value', async () => {
    await assert.rejects(
      owner.query(`begin; set local role pgkiln_runtime; select meta.row_version('meta.account', 'id', '1', array['password_hash']); rollback`),
      /permission denied/,
    );
    await owner.query('rollback').catch(() => {});
    // a key with SQL in it is only a (bad) value of the key's type
    await assert.rejects(owner.query(`select meta.row_version('hr.emp', 'empno', $1, array['ename'])`, [`1 or 1=1`]), /invalid input syntax/);
    assert.equal((await owner.one(`select meta.row_version('hr.emp', 'ename', $1, array['ename']) as v`, [`x' or '1'='1`])).v, null);
    // column names are identifiers, never SQL
    await assert.rejects(owner.query(`select meta.row_version('hr.emp', 'empno', '7839', array['ename) from hr.emp --'])`), /does not exist/);
  });

  test('a posted row version that is not a checksum is ignored', async () => {
    const king = await as('king');
    await king.get(link('king', 3, { P3_EMPNO: '7839' }));
    const region = (await owner.one(`select r.id from meta.region r join meta.page p on p.id = r.page_id join meta.app a on a.id = p.app_id
                                      where a.alias = 'hr' and p.page_no = 3 and r.type = 'form'`)).id;
    const page = (await king.get(link('king', 3, { P3_EMPNO: '7839' }))).body;
    const fields: Record<string, string> = {};
    for (const [, name, value] of page.matchAll(/<input type="hidden" name="(__[a-z_0-9]+)" value="([^"]*)"/g)) fields[name] = value;
    assert.match(fields[`__rv_${region}`] ?? '', /^[0-9a-f]{32}$/);
    const res = await king.post('/a/hr/3', { ...fields, __csrf: king.lastCsrf, [`__rv_${region}`]: `' or 1=1 --`, __request: 'NOTHING' });
    assert.notEqual(res.statusCode, 500);
  });
});

describe('sprint 50 url region', () => {
  test('an item value is URL-encoded: it can\'t change the framed host, break out of the attribute or reach the CSP', async () => {
    const page = (await owner.one(`select p.id from meta.page p where p.app_id = $1 and p.page_no = 1`, [appId])).id;
    const item = (await owner.one(`insert into meta.item (page_id, seq, name, type) values ($1, 999, 'P1_URLTEST', 'hidden') returning id`, [page])).id;
    const region = (await owner.one(`insert into meta.region (page_id, seq, title, type, source) values ($1, 999, 'Embedded', 'url', 'https://example.org/&P1_URLTEST.') returning id`, [page])).id;
    try {
      const king = await as('king');
      for (const evil of ['@evil.example/x', '../../\\evil.example', '"><script>alert(1)</script>', `x" onload="alert(1)`, '//evil.example', `x'; frame-src *`]) {
        const res = await king.get(link('king', 1, { P1_URLTEST: evil }));
        assert.equal(res.statusCode, 200, evil);
        const src = new RegExp(`id="R${region}"[\\s\\S]*?<iframe class="url-frame [^"]+" src="([^"]*)"`).exec(res.body)?.[1] ?? '';
        assert.equal(src, `https://example.org/${encodeURIComponent(evil).replace(/'/g, '&#39;')}`, evil);
        assert.equal(new URL(src.replace(/&#39;/g, "'")).origin, 'https://example.org');
        assert.doesNotMatch(res.body, /<script>alert/);
        assert.match(String(res.headers['content-security-policy']), /frame-src 'self' https:\/\/example\.org; frame-ancestors/);
      }
    } finally {
      await owner.query('delete from meta.region where id = $1', [region]);
      await owner.query('delete from meta.item where id = $1', [item]);
    }
  });
});

describe('sprint 50 developer toolbar', () => {
  const devBrowser = async () => {
    const b = await as('king');
    await b.get('/builder/login');
    const res = await b.post('/builder/login', { __csrf: b.lastCsrf, username: 'admin', password: 'admin' });
    assert.equal(res.statusCode, 303);
    const builder = await b.get('/builder');
    const cookie = (builder.cookies as { name: string; path?: string; httpOnly?: boolean }[]).find((c) => c.name === 'pgkiln_devbar');
    assert.ok(cookie, 'the toolbar cookie is set by the builder');
    assert.equal(cookie.path, '/a');
    assert.equal(cookie.httpOnly, true);
    return b;
  };

  test('an application user can\'t reach the viewer or switch debug on for their session', async () => {
    const king = await as('king');
    await king.get('/a/hr/1');
    assert.equal((await king.get('/a/hr/1/devbar/session')).statusCode, 404);
    assert.equal((await king.post('/a/hr/1/devbar/debug', { __csrf: king.lastCsrf, level: '9' })).statusCode, 404);
    assert.equal((await king.post('/a/hr/1/devbar/clear', { __csrf: king.lastCsrf })).statusCode, 404);
    const state = (await owner.one(`select state from meta.session where app_id = $1 and username = 'king' order by last_seen desc limit 1`, [appId])).state;
    assert.equal(state.__DEBUG_LEVEL, undefined);
    // an item can't be named like the session's debug level: posted and URL values only reach real items
    await king.post('/a/hr/1', { __csrf: king.lastCsrf, __DEBUG_LEVEL: '9' });
    const after = (await owner.one(`select state from meta.session where app_id = $1 and username = 'king' order by last_seen desc limit 1`, [appId])).state;
    assert.equal(after.__DEBUG_LEVEL, undefined);
  });

  test('the toolbar token is not the builder token, and the builder token doesn\'t show the toolbar', async () => {
    const b = await devBrowser();
    const dev = b.cookies.get('pgkiln_dev')!;
    const bar = b.cookies.get('pgkiln_devbar')!;
    assert.notEqual(dev, bar);
    // the toolbar token doesn't open the builder
    const other = new Browser();
    other.cookies.set('pgkiln_dev', bar);
    assert.equal((await other.get('/builder')).statusCode, 302);
    // the builder token in the toolbar cookie shows nothing
    const user = await as('king');
    user.cookies.set('pgkiln_devbar', dev);
    assert.doesNotMatch((await user.get('/a/hr/1')).body, /class="devbar"/);
    user.cookies.set('pgkiln_devbar', bar);
    assert.match((await user.get('/a/hr/1')).body, /class="devbar"/);
  });

  test('an expired builder session shows no toolbar', async () => {
    const b = await devBrowser();
    assert.match((await b.get('/a/hr/1')).body, /class="devbar"/);
    const sid = (await owner.one(`select id from meta.session where app_id is null and devbar_hash is not null order by last_seen desc limit 1`)).id;
    await owner.query(`update meta.session set last_seen = now() - interval '1 day' where id = $1`, [sid]);
    assert.doesNotMatch((await b.get('/a/hr/1')).body, /class="devbar"/);
    assert.equal((await b.get('/a/hr/1/devbar/session')).statusCode, 404);
  });

  test('meta.debug_save stores a session\'s log only for a session the toolbar put in debug', async () => {
    const level = (await owner.one('select debug_level from meta.app where id = $1', [appId])).debug_level;
    await owner.query('update meta.app set debug_level = 0 where id = $1', [appId]);
    try {
      const king = await as('king');
      await king.get('/a/hr/1');
      const s = await owner.one(`select id from meta.session where app_id = $1 and username = 'king' order by last_seen desc limit 1`, [appId]);
      const save = (sid: string) =>
        owner.one(`select meta.debug_save($1, 1, 'king', $2, 'GET', '/a/hr/1', 200, 9, now(), 1, '[]'::jsonb) as id`, [appId, sid]);
      assert.equal((await save(s.id)).id, null, 'not in debug: nothing stored');
      await owner.query(`update meta.session set state = state || '{"__DEBUG_LEVEL": "nine"}' where id = $1`, [s.id]);
      assert.equal((await save(s.id)).id, null, 'only a known level counts');
      await owner.query(`update meta.session set state = state || '{"__DEBUG_LEVEL": "6"}' where id = $1`, [s.id]);
      assert.notEqual((await save(s.id)).id, null);
      // another application's session doesn't count for this application
      const other = (await owner.one(`select id from meta.app where id <> $1 limit 1`, [appId]))?.id;
      if (other) assert.equal((await owner.one(`select meta.debug_save($1, 1, 'king', $2, 'GET', '/', 200, 9, now(), 1, '[]'::jsonb) as id`, [other, s.id])).id, null);
    } finally {
      await owner.query('update meta.app set debug_level = $2 where id = $1', [appId, level]);
    }
  });
});

describe('sprint 50 search', () => {
  test('the search text is a value, the search runs as the application role, and only this application\'s configurations count', async () => {
    const page = (await owner.one(`select id from meta.page where app_id = $1 and page_no = 1`, [appId])).id;
    const other = (await owner.one(`insert into meta.app (alias, name, db_role) values ('sec-search-other', 'Other', 'hr_api') returning id`)).id;
    await owner.query(
      `insert into meta.search_config (app_id, name, label, source_type, source, title_column) values
         ($1, 'SEC_EMP', 'Employees', 'table', 'hr.emp', 'ename'),
         ($1, 'SEC_ACCOUNTS', 'Accounts', 'table', 'meta.account', 'password_hash'),
         ($2, 'SEC_FOREIGN', 'Foreign', 'sql', 'select ename from hr.emp', 'ename')`,
      [appId, other],
    );
    const region = (await owner.one(
      `insert into meta.region (page_id, seq, title, type, config) values ($1, 999, 'Find', 'search', '{"configs": ["SEC_EMP", "SEC_ACCOUNTS", "SEC_FOREIGN"]}') returning id`, [page])).id;
    try {
      const king = await as('king');
      for (const evil of [`' or 1=1 --`, `%' or ''='`, `\\' ; select 1 --`, `a) or (1=1`]) {
        const res = await king.get(`/a/hr/1?s${region}=${encodeURIComponent(evil)}`);
        assert.equal(res.statusCode, 200, evil);
        assert.doesNotMatch(res.body, /class="search-title"/, evil);
      }
      const res = await king.get(`/a/hr/1?s${region}=${encodeURIComponent('$2')}`);
      assert.doesNotMatch(res.body, /\$2[ab]\$/, 'no password hash');
      const any = await king.get(`/a/hr/1?s${region}=a`);
      assert.match(any.body, /<h3>Accounts<\/h3><div class="alert alert-error"/, 'the application role can\'t read meta.account');
      assert.doesNotMatch(any.body, /Foreign/, 'another application\'s configuration');
      // a region the user can't see answers 403 on the endpoint
      await owner.query(`update meta.region set condition = '1 = 0' where id = $1`, [region]);
      assert.equal((await king.get(`/a/hr/1/region/${region}?s${region}=a`)).statusCode, 403);
    } finally {
      await owner.query('delete from meta.region where id = $1', [region]);
      await owner.query(`delete from meta.search_config where name like 'SEC_%'`);
      await owner.query('delete from meta.app where id = $1', [other]);
    }
  });
});

describe('sprint 50 mail', () => {
  const SVC = 'SEC_MAIL';
  const setup = async () => {
    await owner.query('delete from meta.mail_service where name = $1', [SVC]);
    const id = (await owner.one(`insert into meta.mail_service (name, provider, senders, secret_enc) values ($1, 'log', '{@example.com}', 'v1:not-a-real-secret') returning id`, [SVC])).id;
    await owner.query(`insert into meta.app_mail_service (app_id, service_id, from_address) values ($1, $2, 'hr@example.com')
                       on conflict (app_id) do update set service_id = excluded.service_id, from_address = excluded.from_address, max_per_day = null`, [appId, id]);
    return id;
  };
  const asRole = async (roleName: string, app: number, sql: string, params: unknown[] = []) => {
    const c = await owner.pool.connect();
    try {
      await c.query('begin');
      await c.query(`select set_config('pgkiln.app_id', $1, true)`, [String(app)]);
      await c.query(`set local role ${roleName}`);
      return (await c.query(sql, params)).rows;
    } finally {
      await c.query('rollback');
      c.release();
    }
  };

  test('application code can\'t send in another application\'s name, nor with the runtime\'s role', async () => {
    await setup();
    const hrRole = (await owner.one('select db_role from meta.app where id = $1', [appId])).db_role;
    const other = (await owner.one(`insert into meta.app (alias, name, db_role) values ('sec-mail-other', 'Other', 'hr_api') returning id`)).id;
    try {
      assert.ok((await asRole(hrRole, appId, `select meta.send_mail('a@example.com', 'x', 'y') as id`))[0].id);
      // the HR role claiming the other application (which has a mail service too)
      await owner.query(`insert into meta.app_mail_service (app_id, service_id) select $1, service_id from meta.app_mail_service where app_id = $2`, [other, appId]);
      await assert.rejects(asRole(hrRole, other, `select meta.send_mail('a@example.com', 'x', 'y')`), /outside the application's own database role/);
      // resetting the role inside application code
      await assert.rejects(asRole(hrRole, appId, `reset role; select meta.send_mail('a@example.com', 'x', 'y')`), /outside the application's own database role/);
      // no current application at all
      await assert.rejects(owner.query(`select meta.send_mail('a@example.com', 'x', 'y')`), /no current application/);
    } finally {
      await owner.query('delete from meta.app where id = $1', [other]);
    }
  });

  test('applications can\'t read services, secrets, the queue or templates, nor call the internal functions', async () => {
    await setup();
    const hrRole = (await owner.one('select db_role from meta.app where id = $1', [appId])).db_role;
    for (const r of ['pgkiln_runtime', hrRole]) {
      for (const t of ['mail_service', 'app_mail_service', 'mail_queue', 'mail_attachment', 'email_template'])
        await assert.rejects(asRole(r, appId, `select * from meta.${t} limit 1`), /permission denied/, `${r} ${t}`);
      for (const fn of ['meta.mail_caller()', 'meta.mail_enqueue(text, text, text, text, text, text, text, text, text)'])
        assert.equal((await owner.one(`select has_function_privilege($1, $2, 'execute') as ok`, [r, fn])).ok, false, `${r} ${fn}`);
    }
    // meta.mail_status only answers for the application's own mail
    const id = (await asRole(hrRole, appId, `select meta.send_mail('a@example.com', 'x', 'y') as id`))[0].id;
    void id;
    const real = (await owner.one(`insert into meta.mail_queue (app_id, from_address, to_addresses, subject, body_text) values ($1, 'hr@example.com', '{a@example.com}', 'SEC status', 'x') returning id`, [appId])).id;
    assert.equal((await asRole(hrRole, appId, 'select meta.mail_status($1) as s', [real]))[0].s, 'queued');
    assert.equal((await asRole('pgkiln_runtime', appId + 100000, 'select meta.mail_status($1) as s', [real]))[0].s, null);
    await owner.query('delete from meta.mail_queue where id = $1', [real]);
  });

  test('a placeholder value is never searched for placeholders (no RAW injection)', async () => {
    const r = await owner.one(`select meta.mail_fill('<p>#NAME#</p>#SIG!RAW#', $1::jsonb, true) as html`,
      [JSON.stringify({ NAME: '#SIG!RAW#<script>', SIG: '<b>HR</b>' })]);
    assert.equal(r.html, '<p>#SIG!RAW#&lt;script&gt;</p><b>HR</b>');
  });

  test('only administrators reach mail services; the secret never reaches the page; mail of another application is not reachable', async () => {
    const id = await setup();
    const DEV = 'sec_mail_dev';
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password('Sec-mail-dev-password!'), false) on conflict do nothing`, [DEV]);
    const other = (await owner.one(`insert into meta.app (alias, name, db_role) values ('sec-mail-x', 'X', 'hr_app') returning id`)).id;
    try {
      const dev = new Browser();
      await dev.get('/builder/login');
      await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: DEV, password: 'Sec-mail-dev-password!' });
      assert.equal((await dev.get('/builder/mail')).statusCode, 403);
      assert.equal((await dev.get(`/builder/mail/${id}`)).statusCode, 403);
      await dev.get('/builder');
      assert.equal((await dev.post(`/builder/mail/${id}`, { __csrf: dev.lastCsrf, provider: 'smtp', senders: '@evil.example', host: 'evil.example' })).statusCode, 403);
      assert.deepEqual((await owner.one('select senders from meta.mail_service where id = $1', [id])).senders, ['@example.com']);

      const admin = new Browser();
      await admin.get('/builder/login');
      await admin.post('/builder/login', { __csrf: admin.lastCsrf, username: 'admin', password: 'admin' });
      const page = (await admin.get(`/builder/mail/${id}`)).body;
      assert.doesNotMatch(page, /not-a-real-secret/);
      // a mail of another application through this application's URL
      const foreign = (await owner.one(`insert into meta.mail_queue (app_id, from_address, to_addresses, subject, body_text, status) values ($1, 'x@example.com', '{a@example.com}', 'SEC foreign', 'x', 'error') returning id`, [other])).id;
      await admin.get(`/builder/apps/${appId}/mail`);
      await admin.post(`/builder/apps/${appId}/mail/${foreign}/retry`, { __csrf: admin.lastCsrf });
      assert.equal((await owner.one('select status from meta.mail_queue where id = $1', [foreign])).status, 'error');
      // a sender outside the service's list is refused for an application
      await admin.get(`/builder/mail/${id}`);
      await admin.post(`/builder/mail/${id}/apps`, { __csrf: admin.lastCsrf, allow: String(appId), [`from_${appId}`]: 'ceo@other.example' });
      assert.equal((await owner.one('select from_address from meta.app_mail_service where app_id = $1', [appId])).from_address, 'hr@example.com');
    } finally {
      await owner.query('delete from meta.app where id = $1', [other]);
      await owner.query('delete from meta.developer where username = $1', [DEV]);
      await owner.query('delete from meta.mail_service where name = $1', [SVC]);
    }
  });
});

describe('sprint 51 safe deployments and feedback', () => {
  test('the import check plans the SQL and runs none of it', async () => {
    const { advise } = await import('../src/builder/advisor.ts');
    const page = (await owner.one('select id from meta.page where app_id = $1 and page_no = 1', [appId])).id;
    await owner.query('create table if not exists public.sec51_probe (n int)');
    await owner.query('grant select, insert, delete on public.sec51_probe to hr_app');
    await owner.query('insert into public.sec51_probe values (1)');
    const proc = (await owner.one(`insert into meta.process (page_id, seq, name, type, point, code) values ($1, 999, 'sec51', 'sql', 'submit',
      'delete from public.sec51_probe; insert into public.sec51_probe values (2)') returning id`, [page])).id;
    const c = await owner.pool.connect();
    try {
      await c.query('begin');
      const r = await advise(appId, c);
      assert.ok(r.checked > 0);
      assert.deepEqual((await c.query('select n from public.sec51_probe')).rows, [{ n: 1 }], 'nothing ran in the transaction');
      // the role the check took is gone again after it
      assert.equal((await c.query(`select current_setting('role') as r`)).rows[0].r, 'none');
      await c.query('rollback');
    } finally {
      // a failed assertion leaves the transaction open: end it before the connection goes back to the pool
      await c.query('rollback').catch(() => {});
      c.release();
      await owner.query('delete from meta.process where id = $1', [proc]);
      await owner.query('drop table public.sec51_probe');
    }
  });

  test('backups are closed to applications; one is reachable only under its own application', async () => {
    for (const r of ['pgkiln_runtime', 'hr_app']) {
      await assert.rejects(owner.query(`begin; set local role ${r}; select * from meta.app_backup limit 1; rollback`), /permission denied/, r);
      await owner.query('rollback').catch(() => {});
      assert.equal((await owner.one(`select has_function_privilege($1, 'meta.backup_app(int, text, text, text)', 'execute') as ok`, [r])).ok, false, r);
    }
    const b = (await owner.one(`select meta.backup_app($1, 'manual', 'sec51') as id`, [appId])).id;
    const other = (await owner.one(`insert into meta.app (alias, name, db_role) values ('sec51-other', 'Other', 'hr_app') returning id`)).id;
    try {
      const dev = new Browser();
      await dev.get('/builder/login');
      await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
      assert.equal((await dev.get(`/builder/apps/${other}/backups/${b}/download`)).statusCode, 404);
      await dev.get(`/builder/apps/${other}/backups`);
      await dev.post(`/builder/apps/${other}/backups/${b}/delete`, { __csrf: dev.lastCsrf });
      assert.equal((await owner.one('select count(*)::int as n from meta.app_backup where id = $1', [b])).n, 1);
      // an application user can't download it
      const king = await as('king');
      assert.equal((await king.get(`/builder/apps/${appId}/backups/${b}/download`)).statusCode, 302);
    } finally {
      await owner.query('delete from meta.app_backup where id = $1', [b]);
      await owner.query('delete from meta.app where id = $1', [other]);
    }
  });

  test('availability closes the REST API (PostgREST) and REST modules too', async () => {
    const asApi = async (user: string, sql: string) => {
      const c = await owner.pool.connect();
      try {
        await c.query('begin');
        await c.query(`select set_config('request.jwt.claims', $1, true)`, [JSON.stringify({ role: 'hr_api', app_user: user, app: 'hr' })]);
        await c.query('set local role hr_api');
        return (await c.query(sql)).rows;
      } finally {
        await c.query('rollback').catch(() => {});
        c.release();
      }
    };
    const { issueApiToken } = await import('../src/api.ts');
    const token = (await issueApiToken(appId, 'king', 1)).token;
    const rest = () => app.inject({ method: 'GET', url: '/a/hr/rest/v1/employees', headers: { authorization: `Bearer ${token}` } });
    assert.equal((await rest()).statusCode, 200);
    try {
      await owner.query(`update meta.app set availability = 'unavailable', availability_message = 'Maintenance' where id = $1`, [appId]);
      await assert.rejects(asApi('king', 'select meta.api_check()'), /Maintenance/);
      const r = await rest();
      assert.equal(r.statusCode, 503);
      assert.match(r.body, /Maintenance/);
      await owner.query(`update meta.app set availability = 'restricted', availability_users = '{scott}' where id = $1`, [appId]);
      await assert.rejects(asApi('king', 'select meta.api_check()'), /not available to this account/);
      assert.equal((await rest()).statusCode, 403);
      await owner.query(`update meta.app set availability_users = '{KING}' where id = $1`, [appId]);
      await asApi('king', 'select meta.api_check()');
      assert.equal((await rest()).statusCode, 200);
      // developers only: an API token is never a builder session
      await owner.query(`update meta.app set availability = 'developers' where id = $1`, [appId]);
      assert.equal((await rest()).statusCode, 503);
    } finally {
      await owner.query(`update meta.app set availability = 'available', availability_users = '{}', availability_message = null where id = $1`, [appId]);
    }
  });

  test('Run only refuses the Page Designer\'s JSON saves too; feedback rows can only be added and read by the runtime', async () => {
    const page = (await owner.one('select id from meta.page where app_id = $1 and page_no = 1', [appId])).id;
    await owner.query(`update meta.app set build_status = 'run_only' where id = $1`, [appId]);
    try {
      const dev = new Browser();
      await dev.get('/builder/login');
      await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
      await dev.get(`/builder/pages/${page}`);
      const res = await app.inject({ method: 'POST', url: `/builder/pages/${page}`, payload: new URLSearchParams({ __csrf: dev.lastCsrf, page_no: '1', name: 'X' }).toString(),
        headers: { cookie: [...dev.cookies].map(([k, v]) => `${k}=${v}`).join('; '), 'content-type': 'application/x-www-form-urlencoded', accept: 'application/json' } });
      assert.equal(res.statusCode, 423);
      assert.match(res.body, /Run only/);
    } finally {
      await owner.query(`update meta.app set build_status = 'run_and_build' where id = $1`, [appId]);
    }
    for (const sql of ['update meta.feedback set status = \'done\'', 'delete from meta.feedback'])
      await assert.rejects(owner.query(`begin; set local role pgkiln_runtime; ${sql}; rollback`), /permission denied/, sql);
    await owner.query('rollback').catch(() => {});
    await assert.rejects(owner.query(`begin; set local role hr_app; select * from meta.feedback; rollback`), /permission denied/);
    await owner.query('rollback').catch(() => {});
  });
});

describe('sprint 52 page behaviour', () => {
  const inject = (b: Browser, url: string, form: Record<string, string>) =>
    app.inject({ method: 'POST', url, payload: new URLSearchParams(form).toString(),
      headers: { cookie: [...b.cookies].map(([k, v]) => `${k}=${v}`).join('; '), 'content-type': 'application/x-www-form-urlencoded', accept: 'application/json' } });

  test('an Ajax callback sets only items the user may change, and only runs its own application\'s processes', async () => {
    const page = (await owner.one('select id from meta.page where app_id = $1 and page_no = 1', [appId])).id;
    const ro = (await owner.one(`insert into meta.item (page_id, seq, name, type, readonly_condition) values ($1, 990, 'P1_SEC_RO', 'text', 'true') returning id`, [page])).id;
    const hid = (await owner.one(`insert into meta.item (page_id, seq, name, type) values ($1, 991, 'P1_SEC_HID', 'hidden') returning id`, [page])).id;
    const proc = (await owner.one(`insert into meta.process (page_id, seq, name, type, point, code) values ($1, 990, 'SEC_ECHO', 'sql', 'ajax',
      'select :P1_SEC_RO as ro, :P1_SEC_HID as hid, :APP_ID as app') returning id`, [page])).id;
    const other = (await owner.one(`insert into meta.app (alias, name, db_role) values ('sec52-other', 'Other', 'hr_app') returning id`)).id;
    await owner.query(`insert into meta.app_process (app_id, seq, name, point, code) values ($1, 10, 'SEC_OTHER', 'ajax', 'select 1 as x')`, [other]);
    try {
      const king = await as('king');
      await king.get('/a/hr/1');
      const r = await inject(king, '/a/hr/1/ajax/SEC_ECHO', { __csrf: king.lastCsrf, P1_SEC_RO: 'forced', P1_SEC_HID: 'forced', X01: 'x', APP_ID: '999' });
      assert.equal(r.statusCode, 200, r.body);
      const d = JSON.parse(r.body).data;
      assert.equal(d.ro, null, 'a read-only item is not set by the post');
      assert.equal(d.hid, null, 'a hidden item is not set by the post');
      assert.equal(String(d.app), String(appId));
      assert.equal((await inject(king, '/a/hr/1/ajax/SEC_OTHER', { __csrf: king.lastCsrf })).statusCode, 403);
    } finally {
      await owner.query('delete from meta.process where id = $1', [proc]);
      await owner.query('delete from meta.item where id = any($1)', [[ro, hid]]);
      await owner.query('delete from meta.app where id = $1', [other]);
    }
  });

  test('a download dynamic action of another page, and the error function\'s rights', async () => {
    const page2 = (await owner.one('select id from meta.page where app_id = $1 and page_no = 2', [appId])).id;
    const da = (await owner.one(`insert into meta.dynamic_action (page_id, seq, name, event, action, code) values ($1, 990, 'sec dl', 'click', 'download', 'X') returning id`, [page2])).id;
    try {
      const king = await as('king');
      await king.get('/a/hr/1');
      assert.equal((await inject(king, `/a/hr/1/da/${da}/download`, { __csrf: king.lastCsrf })).statusCode, 403);
    } finally {
      await owner.query('delete from meta.dynamic_action where id = $1', [da]);
    }
    // the error function runs as the application's role: pgkiln's tables are out of its reach
    await owner.query(`create or replace function public.sec52_err(e jsonb) returns jsonb language sql as $$ select jsonb_build_object('message', (select count(*)::text from meta.account)) $$`);
    await owner.query('grant execute on function public.sec52_err(jsonb) to public');
    await owner.query(`update meta.app set error_function = 'public.sec52_err' where id = $1`, [appId]);
    const page1 = (await owner.one('select id from meta.page where app_id = $1 and page_no = 1', [appId])).id;
    const proc = (await owner.one(`insert into meta.process (page_id, seq, name, type, point, code) values ($1, 991, 'SEC_FAIL', 'sql', 'ajax', 'do $$ begin raise exception ''kept''; end $$') returning id`, [page1])).id;
    try {
      const king = await as('king');
      await king.get('/a/hr/1');
      assert.equal(JSON.parse((await inject(king, '/a/hr/1/ajax/SEC_FAIL', { __csrf: king.lastCsrf })).body).error, 'kept');
    } finally {
      await owner.query('delete from meta.process where id = $1', [proc]);
      await owner.query(`update meta.app set error_function = null where id = $1`, [appId]);
      await owner.query('drop function public.sec52_err(jsonb)');
    }
  });

  test('Stay signed in works only with that application\'s own signed-in session', async () => {
    const anon = new Browser();
    await anon.get('/a/hr/login');
    assert.equal((await anon.post('/a/hr/session/extend', { __csrf: anon.lastCsrf })).statusCode, 401);
    const king = await as('king');
    await king.get('/a/hr/1');
    assert.equal((await king.post('/a/no-such-app/session/extend', { __csrf: king.lastCsrf })).statusCode, 404);
    assert.equal((await king.post('/a/hr/session/extend', { __csrf: king.lastCsrf })).statusCode, 200);
  });
});

describe('sprint 53 data and settings', () => {
  const inject = (b: Browser, url: string, form: Record<string, string>) =>
    app.inject({ method: 'POST', url, payload: new URLSearchParams(form).toString(),
      headers: { cookie: [...b.cookies].map(([k, v]) => `${k}=${v}`).join('; '), 'content-type': 'application/x-www-form-urlencoded', accept: 'application/json' } });
  /** SQL as a role, for an application and user (rolled back). */
  const asRole = async (roleName: string | null, app: number, sql: string, params: unknown[] = [], user = 'king') => {
    const c = await owner.pool.connect();
    try {
      await c.query('begin');
      await c.query(`select set_config('pgkiln.app_id', $1, true), set_config('pgkiln.app_user', $2, true)`, [String(app), user]);
      if (roleName) await c.query(`set local role ${roleName}`);
      return (await c.query(sql, params)).rows;
    } finally {
      await c.query('rollback');
      c.release();
    }
  };

  test('settings and preferences belong to the calling application, called as its own role', async () => {
    const hrRole = (await owner.one('select db_role from meta.app where id = $1', [appId])).db_role;
    const other = (await owner.one(`insert into meta.app (alias, name, db_role) values ('sec53-other', 'Other', 'hr_api') returning id`)).id;
    try {
      await owner.query(`insert into meta.app_setting (app_id, name, value) values ($1, 'SECRET_THING', 'other''s')`, [other]);
      await owner.query(`insert into meta.user_preference (app_id, username, name, value) values ($1, 'king', 'P1_X', 'other''s')`, [other]);
      assert.equal((await asRole(hrRole, appId, `select meta.get_app_setting('SUPPORT_EMAIL') as v`))[0].v, 'hr-support@example.com');
      // the HR role claiming the other application (which has no role of its own)
      for (const sql of [`select meta.get_app_setting('SECRET_THING')`, `select meta.set_app_setting('SECRET_THING', 'x')`,
                         `select meta.get_preference('P1_X')`, `select meta.set_preference('P1_X', 'x')`, `select meta.remove_preference('P1_X')`])
        await assert.rejects(asRole(hrRole, other, sql), /outside the application's own database role/, sql);
      // the runtime's role claiming HR
      await assert.rejects(asRole('pgkiln_runtime', appId, `select meta.get_app_setting('SUPPORT_EMAIL')`), /outside the application's own database role/);
      // no direct access to the tables, nor to the internal functions
      for (const r of ['pgkiln_runtime', hrRole]) {
        for (const t of ['app_setting', 'user_preference', 'dynamic_translation'])
          await assert.rejects(asRole(r, appId, `select * from meta.${t} limit 1`), /permission denied/, `${r} ${t}`);
        for (const fn of ['meta.caller_app(text)', 'meta.preference_user(text, text)'])
          assert.equal((await owner.one(`select has_function_privilege($1, $2, 'execute') as ok`, [r, fn])).ok, false, `${r} ${fn}`);
      }
      // meta.lang reads only the current application's translations
      await owner.query(`insert into meta.dynamic_translation (app_id, language, source, target) values ($1, 'nl', 'SEC53', 'other''s')`, [other]);
      assert.equal((await asRole(hrRole, appId, `select meta.lang('SEC53', 'nl') as v`))[0].v, 'SEC53');
      // meta.data_export runs with the caller's rights
      await assert.rejects(asRole(hrRole, appId, `select meta.data_export('select * from meta.app_setting')`), /permission denied/);
    } finally {
      await owner.query('delete from meta.app where id = $1', [other]);
    }
  });

  test('image items serve only their own query\'s picture; address items need the token and an editable address item', async () => {
    const page = (await owner.one('select id from meta.page where app_id = $1 and page_no = 43', [appId])).id;
    const hidden = (await owner.one(`insert into meta.item (page_id, seq, name, type, authz, config) values ($1, 990, 'P43_SEC_IMG', 'image', 'NO_SUCH_SCHEME',
      '{"sql": "select convert_to(''secret'', ''UTF8''), ''image/png''"}') returning id`, [page])).id;
    const ro = (await owner.one(`insert into meta.item (page_id, seq, name, type, readonly_condition) values ($1, 991, 'P43_SEC_ADDR', 'address', 'true') returning id`, [page])).id;
    process.env.GEOCODER_URL = 'http://127.0.0.1:1/search';
    try {
      const king = await as('king');
      await king.get('/a/hr/43');
      // an item the user may not see
      assert.equal((await king.get('/a/hr/43/image/P43_SEC_IMG')).statusCode, 404);
      // a public visitor: the page needs a sign-in
      const anon = new Browser();
      assert.notEqual((await anon.get('/a/hr/43/image/P43_PHOTO')).statusCode, 200);
      // the geocoder: a forged token, a read-only address item, another item type
      assert.equal((await inject(king, '/a/hr/43/geocode/P43_ADDRESS', { __csrf: 'forged', q: 'Markt 1' })).statusCode, 403);
      assert.equal((await inject(king, '/a/hr/43/geocode/P43_SEC_ADDR', { __csrf: king.lastCsrf, q: 'Markt 1' })).statusCode, 403);
      assert.equal((await inject(king, '/a/hr/43/geocode/P43_PHOTO', { __csrf: king.lastCsrf, q: 'Markt 1' })).statusCode, 403);
      // a geocoder that can't be reached: an error, not a crash
      assert.equal((await inject(king, '/a/hr/43/geocode/P43_ADDRESS', { __csrf: king.lastCsrf, q: 'Markt 1' })).statusCode, 502);
    } finally {
      delete process.env.GEOCODER_URL;
      await owner.query('delete from meta.item where id = any($1)', [[hidden, ro]]);
    }
  });

  test('a display image URL is never a script, and only https origins reach the CSP', async () => {
    const page = (await owner.one('select id from meta.page where app_id = $1 and page_no = 43', [appId])).id;
    const ids: number[] = [];
    for (const [n, v] of [['A', 'http://plain.example.com/x.png'], ['B', 'javascript:alert(1)'], ['C', '//evil.example.com/x.png'], ['D', 'https://u:p@creds.example.com/x.png'],
                          ['E', 'data:text/html;base64,PHNjcmlwdD4='], ['F', 'https://ok.example.com/x.png" onerror="alert(1)']])
      ids.push((await owner.one(`insert into meta.item (page_id, seq, name, type, default_value) values ($1, 990, $2, 'image', $3) returning id`, [page, `P43_SEC_${n}`, v])).id);
    try {
      const king = await as('king');
      const res = await king.get('/a/hr/43');
      const csp = String(res.headers['content-security-policy']);
      for (const bad of ['plain.example.com', 'evil.example.com', 'creds.example.com', 'javascript:', 'data:text/html', 'onerror="alert'])
        assert.ok(!res.body.includes(bad), bad);
      assert.doesNotMatch(csp, /plain\.example|evil\.example|creds\.example/);
      assert.match(csp, /img-src 'self' data:[^;]* https:\/\/ok\.example\.com/);
    } finally {
      await owner.query('delete from meta.item where id = any($1)', [ids]);
    }
  });
});

describe('sprint 54 interactive grid views', () => {
  const grid10 = async () =>
    (await owner.one(`select r.id, r.config from meta.region r join meta.page p on p.id = r.page_id where p.app_id = $1 and p.page_no = 10 and r.type = 'grid'`, [appId])) as { id: number; config: unknown };
  const sectionOf = (page: string, id: number) => page.slice(page.indexOf(`id="R${id}"`), page.indexOf('</section>', page.indexOf(`id="R${id}"`)));

  test('group by, chart and single row parameters of a grid cannot inject SQL', async () => {
    const king = await as('king');
    const { id } = await grid10();
    const get = (params: [string, string][]) => king.get(`/a/hr/10?${new URLSearchParams(params.map(([k, v]) => [`r${id}_${k}`, v]))}`);
    for (const params of [
      [['g', 'dname" from meta.account --'], ['ga', 'sum|deptno) from meta.account --'], ['v', 'group']],
      [['ch', 'bar|dname"; drop table hr.dept; --|count|deptno'], ['v', 'chart']],
      [['v', 'row'], ['row', '1; drop table hr.dept']],
      [['v', 'row'], ['row', '-5']],
      [['v', 'row'], ['row', '99999999999999999999']],
      [['v', 'pivot'], ['pv', 'dname|loc|count|deptno']],
    ] as [string, string][][]) {
      const res = await get(params);
      assert.equal(res.statusCode, 200, JSON.stringify(params));
      assert.doesNotMatch(res.body, /\$2[aby]\$/, 'no password hashes');
      assert.doesNotMatch(res.body, /pgkiln_runtime|syntax error|alert-error/, JSON.stringify(params));
    }
    assert.ok((await owner.one('select count(*)::int as n from hr.dept')).n > 0);
  });

  test('after a grid save the redirect keeps only report and grid parameters, on the same page', async () => {
    const king = await as('king');
    const { id } = await grid10();
    await king.get('/a/hr/10');
    const res = await king.post(`/a/hr/10?r${id}_q=x&next=https://evil.example.com&r${id}_csv=1&P10_X=1&r${id}_x=${encodeURIComponent('//evil.example.com')}`, { __csrf: king.lastCsrf, __request: `GRID_SAVE_${id}` });
    assert.equal(res.statusCode, 303, res.body.slice(0, 200));
    assert.equal(res.headers.location, `/a/hr/10?r${id}_q=x&r${id}_x=%2F%2Fevil.example.com`);
  });

  test('a column the developer hides stays hidden in every view', async () => {
    const { id, config } = await grid10();
    await owner.query(`update meta.region set config = config || '{"hidden": ["loc"]}' where id = $1`, [id]);
    try {
      const king = await as('king');
      const locs = (await owner.query('select loc from hr.dept where loc is not null')).rows.map((x) => x.loc as string);
      const views: [string, string][][] = [
        [['v', 'group'], ['g', 'loc']],
        [['v', 'group'], ['g', 'dname'], ['ga', 'max|loc']],
        [['v', 'chart'], ['ch', 'bar|loc|count|deptno']],
        [['v', 'chart'], ['ch', 'bar|dname|max|loc']],
        [['v', 'row'], ['row', '1']],
        [['v', 'row'], ['row', 'new']],
      ];
      for (const params of views) {
        const s = sectionOf((await king.get(`/a/hr/10?${new URLSearchParams(params.map(([k, v]) => [`r${id}_${k}`, v]))}`)).body, id);
        for (const loc of locs) assert.ok(!s.includes(loc), `${loc} in ${JSON.stringify(params)}`);
      }
      // nor offered in the Actions menu
      assert.doesNotMatch(sectionOf((await king.get('/a/hr/10')).body, id), /<option value="loc"/);
    } finally {
      await owner.query('update meta.region set config = $2 where id = $1', [id, config]);
    }
  });
});

describe('sprint 55 login page and forgot password', () => {
  const SERVICE = 'SEC_RESET_TEST';
  let saved: { login_page: number | null; password_reset: boolean; access_control: string };
  let kingHash = '';
  const link = (body: string) => /token=([A-Za-z0-9_-]{43})/.exec(body)?.[1];
  const lastMail = async (after: number) =>
    (await owner.query(`select to_addresses, body_text from meta.mail_queue where id > $1 and template = 'PASSWORD_RESET' order by id`, [after])).rows;
  const maxMail = async () => Number((await owner.one('select coalesce(max(id), 0) as id from meta.mail_queue')).id);
  const fresh = async () => {
    await owner.query('delete from meta.password_reset where app_id = $1', [appId]);
    await owner.query(`delete from meta.activity_log where app_id = $1 and event = 'password_reset_request'`, [appId]);
  };
  const request = async (login: string, headers: Record<string, string> = {}) => {
    const b = new Browser();
    b.headers = headers;
    await b.get('/a/hr/password/forgot');
    return b.post('/a/hr/password/forgot', { __csrf: b.lastCsrf, login });
  };

  before(async () => {
    saved = (await owner.one('select login_page, password_reset, access_control from meta.app where id = $1', [appId]))!;
    kingHash = (await owner.one(`select password_hash from meta.account where username = 'king'`)).password_hash;
    await owner.query('delete from meta.mail_service where name = $1', [SERVICE]);
    const id = (await owner.one(`insert into meta.mail_service (name, provider, senders) values ($1, 'log', '{@example.com}') returning id`, [SERVICE])).id;
    await owner.query(`insert into meta.app_mail_service (app_id, service_id, from_address) values ($1, $2, 'hr@example.com')
                       on conflict (app_id) do update set service_id = excluded.service_id, from_address = excluded.from_address`, [appId, id]);
    await owner.query('update meta.app set password_reset = true, login_page = null where id = $1', [appId]);
  });
  after(async () => {
    await owner.query('update meta.app set login_page = $2, password_reset = $3, access_control = $4 where id = $1', [appId, saved.login_page, saved.password_reset, saved.access_control]);
    await owner.query('update meta.account set password_hash = $1 where username = $2', [kingHash, 'king']);
    await owner.query('delete from meta.app_mail_service where app_id = $1', [appId]);
    await owner.query('delete from meta.mail_service where name = $1', [SERVICE]);
    await owner.query(`delete from meta.mail_queue where app_id = $1 and template = 'PASSWORD_RESET'`, [appId]);
    await fresh();
  });

  test('the reset link uses PUBLIC_URL, never the request\'s Host header', async () => {
    await fresh();
    const from = await maxMail();
    await request('king', { host: 'evil.example.com', 'x-forwarded-host': 'evil.example.com' });
    const [m] = await lastMail(from);
    assert.ok(m, 'a mail');
    assert.doesNotMatch(m.body_text, /evil\.example\.com/);
  });

  test('requests are limited per address and per account; unknown, inactive and other accounts get nothing', async () => {
    await fresh();
    const from = await maxMail();
    for (let i = 0; i < 5; i++) assert.equal((await request(i < 4 ? 'king' : 'nobody-at-all')).statusCode, 200);
    assert.equal((await request('king')).statusCode, 429, 'the sixth from one address');
    assert.equal((await lastMail(from)).length, 3, 'three per account per hour');
    // an account without access to the application gets no mail
    await fresh();
    await owner.query(`update meta.app set access_control = 'assigned' where id = $1`, [appId]);
    try {
      const outsider = (await owner.one(`select ac.username from meta.account ac where ac.active and ac.email is not null and ac.password_hash is not null
                                          and not exists (select 1 from meta.app_access aa where aa.app_id = $1 and aa.account_id = ac.id) limit 1`, [appId]))?.username;
      if (outsider) {
        const f2 = await maxMail();
        assert.equal((await request(outsider)).statusCode, 200);
        assert.equal((await lastMail(f2)).length, 0);
      }
    } finally {
      await owner.query('update meta.app set access_control = $2 where id = $1', [appId, saved.access_control]);
    }
  });

  test('a token works once, only for its application, not after it expires, and only with the session\'s CSRF token', async () => {
    await fresh();
    const from = await maxMail();
    await request('king');
    const token = link((await lastMail(from))[0].body_text)!;
    // another application: not valid there
    const other = (await owner.one(`select alias from meta.app where id <> $1 and authentication = 'app_users' limit 1`, [appId]))?.alias;
    if (other) {
      await owner.query('update meta.app set password_reset = true where alias = $1', [other]);
      try {
        const b = new Browser();
        await b.get(`/a/${other}/password/reset?token=${token}`);
        assert.notEqual((await b.get(`/a/${other}/password/reset`)).statusCode, 200);
      } finally {
        await owner.query('update meta.app set password_reset = false where alias = $1', [other]);
      }
    }
    // a forged CSRF token
    const b = new Browser();
    await b.get(`/a/hr/password/reset?token=${token}`);
    await b.get('/a/hr/password/reset');
    assert.equal((await b.post('/a/hr/password/reset', { __csrf: 'forged', new_password: 'Kiln-new-1234', confirm_password: 'Kiln-new-1234' })).statusCode, 403);
    // expired
    await owner.query(`update meta.password_reset set expires_at = now() - interval '1 second' where app_id = $1`, [appId]);
    assert.equal((await b.get('/a/hr/password/reset')).statusCode, 410);
    assert.equal((await b.post('/a/hr/password/reset', { __csrf: b.lastCsrf, new_password: 'Kiln-new-1234', confirm_password: 'Kiln-new-1234' })).statusCode, 410);
    assert.equal((await owner.one(`select password_hash from meta.account where username = 'king'`)).password_hash, kingHash);
    // the reset functions are not for applications' own roles
    const grants = await owner.one(`select has_function_privilege('public', 'meta.reset_password(int, text, text)', 'execute') as reset,
                                           has_function_privilege('public', 'meta.request_password_reset(int, text, text, text, text, text, text)', 'execute') as req`);
    assert.deepEqual(grants, { reset: false, req: false });
  });

  test('the login page: next stays in the application, a failed user name is escaped', async () => {
    const page = (await owner.one(`insert into meta.page (app_id, page_no, name, requires_auth, page_template) values ($1, 9998, 'Sec login', false, 'minimal') returning id`, [appId])).id;
    await owner.query(`insert into meta.region (page_id, seq, title, type) values ($1, 10, 'Sign in', 'login')`, [page]);
    await owner.query('update meta.app set login_page = 9998 where id = $1', [appId]);
    try {
      const b = new Browser();
      const res = await b.get('/a/hr/login?next=//evil.example.com/x');
      assert.equal(res.headers.location, '/a/hr/9998?next=%2Fa%2Fhr%2F1');
      await b.get('/a/hr/9998');
      const bad = await b.post('/a/hr/login', { __csrf: b.lastCsrf, username: '<script>alert(1)</script>', password: 'x', next: 'https://evil.example.com' });
      assert.equal(bad.headers.location, '/a/hr/9998?next=%2Fa%2Fhr%2F1');
      const body = (await b.get('/a/hr/9998')).body;
      assert.doesNotMatch(body, /<script>alert\(1\)/);
      assert.match(body, /value="&lt;script&gt;alert\(1\)&lt;\/script&gt;"/);
    } finally {
      await owner.query('update meta.app set login_page = $2 where id = $1', [appId, saved.login_page]);
      await owner.query('delete from meta.page where id = $1', [page]);
    }
  });
});

describe('sprint 56 generate DDL and schema comparison', () => {
  test('only developers; only schemas from the list (not meta, not a made-up name); nothing is run', async () => {
    // an application user can't open the builder pages
    const king = await as('king');
    for (const url of ['/builder/sql/ddl?schema=hr', '/builder/sql/compare?source=hr&target=public'])
      assert.notEqual((await king.get(url)).statusCode, 200, url);
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    const before = (await owner.one(`select count(*)::int as n from pg_namespace`)).n;
    for (const bad of ['meta', 'pg_catalog', 'hr; drop schema hr cascade', 'hr"; select 1; --', 'nope']) {
      const r = await dev.get(`/builder/sql/ddl?schema=${encodeURIComponent(bad)}`);
      assert.equal(r.statusCode, 200, bad);
      assert.doesNotMatch(r.body, /<textarea[^>]*aria-label="DDL of/, `${bad}: not generated`);
      const c = await dev.get(`/builder/sql/compare?source=hr&target=${encodeURIComponent(bad)}`);
      assert.doesNotMatch(c.body, /Change script/, `${bad}: not compared`);
    }
    assert.equal((await owner.one(`select count(*)::int as n from pg_namespace`)).n, before);
    // the meta schema (pgkiln's own, with password hashes) is never read
    assert.doesNotMatch((await dev.get('/builder/sql/ddl')).body, /<option value="meta">/);
  });
});

