describe('sprint 67 REST source catalogs', () => {
  const DEV = 'sec67_dev';
  const DEV_PW = 'Sec67-dev-password!';
  let otherWs: number;
  let defaultCatalog: number;
  let defaultService: number;
  const doc = (title: string) => JSON.stringify({
    openapi: '3.0.0', info: { title, version: '1' }, servers: [{ url: 'https://sec67.example.com' }],
    paths: { '/things': { get: { operationId: 'listThings', responses: { 200: { content: { 'application/json': { schema: { type: 'array', items: { type: 'object', properties: { id: { type: 'integer' } } } } } } } } } } },
  });
  const signIn = async (username: string, password: string) => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    await b.submit('/builder/login', { username, password });
    await b.get('/builder/rest-catalogs');
    return b;
  };
  before(async () => {
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false) on conflict do nothing`, [DEV, DEV_PW]);
    otherWs = (await owner.one(`insert into meta.workspace (name) values ('Sec67 Other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [otherWs, DEV]);
    defaultCatalog = (await owner.one(`insert into meta.rest_catalog (workspace_id, name, base_url) values (1, 'Sec67 Default', 'https://sec67.example.com') returning id`)).id;
    defaultService = (await owner.one(`insert into meta.rest_catalog_service (catalog_id, name, path) values ($1, 'SEC67_LIST', '/things') returning id`, [defaultCatalog])).id;
  });
  after(async () => {
    await owner.query(`delete from meta.rest_catalog where name like 'Sec67%'`);
    await owner.query(`delete from meta.workspace where name = 'Sec67 Other'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`delete from meta.rest_source where name like 'SEC67%'`);
  });

  test('another workspace\'s catalog doesn\'t exist for a developer: pages, posts, download and "from a catalog"', async () => {
    const d = await signIn(DEV, DEV_PW);
    assert.doesNotMatch((await d.get('/builder/rest-catalogs')).body, /Sec67 Default/);
    for (const url of [`/builder/rest-catalogs/${defaultCatalog}`, `/builder/rest-catalogs/${defaultCatalog}/download`])
      assert.equal((await d.get(url)).statusCode, 404, url);
    for (const url of [`/builder/rest-catalogs/${defaultCatalog}`, `/builder/rest-catalogs/${defaultCatalog}/delete`, `/builder/rest-catalogs/${defaultCatalog}/services`,
      `/builder/rest-catalogs/${defaultCatalog}/services/${defaultService}`, `/builder/rest-catalogs/${defaultCatalog}/services/${defaultService}/delete`])
      assert.equal((await d.submit(url, { name: 'SEC67_X', base_url: 'https://evil.example', path: '/x', method: 'GET' })).statusCode, 404, url);
    assert.deepEqual(await owner.one('select name, base_url from meta.rest_catalog where id = $1', [defaultCatalog]), { name: 'Sec67 Default', base_url: 'https://sec67.example.com' });
    assert.ok(await owner.one('select 1 as ok from meta.rest_catalog_service where id = $1', [defaultService]));
    // an application of the Default workspace can't use the other workspace's catalog, and vice versa
    const hr = (await owner.one(`select id from meta.app where alias = 'hr'`)).id;
    const otherCatalog = (await owner.one(`insert into meta.rest_catalog (workspace_id, name, base_url) values ($1, 'Sec67 Theirs', 'https://sec67.example.com') returning id`, [otherWs])).id;
    const otherService = (await owner.one(`insert into meta.rest_catalog_service (catalog_id, name, path) values ($1, 'SEC67_THEIRS', '/things') returning id`, [otherCatalog])).id;
    const a = await signIn('admin', 'admin');
    await a.get(`/builder/apps/${hr}/shared?new=rest_source`);
    for (const service of [String(otherService), `${defaultService} or 1=1`, '-1', ''])
      await a.submit(`/builder/apps/${hr}/rest-sources/from-catalog`, { service, name: 'SEC67_SRC' });
    assert.equal(await owner.one(`select 1 as ok from meta.rest_source where name = 'SEC67_SRC'`), undefined);
    assert.equal((await d.submit(`/builder/apps/${hr}/rest-sources/from-catalog`, { service: String(otherService), name: 'SEC67_SRC' })).statusCode, 404, 'not their application');
  });

  test('CSRF on every post; app users never reach the pages', async () => {
    const a = await signIn('admin', 'admin');
    a.lastCsrf = 'wrong';
    assert.equal((await a.upload('/builder/rest-catalogs/import', { text: doc('Sec67 Nope') }, {})).statusCode, 403);
    for (const url of ['/builder/rest-catalogs', `/builder/rest-catalogs/${defaultCatalog}/delete`, `/builder/rest-catalogs/${defaultCatalog}/services`])
      assert.equal((await a.post(url, { name: 'Sec67 Nope', base_url: 'https://x.example', path: '/x' })).statusCode, 403, url);
    assert.equal(await owner.one(`select 1 as ok from meta.rest_catalog where name = 'Sec67 Nope'`), undefined);
    const king = await as('king');
    for (const url of ['/builder/rest-catalogs', `/builder/rest-catalogs/${defaultCatalog}`]) assert.notEqual((await king.get(url)).statusCode, 200, url);
  });

  test('reading a document from a URL obeys the allow-list and private addresses; secrets never become parameters', async () => {
    const saved = [process.env.PGKILN_REST_ALLOWED_HOSTS, process.env.PGKILN_REST_PRIVATE_HOSTS];
    process.env.PGKILN_REST_ALLOWED_HOSTS = 'sec67.example.com,169.254.169.254';
    delete process.env.PGKILN_REST_PRIVATE_HOSTS;
    try {
      const a = await signIn('admin', 'admin');
      for (const url of ['http://169.254.169.254/latest/meta-data/', 'http://127.0.0.1:5432/', 'file:///etc/passwd']) {
        const res = await a.upload('/builder/rest-catalogs/import', { url }, {});
        const page = (await a.get(res.headers.location as string)).body;
        assert.match(page, /Import failed/, url);
      }
      assert.equal(await owner.one(`select 1 as ok from meta.rest_catalog where workspace_id = 1 and name <> 'Sec67 Default' and base_url like '%169.254%'`), undefined);
    } finally {
      process.env.PGKILN_REST_ALLOWED_HOSTS = saved[0];
      if (saved[1] === undefined) delete process.env.PGKILN_REST_PRIVATE_HOSTS;
      else process.env.PGKILN_REST_PRIVATE_HOSTS = saved[1];
    }
    const { sourceProblems } = await import('../src/websources.ts');
    for (const p of [{ name: 'auth', in: 'header', key: 'Authorization' }, { name: 'authorization', in: 'header' }, { name: 'c', in: 'header', key: 'Cookie' }, { name: 'h', in: 'header', key: 'Host' }, { name: 'x', in: 'query', key: 'a b' }])
      assert.ok(sourceProblems({ url: 'https://x.example/', params: [p], columns: [] }).length, JSON.stringify(p));
    // the catalog's checks refuse the same as a data source's
    const { serviceProblems, serviceUrl } = await import('../src/restcatalog.ts');
    assert.ok(serviceProblems('https://x.example', { name: 'S', path: '/x', method: 'GET', params: [{ name: 'a', in: 'header', key: 'Proxy-Authorization' }] as never }).length);
    // a service's path never changes the catalog's host
    for (const path of ['//evil.example/x', '/@evil.example', '/.@evil.example/', '/..//evil.example'])
      assert.equal(new URL(serviceUrl('https://x.example/v1', path)).host, 'x.example', path);
    assert.ok(serviceProblems('https://x.example', { name: 'S', path: 'evil.example/x', method: 'GET' }).length, 'a path starts with /');
  });

  test('names, descriptions and base URLs are escaped; the database refuses what the checks refuse', async () => {
    await assert.rejects(owner.query(`insert into meta.rest_catalog (workspace_id, name, base_url) values (1, 'Sec67 js', 'javascript:alert(1)')`));
    await assert.rejects(owner.query(`insert into meta.rest_catalog (workspace_id, name, base_url) values (1, 'Sec67 q', 'https://x.example/"onmouseover=alert(1)')`));
    await assert.rejects(owner.query(`insert into meta.rest_catalog_service (catalog_id, name, path) values ($1, 'SEC67_P', 'https://evil.example/')`, [defaultCatalog]));
    const a = await signIn('admin', 'admin');
    const evil = JSON.parse(doc('Sec67 <img src=x onerror=alert(1)>'));
    evil.info.description = '"><script>alert(1)</script>';
    evil.paths['/things'].get.summary = '<script>alert(2)</script>';
    const res = await a.upload('/builder/rest-catalogs/import', { text: JSON.stringify(evil) }, {});
    for (const url of [res.headers.location as string, '/builder/rest-catalogs']) {
      const page = (await a.get(url)).body;
      assert.match(page, /Sec67 &lt;img src=x onerror=alert\(1\)&gt;/, url);
      assert.doesNotMatch(page, /<script>alert|<img src=x/, url);
    }
  });
});

describe('sprint 67 workspace export and import', () => {
  let ws: number;
  const signIn = async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    await b.submit('/builder/login', { username: 'admin', password: 'admin' });
    await b.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
    await b.get('/builder');
    await b.submit('/builder/workspace', { workspace: String(ws) });
    await b.get('/builder/workspace-export');
    return b;
  };
  const file = (doc: Record<string, unknown>) => ({ file: { name: 'w.json', type: 'application/json', data: Buffer.from(JSON.stringify({ format: 'pgkiln-workspace/1', ...doc })) } });
  before(async () => {
    ws = (await owner.one(`insert into meta.workspace (name) values ('Sec67x Target') returning id`)).id;
  });
  after(async () => {
    await owner.query(`delete from meta.workspace where name = 'Sec67x Target'`);
  });

  test('CSRF on export and import', async () => {
    const b = await signIn();
    b.lastCsrf = 'wrong';
    assert.equal((await b.post('/builder/workspace-export', { __csrf: 'wrong', part: 'sql_scripts' })).statusCode, 403);
    assert.equal((await b.upload('/builder/workspace-import', { part: 'sql_scripts' }, file({ sql_scripts: [{ name: 'sec67x.sql', content: 'x' }] }))).statusCode, 403);
    assert.equal(await owner.one(`select 1 as ok from meta.sql_script where name = 'sec67x.sql'`), undefined);
    const king = await as('king');
    assert.notEqual((await king.get('/builder/workspace-export')).statusCode, 200);
  });

  test('a file never isolates a workspace, changes its name or roles, creates developers or makes installation administrators', async () => {
    const b = await signIn();
    await b.upload('/builder/workspace-import', { part: ['settings', 'developers'], replace: 'true' }, file({
      workspace: 'Default',
      settings: { name: 'Hijacked', isolated: true, run_role: 'postgres', dev_role: 'pgkiln', banner_color: 'red;background:url(x)', message: 'ok' },
      developers: [{ username: 'sec67x_ghost', admin: true }, { username: 'admin', admin: true, is_admin: true, password_hash: 'x' }],
    }));
    const w = await owner.one('select name, isolated, run_role, dev_role, banner_color, message from meta.workspace where id = $1', [ws]);
    // (sprint 185) every workspace has its developer login, named by pgkiln (pgkiln_ws<id>_dev_<suffix>), never by a file
    assert.match(w.dev_role, new RegExp(`^pgkiln_ws${ws}_dev_[0-9a-f]{8}$`));
    delete w.dev_role;
    assert.deepEqual(w, { name: 'Sec67x Target', isolated: false, run_role: null, banner_color: 'blue', message: 'ok' });
    assert.equal(await owner.one(`select 1 as ok from meta.developer where username = 'sec67x_ghost'`), undefined);
    assert.equal((await owner.one(`select password_hash <> 'x' as ok from meta.developer where username = 'admin'`)).ok, true);
  });

  test('application groups never take another workspace\'s applications; generators never target pgkiln\'s schema', async () => {
    const b = await signIn();
    await b.upload('/builder/workspace-import', { part: 'app_groups' }, file({ app_groups: [{ name: 'Sec67x group', apps: ['hr'] }] }));
    assert.equal(await owner.one(`select 1 as ok from meta.app_group_member m join meta.app_group g on g.id = m.group_id where g.name = 'Sec67x group'`), undefined);
    await b.upload('/builder/workspace-import', { part: ['data_generators', 'sql_scripts'] }, file({ data_generators: [{ name: 'sec67x', schema_name: 'meta', tables: [] }], sql_scripts: [{ name: 'sec67x.sql', content: 'x' }] }));
    assert.match((await b.get('/builder/workspace-export')).body, /Import failed, nothing was changed/);
    assert.equal(await owner.one(`select 1 as ok from meta.sql_script where name = 'sec67x.sql'`), undefined, 'all or nothing');
    // names and texts from the file are escaped on the result page
    await b.upload('/builder/workspace-import', { part: 'extension_links' }, file({ extension_links: [{ label: 'Sec67x <img src=x onerror=alert(1)>', url: 'https://x.example/' }] }));
    const page = (await b.get('/builder')).body;
    assert.doesNotMatch(page, /<img src=x/);
  });
});

describe('sprint 68 find my workspace and the data reporter welcome page', () => {
  const logged: string[] = [];
  const realLog = console.log;
  const mails = async () => {
    await new Promise((r) => setTimeout(r, 300));
    return logged.splice(0).filter((l) => l.startsWith('mail (log only)'));
  };
  before(async () => {
    await owner.query(`insert into meta.mail_service (name, provider, senders) values ('SEC68_LOG', 'log', '{@example.com}') on conflict do nothing`);
    await owner.query(`insert into meta.setting (name, value) values ('builder_mail_service', 'SEC68_LOG'), ('builder_mail_from', 'pgkiln@example.com') on conflict (name) do update set value = excluded.value`);
    await owner.query(`insert into meta.developer (username, password_hash, is_admin, email) values ('sec68_dev', meta.hash_password('Sec68-dev-password!'), false, 'sec68@example.com') on conflict do nothing`);
    await owner.query(`delete from meta.activity_log where event = 'find_workspace'`);
    console.log = (...a: unknown[]) => (logged.push(a.map(String).join(' ')), undefined);
  });
  after(async () => {
    console.log = realLog;
    await owner.query(`delete from meta.setting where name in ('builder_mail_service', 'builder_mail_from')`);
    await owner.query(`delete from meta.mail_service where name = 'SEC68_LOG'`);
    await owner.query(`delete from meta.developer where username = 'sec68_dev'`);
    await owner.query(`delete from meta.activity_log where event = 'find_workspace'`);
  });

  test('find my workspace: CSRF, no header injection, a limit per IP address', async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/find-workspace');
    await b.post('/builder/find-workspace', { email: 'sec68@example.com' });
    assert.deepEqual(await mails(), [], 'no CSRF token: nothing');
    for (const email of ['sec68@example.com\r\nBcc: victim@example.com', 'sec68@example.com,victim@example.com', '<sec68@example.com>', 'a@b'])
      await b.submit('/builder/find-workspace', { email });
    assert.deepEqual(await mails(), []);
    // ten requests an hour from one address, whatever they ask for
    for (let i = 0; i < 10; i++) await b.submit('/builder/find-workspace', { email: `nobody${i}@example.com` });
    await b.submit('/builder/find-workspace', { email: 'sec68@example.com' });
    assert.deepEqual(await mails(), [], 'limited per IP address');
  });

  test('only administrators set the builder\'s mail; another developer\'s address stays theirs; addresses are escaped', async () => {
    const d = new FileBrowser(app);
    await d.get('/builder/login');
    await d.submit('/builder/login', { username: 'sec68_dev', password: 'Sec68-dev-password!' });
    await d.get('/builder/developers');
    assert.equal((await d.submit('/builder/mail/builder', { service: '' })).statusCode, 403);
    assert.equal((await owner.one(`select value from meta.setting where name = 'builder_mail_service'`)).value, 'SEC68_LOG');
    await d.get('/builder/developers');
    assert.equal((await d.submit('/builder/developers/email', { username: 'admin', email: 'x@example.com' })).statusCode, 403);
    await assert.rejects(owner.query(`update meta.developer set email = 'a@example.com"><script>' where username = 'sec68_dev'`));
    await owner.query(`update meta.developer set email = $1 where username = 'sec68_dev'`, [`o'neil&co@example.com`]);
    assert.doesNotMatch((await d.get('/builder/developers')).body, /o'neil&co/, 'escaped');
    assert.equal((await new FileBrowser(app).get('/builder/developers')).statusCode, 302, 'not signed in');
  });

  test('the data reporter search is a value, never SQL; another user\'s private reports never show', async () => {
    const b = new Browser();
    await b.login('blake');
    const rid = (await owner.one(`select r.id from meta.region r join meta.page p on p.id = r.page_id join meta.app a on a.id = p.app_id where a.alias = 'hr' and p.page_no = 36 and r.type = 'data_reporter'`)).id;
    await owner.query(`insert into meta.data_report (app_id, region_id, username, name, definition) select p.app_id, $1, 'king', 'Sec68 private', '{"source": "employees"}' from meta.region r join meta.page p on p.id = r.page_id where r.id = $1`, [rid]);
    try {
      for (const q of [`') or true --`, '%', '_', 'Sec68'])
        assert.doesNotMatch((await b.get(`/a/hr/36?dr${rid}_q=${encodeURIComponent(q)}`)).body, /Sec68 private/, q);
      assert.match((await b.get(`/a/hr/36?dr${rid}_q=${encodeURIComponent('<script>x')}`)).body, /value="&lt;script&gt;x"/);
    } finally {
      await owner.query(`delete from meta.data_report where name = 'Sec68 private'`);
    }
  });
});

describe('sprint 69 gantt drag and drop', () => {
  let rid: number;
  let saved: { id: number; starts: string; ends: string | null }[];
  before(async () => {
    rid = (await owner.one(`select r.id from meta.region r join meta.page p on p.id = r.page_id join meta.app a on a.id = p.app_id where a.alias = 'hr' and p.page_no = 32 and r.title = 'Office move'`)).id;
    saved = (await owner.query('select id, starts::text, ends::text from hr.project_task')).rows;
  });
  after(async () => {
    for (const t of saved) await owner.query('update hr.project_task set starts = $2, ends = $3 where id = $1', [t.id, t.starts, t.ends]);
  });

  test('CSRF, the region\'s authorization, a numeric region, dates as dates; the SQL sees only checked values', async () => {
    const b = new Browser();
    await b.login('scott');
    await b.get('/a/hr/32');
    const before = (await owner.query('select id, starts, ends from hr.project_task order by id')).rows;
    assert.equal((await b.post(`/a/hr/32/chart/${rid}/move`, { __csrf: b.lastCsrf, task: '3', start: '2031-01-01', end: '2031-01-02' })).statusCode, 403, 'not a manager');
    const k = new Browser();
    await k.login('king');
    await k.get('/a/hr/32');
    assert.equal((await k.post(`/a/hr/32/chart/${rid}/move`, { task: '3', start: '2031-01-01', end: '2031-01-02' })).statusCode, 403, 'no CSRF token');
    for (const id of [`${rid} or 1=1`, '-1', 'x'])
      assert.notEqual((await k.post(`/a/hr/32/chart/${encodeURIComponent(id)}/move`, { __csrf: k.lastCsrf, task: '3', start: '2031-01-01', end: '2031-01-02' })).statusCode, 200, id);
    for (const [start, end] of [['2031-01-01', "2031-01-02'::date, ends = null where true; --"], ["now()", '2031-01-02'], ['2031-01-01T10:00:00Z', '2031-01-02']])
      assert.equal((await k.post(`/a/hr/32/chart/${rid}/move`, { __csrf: k.lastCsrf, task: '3', start, end })).statusCode, 400, `${start} ${end}`);
    assert.deepEqual((await owner.query('select id, starts, ends from hr.project_task order by id')).rows, before);
    // a task outside the region's query (here: a row the query doesn't return) can't be moved
    await owner.query(`insert into hr.project_task (id, name, starts) values (9069, 'Sec69 hidden', '2031-01-01')`);
    try {
      await owner.query(`update meta.region set source = replace(source, 'from hr.project_task t', 'from hr.project_task t where t.id < 9000') where id = $1`, [rid]);
      assert.equal((await k.post(`/a/hr/32/chart/${rid}/move`, { __csrf: k.lastCsrf, task: '9069', start: '2031-02-01', end: '2031-02-01' })).statusCode, 403);
      assert.equal((await owner.one(`select starts::text from hr.project_task where id = 9069`)).starts, '2031-01-01');
    } finally {
      await owner.query(`update meta.region set source = replace(source, ' where t.id < 9000', '') where id = $1`, [rid]);
      await owner.query('delete from hr.project_task where id = 9069');
    }
  });
});

describe('sprint 71 generated applications', () => {
  const ALIAS = 'sec71-gen';
  const SCHEMA = 'sec71';
  const ROLE = 'pgkiln_sec71';
  let id: number;
  before(async () => {
    await owner.query(`delete from meta.app where alias = $1`, [ALIAS]);
    await owner.query(`drop schema if exists ${SCHEMA} cascade`);
    await owner.query(`drop owned by ${ROLE}`).catch(() => undefined);
    await owner.query(`drop role if exists ${ROLE}`);
    await owner.query(`create role ${ROLE} nologin`);
    await owner.query(`grant ${ROLE} to pgkiln_runtime`);
    // names that would break SQL or HTML unless quoted and escaped
    await owner.query(`
      create schema ${SCHEMA};
      create table ${SCHEMA}."par""ent" ("k'ey" int primary key, "na<b>me" text);
      create table ${SCHEMA}.child (id int primary key, "p""ref" int references ${SCHEMA}."par""ent", "doc;drop" bytea, "doc;drop_name" text, "doc;drop_updated" timestamptz);
      comment on column ${SCHEMA}.child.id is '<img src=x onerror=alert(1)>';
      insert into ${SCHEMA}."par""ent" values (1, '<script>alert(1)</script>');
      insert into ${SCHEMA}.child values (5, 1, null, null, null);
      grant usage on schema ${SCHEMA} to ${ROLE};
      grant select, insert, update, delete on all tables in schema ${SCHEMA} to ${ROLE};
    `);
    id = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ($1, 'Sec71', 'none', $2) returning id`, [ALIAS, ROLE])).id;
    await owner.query(`insert into meta.page (app_id, page_no, name, requires_auth) values ($1, 1, 'Home', false)`, [id]);
  });
  after(async () => {
    await owner.query('delete from meta.app where id = $1', [id]);
    await owner.query(`drop schema if exists ${SCHEMA} cascade`);
    await owner.query(`drop owned by ${ROLE}`);
    await owner.query(`drop role if exists ${ROLE}`);
  });

  test('the new wizard functions are not granted to application roles', async () => {
    for (const fn of ['meta.wizard_report(regclass, text[])', 'meta.wizard_report_form(meta.app, regclass, int, int, text, text)', 'meta.wizard_files(regclass)',
      'meta.wizard_column_label(regclass, text)', 'meta.wizard_table_label(regclass, boolean)'])
      for (const role of ['pgkiln_runtime', 'hr_app'])
        assert.equal((await owner.one('select has_function_privilege($1, $2, \'execute\') as ok', [role, fn])).ok, false, `${role} ${fn}`);
  });

  test('odd names stay quoted in the generated SQL; labels and values are escaped on the page', async () => {
    await owner.query('select meta.generate_page($1, $2, $3::regclass, $4, $5::jsonb)', [ALIAS, 'report_form', `${SCHEMA}.child`, 10, '{"form_page": 11}']);
    const r = await owner.one(`select r.source, r.config from meta.region r join meta.page p on p.id = r.page_id where p.app_id = $1 and p.page_no = 10`, [id]);
    assert.match(r.source, /left join sec71\."par""ent" p1 on p1\."k'ey" = t\."p""ref"/);
    assert.doesNotMatch(r.source, /doc;drop/, 'the file columns are left out');
    const file = await owner.one(`select i.config from meta.item i join meta.page p on p.id = i.page_id where p.app_id = $1 and p.page_no = 11 and i.type = 'file'`, [id]);
    assert.deepEqual(file.config, { filename_column: 'doc;drop_name', updated_column: 'doc;drop_updated' });
    await owner.query('update meta.page set requires_auth = false where app_id = $1', [id]);
    const res = await new Browser().get(`/a/${ALIAS}/10`);
    assert.equal(res.statusCode, 200);
    assert.doesNotMatch(res.body, /<script>alert|<img src=x/);
    assert.match(res.body, /&lt;script&gt;alert\(1\)&lt;\/script&gt;/);
  });

  test('chart "top": only a whole number from 2 to 100 changes the rows', async () => {
    const { topRows } = await import('../src/runtime/regions.ts');
    const rows = [['a', 3], ['b', 2], ['c', 1]];
    for (const top of ['2; drop', '1e9', null, {}, 1000]) assert.equal(topRows({ config: { top } } as never, 'bar', rows, 'Other'), rows, String(top));
  });
});

describe('sprint 73 activity reporting', () => {
  let hrSession: string;
  let readerSession: string;
  let otherApp: number;
  before(async () => {
    hrSession = (await owner.one(`insert into meta.session (token_hash, app_id, username, roles) values ('sec73-a', $1, 'king', '{admin}') returning id`, [appId])).id;
    readerSession = (await owner.one(`insert into meta.session (token_hash, app_id, username, roles) values ('sec73-r', $1, 'allen', '{employee}') returning id`, [appId])).id;
    await owner.query(`delete from meta.app where alias = 'sec73-other'`);
    otherApp = (await owner.one(`insert into meta.app (alias, name, db_role) values ('sec73-other', 'Other', 'hr_app') returning id`)).id;
    await owner.query(`insert into meta.activity_log (app_id, page_no, username, event, ip, detail) values ($1, 1, 'king', 'page_view', '10.0.0.1', 'sec73'), ($2, 1, 'eve', 'page_view', '10.0.0.2', 'sec73')`, [appId, otherApp]);
  });
  after(async () => {
    await owner.query(`delete from meta.session where token_hash in ('sec73-a', 'sec73-r')`);
    await owner.query(`delete from meta.activity_log where detail = 'sec73'`);
    await owner.query('delete from meta.app where id = $1', [otherApp]);
  });
  /** meta.app_activity as the HR application's role, with the given app and session settings */
  const activity = (app: number, session: string | null) =>
    runtime.tx(async (c) => {
      await c.query(`select set_config('pgkiln.app_id', $1, true), set_config('pgkiln.session_id', $2, true)`, [String(app), session ?? '']);
      await c.query('set local role hr_app');
      return (await c.query('select * from meta.app_activity(1)')).rows;
    });

  test("only the application's administrators, only its own activity, without IP addresses", async () => {
    const rows = await activity(appId, hrSession);
    assert.ok(rows.some((r) => r.username === 'king'));
    assert.ok(!rows.some((r) => r.username === 'eve'), "not another application's activity");
    assert.deepEqual(Object.keys(rows[0]).sort(), ['at', 'elapsed_ms', 'event', 'page_no', 'username']);
    await assert.rejects(activity(appId, readerSession), /for its administrators/, 'not an admin');
    await assert.rejects(activity(appId, null), /for its administrators/, 'no session');
    await assert.rejects(activity(otherApp, hrSession), /for its administrators/, "an admin of HR asking for another application's");
    await assert.rejects(activity(appId, '00000000-0000-0000-0000-000000000000'), /for its administrators/, 'an unknown session');
  });
});

describe('sprint 76 report column values', () => {
  test('signed in, the page\'s own visible report, a column the user may see; read only', async () => {
    const r = await owner.one(`select r.id from meta.region r join meta.page p on p.id = r.page_id join meta.app a on a.id = p.app_id where a.alias = 'hr' and p.page_no = 2 and r.type = 'report'`);
    const other = await owner.one(`select r.id from meta.region r join meta.page p on p.id = r.page_id join meta.app a on a.id = p.app_id where a.alias = 'hr' and p.page_no <> 2 and r.type = 'report' limit 1`);
    const anon = await new Browser().get(`/a/hr/2/report/${r.id}/values?col=job`);
    assert.notEqual(anon.statusCode, 200, 'signed out');
    assert.doesNotMatch(anon.body, /CLERK/);
    const b = new Browser();
    await b.login('scott');
    const ok = await b.get(`/a/hr/2/report/${r.id}/values?col=job`);
    assert.equal(ok.statusCode, 200);
    assert.ok(JSON.parse(ok.body).values.some((v: { value: string }) => v.value === 'CLERK'));
    assert.equal((await b.get(`/a/hr/2/report/${other.id}/values?col=job`)).statusCode, 403, "another page's report");
    for (const col of ['sal) from hr.emp --', '*', '__k0', ''])
      assert.equal((await b.get(`/a/hr/2/report/${r.id}/values?col=${encodeURIComponent(col)}`)).statusCode, 403, col);
  });
});

describe('sprint 77 display positions, duplicate and copy to other page', () => {
  const devLogin = async () => {
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    return dev;
  };
  test('a signed-in developer with the CSRF token; only pages of the same application; only known positions', async () => {
    await owner.query('delete from meta.page where app_id = $1 and page_no in (9111, 9112)', [appId]);
    const other = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('sec-s77', 'Other', 'none', 'hr_app') returning id`)).id;
    try {
      const p = (await owner.one(`insert into meta.page (app_id, page_no, name) values ($1, 9111, 'Positions') returning id`, [appId])).id;
      const r1 = (await owner.one(`insert into meta.region (page_id, seq, title, type, source) values ($1, 10, 'One', 'static', '<p>1</p>') returning id`, [p])).id;
      const otherPage = (await owner.one(`insert into meta.page (app_id, page_no, name) values ($1, 1, 'Other') returning id`, [other])).id;
      const anon = new Browser();
      const king = await as('king');
      const dev = await devLogin();
      for (const [op, form] of [
        ['duplicate', { kind: 'region', id: String(r1) }],
        ['copy', { kind: 'region', id: String(r1), page: String(p) }],
        ['move', { kind: 'region', id: String(r1), position: 'banner', before: '' }],
      ] as [string, Record<string, string>][]) {
        const url = `/builder/pages/${p}/layout/${op}`;
        assert.equal((await anon.post(url, { ...form, __csrf: 'x' })).statusCode, 302, `${op}: anonymous`);
        assert.equal((await king.post(url, { ...form, __csrf: king.lastCsrf })).statusCode, 302, `${op}: an application user`);
        assert.equal((await dev.post(url, { ...form, __csrf: 'forged' })).statusCode, 403, `${op}: forged token`);
      }
      assert.equal((await owner.one('select count(*)::int as n from meta.region where page_id = $1', [p])).n, 1, 'nothing copied');
      assert.equal((await owner.one('select position from meta.region where id = $1', [r1])).position, null, 'nothing moved');
      await dev.get(`/builder/pages/${p}`);
      const post = (op: string, form: Record<string, string>) => dev.post(`/builder/pages/${p}/layout/${op}`, { ...form, __csrf: dev.lastCsrf });
      // a page of another application, and another page's component through this page, are refused
      assert.equal((await post('copy', { kind: 'region', id: String(r1), page: String(otherPage) })).statusCode, 400);
      assert.equal((await owner.one('select count(*)::int as n from meta.region where page_id = $1', [otherPage])).n, 0);
      const foreign = (await owner.one(`insert into meta.region (page_id, seq, title, type) values ($1, 10, 'Theirs', 'static') returning id`, [otherPage])).id;
      assert.equal((await post('duplicate', { kind: 'region', id: String(foreign) })).statusCode, 404);
      assert.equal((await post('copy', { kind: 'region', id: String(foreign), page: String(p) })).statusCode, 404);
      // positions and button positions from the fixed lists only
      for (const position of ["banner'; drop table meta.page; --", 'toString', 'side'])
        assert.equal((await post('move', { kind: 'region', id: String(r1), position, before: '' })).statusCode, 400, position);
      assert.equal((await post('create', { kind: 'button', type: 'submit', region: String(r1), slot: '__proto__' })).statusCode, 400);
      assert.equal((await owner.one('select count(*)::int as n from meta.button where page_id = $1', [p])).n, 0);
      // the page template from its list only
      await dev.post(`/builder/pages/${p}`, { __csrf: dev.lastCsrf, page_no: '9111', name: 'Positions', mode: 'normal', protection: 'none', page_template: 'two_columns' });
      assert.equal((await owner.one('select page_template from meta.page where id = $1', [p])).page_template, 'standard');
    } finally {
      await owner.query('delete from meta.page where app_id = $1 and page_no in (9111, 9112)', [appId]);
      await owner.query('delete from meta.app where id = $1', [other]);
    }
  });
});

describe('sprint 81 application computations and shortcuts', () => {
  test('the runtime role reads them only; a text shortcut is escaped; the builder takes them from developers only', async () => {
    for (const sql of [`insert into meta.app_computation (app_id, item_name) values (${appId}, 'X_SEC')`, `update meta.app_computation set expression = 'x'`,
      `insert into meta.shortcut (app_id, name, value) values (${appId}, 'X_SEC', 'x')`, `update meta.shortcut set value = 'x'`, `delete from meta.shortcut`])
      await assert.rejects(runtime.query(sql), /permission denied/, sql);
    const p = (await owner.one(`insert into meta.page (app_id, page_no, name) values ($1, 9113, 'Shortcuts') returning id`, [appId])).id;
    try {
      await owner.query(`insert into meta.shortcut (app_id, name, type, value) values ($1, 'SEC_SC_TEXT', 'text', '"><img src=x onerror=alert(1)>')`, [appId]);
      await owner.query(`insert into meta.region (page_id, seq, title, type, source) values ($1, 10, 'S', 'static', '<p id="sec-sc">"SEC_SC_TEXT"</p>')`, [p]);
      await owner.query(`insert into meta.button (page_id, seq, name, label, action, confirm) values ($1, 10, 'GO', 'Go', 'submit', '"SEC_SC_TEXT"')`, [p]);
      const body = (await (await as('king')).get('/a/hr/9113')).body;
      assert.match(body, /<p id="sec-sc">&quot;&gt;&lt;img src=x onerror=alert\(1\)&gt;<\/p>/);
      assert.match(body, /data-confirm="&quot;&gt;&lt;img src=x onerror=alert\(1\)&gt;"/);
      assert.doesNotMatch(body, /<img src=x/);
      // only developers make them
      const king = await as('king');
      for (const kind of ['app_computation', 'shortcut']) {
        const res = await king.post(`/builder/apps/${appId}/shared/${kind}`, { __csrf: king.lastCsrf, name: 'SEC_SC_KING', item_name: 'SEC_SC_KING', value: 'x', expression: 'x' });
        assert.equal(res.statusCode, 302, `${kind}: an application user is sent to the builder's sign-in`);
      }
      assert.equal((await owner.one(`select count(*)::int as n from meta.shortcut where name = 'SEC_SC_KING'`)).n, 0);
      assert.equal((await owner.one(`select count(*)::int as n from meta.app_computation where item_name = 'SEC_SC_KING'`)).n, 0);
    } finally {
      await owner.query('delete from meta.page where id = $1', [p]);
      await owner.query(`delete from meta.shortcut where app_id = $1 and name like 'SEC\\_SC\\_%'`, [appId]);
    }
  });
});

describe('sprint 82 report queries', () => {
  test('?doc= serves a report query only with its authorization, on a public page only through the page\'s own button; HTML stays sandboxed', async () => {
    await assert.rejects(runtime.query(`insert into meta.report_query (app_id, name, query) values (${appId}, 'SEC_RQ_X', 'select 1')`), /permission denied/);
    const p = (await owner.one(`insert into meta.page (app_id, page_no, name, requires_auth) values ($1, 9114, 'Report queries', false) returning id`, [appId])).id;
    try {
      await owner.query(`insert into meta.report_query (app_id, name, query, format) values
                           ($1, 'SEC_RQ_HTML', $$select '<img src=x onerror=alert(1)>' as note$$, 'html'),
                           ($1, 'SEC_RQ_ADMIN', 'select ename from hr.emp', 'csv')`, [appId]);
      await owner.query(`update meta.report_query set authz = '!MUST_NOT_BE_PUBLIC_USER' where app_id = $1 and name = 'SEC_RQ_ADMIN'`, [appId]);
      const king = await as('king');
      const html = await king.get('/a/hr/9114?doc=SEC_RQ_HTML');
      assert.equal(html.statusCode, 200);
      assert.match(String(html.headers['content-security-policy']), /default-src 'none'.*sandbox/, 'the file\'s own policy, not the page\'s');
      assert.match(String(html.headers['content-disposition']), /^attachment/);
      assert.doesNotMatch(html.body, /<img src=x/);
      assert.equal((await king.get('/a/hr/9114?doc=SEC_RQ_ADMIN')).statusCode, 403, 'its authorization');
      // signed out on a public page: only a report query the page offers with a button
      const anon = new FileBrowser(app);
      assert.equal((await anon.get('/a/hr/9114?doc=SEC_RQ_HTML')).statusCode, 403);
      await owner.query(`insert into meta.button (page_id, seq, name, label, action, document) values ($1, 10, 'PRINT', 'Print', 'document', 'SEC_RQ_HTML')`, [p]);
      assert.equal((await anon.get('/a/hr/9114?doc=SEC_RQ_HTML')).statusCode, 200);
    } finally {
      await owner.query('delete from meta.page where id = $1', [p]);
      await owner.query(`delete from meta.report_query where app_id = $1 and name like 'SEC\\_RQ\\_%'`, [appId]);
    }
  });
});

describe('sprint 83 component settings and component groups', () => {
  const devLogin = async () => {
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    return dev;
  };
  test('only developers change them; a stored setting out of bounds is not used; a group from another workspace is refused', async () => {
    const before = (await owner.one('select component_settings from meta.app where id = $1', [appId])).component_settings;
    const ws = (await owner.one(`insert into meta.workspace (name) values ('SEC83 other') returning id`)).id;
    const lib = (await owner.one(`insert into meta.app (alias, name, app_type, db_role) values ('sec83-lib', 'SEC83 library', 'library', 'hr_app') returning id`)).id;
    try {
      const king = await as('king');
      assert.equal((await king.post(`/builder/apps/${appId}/component-settings`, { __csrf: king.lastCsrf, report_rows: '1' })).statusCode, 302, 'an application user goes to the builder sign-in');
      const dev = await devLogin();
      await dev.get(`/builder/apps/${appId}/component-settings`);
      assert.equal((await dev.post(`/builder/apps/${appId}/component-settings`, { __csrf: 'forged', report_rows: '1' })).statusCode, 403);
      assert.deepEqual((await owner.one('select component_settings from meta.app where id = $1', [appId])).component_settings, before);
      // a hand-edited or imported value without bounds: the default
      await owner.query(`update meta.app set component_settings = '{"report_rows": 100000000, "lov_max_rows": -1}' where id = $1`, [appId]);
      assert.match((await king.get('/a/hr/2')).body, /1–\d+ of \d+/);
      assert.doesNotMatch((await king.get('/a/hr/2')).body, /1–100000000/);
      // a library application of another workspace: its groups are not offered and can't be subscribed to
      await owner.query(`insert into meta.workspace_app (workspace_id, app_id) values ($2, $1) on conflict (app_id) do update set workspace_id = excluded.workspace_id`, [lib, ws]);
      await owner.query(`insert into meta.component_group (app_id, name, members) values ($1, 'Theirs', '{}')`, [lib]);
      await dev.get(`/builder/apps/${appId}/subscriptions`);
      await dev.post(`/builder/apps/${appId}/subscriptions/group`, { __csrf: dev.lastCsrf, group: `${lib}|Theirs` });
      assert.match((await dev.get(`/builder/apps/${appId}/subscriptions`)).body, /Choose a component group/);
    } finally {
      await owner.query('update meta.app set component_settings = $2 where id = $1', [appId, JSON.stringify(before)]);
      await owner.query('delete from meta.app where id = $1', [lib]);
      await owner.query('delete from meta.workspace where id = $1', [ws]);
    }
  });
});

describe('sprint 84 dates in the date format, facet order', () => {
  test('typed dates are parameters or refused, never SQL; a facet order is only "name"', async () => {
    const king = await as('king');
    const r = await owner.one(`select (r.config->>'report')::int as report from meta.region r join meta.page p on p.id = r.page_id
                                where p.app_id = $1 and p.page_no = 21 and r.type = 'facets'`, [appId]);
    for (const bad of ["1981-01-01'; drop table hr.emp; --", '31-31-1981', 'x'.repeat(500), '1e9']) {
      const res = await king.get(`/a/hr/21?r${r.report}_rg_hiredate=~&r${r.report}_rf_hiredate=${encodeURIComponent(bad)}`);
      assert.equal(res.statusCode, 200, bad);
      assert.doesNotMatch(res.body, /alert-error/, `${bad}: ignored, not an error`);
    }
    assert.ok(await owner.one(`select 1 from hr.emp limit 1`), 'still there');
    // a facet's order parameter: anything but "name" is the default order, and is not reflected unescaped
    const odd = await king.get(`/a/hr/21?r${r.report}_fo_job=${encodeURIComponent('"><script>alert(1)</script>')}`);
    assert.equal(odd.statusCode, 200);
    assert.doesNotMatch(odd.body, /<script>alert\(1\)/);
  });
});

describe('sprint 85 form designer', () => {
  let rid: number;
  let pageId: number;
  let deptForm: number;
  const P = () => `fd${rid}_`;
  const row = (b: Browser, form: Record<string, string>) => b.post(`/a/hr/45/formdesigner/${rid}/row`, { __csrf: b.lastCsrf, ...form });
  before(async () => {
    const r = await owner.one(`select r.id, r.page_id from meta.region r join meta.page p on p.id = r.page_id where p.app_id = $1 and p.page_no = 45 and r.type = 'form_designer'`, [appId]);
    rid = r.id;
    pageId = r.page_id;
    deptForm = (await owner.one(`select id from meta.user_form where region_id = $1 and name = 'Departments'`, [rid])).id;
  });
  after(async () => {
    await owner.query(`delete from hr.dept where dname like 'Sec85%'`);
    await owner.query(`delete from meta.user_form where region_id = $1 and name like 'Sec85%'`, [rid]);
  });

  test('saving a row needs the CSRF token and a region on the page; only the form\'s fields are written', async () => {
    const allen = await as('allen');
    await allen.get('/a/hr/45');
    assert.equal((await allen.post(`/a/hr/45/formdesigner/${rid}/row`, { __csrf: 'forged', form: String(deptForm), row: '', mode: 'save', 'c:dname': 'Sec85 forged' })).statusCode, 403);
    assert.equal((await allen.post(`/a/hr/1/formdesigner/${rid}/row`, { __csrf: allen.lastCsrf, form: String(deptForm), row: '', 'c:dname': 'Sec85 elsewhere' })).statusCode, 403, 'not a region of that page');
    assert.equal(await owner.one(`select 1 from hr.dept where dname in ('Sec85 forged', 'Sec85 elsewhere')`), undefined);
    // columns that are not on the form (or not offered) are ignored; values are parameters
    await allen.get('/a/hr/45');
    await row(allen, { form: String(deptForm), row: '', mode: 'save', 'c:dname': "Sec85 '); drop table hr.dept; --", 'c:deptno': '9999', 'c:lat': '1', 'c:"lat" = 1, "lng"': '2' });
    const d = await owner.one(`select deptno, lat, lng from hr.dept where dname like 'Sec85 ''%'`);
    assert.ok(d && d.deptno !== 9999 && d.lat === null && d.lng === null);
  });

  test('a row key is a parameter; a forged definition reaches only offered columns; drafts are for designers', async () => {
    const allen = await as('allen');
    for (const key of ['1 or 1=1', "10'; --", 'x'.repeat(300)]) {
      const page = (await allen.get(`/a/hr/45?${P()}form=${deptForm}&${P()}row=${encodeURIComponent(key)}`)).body;
      assert.match(page, /This row does not exist/, key.slice(0, 20));
    }
    // a definition written past the designer (e.g. by the application's own SQL) is checked before it runs
    const forged = (await owner.one(`insert into meta.user_form (app_id, region_id, name, published, definition, created_by, updated_by)
      values ($1, $2, 'Sec85 forged', true, $3, 'x', 'x') returning id`, [appId, rid, JSON.stringify({
      source: 'departments', fields: [{ column: 'dname' }, { column: 'lat' }, { column: '"lat"; drop table hr.dept' }, { column: 'dname', display: '<script>' }],
      list: ['dname', 'lng'], actions: { insert: true, update: true, delete: true },
    })])).id;
    const list = (await allen.get(`/a/hr/45?${P()}form=${forged}`)).body;
    assert.doesNotMatch(list, /fdr\d+_1|value="delete"|<script>/);
    assert.ok(await owner.one('select 1 from hr.dept limit 1'));
    const res = await row(allen, { form: String(forged), row: '10', mode: 'delete' });
    assert.equal(res.statusCode, 303);
    assert.ok(await owner.one('select 1 from hr.dept where deptno = 10'), 'the source does not delete');
    await owner.query(`update meta.user_form set published = false where id = $1`, [forged]);
    await allen.get('/a/hr/45');
    await row(allen, { form: String(forged), row: '', mode: 'save', 'c:dname': 'Sec85 via draft' });
    assert.equal(await owner.one(`select 1 from hr.dept where dname = 'Sec85 via draft'`), undefined, 'a draft is not used by non-designers');
  });

  test('designing needs the region\'s authorization scheme; without one nobody designs', async () => {
    const blake = await as('blake');
    await blake.get('/a/hr/45');
    assert.equal((await blake.post(`/a/hr/45/formdesigner/${rid}/design`, { __csrf: blake.lastCsrf, src: 'departments', name: 'Sec85 manager', col_0: 'dname', on_0: 'true' })).statusCode, 403);
    assert.equal((await blake.post(`/a/hr/45/formdesigner/${rid}/delete`, { __csrf: blake.lastCsrf, form: String(deptForm) })).statusCode, 403);
    const config = (await owner.one('select config from meta.region where id = $1', [rid])).config;
    try {
      await owner.query(`update meta.region set config = config - 'design_authz' where id = $1`, [rid]);
      const king = await as('king');
      assert.doesNotMatch((await king.get('/a/hr/45')).body, /New form/);
      assert.equal((await king.post(`/a/hr/45/formdesigner/${rid}/design`, { __csrf: king.lastCsrf, src: 'departments', name: 'Sec85 admin', col_0: 'dname', on_0: 'true' })).statusCode, 403);
    } finally {
      await owner.query(`update meta.region set config = $2 where id = $1`, [rid, JSON.stringify(config)]);
    }
    assert.equal(await owner.one(`select 1 from meta.user_form where name like 'Sec85 %a%' and region_id = $1 and name in ('Sec85 manager', 'Sec85 admin')`, [rid]), undefined);
  });

  test('labels and help texts are escaped; applications reach forms only through the view and functions', async () => {
    const f = (await owner.one(`insert into meta.user_form (app_id, region_id, name, description, published, definition, created_by, updated_by)
      values ($1, $2, 'Sec85 <b>x</b>', '<img src=x onerror=alert(1)>', true, $3, 'x', 'x') returning id`, [appId, rid, JSON.stringify({
      source: 'departments', fields: [{ column: 'dname', label: '<script>alert(1)</script>', help: '<i onmouseover=alert(1)>' }], list: [], actions: { insert: true },
    })])).id;
    const page = (await (await as('allen')).get(`/a/hr/45?${P()}form=${f}`)).body;
    assert.doesNotMatch(page, /<script>alert|<img src=x|<i onmouseover|<b>x<\/b>/);
    assert.match(page, /&lt;script&gt;alert\(1\)&lt;\/script&gt;/);
    await assert.rejects(runtime.query('select * from meta.user_form'), /permission denied/);
    await assert.rejects(runtime.query(`insert into meta.user_form (app_id, region_id, name, definition, created_by, updated_by) values (${appId}, ${rid}, 'x', '{}', 'x', 'x')`), /permission denied/);
    assert.equal((await runtime.query('select * from meta.user_forms')).rowCount, 0, 'no application context: nothing');
    await assert.rejects(runtime.query(`select meta.save_user_form(${rid}, null, 'x', null, '{}'::jsonb, true)`), /sign in|unknown/);
    assert.equal((await runtime.query(`select meta.delete_user_form(${rid}, ${f}) as d`)).rows[0].d, false);
  });

  test('the builder settings need a developer and the CSRF token, and refuse pgkiln\'s own tables', async () => {
    const anon = new FileBrowser(app);
    assert.equal((await anon.post(`/builder/pages/${pageId}/region/${rid}/form-designer`, { __csrf: 'x', new_object: '1' })).statusCode, 302);
    const dev = new FileBrowser(app);
    await dev.get('/builder/login');
    await dev.submit('/builder/login', { username: 'admin', password: 'admin' });
    await dev.get(`/builder/pages/${pageId}?c=region-${rid}`);
    assert.equal((await dev.post(`/builder/pages/${pageId}/region/${rid}/form-designer`, { __csrf: 'forged', new_object: '1' })).statusCode, 403);
    const config = (await owner.one('select config from meta.region where id = $1', [rid])).config;
    const account = (await owner.one(`select 'meta.account'::regclass::oid::int as oid`)).oid;
    try {
      await dev.submit(`/builder/pages/${pageId}/region/${rid}/form-designer`, { new_object: String(account), new_id: 'accounts', design_authz: 'ADMIN',
        s0_key: 'departments', s0_insert: 'true', s0_col_0: 'dname', s0_on_0: 'true', s0_lov_0: "select password_hash, username from meta.app_user" });
      const cfg = (await owner.one('select config from meta.region where id = $1', [rid])).config;
      assert.ok(!(cfg.sources ?? []).some((s: any) => s.schema === 'meta'));
      assert.equal(cfg.sources.find((s: any) => s.id === 'departments')?.columns[0].lov, undefined, 'a list of values is a shared one, never SQL');
    } finally {
      await owner.query(`update meta.region set config = $2 where id = $1`, [rid, JSON.stringify(config)]);
    }
  });
});

describe('sprint 86 builder addresses and error pages', () => {
  const developer = async () => {
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    dev.headers.accept = 'text/html';
    return dev;
  };
  test('the redirect from the internal id stays in the builder; the page number is a number', async () => {
    const dev = await developer();
    const page3 = (await owner.one('select id from meta.page where app_id = $1 and page_no = 3', [appId])).id;
    for (const q of ['//evil.example/x', 'next=https://evil.example', '%0d%0aSet-Cookie:%20x=1']) {
      const res = await dev.get(`/builder/pages/${page3}?${q}`);
      assert.equal(res.statusCode, 302, q);
      assert.ok(String(res.headers.location).startsWith(`/builder/apps/${appId}/pages/3?`), q);
      assert.equal(res.headers['set-cookie']?.toString().includes('x=1') ?? false, false, q);
    }
    for (const no of ["3' or 1=1 --", '-1', '1e3', '99999999999']) assert.equal((await dev.get(`/builder/apps/${appId}/pages/${encodeURIComponent(no)}`)).statusCode, 404, no);
  });

  test('error pages escape the address and say nothing about the server', async () => {
    const dev = await developer();
    const res = await dev.get('/builder/x%22%3E%3Cimg%20src%3Dx%20onerror%3Dalert(1)%3E');
    assert.equal(res.statusCode, 404);
    assert.doesNotMatch(res.body, /<img src=x/);
    assert.match(String(res.headers['content-security-policy'] ?? ''), /script-src/, 'the page keeps the CSP');
    // (UX-10) the search field filled from the address holds words only
    assert.match(res.body, /<input id="nf-q" type="search" name="q" value="x img src x onerror alert 1"/);
    // signed out: the same page, nothing about the builder's applications
    const anon = new Browser();
    anon.headers.accept = 'text/html';
    const out = await anon.get('/builder/apps/1/nope');
    assert.equal(out.statusCode, 404);
    assert.doesNotMatch(out.body, /HR Demo|hr\b/);
  });
});

describe('sprint 88 the application version', () => {
  after(async () => {
    await owner.query('update meta.app set version = null where id = $1', [appId]);
  });
  test('the version is escaped in the footer; changing it needs a developer and the CSRF token', async () => {
    await owner.query(`update meta.app set version = '<img src=x onerror=alert(1)>' where id = $1`, [appId]);
    const king = await as('king');
    const page = (await king.get('/a/hr/1')).body;
    assert.doesNotMatch(page, /<img src=x/);
    assert.match(page, /<span class="t-version">&lt;img src=x onerror=alert\(1\)&gt;<\/span>/);
    // a signed-in application user is no developer; a developer without the token is refused
    assert.equal((await king.post(`/builder/apps/${appId}/settings`, { __csrf: king.lastCsrf, version: 'hacked' })).statusCode, 302);
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    assert.equal((await dev.post(`/builder/apps/${appId}/settings`, { __csrf: 'forged', version: 'hacked' })).statusCode, 403);
    assert.notEqual((await owner.one('select version from meta.app where id = $1', [appId])).version, 'hacked');
  });
});

describe('sprint 89 Object Browser column toolbar', () => {
  test('Modify only writes a statement to review: a default is one expression; nothing runs; developers only, with the token', async () => {
    await owner.query(`drop schema if exists sec89 cascade; create schema sec89; create table sec89.t (id int primary key, name text not null)`);
    try {
      const dev = new Browser();
      await dev.get('/builder/login');
      await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
      await dev.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
      await dev.get('/builder/sql/objects?schema=sec89&k=table&o=sec89.t&tab=columns');
      for (const expr of ["0); drop table sec89.t; select (1", "0 /* x */", "now() -- x", 'x'.repeat(201)]) {
        const res = await dev.post('/builder/sql/objects/alter', { __csrf: dev.lastCsrf, schema: 'sec89', table: 'sec89.t', action: 'modify', column: 'name', default_action: 'set', default: expr });
        assert.notEqual(res.headers.location, '/builder/sql/worksheet', expr.slice(0, 20));
      }
      const ok = await dev.post('/builder/sql/objects/alter', { __csrf: dev.lastCsrf, schema: 'sec89', table: 'sec89.t', action: 'modify', column: 'name', nullable: 'null' });
      assert.equal(ok.headers.location, '/builder/sql/worksheet');
      assert.equal((await owner.one(`select attnotnull from pg_attribute where attrelid = 'sec89.t'::regclass and attname = 'name'`)).attnotnull, true, 'nothing ran');
      assert.equal((await dev.post('/builder/sql/objects/alter', { __csrf: 'forged', schema: 'sec89', table: 'sec89.t', action: 'modify', column: 'name', nullable: 'null' })).statusCode, 403);
      const king = await as('king');
      assert.equal((await king.post('/builder/sql/objects/alter', { __csrf: king.lastCsrf, table: 'sec89.t', action: 'modify', column: 'name', nullable: 'null' })).headers.location, '/builder/login');
    } finally {
      await owner.query('drop schema if exists sec89 cascade');
    }
  });
});

describe('sprint 91 the SQL Worksheet', () => {
  const DEV = 'sec91dev';
  let otherWs: number;
  const signIn = async (username: string, password: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password });
    await b.get('/builder/sql/worksheet');
    return b;
  };
  before(async () => {
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    otherWs = (await owner.one(`insert into meta.workspace (name) values ('Sec91 Other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [otherWs, DEV]);
  });
  after(async () => {
    await owner.query(`delete from meta.workspace where name = 'Sec91 Other'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query('drop table if exists public.sec91_t');
  });

  test('developers only, with the CSRF token: app users and forged posts run nothing', async () => {
    const anon = new Browser();
    assert.equal((await anon.get('/builder/sql/worksheet')).headers.location, '/builder/login');
    assert.equal((await anon.get('/builder/sql/worksheet/navigator?schema=public')).headers.location, '/builder/login');
    const king = await as('king');
    assert.equal((await king.post('/builder/sql/worksheet', { __csrf: king.lastCsrf, sql: 'create table public.sec91_t (a int)', mode: 'script' })).headers.location, '/builder/login');
    const a = await signIn('admin', 'admin');
    assert.equal((await a.post('/builder/sql/worksheet', { __csrf: 'forged', sql: 'create table public.sec91_t (a int)', mode: 'script' })).statusCode, 403);
    assert.equal((await owner.one(`select to_regclass('public.sec91_t') as t`)).t, null);
  });

  test('output is escaped everywhere: grid, script output, notices, history, status bar', async () => {
    const a = await signIn('admin', 'admin');
    const evil = '<img src=x onerror=alert(91)>';
    for (const mode of ['statement', 'script']) {
      const out = (await a.post('/builder/sql/worksheet', { __csrf: a.lastCsrf, sql: `select '${evil}' as "${evil}"; do $$ begin raise notice '${evil}'; end $$; select 1 from "${evil}"`, mode, continue_on_error: 'on' })).body;
      assert.doesNotMatch(out, /<img src=x/, mode);
    }
    const hist = (await a.get('/builder/sql/worksheet')).body;
    assert.doesNotMatch(hist, /<img src=x/);
    assert.match(hist, /data-ws-history="select &#39;&lt;img src=x/);
  });

  test('Run as: only an application of the developer\'s workspace; another workspace\'s app is refused', async () => {
    const hr = (await owner.one(`select id from meta.app where alias = 'hr'`)).id;
    const d = await signIn(DEV, DEV);
    const page = (await d.get('/builder/sql/worksheet')).body;
    assert.doesNotMatch(page, new RegExp(`<option value="${hr}">`));
    for (const as_app of [String(hr), '0', '1 or 1=1', '-1'])
      assert.notEqual((await d.post('/builder/sql/worksheet', { __csrf: d.lastCsrf, sql: 'select current_user', mode: 'statement', as_app })).statusCode, 200, as_app);
    // the navigator never lists pgkiln's schemas
    assert.equal((await d.get('/builder/sql/worksheet/navigator?schema=meta')).statusCode, 404);
  });
});

describe('sprint 92 the SQL Worksheet: history, plans, SQL inserts', () => {
  const signIn = async () => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username: 'admin', password: 'admin' });
    await b.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
    await b.get('/builder/sql/worksheet');
    return b;
  };
  after(async () => {
    await owner.query(`drop schema if exists "sec92<b>" cascade`);
  });

  test('history ids are numbers of one\'s own rows; names in plans and history are escaped', async () => {
    const a = await signIn();
    for (const h of ['1 or 1=1', '-1', "1'; drop table meta.sql_history; --"])
      assert.equal((await a.get(`/builder/sql/worksheet?history=${encodeURIComponent(h)}`)).statusCode, 200, h);
    assert.ok(await owner.one(`select to_regclass('meta.sql_history') as t`));
    await owner.query(`drop schema if exists "sec92<b>" cascade; create schema "sec92<b>"; create table "sec92<b>"."<img src=x onerror=alert(92)>" (a int)`);
    for (const mode of ['explain', 'autotrace']) {
      const out = (await a.post('/builder/sql/worksheet', { __csrf: a.lastCsrf, sql: `select * from "sec92<b>"."<img src=x onerror=alert(92)>" where a = 1`, mode })).body;
      assert.doesNotMatch(out, /<img src=x/, mode);
      assert.match(out, /ws-plan-target/, mode);
    }
    assert.doesNotMatch((await a.get('/builder/sql/worksheet?tab=history')).body, /<img src=x|<b>/);
  });

  test('SQL inserts quote values and names; the download stays one read-only SELECT', async () => {
    const a = await signIn();
    const res = await a.post('/builder/sql/unload', { __csrf: a.lastCsrf, source: 'query', query: `select 'O''Brien''); drop table x; --' as "a""b", 'NaN'::numeric as n`, format: 'sql' });
    assert.equal(res.body, `insert into "query" ("a""b", "n") values ('O''Brien''); drop table x; --', 'NaN');\n`);
    const refused = await a.post('/builder/sql/unload', { __csrf: a.lastCsrf, source: 'query', query: 'delete from meta.sql_history', format: 'sql' });
    assert.equal(refused.statusCode, 422);
  });
});

describe('sprint 93 the SQL Worksheet: scripts as files, bind values', () => {
  const DEV = 'sec93dev';
  let otherWs: number;
  let theirs: number;
  const signIn = async (username: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username });
    if (username === 'admin') await b.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
    await b.get('/builder/sql/worksheet');
    return b;
  };
  before(async () => {
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    otherWs = (await owner.one(`insert into meta.workspace (name) values ('Sec93 Other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [otherWs, DEV]);
    theirs = (await owner.one(`insert into meta.sql_script (name, content, workspace_id) values ('sec93 secret', 'select ''secret 93''', 1) returning id`)).id;
  });
  after(async () => {
    await owner.query(`delete from meta.sql_script where name like 'sec93%'`);
    await owner.query(`delete from meta.workspace where name = 'Sec93 Other'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
  });

  test('another workspace\'s script is neither opened, listed nor changed', async () => {
    const d = await signIn(DEV);
    const page = (await d.get(`/builder/sql/worksheet?script=${theirs}`)).body;
    assert.doesNotMatch(page, /secret 93|sec93 secret/);
    for (const mode of ['save', 'rename'])
      await d.post('/builder/sql/worksheet', { __csrf: d.lastCsrf, sql: 'select 1 -- hacked', mode, script_id: String(theirs), ws_name: 'sec93 hacked' });
    assert.deepEqual(await owner.one('select name, content, workspace_id from meta.sql_script where id = $1', [theirs]), { name: 'sec93 secret', content: "select 'secret 93'", workspace_id: 1 });
    // a save without a script of one's own makes a new one in one's own workspace
    assert.equal((await owner.one(`select workspace_id from meta.sql_script where name = 'sec93 hacked'`))?.workspace_id, otherWs);
    const dl = await d.post('/builder/sql/worksheet', { __csrf: d.lastCsrf, sql: 'x', mode: 'download', script_id: String(theirs), ws_name: 'a"\r\nSet-Cookie: x=1' });
    assert.equal(dl.headers['content-disposition'], 'attachment; filename="a_Set-Cookie_x_1.sql"');
    assert.equal(dl.headers['set-cookie'], undefined);
  });

  test('bind values never become SQL; names and values are escaped in the dialog', async () => {
    const a = await signIn('admin');
    const ask = (await a.post('/builder/sql/worksheet', { __csrf: a.lastCsrf, sql: 'select :x, &y.', mode: 'statement' })).body;
    assert.match(ask, /name="bind_X"/);
    const out = (await a.post('/builder/sql/worksheet', { __csrf: a.lastCsrf, sql: 'select :x as v', mode: 'statement', binds_given: '1', bind_X: "'); drop table meta.sql_script; --" })).body;
    assert.match(out, /<td>&#39;\); drop table meta\.sql_script; --<\/td>/);
    assert.ok(await owner.one(`select to_regclass('meta.sql_script') as t`));
    const again = (await a.post('/builder/sql/worksheet', { __csrf: a.lastCsrf, sql: 'select :x as v', mode: 'statement' })).body;
    assert.match(again, /value="&#39;\); drop table meta\.sql_script; --"/);
  });
});

