describe('sprint 98 data modeler', () => {
  const DEV = 'sec98dev';
  let otherWs: number;
  let id: string;
  before(async () => {
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    otherWs = (await owner.one(`insert into meta.workspace (name) values ('Sec98 Other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [otherWs, DEV]);
    await owner.query(`drop schema if exists "sec98<b>" cascade; create schema "sec98<b>";
      create table "sec98<b>"."t<img src=x onerror=alert(98)>" (id int primary key, "c<script>" text);
      create table "sec98<b>".child (id int primary key, p int references "sec98<b>"."t<img src=x onerror=alert(98)>");
      comment on table "sec98<b>".child is '</title><script>alert(1)</script>'`);
    await owner.query(`delete from meta.sql_diagram where name like 'sec98%'`);
  });
  after(async () => {
    await owner.query(`delete from meta.sql_diagram where name like 'sec98%'`);
    await owner.query(`delete from meta.workspace where name = 'Sec98 Other'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`drop schema if exists "sec98<b>" cascade`);
  });
  const signIn = async (username: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username });
    if (username === 'admin') await b.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
    await b.get('/builder/sql/modeler');
    return b;
  };

  test('developers only; every change needs the CSRF token', async () => {
    const anon = new Browser();
    assert.equal((await anon.get('/builder/sql/modeler')).headers.location, '/builder/login');
    const king = await as('king');
    assert.equal((await king.get('/builder/sql/modeler')).headers.location, '/builder/login', 'an application user is no developer');
    const a = await signIn('admin');
    assert.equal((await a.post('/builder/sql/modeler', { __csrf: 'forged', name: 'sec98 forged', schema: 'sec98<b>' })).statusCode, 403);
    const created = await a.post('/builder/sql/modeler', { __csrf: a.lastCsrf, name: 'sec98 <svg onload=alert(1)>', schema: 'sec98<b>', objects: '*' });
    assert.equal(created.statusCode, 303);
    id = /modeler\/(\d+)/.exec(String(created.headers.location))![1];
    for (const [path, form] of <[string, Record<string, string>][]>[
      ['layout', { layout: 'auto' }], ['layout', { positions: '[]', format: 'json' }], ['objects', { remove: 'child' }], ['rename', { name: 'sec98 x' }], ['delete', {}],
    ]) assert.equal((await a.post(`/builder/sql/modeler/${id}/${path}`, { __csrf: 'forged', ...form })).statusCode, 403, path);
    assert.equal((await owner.one('select count(*)::int as n from meta.sql_diagram where id = $1', [id]))!.n, 1);
    // a schema the workshop can't use, and odd input
    assert.equal((await a.post('/builder/sql/modeler', { __csrf: a.lastCsrf, name: 'sec98 meta', schema: 'meta' })).statusCode, 404);
    assert.equal((await a.post(`/builder/sql/modeler/${id}/layout`, { __csrf: a.lastCsrf, positions: '{not json', format: 'json' })).statusCode, 400);
    assert.equal((await a.get('/builder/sql/modeler/1%27%20or%201=1')).statusCode, 404);
  });

  test('a diagram stays in its workspace', async () => {
    const d = await signIn(DEV);
    assert.doesNotMatch((await d.get('/builder/sql/modeler')).body, /sec98 &lt;svg/);
    for (const path of ['', '/svg', '/ddl', '/dictionary']) assert.equal((await d.get(`/builder/sql/modeler/${id}${path}`)).statusCode, 404, path);
    for (const [path, form] of <[string, Record<string, string>][]>[['layout', { layout: 'auto' }], ['objects', { remove: 'child' }], ['rename', { name: 'sec98 stolen' }], ['delete', {}]])
      assert.equal((await d.post(`/builder/sql/modeler/${id}/${path}`, { __csrf: d.lastCsrf, ...form })).statusCode, 404, path);
    assert.equal((await owner.one('select name from meta.sql_diagram where id = $1', [id]))!.name, 'sec98 <svg onload=alert(1)>');
  });

  test('names and comments are escaped in the page, the SVG, the DDL and the dictionary', async () => {
    const a = await signIn('admin');
    assert.match((await a.get('/builder/sql/modeler')).body, /sec98 &lt;svg onload=alert\(1\)&gt;/);
    for (const path of ['', '/svg', '/ddl', '/dictionary', '/dictionary?download=1', '?q=*']) {
      const body = (await a.get(`/builder/sql/modeler/${id}${path}`)).body;
      assert.doesNotMatch(body, /<img src=x|<script>alert|<svg onload|<\/title><script>/, path);
    }
    const page = (await a.get(`/builder/sql/modeler/${id}`)).body;
    assert.match(page, /data-name="t&lt;img src=x onerror=alert\(98\)&gt;"/);
    assert.match(page, /c&lt;script&gt;/);
  });
});

describe('sprint 99 database users', () => {
  const DEV = 'sec99dev';
  const PW = `Sec99-<b>&"pw'`;
  const dropRoles = async () => {
    for (const { r } of (await owner.query(`select rolname as r from pg_roles where rolname like 'sec99%'`)).rows)
      await owner.query(`drop owned by "${r.replace(/"/g, '""')}"; drop role "${r.replace(/"/g, '""')}"`);
  };
  before(async () => {
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    await dropRoles();
  });
  after(async () => {
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`delete from meta.activity_log where event = 'db_role' and detail like '%sec99%'`);
    await dropRoles();
  });
  const signIn = async (username: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username });
    if (username === 'admin') await b.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
    await b.get('/builder/db-users/new');
    return b;
  };
  const base = { original: '', name: 'sec99_role', login: '1', password_mode: 'keep', valid_until: '', conn_limit: '', search_path: '', comment: '' };
  const exists = async (name: string) => (await owner.one('select count(*)::int as n from pg_roles where rolname = $1', [name])).n === 1;

  test('administrators only: another developer gets 403 on every page and action', async () => {
    const d = await signIn(DEV);
    for (const url of ['/builder/db-users', '/builder/db-users/new', '/builder/db-users/role/pgkiln_runtime', '/builder/db-users/role/pgkiln_runtime/drop'])
      assert.equal((await d.get(url)).statusCode, 403, url);
    await d.get('/builder');
    assert.equal((await d.post('/builder/db-users/save', { __csrf: d.lastCsrf, ...base, mode: 'apply', reviewed: 'x' })).statusCode, 403);
    assert.equal((await d.post('/builder/db-users/drop', { __csrf: d.lastCsrf, name: 'hr_app', to: '' })).statusCode, 403);
    assert.equal(await exists('sec99_role'), false);
    assert.doesNotMatch((await d.get('/builder')).body, /href="\/builder\/db-users"/, 'not in a developer\'s menu');
  });

  test('CSRF: a forged token changes nothing', async () => {
    const a = await signIn('admin');
    assert.equal((await a.post('/builder/db-users/save', { __csrf: 'forged', ...base, mode: 'apply', reviewed: 'x' })).statusCode, 403);
    await owner.query('create role sec99_victim nologin');
    assert.equal((await a.post('/builder/db-users/drop', { __csrf: 'forged', name: 'sec99_victim', to: '' })).statusCode, 403);
    assert.equal(await exists('sec99_victim'), true);
  });

  test('names, dates, search paths, memberships and schemas are checked; values are escaped in SQL and pages', async () => {
    const a = await signIn('admin');
    for (const evil of <Record<string, string>[]>[
      { name: 'x"; drop role pgkiln; --' }, { name: 'pgkiln_sec99' }, { name: 'pg_sec99' }, { valid_until: "2030-01-01' superuser --" },
      { conn_limit: '1; drop role x' }, { search_path: 'public; drop schema hr cascade' }, { member: 'pgkiln_runtime' }, { member: 'pg_execute_server_program' },
      { 's.0.name': 'meta', 's.0.usage': '1', 's.0.defaults': 'none' },
    ]) {
      const res = await a.post('/builder/db-users/save', { __csrf: a.lastCsrf, ...base, ...evil, mode: 'review' });
      assert.equal(res.statusCode, 200, JSON.stringify(evil));
      assert.match(res.body, /class="alert alert-error"/, JSON.stringify(evil));
      assert.doesNotMatch(res.body, /name="reviewed"/, JSON.stringify(evil));
    }
    const comment = `it's <img src=x onerror=alert(99)> \\'; drop table hr.emp; --`;
    const review = await a.post('/builder/db-users/save', { __csrf: a.lastCsrf, ...base, comment, mode: 'review' });
    assert.doesNotMatch(review.body, /<img src=x/);
    assert.match(review.body, /COMMENT ON ROLE &quot;sec99_role&quot; IS E&#39;it&#39;&#39;s &lt;img src=x onerror=alert\(99\)&gt; \\\\&#39;&#39;; drop table hr.emp; --&#39;;/);
    const reviewed = /name="reviewed" value="([^"]+)"/.exec(review.body)![1];
    assert.equal((await a.post('/builder/db-users/save', { __csrf: a.lastCsrf, ...base, comment, mode: 'apply', reviewed })).statusCode, 303);
    assert.equal((await owner.one(`select shobj_description(oid, 'pg_authid') as c from pg_roles where rolname = 'sec99_role'`)).c, comment);
    assert.ok((await owner.one(`select to_regclass('hr.emp') as t`)).t);
    assert.doesNotMatch((await a.get('/builder/db-users')).body, /<img src=x/);
  });

  test('the password is never in a page, a preview or the activity log; it reaches PostgreSQL as a SCRAM verifier', async () => {
    const a = await signIn('admin');
    const review = await a.post('/builder/db-users/save', { __csrf: a.lastCsrf, ...base, name: 'sec99_pw', password_mode: 'set', mode: 'review' });
    assert.match(review.body, /PASSWORD &#39;\*{8}&#39;/);
    const reviewed = /name="reviewed" value="([^"]+)"/.exec(review.body)![1];
    const form = { __csrf: a.lastCsrf, ...base, name: 'sec99_pw', password_mode: 'set', reviewed, mode: 'apply' };
    const mismatch = await a.post('/builder/db-users/save', { ...form, password: PW, confirm: `${PW}x` });
    const short = await a.post('/builder/db-users/save', { ...form, password: 'short', confirm: 'short' });
    for (const res of [review, mismatch, short]) {
      for (const needle of [PW, 'Sec99-&lt;b&gt;', 'value="short"', 'SCRAM-SHA-256$']) assert.ok(!res.body.includes(needle), needle);
    }
    assert.equal(await exists('sec99_pw'), false);
    assert.equal((await a.post('/builder/db-users/save', { ...form, password: PW, confirm: PW })).statusCode, 303);
    assert.match((await owner.one(`select rolpassword from pg_authid where rolname = 'sec99_pw'`)).rolpassword, /^SCRAM-SHA-256\$4096:/);
    for (const url of ['/builder/db-users', '/builder/db-users/role/sec99_pw', '/builder/db-users/role/sec99_pw/drop']) {
      const body = (await a.get(url)).body;
      assert.ok(!body.includes(PW) && !body.includes('SCRAM-SHA-256$'), url);
    }
    const logs = (await owner.query(`select detail from meta.activity_log where detail like '%sec99_pw%'`)).rows.map((r) => String(r.detail)).join('\n');
    assert.match(logs, /PASSWORD '\*{8}'/);
    assert.ok(!logs.includes(PW) && !logs.includes('SCRAM-SHA-256$'));
  });

  test('pgkiln\'s own roles can\'t be changed, dropped or granted; roles in use can\'t be dropped', async () => {
    const a = await signIn('admin');
    for (const role of ['pgkiln_runtime', 'pgkiln_authenticator', 'pgkiln']) {
      const res = await a.post('/builder/db-users/save', { __csrf: a.lastCsrf, ...base, original: role, login: '', conn_limit: '0', mode: 'apply', reviewed: 'x' });
      assert.equal(res.statusCode, 403, role);
      assert.equal((await a.post('/builder/db-users/drop', { __csrf: a.lastCsrf, name: role, to: '' })).statusCode, 403, role);
    }
    assert.equal((await owner.one(`select rolcanlogin from pg_roles where rolname = 'pgkiln_runtime'`)).rolcanlogin, true);
    assert.equal((await a.post('/builder/db-users/drop', { __csrf: a.lastCsrf, name: 'hr_app', to: '' })).statusCode, 403);
    assert.equal(await exists('hr_app'), true);
    const res = await a.post('/builder/db-users/save', { __csrf: a.lastCsrf, ...base, name: 'sec99_member', member: 'pgkiln_app_code', mode: 'review' });
    assert.match(res.body, /pgkiln_app_code can&#39;t be granted here/);
    assert.doesNotMatch((await a.get('/builder/db-users/new')).body, /name="member" value="pgkiln/);
  });
});

describe('sprint 100 rest', () => {
  const S = 'sec100';
  const DEV = 'sec100dev';
  let otherWs: number;
  let noteId: number;
  const tok: Record<string, string> = {};
  const call = (method: string, path: string, who?: string, payload?: unknown) =>
    app.inject({
      method: method as 'GET',
      url: `/a/hr/autorest/${path}`,
      headers: { ...(who ? { authorization: `Bearer ${tok[who] ?? who}` } : {}), ...(payload !== undefined ? { 'content-type': 'application/json' } : {}) },
      payload: payload !== undefined ? JSON.stringify(payload) : undefined,
    });
  const signIn = async (username: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username });
    if (username === 'admin') await b.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
    await b.get('/builder/sql/rest');
    return b;
  };
  before(async () => {
    const { issueApiToken } = await import('../src/api.ts');
    const { SignJWT } = await import('jose');
    for (const u of ['king', 'allen', 'scott']) tok[u] = (await issueApiToken(appId, u, 1)).token;
    const sign = (claims: Record<string, unknown>, secret = process.env.API_JWT_SECRET!) =>
      new SignJWT(claims).setProtectedHeader({ alg: 'HS256' }).setIssuedAt().setExpirationTime('1h').sign(new TextEncoder().encode(secret));
    tok.forged = await sign({ app: 'hr', app_user: 'king' }, 'another-secret-that-is-long-enough-0123456789');
    tok.otherApp = await sign({ app: 'other', app_user: 'king' });
    tok.expired = await new SignJWT({ app: 'hr', app_user: 'king' }).setProtectedHeader({ alg: 'HS256' }).setIssuedAt(1000).setExpirationTime(2000).sign(new TextEncoder().encode(process.env.API_JWT_SECRET!));
    tok.none = `${Buffer.from('{"alg":"none"}').toString('base64url')}.${Buffer.from('{"app":"hr","app_user":"king"}').toString('base64url')}.`;
    await owner.query(`drop schema if exists ${S} cascade`);
    await owner.query(`
      create schema ${S};
      grant usage on schema ${S} to hr_app;
      create table ${S}.note (id int generated by default as identity primary key, owner text not null default meta.app_user(), body text);
      grant select, insert, update, delete on ${S}.note to hr_app;
      alter table ${S}.note enable row level security;
      create policy mine on ${S}.note using (owner = meta.app_user());
      insert into ${S}.note (owner, body) values ('king', 'king''s'), ('allen', 'allen''s');
      create view ${S}.who with (security_invoker = true) as select current_user::text as u, session_user::text as s;
      grant select on ${S}.who to hr_app;
      create table ${S}.owned (id int primary key);
      alter table ${S}.owned owner to hr_app;
      create table ${S}."<img src=x onerror=alert(100)>" (id int primary key);
      grant select on ${S}."<img src=x onerror=alert(100)>" to hr_app;
    `);
    noteId = (await owner.one(`select id from ${S}.note where owner = 'king'`)).id;
    for (const [name, alias, auth] of [['note', 'note', 'token'], ['who', 'who', 'public'], ['owned', 'owned', 'token'], ['<img src=x onerror=alert(100)>', 'img', 'token']])
      await owner.query(`insert into meta.rest_object (app_id, schema_name, object_name, alias, methods, auth) values ($1, $2, $3, $4, '{GET,POST,PUT,DELETE}', $5)`, [appId, S, name, alias, auth]);
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    otherWs = (await owner.one(`insert into meta.workspace (name) values ('Sec100 Other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [otherWs, DEV]);
  });
  after(async () => {
    await owner.query(`update meta.account set active = true where username = 'scott'`);
    await owner.query('update meta.workspace set rest_services = true where id = 1');
    await owner.query(`delete from meta.rest_object where schema_name = $1`, [S]);
    await owner.query(`delete from meta.workspace where name = 'Sec100 Other'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`drop schema if exists ${S} cascade`);
  });

  test('every method needs a valid token of this application', async () => {
    for (const [m, p, body] of [['GET', 'note/'], ['GET', `note/${noteId}`], ['POST', 'note/', { body: 'x' }], ['PUT', `note/${noteId}`, { body: 'x' }], ['DELETE', `note/${noteId}`]] as [string, string, unknown?][]) {
      for (const who of [undefined, 'forged', 'otherApp', 'expired', 'none', 'garbage'])
        assert.equal((await call(m, p, who, body)).statusCode, 401, `${m} ${p} as ${who}`);
    }
    await owner.query(`update meta.account set active = false where username = 'scott'`);
    assert.equal((await call('GET', 'note/', 'scott')).statusCode, 403, 'inactive account');
    await owner.query(`update meta.account set active = true where username = 'scott'`);
    assert.equal((await owner.one(`select count(*)::int as n from ${S}.note`)).n, 2, 'nothing changed');
    // a browser session (cookie) is not a token
    const king = await as('king');
    assert.equal((await app.inject({ url: '/a/hr/autorest/note/', headers: { cookie: [...king.cookies].map(([k, v]) => `${k}=${v}`).join('; ') } })).statusCode, 401);
  });

  test('statements run as the application role, never the owner; RLS holds', async () => {
    const who = (await call('GET', 'who/')).json().items[0];
    assert.equal(who.u, 'hr_app');
    assert.notEqual(who.u, 'pgkiln');
    assert.equal((await call('GET', 'owned/', 'king')).statusCode, 403, 'the role owns the table');
    assert.equal((await call('POST', 'owned/', 'king', { id: 1 })).statusCode, 403);
    assert.deepEqual((await call('GET', 'note/', 'allen')).json().items.map((r: any) => r.owner), ['allen']);
    assert.equal((await call('GET', `note/${noteId}`, 'allen')).statusCode, 404);
    assert.equal((await call('PUT', `note/${noteId}`, 'allen', { body: 'x' })).statusCode, 404);
    assert.equal((await call('DELETE', `note/${noteId}`, 'allen')).statusCode, 404);
    assert.equal((await call('POST', 'note/', 'allen', { owner: 'king', body: 'forged' })).statusCode, 403, 'with check');
    assert.equal((await owner.one(`select body from ${S}.note where id = $1`, [noteId])).body, 'king\'s');
    // the workspace preference turns AutoREST off with the REST modules
    await owner.query('update meta.workspace set rest_services = false where id = 1');
    assert.equal((await call('GET', 'note/', 'king')).statusCode, 404);
    assert.equal((await app.inject({ url: '/a/hr/autorest/openapi.json' })).statusCode, 404);
    await owner.query('update meta.workspace set rest_services = true where id = 1');
  });

  test('filters, order, keys, paths and bodies cannot inject SQL', async () => {
    const before = (await owner.one(`select count(*)::int as n from ${S}.note`)).n;
    for (const qs of [
      'id%3Bdrop%20table%20x=1', '%22id%22=1', 'id)%20or%20(1=1=1', 'order=id%3Bdrop%20table%20x', 'order=id%20desc', 'order=(select%201)', 'order=t.id',
      'limit=1;select', 'offset=-1', 'limit=1e3',
    ]) assert.equal((await call('GET', `note/?${qs}`, 'king')).statusCode, 400, qs);
    assert.deepEqual((await call('GET', `note/?body=${encodeURIComponent("x' or '1'='1")}`, 'king')).json().items, []);
    assert.deepEqual((await call('GET', `note/?q=${encodeURIComponent("' or 1=1 --")}`, 'king')).json().items, []);
    assert.equal((await call('GET', `note/${encodeURIComponent('1 or 1=1')}`, 'king')).statusCode, 400);
    assert.equal((await call('GET', `note/${encodeURIComponent("1'; drop table x; --")}`, 'king')).statusCode, 400);
    assert.equal((await call('GET', 'note/1,2', 'king')).statusCode, 404);
    assert.equal((await call('GET', 'note/1/2', 'king')).statusCode, 404);
    assert.equal((await call('GET', `${encodeURIComponent('note" t; --')}/`, 'king')).statusCode, 404);
    assert.equal((await call('GET', '..%2F..%2Fmeta/', 'king')).statusCode, 404);
    assert.equal((await call('POST', 'note/', 'king', { 'body") values (1); drop table x; --': 1 })).statusCode, 400);
    assert.equal((await call('PUT', `note/${noteId}`, 'king', { 'body = 1, owner': 'x' })).statusCode, 400);
    assert.equal((await owner.one(`select count(*)::int as n from ${S}.note`)).n, before);
    assert.ok((await owner.one(`select to_regclass('${S}.note') as t`)).t);
    // an object that isn't published doesn't exist, even if the role could read it (the e2e responsive test
    // publishes hr.dept and keeps it, so a database shared with an e2e run has it)
    await owner.query(`delete from meta.rest_object where app_id = $1 and schema_name = 'hr' and object_name = 'dept'`, [appId]);
    assert.equal((await call('GET', 'dept/', 'king')).statusCode, 404);
  });

  test('builder: CSRF, developers only, workspace scoping, names escaped', async () => {
    const id = (await owner.one(`select id from meta.rest_object where schema_name = $1 and alias = 'note'`, [S])).id;
    const imgId = (await owner.one(`select id from meta.rest_object where schema_name = $1 and alias = 'img'`, [S])).id;
    const a = await signIn('admin');
    const enable = { object: JSON.stringify([S, 'who']), app_id: String(appId), alias: 'who2', methods: 'GET', auth: 'token', page_size: '25' };
    assert.equal((await a.post('/builder/sql/rest', { __csrf: 'forged', ...enable })).statusCode, 403);
    assert.equal((await a.post(`/builder/sql/rest/${id}`, { __csrf: 'forged', methods: 'GET', auth: 'public', page_size: '25', enabled: '1' })).statusCode, 403);
    assert.equal((await a.post(`/builder/sql/rest/${id}/delete`, { __csrf: 'forged' })).statusCode, 403);
    assert.equal((await owner.one('select auth from meta.rest_object where id = $1', [id])).auth, 'token');
    const list = (await a.get('/builder/sql/rest')).body;
    assert.doesNotMatch(list, /<img src=x/);
    assert.match(list, /sec100\.&lt;img src=x onerror=alert\(100\)&gt;/);
    const detail = (await a.get(`/builder/sql/rest/${imgId}`)).body;
    assert.doesNotMatch(detail, /<img src=x/);
    assert.doesNotMatch((await a.get(`/builder/sql/rest/object?${new URLSearchParams({ schema: S, name: '<img src=x onerror=alert(100)>' })}`)).body, /<img src=x/);
    // a schema the SQL Workshop may not use, and meta, are refused
    assert.match((await a.post('/builder/sql/rest', { __csrf: a.lastCsrf, ...enable, object: '["meta","account"]' })).body, /Choose a table or view/);
    assert.equal((await a.get('/builder/sql/rest/object?schema=meta&name=account')).statusCode, 404);
    // another workspace's developer sees none of it and can't publish through hr
    const d = await signIn(DEV);
    assert.doesNotMatch((await d.get('/builder/sql/rest')).body, new RegExp(`href="/builder/sql/rest/${id}"`));
    assert.equal((await d.get(`/builder/sql/rest/${id}`)).statusCode, 404);
    assert.equal((await d.post(`/builder/sql/rest/${id}`, { __csrf: d.lastCsrf, methods: 'GET', auth: 'public', page_size: '25', enabled: '1' })).statusCode, 404);
    assert.equal((await d.post(`/builder/sql/rest/${id}/delete`, { __csrf: d.lastCsrf })).statusCode, 404);
    // (sprint 185) its developer login can't see the owner's schema at all: refused as an object, before the application
    assert.match((await d.post('/builder/sql/rest', { __csrf: d.lastCsrf, ...enable })).body, /Choose a table or view|Choose an application of this workspace/);
    assert.equal((await owner.one('select count(*)::int as n from meta.rest_object where id = $1 and auth = $2', [id, 'token'])).n, 1);
    // application users are not developers
    const king = await as('king');
    assert.equal((await king.get('/builder/sql/rest')).headers.location, '/builder/login');
    assert.equal((await king.post(`/builder/sql/rest/${id}/delete`, { __csrf: king.lastCsrf })).headers.location, '/builder/login');
    // public is an explicit choice: an unknown auth value is refused, not taken as public
    assert.match((await a.post('/builder/sql/rest', { __csrf: a.lastCsrf, ...enable, auth: 'anonymous' })).body, /Choose who may call it/);
  });
});

describe('sprint 102 monitor', () => {
  const DEV = 'sec102dev';
  before(async () => {
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    await owner.query(`drop table if exists public.sec102_t; create table public.sec102_t (id int primary key)`);
  });
  after(async () => {
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query('drop table if exists public.sec102_t');
  });
  const signIn = async (username: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username });
    if (username === 'admin') await b.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
    await b.get('/builder/sql');
    return b;
  };

  test('administrators only; anonymous visitors sign in first', async () => {
    const anon = new Browser();
    for (const url of ['/builder/sql/monitor', '/builder/sql/monitor?fragment=1', '/builder/sql/monitor/top', '/builder/sql/monitor/statements/1'])
      assert.equal((await anon.get(url)).statusCode, 302, url);
    assert.equal((await anon.post('/builder/sql/monitor/session', { pid: '1', action: 'terminate' })).statusCode, 302);
    const d = await signIn(DEV);
    for (const url of ['/builder/sql/monitor', '/builder/sql/monitor?fragment=1', '/builder/sql/monitor/top?sort=calls', '/builder/sql/monitor/statements/1?explain=1'])
      assert.equal((await d.get(url)).statusCode, 403, url);
    for (const url of ['/builder/sql/monitor/session', '/builder/sql/monitor/reset', '/builder/sql/monitor/statements/1/worksheet'])
      assert.equal((await d.post(url, { __csrf: d.lastCsrf, pid: '1', action: 'terminate' })).statusCode, 403, url);
  });

  test('CSRF: a forged token signals no session and resets nothing', async () => {
    const a = await signIn('admin');
    const pid = String((await owner.one('select pg_backend_pid() as pid')).pid);
    assert.equal((await a.post('/builder/sql/monitor/session', { __csrf: 'forged', pid, action: 'terminate' })).statusCode, 403);
    assert.equal((await a.post('/builder/sql/monitor/reset', { __csrf: 'forged' })).statusCode, 403);
    assert.equal((await a.post('/builder/sql/monitor/statements/1/worksheet', { __csrf: 'forged' })).statusCode, 403);
  });

  test('a pid, an action, a sort or a statement id cannot inject SQL; texts are escaped', async () => {
    const a = await signIn('admin');
    for (const form of [{ pid: '1 or 1=1', action: 'cancel' }, { pid: '1);select pg_terminate_backend(1', action: 'cancel' }, { pid: '1', action: 'pg_reload_conf' }, { pid: '', action: 'cancel' }])
      assert.equal((await a.post('/builder/sql/monitor/session', { __csrf: a.lastCsrf, ...form })).statusCode, 400, JSON.stringify(form));
    for (const qs of ['sort=calls%3Bdrop%20table%20x', 'sort=total&dir=desc%3Bselect%201', 'q=%27%20or%201%3D1%20--', 'q=%25_%5C'])
      assert.equal((await a.get(`/builder/sql/monitor/top?${qs}`)).statusCode, 200, qs);
    for (const id of ['1%20or%201=1', 'abc', '99999999999999999999999', '1%3Bselect%201'])
      assert.equal((await a.get(`/builder/sql/monitor/statements/${id}`)).statusCode, 404, id);
    assert.ok(await owner.one(`select to_regclass('public.sec102_t') as t`));
    // a session's query text and application name are escaped
    const { default: pg } = await import('pg');
    const c = new pg.Client({ connectionString: process.env.DATABASE_URL, application_name: '<img src=x onerror=alert(102)>' });
    await c.connect();
    try {
      await c.query('begin');
      await c.query(`select '<script>alert(102)</script>' as x`);
      const page = (await a.get('/builder/sql/monitor')).body;
      assert.doesNotMatch(page, /<img src=x|<script>alert/);
      assert.match(page, /&lt;img src=x onerror=alert\(102\)&gt;/);
      const top = (await a.get('/builder/sql/monitor/top?q=alert')).body;
      assert.doesNotMatch(top, /<script>alert/);
    } finally {
      await c.end();
    }
  });

  test('Explain of a recorded statement never changes data, and runs one statement only', async () => {
    const { explainForMonitor } = await import('../src/builder/sql-monitor.ts');
    for (const sql of [
      'insert into public.sec102_t values (1)',
      'with x as (insert into public.sec102_t values (2) returning *) select * from x',
      'select 1; insert into public.sec102_t values (3)',
      'select 1; commit; insert into public.sec102_t values (4)',
      `select $$;$$; insert into public.sec102_t values (5)`,
      'create table public.sec102_u as select 1',
      'select pg_terminate_backend(pg_backend_pid())',
    ]) await explainForMonitor(sql, null);
    assert.equal((await owner.one('select count(*)::int as n from public.sec102_t')).n, 0);
    assert.equal((await owner.one(`select to_regclass('public.sec102_u') as t`)).t, null);
    // a schema that doesn't exist or is crafted is only quoted into the search path
    await explainForMonitor('select * from sec102_t', 'public"; drop table public.sec102_t; --');
    assert.ok(await owner.one(`select to_regclass('public.sec102_t') as t`));
  });
});

describe('sprint 101 scheduling', () => {
  // SQL Workshop › Scheduling (pg_cron): administrators only, CSRF, values only as SQL literals, Apply runs only the
  // reviewed SQL, Run now runs the stored command. pg_cron itself when installed, else test/pgcron-mock.ts.
  const DEV = 'sec101dev';
  const URL = '/builder/sql/scheduling';
  let mock: typeof import('./pgcron-mock.ts');
  before(async () => {
    mock = await import('./pgcron-mock.ts');
    await mock.mockPgCron();
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    await owner.query('drop role if exists sec101_nologin; create role sec101_nologin nologin');
  });
  after(async () => {
    await owner.query(`select cron.unschedule(jobid) from cron.job where jobname like 'sec101%'`);
    await mock.dropMockPgCron();
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query('drop role if exists sec101_nologin');
    await owner.query(`delete from meta.activity_log where event in ('cron_job', 'cron_run_now') and detail like '%sec101%'`);
  });
  const signIn = async (username: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username });
    if (username === 'admin') await b.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
    await b.get('/builder/sql');
    return b;
  };
  const ctx = async () => (await owner.one<{ d: string; u: string }>('select current_database() as d, current_user as u'))!;
  const review = async (b: Browser, form: Record<string, string>) => {
    const res = await b.post(`${URL}/save`, { __csrf: b.lastCsrf, ...form, mode: 'review' });
    const f = res.body.slice(res.body.lastIndexOf(`<form method="post" action="${URL}/save"`));
    const out: Record<string, string> = {};
    for (const m of f.slice(0, f.indexOf('</form>')).matchAll(/<input type="hidden" name="([^"]+)" value="([^"]*)">/g))
      out[m[1]] = m[2].replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
    return { res, hidden: out };
  };
  const jobOf = async (name: string) => (await owner.one<{ jobid: string; command: string; schedule: string }>('select jobid::text, command, schedule from cron.job where jobname = $1', [name])) ?? null;

  test('administrators only: another developer gets 403 on every page and action', async () => {
    const { d, u } = await ctx();
    await owner.query(`select cron.schedule_in_database('sec101 victim', '0 1 * * *', 'select 1', $1, $2)`, [d, u]);
    const id = (await jobOf('sec101 victim'))!.jobid;
    const dev = await signIn(DEV);
    for (const url of [URL, `${URL}/new`, `${URL}/history`, `${URL}/history/purge`, `${URL}/job/${id}`, `${URL}/job/${id}/edit`, `${URL}/job/${id}/unschedule`, `${URL}/preview?schedule=*`])
      assert.equal((await dev.get(url)).statusCode, 403, url);
    for (const url of [`${URL}/save`, `${URL}/job/${id}/active`, `${URL}/job/${id}/run`, `${URL}/job/${id}/unschedule`, `${URL}/history/purge`])
      assert.equal((await dev.post(url, { __csrf: dev.lastCsrf, jobid: id, name: 'sec101 victim', schedule: '* * * * *', command: 'select 2', database: d, username: u, mode: 'apply', reviewed: 'x', days: 'all' })).statusCode, 403, url);
    assert.deepEqual(await jobOf('sec101 victim'), { jobid: id, command: 'select 1', schedule: '0 1 * * *' });
    assert.doesNotMatch((await dev.get('/builder/sql')).body, /href="\/builder\/sql\/scheduling"/, 'not on a developer\'s Launchpad');
  });

  test('CSRF: a forged token changes nothing', async () => {
    const a = await signIn('admin');
    const id = (await jobOf('sec101 victim'))!.jobid;
    for (const url of [`${URL}/job/${id}/active`, `${URL}/job/${id}/unschedule`, `${URL}/job/${id}/run`])
      assert.equal((await a.post(url, { __csrf: 'forged', active: '' })).statusCode, 403, url);
    assert.ok(await jobOf('sec101 victim'));
  });

  test('names, schedules and commands stay literals; pages escape them', async () => {
    const a = await signIn('admin');
    const { d, u } = await ctx();
    const name = `sec101 x'); select cron.unschedule(1); --<b>`;
    const command = `select '$cmd$' as a, $cmd$ $$ </pre><script>alert(1)</script> $cmd$ as b; -- '); drop table meta.app; --`;
    const r = await review(a, { jobid: '', name, schedule: '0 2 * * *', command, database: d, username: u, active: '1' });
    assert.doesNotMatch(r.res.body, /<script>alert|<b>/);
    assert.equal((await a.post(`${URL}/save`, { __csrf: a.lastCsrf, ...r.hidden, mode: 'apply' })).statusCode, 303);
    const job = await jobOf(name);
    assert.equal(job?.command, command, 'stored exactly as typed');
    const page = await a.get(`${URL}/job/${job!.jobid}`);
    assert.doesNotMatch(page.body, /<script>alert|<b>|<\/pre><script>/);
    assert.match((await a.get(URL)).body, /sec101 x&#39;\); select cron\.unschedule\(1\); --&lt;b&gt;/);
    // a schedule that isn't one, a database or role it may not use: refused before any SQL is shown
    for (const [k, v, msg] of [['schedule', "0 2 * * *'); drop table meta.app; --", /Schedule:/], ['database', 'template0', /database/], ['username', 'sec101_nologin', /role that can sign in/], ['username', 'nobody"; drop', /role/]]) {
      const bad = await review(a, { jobid: '', name: 'sec101 bad', schedule: '0 2 * * *', command: 'select 1', database: d, username: u, active: '1', [k as string]: v as string });
      assert.equal(bad.res.statusCode, 422, String(k));
      assert.match(bad.res.body, msg as RegExp);
      assert.doesNotMatch(bad.res.body, /cron\.schedule_in_database\(/);
    }
    assert.equal(await jobOf('sec101 bad'), null);
    // the preview escapes what it echoes
    assert.doesNotMatch((await a.get(`${URL}/preview?schedule=${encodeURIComponent('<img src=x onerror=alert(1)>')}`)).body, /<img/);
  });

  test('Apply runs only the reviewed SQL; ids in paths are numbers', async () => {
    const a = await signIn('admin');
    const { d, u } = await ctx();
    const r = await review(a, { jobid: '', name: 'sec101 reviewed', schedule: '0 2 * * *', command: 'select 1', database: d, username: u, active: '1' });
    const tampered = await a.post(`${URL}/save`, { __csrf: a.lastCsrf, ...r.hidden, command: 'drop table meta.app', mode: 'apply' });
    assert.match(tampered.body, /changed since you reviewed/);
    assert.equal(await jobOf('sec101 reviewed'), null);
    // purge: the reviewed statement, not one the form names
    const purge = await a.get(`${URL}/history/purge?days=7`);
    assert.equal((await a.post(`${URL}/history/purge`, { __csrf: a.lastCsrf, days: 'all', reviewed: /name="reviewed" value="([^"]+)"/.exec(purge.body)![1], mode: 'apply' })).statusCode, 422);
    assert.match((await a.get(`${URL}/history/purge?days=1;drop`)).body, /interval &#39;30 days&#39;/, 'an unknown choice is the default');
    for (const url of [`${URL}/job/1;drop`, `${URL}/job/99999999999999999999`, `${URL}/job/-1/edit`, `${URL}/history/purge?job=1%20or%201=1`])
      assert.equal((await a.get(url)).statusCode, 404, url);
    assert.equal((await a.get(`${URL}/history?job=1%20or%201=1&status=x'&q=%27%3B`)).statusCode, 200);
  });

  test('Run now runs the stored command, not one from the request', async () => {
    const a = await signIn('admin');
    const { d, u } = await ctx();
    await owner.query('drop table if exists public.sec101_t; create table public.sec101_t (n int)');
    try {
      await owner.query(`select cron.schedule_in_database('sec101 run', '0 1 * * *', 'insert into public.sec101_t values (1)', $1, $2)`, [d, u]);
      const id = (await jobOf('sec101 run'))!.jobid;
      await a.get(`${URL}/job/${id}`);
      const res = await a.post(`${URL}/job/${id}/run`, { __csrf: a.lastCsrf, command: 'insert into public.sec101_t values (666)' });
      assert.equal(res.statusCode, 200);
      assert.deepEqual((await owner.query('select n from public.sec101_t')).rows, [{ n: 1 }]);
    } finally {
      await owner.query('drop table if exists public.sec101_t');
    }
  });
});

describe('sprint 103 dump', () => {
  const DEV = 'sec103dev';
  let job = 0;
  let file = '';
  before(async () => {
    const { DUMP_DIR } = await import('../src/datapump.ts');
    const { mkdir, writeFile } = await import('node:fs/promises');
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    await mkdir(DUMP_DIR, { recursive: true });
    file = `upload-sec103-${Date.now()}.dump`;
    await writeFile(`${DUMP_DIR}/${file}`, 'not really an archive');
    job = (await owner.one(`insert into meta.dump_job (kind, status, username, file_name, original_name, bytes, expires_at)
      values ('import', 'uploaded', 'admin', $1, 'sec103.dump', 21, now() + interval '1 day') returning id::int`, [file])).id;
  });
  after(async () => {
    const { DUMP_DIR } = await import('../src/datapump.ts');
    const { rm } = await import('node:fs/promises');
    await rm(`${DUMP_DIR}/${file}`, { force: true });
    await owner.query(`delete from meta.dump_job where username in ('admin', $1) and (original_name like 'sec103%' or schema_name like 'sec103%' or id = $2)`, [DEV, job]);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`delete from meta.activity_log where event like 'schema_%' and detail like '%sec103%'`);
    delete process.env.PGKILN_DUMP_MAX_MB;
  });
  const signIn = async (username: string) => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    await b.submit('/builder/login', { username, password: username === 'admin' ? 'admin' : username });
    await b.get('/builder/sql/data-pump/import');
    return b;
  };
  const jobs = async () => (await owner.one(`select count(*)::int as n from meta.dump_job`)).n as number;

  test('administrators only: another developer gets 403 on every page and action, and no menu entry', async () => {
    const d = await signIn(DEV);
    for (const url of ['/builder/sql/data-pump', '/builder/sql/data-pump/export?schema=hr', '/builder/sql/data-pump/import',
      `/builder/sql/data-pump/job/${job}`, `/builder/sql/data-pump/job/${job}/import`, `/builder/sql/data-pump/job/${job}/download`])
      assert.equal((await d.get(url)).statusCode, 403, url);
    await d.get('/builder/sql');
    const n = await jobs();
    for (const [url, form] of [['/builder/sql/data-pump/export', { schema: 'hr', mode: 'all' }], [`/builder/sql/data-pump/job/${job}/import`, { target: 'sec103_x' }],
      [`/builder/sql/data-pump/job/${job}/cancel`, {}], [`/builder/sql/data-pump/job/${job}/delete`, {}]] as [string, Record<string, string>][])
      assert.equal((await d.submit(url, form)).statusCode, 403, url);
    const up = await d.upload('/builder/sql/data-pump/upload', {}, { file: { name: 'sec103-dev.dump', type: 'application/octet-stream', data: Buffer.from('PGDMP') } });
    assert.equal(up.statusCode, 403);
    assert.equal(await jobs(), n);
    assert.ok(await getJobRow(job), 'the job is still there');
    assert.doesNotMatch((await d.get('/builder/sql')).body, /href="\/builder\/sql\/data-pump"/, 'not on a developer\'s Launchpad');
  });
  const getJobRow = async (id: number) => (await owner.one('select id from meta.dump_job where id = $1', [id])) ?? null;

  test('CSRF: a forged token starts, uploads and deletes nothing', async () => {
    const a = await signIn('admin');
    const n = await jobs();
    for (const url of ['/builder/sql/data-pump/export', `/builder/sql/data-pump/job/${job}/import`, `/builder/sql/data-pump/job/${job}/delete`, `/builder/sql/data-pump/job/${job}/cancel`])
      assert.equal((await a.post(url, { __csrf: 'forged', schema: 'hr', mode: 'all', target: 'sec103_x' })).statusCode, 403, url);
    a.lastCsrf = 'forged';
    assert.equal((await a.upload('/builder/sql/data-pump/upload', {}, { file: { name: 'sec103-forged.dump', type: 'application/octet-stream', data: Buffer.from('PGDMP') } })).statusCode, 403);
    assert.equal(await jobs(), n);
    assert.ok(await getJobRow(job));
  });

  test('uploads over PGKILN_DUMP_MAX_MB are refused and their file removed', async () => {
    process.env.PGKILN_DUMP_MAX_MB = '1';
    const a = await signIn('admin');
    const n = await jobs();
    const res = await a.upload('/builder/sql/data-pump/upload', {}, { file: { name: 'sec103-big.dump', type: 'application/octet-stream', data: Buffer.alloc(1536 * 1024, 65) } });
    assert.equal(res.statusCode, 303);
    assert.match((await a.get(res.headers.location as string)).body, /larger than 1 MB/);
    assert.equal(await jobs(), n);
    const { DUMP_DIR } = await import('../src/datapump.ts');
    const { readdir } = await import('node:fs/promises');
    for (const f of await readdir(DUMP_DIR)) if (f.startsWith('upload-') && f !== file) {
      const { stat } = await import('node:fs/promises');
      assert.ok((await stat(`${DUMP_DIR}/${f}`)).size < 1024 * 1024, `no cut-off upload left: ${f}`);
    }
    delete process.env.PGKILN_DUMP_MAX_MB;
  });

  test('schema names: quotes and pgkiln\'s own schemas are refused; names are escaped in pages and pg_dump arguments', async () => {
    const a = await signIn('admin');
    const n = await jobs();
    for (const schema of ['hr"; drop schema hr cascade; --', 'meta', 'pg_catalog', '--help', '*'])
      assert.equal((await a.submit('/builder/sql/data-pump/export', { schema, mode: 'all', format: 'custom', content: 'all' })).statusCode, 422, schema);
    const tbl = await a.submit('/builder/sql/data-pump/export', { schema: 'hr', mode: 'only', t: ['emp", "meta.account'], format: 'custom', content: 'all' });
    assert.equal(tbl.statusCode, 422);
    assert.match(tbl.body, /Not in hr: emp&quot;, &quot;meta.account|Export and import need pg_dump/);
    assert.equal(await jobs(), n);
    for (const target of ['x"; drop schema hr cascade; --', 'sec103 x', '1abc', '']) {
      const res = await a.submit(`/builder/sql/data-pump/job/${job}/import`, { target, content: 'all' });
      assert.equal(res.statusCode, 422, target);
      assert.doesNotMatch(res.body, /drop schema hr cascade; --"/);
    }
    for (const target of ['meta', 'pg_toast', 'pgkiln_x', 'information_schema'])
      assert.equal((await a.submit(`/builder/sql/data-pump/job/${job}/import`, { target, content: 'all' })).statusCode, 422, target);
    assert.equal((await owner.one(`select status from meta.dump_job where id = $1`, [job])).status, 'uploaded');
    assert.equal((await owner.one(`select count(*)::int as n from pg_namespace where nspname = 'hr'`)).n, 1);
  });

  test('jobs by id only; an upload is not downloadable; file names can\'t leave the dump directory', async () => {
    const a = await signIn('admin');
    for (const url of ['/builder/sql/data-pump/job/..%2F..%2Fetc%2Fpasswd', '/builder/sql/data-pump/job/1e9', '/builder/sql/data-pump/job/999999999/download'])
      assert.equal((await a.get(url)).statusCode, 404, url);
    assert.equal((await a.get(`/builder/sql/data-pump/job/${job}/download`)).statusCode, 404, 'uploads are not served back');
    await assert.rejects(owner.query(`update meta.dump_job set file_name = '../../etc/passwd' where id = $1`, [job]), /check constraint/);
    const { filePath } = await import('../src/datapump.ts');
    assert.throws(() => filePath('../x'));
    assert.throws(() => filePath('.hidden'));
  });

  test('an import refuses statements outside the dump\'s schema before they reach the server', async () => {
    const { checkStatement } = await import('../src/dumpscript.ts');
    for (const sql of [`CREATE TABLE meta.sec103 (id int);`, `ALTER TABLE meta.developer ALTER COLUMN is_admin SET DEFAULT true;`, `COPY meta.developer (username) FROM stdin;`,
      `COPY hr.emp FROM PROGRAM 'id';`, `SET ROLE postgres;`, `GRANT pg_write_server_files TO hr_app;`, `DO $$ begin end $$;`, `ALTER TABLE hr.emp OWNER TO postgres;`])
      assert.notEqual(checkStatement(sql, 'hr'), null, sql);
  });
});

describe('sprint 104 rest handlers', () => {
  const S = 'sec104';
  const DEV = 'sec104dev';
  const MOD = 'sec104';
  const tok: Record<string, string> = {};
  let modId: number;
  let otherWs: number;
  const call = (method: string, path: string, who?: string, payload?: unknown, raw?: string) =>
    app.inject({
      method: method as 'GET',
      url: `/a/hr/rest/${MOD}/${path}`,
      headers: { ...(who ? { authorization: `Bearer ${tok[who] ?? who}` } : {}), ...(payload !== undefined || raw !== undefined ? { 'content-type': 'application/json' } : {}) },
      payload: raw ?? (payload !== undefined ? JSON.stringify(payload) : undefined),
    });
  const signIn = async (username: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username });
    if (username === 'admin') await b.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
    await b.get('/builder/sql/rest/modules');
    return b;
  };
  const notes = async () => (await owner.one(`select count(*)::int as n from ${S}.note`)).n;
  const handlers = [
    { method: 'GET', path: 'who', type: 'item', source: 'select current_user::text as u, session_user::text as s, meta.app_user() as app_user' },
    { method: 'POST', path: 'note', type: 'plpgsql', params: [{ name: 'body_text', in: 'body', required: true }],
      source: "declare v int; begin insert into sec104.note (body) values (:BODY_TEXT) returning id into v; perform meta.rest_reply(jsonb_build_object('id', v, 'app_user', :APP_USER, 'timeout', current_setting('statement_timeout'), 'role', current_user::text, 'raw', :BODY::jsonb), 201); end" },
    { method: 'GET', path: 'note/:id', type: 'item', source: 'select id, owner, body from sec104.note where id = :ID::int' },
    { method: 'GET', path: 'file/:id', type: 'media', auth: 'public', source: "select 'text/html' as content_type, '<script>alert(104)</script>' as content, :ID as filename" },
    { method: 'GET', path: 'boss', type: 'item', roles: ['manager'], source: 'select 1 as ok' },
  ];
  before(async () => {
    const { issueApiToken } = await import('../src/api.ts');
    const { SignJWT } = await import('jose');
    for (const u of ['king', 'allen', 'scott']) tok[u] = (await issueApiToken(appId, u, 1)).token;
    tok.forged = await new SignJWT({ app: 'hr', app_user: 'king' }).setProtectedHeader({ alg: 'HS256' }).setExpirationTime('1h').sign(new TextEncoder().encode('another-secret-that-is-long-enough-0123456789'));
    tok.otherApp = await new SignJWT({ app: 'other', app_user: 'king' }).setProtectedHeader({ alg: 'HS256' }).setExpirationTime('1h').sign(new TextEncoder().encode(process.env.API_JWT_SECRET!));
    tok.expired = await new SignJWT({ app: 'hr', app_user: 'king' }).setProtectedHeader({ alg: 'HS256' }).setIssuedAt(1000).setExpirationTime(2000).sign(new TextEncoder().encode(process.env.API_JWT_SECRET!));
    await owner.query(`drop schema if exists ${S} cascade`);
    await owner.query(`
      create schema ${S};
      grant usage on schema ${S} to hr_app;
      create table ${S}.note (id int generated by default as identity primary key, owner text not null default meta.app_user(), body text);
      grant select, insert on ${S}.note to hr_app;
      alter table ${S}.note enable row level security;
      create policy mine on ${S}.note using (owner = meta.app_user());
      insert into ${S}.note (owner, body) values ('king', 'king''s');
    `);
    await owner.query(`delete from meta.rest_module where app_id = $1 and name = $2`, [appId, MOD]);
    modId = (await owner.one(`insert into meta.rest_module (app_id, name, title, handlers, templates) values ($1, $2, '<img src=x onerror=alert(104)>', $3, $4) returning id`,
      [appId, MOD, JSON.stringify(handlers), JSON.stringify([{ uri: 'who', description: '<script>alert(1041)</script>' }])])).id;
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    otherWs = (await owner.one(`insert into meta.workspace (name) values ('Sec104 Other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [otherWs, DEV]);
  });
  after(async () => {
    await owner.query(`update meta.app set db_role = 'hr_app' where id = $1`, [appId]);
    await owner.query(`delete from meta.rest_module where app_id = $1 and name = $2`, [appId, MOD]);
    await owner.query(`delete from meta.workspace where name = 'Sec104 Other'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`drop schema if exists ${S} cascade`);
    await owner.query(`do $$ begin if exists (select 1 from pg_roles where rolname = 'sec104_bypass') then
      execute 'revoke sec104_bypass from pgkiln_runtime'; execute 'drop role sec104_bypass'; end if; end $$`);
  });

  test('every handler needs a valid token of this application (401), a role it names (403)', async () => {
    for (const [m, p, body] of [['GET', 'who'], ['POST', 'note', { body_text: 'x' }], ['GET', 'note/1'], ['GET', 'boss']] as [string, string, unknown?][])
      for (const who of [undefined, 'forged', 'otherApp', 'expired', 'garbage'])
        assert.equal((await call(m, p, who, body)).statusCode, 401, `${m} ${p} as ${who}`);
    assert.equal((await call('GET', 'boss', 'allen')).statusCode, 403);
    assert.equal((await call('GET', 'boss', 'king')).statusCode, 200);
    // the module's privilege covers every handler, the public ones too
    await owner.query(`update meta.rest_module set roles = '{manager}' where id = $1`, [modId]);
    assert.equal((await call('GET', 'who', 'allen')).statusCode, 403);
    assert.equal((await call('POST', 'note', 'allen', { body_text: 'x' })).statusCode, 403);
    assert.equal((await call('GET', 'file/1')).statusCode, 403);
    assert.equal((await call('GET', 'who', 'king')).statusCode, 200);
    await owner.query(`update meta.rest_module set roles = '{}' where id = $1`, [modId]);
    await owner.query(`update meta.account set active = false where username = 'scott'`);
    assert.equal((await call('POST', 'note', 'scott', { body_text: 'x' })).statusCode, 403, 'inactive account');
    await owner.query(`update meta.account set active = true where username = 'scott'`);
    assert.equal(await notes(), 1, 'nothing written');
    // a browser session (cookie) is not a token
    const king = await as('king');
    assert.equal((await app.inject({ url: `/a/hr/rest/${MOD}/who`, headers: { cookie: [...king.cookies].map(([k, v]) => `${k}=${v}`).join('; ') } })).statusCode, 401);
  });

  test('handlers run as the application role, never the owner; RLS holds; a role that bypasses RLS is refused', async () => {
    const who = (await call('GET', 'who', 'allen')).json();
    assert.deepEqual([who.u, who.app_user], ['hr_app', 'allen']);
    assert.notEqual(who.s, 'pgkiln');
    const kings = (await owner.one(`select id from ${S}.note where owner = 'king'`)).id;
    assert.equal((await call('GET', `note/${kings}`, 'allen')).statusCode, 404, 'row level security');
    assert.equal((await call('GET', `note/${kings}`, 'king')).statusCode, 200);
    const posted = await call('POST', 'note', 'allen', { body_text: 'mine' });
    assert.equal(posted.statusCode, 201, posted.body);
    assert.equal(posted.json().role, 'hr_app', 'the PL/pgSQL block runs as the role too');
    assert.equal((await owner.one(`select owner from ${S}.note where id = $1`, [posted.json().id])).owner, 'allen');
    // a role that bypasses row level security (or pgkiln's owner) is refused before the SQL runs
    await owner.query(`do $$ begin if not exists (select 1 from pg_roles where rolname = 'sec104_bypass') then create role sec104_bypass nologin bypassrls; end if; end $$`);
    await owner.query(`grant usage on schema ${S} to sec104_bypass; grant select, insert on ${S}.note to sec104_bypass; grant sec104_bypass to pgkiln_runtime`);
    // (sprint 186) meta.app refuses such a role: one that was given BYPASSRLS after it was saved
    await owner.tx(async (c) => {
      await c.query('alter table meta.app disable trigger app_role_check');
      await c.query(`update meta.app set db_role = 'sec104_bypass' where id = $1`, [appId]);
      await c.query('set constraints all immediate'); // the deferred workspace check first: ALTER TABLE refuses pending trigger events
      await c.query('alter table meta.app enable trigger app_role_check');
    });
    try {
      const n = await notes();
      // (sprint 186) refused before the handler as an application that can't run (503)
      assert.equal((await call('GET', 'who', 'king')).statusCode, 503);
      assert.equal((await call('POST', 'note', 'king', { body_text: 'bypass' })).statusCode, 503);
      assert.equal(await notes(), n);
      // the Advisor says so before the endpoints fail, and is quiet again for the application's own role
      const { advise } = await import('../src/builder/advisor.ts');
      const restFinding = async () => (await advise(appId)).findings.filter((f) => f.field === 'REST modules');
      const found = await restFinding();
      assert.equal(found.length, 1);
      assert.equal(found[0].severity, 'error');
      assert.match(found[0].message, /sec104_bypass.*403/);
      await owner.query(`update meta.app set db_role = 'hr_app' where id = $1`, [appId]);
      assert.equal((await restFinding()).length, 0);
    } finally {
      await owner.query(`update meta.app set db_role = 'hr_app' where id = $1`, [appId]);
    }
  });

  test('parameters are bound: bodies, paths and queries cannot inject SQL or set server binds and settings', async () => {
    const before = await notes();
    const evil = `x'); drop table ${S}.note; --`;
    const res = await call('POST', 'note', 'allen', { body_text: evil, app_user: 'king', APP_USER: 'king', statement_timeout: '0', 'role; drop table x': 1, "a'b": 2 });
    assert.equal(res.statusCode, 201, res.body);
    const out = res.json();
    assert.equal(out.app_user, 'allen', 'APP_USER is the server\'s');
    assert.equal(out.timeout, '30s', 'a body field named like a setting does not set it');
    assert.equal((await owner.one(`select body from ${S}.note where id = $1`, [out.id])).body, evil);
    assert.equal(out.raw.body_text, evil, ':BODY is the whole JSON body, as data');
    assert.equal(await notes(), before + 1);
    // a NUL byte is refused; a required parameter missing is a 400; a path parameter is a value
    assert.equal((await call('POST', 'note', 'allen', { body_text: 'a\u0000b' })).statusCode, 400);
    assert.equal((await call('POST', 'note', 'allen', {})).statusCode, 400);
    assert.equal((await call('GET', `note/${encodeURIComponent("1' or '1'='1")}`, 'allen')).statusCode, 400);
    assert.equal((await call('GET', `note/1?ID=${encodeURIComponent('1 or true')}`, 'king')).json().id, 1, 'the path parameter wins over the query');
    assert.equal(await notes(), before + 1);
    assert.ok((await owner.one(`select to_regclass('${S}.note') as t`)).t);
  });

  test('media handlers are served sandboxed: HTML from a table runs no script in the application\'s origin', async () => {
    const res = await call('GET', `file/${encodeURIComponent('x"\r\nSet-Cookie: a=1')}`);
    assert.equal(res.statusCode, 200);
    assert.match(String(res.headers['content-security-policy']), /sandbox/);
    assert.match(String(res.headers['content-security-policy']), /default-src 'none'/);
    assert.equal(res.headers['x-content-type-options'], 'nosniff');
    assert.equal(res.headers['set-cookie'], undefined);
    assert.equal(res.headers['content-disposition'], 'inline; filename="x___Set-Cookie: a=1"');
  });

  test('the builder: CSRF, developers only, workspace scoping, names escaped, the DO tag refused', async () => {
    const a = await signIn('admin');
    const forged = { __csrf: 'forged' };
    for (const [url, form] of [
      ['/builder/sql/rest/modules', { app_id: String(appId), name: 'sec104x', title: 'x' }],
      [`/builder/sql/rest/modules/${modId}`, { name: MOD, title: 'x', enabled: '0' }],
      [`/builder/sql/rest/modules/${modId}/delete`, {}],
      [`/builder/sql/rest/modules/${modId}/template`, { uri: 'forged' }],
      [`/builder/sql/rest/modules/${modId}/template/delete`, { uri: 'who' }],
      [`/builder/sql/rest/modules/${modId}/handler`, { t: 'who', orig_m: 'GET', method: 'GET', type: 'item', source: 'select 2', auth: 'public' }],
      [`/builder/sql/rest/modules/${modId}/handler/delete`, { t: 'who', m: 'GET' }],
      [`/builder/sql/rest/modules/${modId}/try`, { t: 'note', m: 'POST', as: 'king', body: '{"body_text": "forged"}' }],
    ] as [string, Record<string, string>][])
      assert.equal((await a.post(url, { ...forged, ...form })).statusCode, 403, url);
    const row = await owner.one('select title, enabled, handlers from meta.rest_module where id = $1', [modId]);
    assert.equal(row.enabled, true);
    assert.equal(row.handlers.length, handlers.length);
    assert.equal(await owner.one(`select 1 from meta.rest_module where name = 'sec104x'`), undefined);
    // names and descriptions are escaped
    for (const url of ['/builder/sql/rest/modules', `/builder/sql/rest/modules/${modId}`, `/builder/sql/rest/modules/${modId}/template?t=who`, `/builder/sql/rest/modules/${modId}/handler?t=who&m=GET`]) {
      const body = (await a.get(url)).body;
      assert.doesNotMatch(body, /<img src=x|<script>alert\(1041/, url);
    }
    // a PL/pgSQL block can't close the DO statement around it
    const esc = await a.post(`/builder/sql/rest/modules/${modId}/handler`, { __csrf: a.lastCsrf, t: 'note', orig_m: 'POST', method: 'POST', type: 'plpgsql', auth: 'token', source: 'begin end $pgkiln_rest$; drop table sec104.note; --' });
    assert.equal(esc.statusCode, 422);
    assert.match(esc.body, /may not contain/);
    // public must be chosen explicitly
    const anon = await a.post(`/builder/sql/rest/modules/${modId}/handler`, { __csrf: a.lastCsrf, t: 'who', orig_m: 'GET', method: 'GET', type: 'item', auth: 'anonymous', source: 'select 1' });
    assert.equal(anon.statusCode, 422);
    // Try it runs only as an account of the application
    const tried = await a.post(`/builder/sql/rest/modules/${modId}/try`, { __csrf: a.lastCsrf, t: 'who', m: 'GET', as: 'admin-not-an-account' });
    assert.match(tried.body, /Choose an account/);
    assert.equal((await owner.one('select handlers from meta.rest_module where id = $1', [modId])).handlers.length, handlers.length);
    // another workspace's developer sees none of it
    const d = await signIn(DEV);
    assert.doesNotMatch((await d.get('/builder/sql/rest/modules')).body, new RegExp(`/builder/sql/rest/modules/${modId}"`));
    for (const url of [`/builder/sql/rest/modules/${modId}`, `/builder/sql/rest/modules/${modId}/template?t=who`, `/builder/sql/rest/modules/${modId}/handler?t=who&m=GET`])
      assert.equal((await d.get(url)).statusCode, 404, url);
    for (const [url, form] of [
      [`/builder/sql/rest/modules/${modId}`, { name: MOD, title: 'x', enabled: '0' }],
      [`/builder/sql/rest/modules/${modId}/delete`, {}],
      [`/builder/sql/rest/modules/${modId}/handler`, { t: 'who', orig_m: 'GET', method: 'GET', type: 'item', source: 'select 2', auth: 'public' }],
      [`/builder/sql/rest/modules/${modId}/try`, { t: 'note', m: 'POST', as: 'king', body: '{"body_text": "x"}' }],
    ] as [string, Record<string, string>][])
      assert.equal((await d.post(url, { __csrf: d.lastCsrf, ...form })).statusCode, 404, url);
    assert.match((await d.post('/builder/sql/rest/modules', { __csrf: d.lastCsrf, app_id: String(appId), name: 'sec104y', title: 'x' })).body, /Choose an application of this workspace/);
    assert.equal(await owner.one(`select 1 from meta.rest_module where name = 'sec104y'`), undefined);
    // application users are not developers
    const king = await as('king');
    assert.equal((await king.get('/builder/sql/rest/modules')).headers.location, '/builder/login');
    assert.equal((await king.post(`/builder/sql/rest/modules/${modId}/delete`, { __csrf: king.lastCsrf })).headers.location, '/builder/login');
    assert.ok(await owner.one('select 1 from meta.rest_module where id = $1', [modId]));
  });
});

describe('sprint 106 change log', () => {
  const S = 'sec106';
  const DEV = 'sec106dev';
  let otherWs: number;
  let id: number;
  const signIn = async (username: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username });
    if (username === 'admin') await b.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
    await b.get('/builder/sql/changes');
    return b;
  };
  const count = async () => (await owner.one(`select count(*)::int as n from meta.change_set where schema_name like 'sec106%'`)).n;
  before(async () => {
    await owner.query(`drop schema if exists ${S} cascade; drop schema if exists ${S}_b cascade`);
    await owner.query(`delete from meta.change_set where schema_name like 'sec106%' or schema_name like 'we%'`);
    await owner.query(`create schema ${S}; create table ${S}.t (id int primary key)`);
    id = (await owner.one(`insert into meta.change_set (workspace_id, schema_name, name, author, source, sql) values (1, $1, 'xss', '<img src=x onerror=alert(106)>', 'worksheet', $2) returning id`,
      [S, `comment on table ${S}.t is '<script>alert(106)</script>';`])).id;
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    otherWs = (await owner.one(`insert into meta.workspace (name) values ('Sec106 Other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [otherWs, DEV]);
  });
  after(async () => {
    await owner.query(`delete from meta.change_set where schema_name like 'sec106%' or schema_name like 'we%'`);
    await owner.query(`delete from meta.change_set_counter where schema_name like 'sec106%' or schema_name like 'we%'`);
    await owner.query(`delete from meta.workspace where name = 'Sec106 Other'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`drop schema if exists ${S} cascade; drop schema if exists ${S}_b cascade`);
    await owner.query(`do $$ begin if exists (select 1 from pg_roles where rolname = 'sec106_role') then drop role sec106_role; end if; end $$`);
  });

  test('CSRF: a forged token downloads, renames, deletes and applies nothing', async () => {
    const a = await signIn('admin');
    await owner.query(`create schema ${S}_b`);
    for (const [url, form] of [
      ['/builder/sql/changes/download', { schema: S, format: 'flyway', which: 'all' }],
      [`/builder/sql/changes/${id}/download`, {}],
      [`/builder/sql/changes/${id}`, { name: 'renamed' }],
      [`/builder/sql/changes/${id}/delete`, {}],
      ['/builder/sql/compare/apply', { source: S, target: `${S}_b` }],
    ] as [string, Record<string, string>][])
      assert.equal((await a.post(url, { __csrf: 'forged', ...form })).statusCode, 403, url);
    const row = await owner.one('select name, exported_at from meta.change_set where id = $1', [id]);
    assert.deepEqual(row, { name: 'xss', exported_at: null });
    assert.equal(await owner.one(`select to_regclass('${S}_b.t') as t`).then((r) => r.t), null, 'the target is unchanged');
  });

  test('change sets are escaped in the page; names are checked; file names are safe', async () => {
    const a = await signIn('admin');
    const page = (await a.get(`/builder/sql/changes?schema=${S}`)).body;
    assert.doesNotMatch(page, /<script>alert\(106\)|<img src=x/);
    assert.match(page, /&lt;script&gt;alert\(106\)/);
    for (const name of ['x"; drop table t; --', '../../etc/passwd', 'A B', ''])
      await a.post(`/builder/sql/changes/${id}`, { __csrf: a.lastCsrf, name });
    assert.equal((await owner.one('select name from meta.change_set where id = $1', [id])).name, 'xss');
    await assert.rejects(owner.query(`update meta.change_set set name = 'a/../b' where id = $1`, [id]), /check constraint/);
    const weird = 'we"ird\r\nx';
    await owner.query(`insert into meta.change_set (workspace_id, schema_name, name, author, source, sql) values (1, $1, 'w', 'admin', 'worksheet', 'create table x (a int);')`, [weird]);
    const res = await a.post('/builder/sql/changes/download', { __csrf: a.lastCsrf, schema: weird, format: 'liquibase', which: 'all' });
    assert.equal(res.statusCode, 200);
    assert.equal(res.headers['content-disposition'], 'attachment; filename="we_ird__x.changelog.sql"');
  });

  test('only schema DDL that succeeded is recorded: no role passwords, no failed statements', async () => {
    const a = await signIn('admin');
    await a.get('/builder/sql/worksheet');
    const n = await count();
    await a.post('/builder/sql/worksheet', { __csrf: a.lastCsrf, mode: 'script', continue: '1',
      sql: `create role sec106_role login password 'sec106-secret';\nalter role sec106_role password 'sec106-other';\ncreate table ${S}.bad (id nope);\ninsert into ${S}.t values (1);` });
    assert.equal(await count(), n);
    assert.equal((await owner.one(`select count(*)::int as n from meta.change_set where sql like '%sec106-secret%' or sql like '%sec106-other%'`)).n, 0);
  });

  test('another workspace\'s developer sees and changes none of it; schemas are checked; users are not developers', async () => {
    const d = await signIn(DEV);
    assert.doesNotMatch((await d.get(`/builder/sql/changes?schema=${S}`)).body, /alert\(106\)|sec106\.t/);
    for (const url of [`/builder/sql/changes/${id}/download`, `/builder/sql/changes/${id}`, `/builder/sql/changes/${id}/delete`])
      assert.equal((await d.post(url, { __csrf: d.lastCsrf, name: 'mine' })).statusCode, 404, url);
    assert.equal((await d.post('/builder/sql/changes/download', { __csrf: d.lastCsrf, schema: S, format: 'sql', which: 'all' })).statusCode, 404);
    assert.ok(await owner.one('select 1 from meta.change_set where id = $1 and name = $2', [id, 'xss']));
    const a = await signIn('admin');
    for (const [source, target] of [['meta', S], [S, 'meta'], [S, S], [S, 'pg_catalog'], [`${S}"; drop schema ${S} cascade; --`, S]])
      assert.equal((await a.post('/builder/sql/compare/apply', { __csrf: a.lastCsrf, source, target })).statusCode, 404, `${source} → ${target}`);
    assert.ok(await owner.one(`select to_regclass('${S}.t') as t`).then((r) => r.t));
    const king = await as('king');
    assert.equal((await king.get('/builder/sql/changes')).headers.location, '/builder/login');
    assert.equal((await king.post(`/builder/sql/changes/${id}/delete`, { __csrf: king.lastCsrf })).headers.location, '/builder/login');
  });
});

describe('sprint 107 transaction mode', () => {
  const DEV = 'sec107dev';
  const S = 'sec107';
  let ws: number;
  const signIn = async (username: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username });
    if (username === 'admin') await b.ownerConnection(); // (sprint 185) the owner's tables: the Owner connection
    await b.get('/builder/sql/worksheet');
    return b;
  };
  const run = (b: Browser, tab: string, sql: string, extra: Record<string, string> = {}) =>
    b.post('/builder/sql/worksheet', { __csrf: b.lastCsrf, sql, mode: 'statement', ws_tab: tab, txn: 'on', ...extra });
  const end = (b: Browser, tab: string) => b.post('/builder/sql/worksheet/txn', { __csrf: b.lastCsrf, tab, action: 'rollback' });
  const status = async (b: Browser, tab: string) => JSON.parse((await b.get(`/builder/sql/worksheet/txn?tab=${tab}`)).body);
  const v = async () => Number((await owner.one(`select v from ${S}.t where id = 1`)).v);
  before(async () => {
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    ws = (await owner.one(`insert into meta.workspace (name) values ('Sec107 Other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [ws, DEV]);
    await owner.query(`drop schema if exists ${S} cascade; create schema ${S}; create table ${S}.t (id int primary key, v int); insert into ${S}.t values (1, 0)`);
    await owner.query(`grant usage on schema ${S} to public; grant select on ${S}.t to public`);
  });
  after(async () => {
    const { endAllTxns } = await import('../src/worksheet-txn.ts');
    await endAllTxns();
    delete process.env.WORKSHEET_TXN_MAX_PER_DEVELOPER;
    delete process.env.WORKSHEET_TXN_MAX;
    await owner.query(`delete from meta.workspace where name = 'Sec107 Other'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`drop schema if exists ${S} cascade`);
    await owner.query('drop role if exists sec107_login');
  });

  test('another developer, or another session of the same one, never reaches a transaction: same tab key, status, commit', async () => {
    const a = await signIn('admin');
    await run(a, 'sec107a', `update ${S}.t set v = 107 where id = 1`);
    assert.equal((await status(a, 'sec107a')).state, 'open');
    for (const other of [await signIn(DEV), await signIn('admin')]) {
      assert.equal((await status(other, 'sec107a')).state, 'none');
      const c = JSON.parse((await other.post('/builder/sql/worksheet/txn', { __csrf: other.lastCsrf, tab: 'sec107a', action: 'commit' })).body);
      assert.equal(c.ok, false);
      assert.match((await other.post('/builder/sql/worksheet', { __csrf: other.lastCsrf, sql: '', mode: 'commit', ws_tab: 'sec107a', txn: 'on' })).body, /This worksheet has no open transaction/);
      // its own run with that tab key is a transaction of its own, which doesn't see the change
      const page = (await run(other, 'sec107a', `select v from ${S}.t where id = 1`)).body;
      assert.match(page, /<td class="num">0<\/td>/);
      await end(other, 'sec107a');
    }
    assert.equal((await status(a, 'sec107a')).state, 'open', 'still open, still the first developer\'s');
    assert.equal(await v(), 0);
    await end(a, 'sec107a');
    assert.equal(await v(), 0);
  });

  test('limits per developer and per server', async () => {
    const { openTxnCount } = await import('../src/worksheet-txn.ts');
    process.env.WORKSHEET_TXN_MAX_PER_DEVELOPER = '2';
    try {
      const a = await signIn('admin');
      for (const tab of ['seclim1', 'seclim2']) assert.match((await run(a, tab, 'select 1')).body, /data-state="open"/);
      const third = (await run(a, 'seclim3', `update ${S}.t set v = 1 where id = 1`)).body;
      assert.match(third, /You have 2 worksheets with an open transaction, the most allowed/);
      assert.equal(await v(), 0, 'the refused run ran nothing');
      // a second session of the same developer counts too
      assert.match((await run(await signIn('admin'), 'seclim4', 'select 1')).body, /the most allowed/);
      assert.equal(openTxnCount('admin'), 2);
      process.env.WORKSHEET_TXN_MAX = '2';
      assert.match((await run(await signIn(DEV), 'seclim5', 'select 1')).body, /The server has as many open worksheet transactions as it allows/);
      for (const tab of ['seclim1', 'seclim2']) await end(a, tab);
      assert.equal(openTxnCount(), 0);
    } finally {
      delete process.env.WORKSHEET_TXN_MAX_PER_DEVELOPER;
      delete process.env.WORKSHEET_TXN_MAX;
    }
  });

  test('the idle timeout rolls back and closes the connection; the database has its own backstop', async () => {
    const { sweepTxns, txnIdleSeconds } = await import('../src/worksheet-txn.ts');
    const a = await signIn('admin');
    const page = (await run(a, 'secidle', 'show idle_in_transaction_session_timeout')).body;
    assert.match(page, new RegExp(`<td>${(txnIdleSeconds() + 60) / 60}min</td>`));
    await run(a, 'secidle', `update ${S}.t set v = 5 where id = 1`);
    const pid = Number(/<td class="num">(\d+)<\/td>/.exec((await run(a, 'secidle', 'select pg_backend_pid()')).body)![1]);
    assert.equal((await owner.one(`select state from pg_stat_activity where pid = $1`, [pid])).state, 'idle in transaction');
    await sweepTxns(Date.now() + txnIdleSeconds() * 1000 + 5000);
    assert.equal(await v(), 0);
    for (let i = 0; i < 50 && (await owner.one('select 1 as x from pg_stat_activity where pid = $1', [pid])); i++) await new Promise((r) => setTimeout(r, 20));
    assert.equal(await owner.one('select 1 as x from pg_stat_activity where pid = $1', [pid]), undefined, 'the connection is gone, never back in a pool');
    assert.equal((await status(a, 'secidle')).state, 'none');
  });

  test('CSRF on Commit / Rollback (page and JSON); developers only', async () => {
    const a = await signIn('admin');
    await run(a, 'seccsrf', `update ${S}.t set v = 9 where id = 1`);
    assert.equal((await a.post('/builder/sql/worksheet/txn', { tab: 'seccsrf', action: 'commit' })).statusCode, 403);
    assert.equal((await a.post('/builder/sql/worksheet/txn', { __csrf: 'forged', tab: 'seccsrf', action: 'commit' })).statusCode, 403);
    assert.equal((await a.post('/builder/sql/worksheet', { __csrf: 'forged', sql: '', mode: 'commit', ws_tab: 'seccsrf', txn: 'on' })).statusCode, 403);
    assert.equal((await a.post('/builder/sql/worksheet', { __csrf: 'forged', sql: `update ${S}.t set v = 10 where id = 1`, mode: 'statement', ws_tab: 'seccsrf', txn: 'on' })).statusCode, 403);
    assert.equal((await status(a, 'seccsrf')).state, 'open');
    assert.equal(await v(), 0, 'nothing committed');
    const anon = new Browser();
    assert.equal((await anon.get('/builder/sql/worksheet/txn?tab=seccsrf')).headers.location, '/builder/login');
    const king = await as('king');
    assert.equal((await king.post('/builder/sql/worksheet/txn', { __csrf: king.lastCsrf, tab: 'seccsrf', action: 'commit' })).headers.location, '/builder/login');
    assert.equal((await a.get('/builder/sql/worksheet/txn?tab=../x')).statusCode, 400);
    await end(a, 'seccsrf');
    assert.equal(await v(), 0);
  });

  test('role escalation: the pinned connection is the pool\'s login, SET ROLE stays within it, Run as is checked and never leaks', async () => {
    const { beginTxn, endTxn } = await import('../src/worksheet-txn.ts');
    const { makePool, ownerUrl } = await import('../src/db.ts');
    // a non-superuser login, like an isolated workspace's developer login
    await owner.query(`drop role if exists sec107_login; create role sec107_login login password 'sec107-pw' nosuperuser nocreaterole`);
    const url = new URL(ownerUrl);
    url.username = 'sec107_login';
    url.password = 'sec107-pw';
    const pool = makePool(url.toString(), 'sec107');
    try {
      const t = await beginTxn({ sessionId: 'sec107-session', username: 'sec107', workspaceId: -1, tab: 'secrole', db: pool, runsAs: 'test', searchSchema: null });
      assert.ok(typeof t !== 'string', String(t));
      if (typeof t === 'string') return;
      assert.deepEqual((await t.client.query('select session_user::text as s, current_user::text as c')).rows[0], { s: 'sec107_login', c: 'sec107_login' });
      await assert.rejects(t.client.query('set role pgkiln'), /permission denied/);
      await endTxn(t, 'rollback');
    } finally {
      await pool.end();
    }
    // Run as: another workspace's application is refused in transaction mode too, and nothing opens
    const { openTxnCount } = await import('../src/worksheet-txn.ts');
    const hr = await owner.one(`select id, db_role from meta.app where alias = 'hr'`);
    const d = await signIn(DEV);
    assert.equal((await run(d, 'secrunas', 'select 1', { as_app: String(hr.id) })).statusCode, 404);
    assert.equal(openTxnCount(DEV), 0);
    // the application's role lasts as long as the transaction's own connection
    const a = await signIn('admin');
    assert.match((await run(a, 'secrunas', 'select current_user::text as u', { as_app: String(hr.id) })).body, new RegExp(`<td>${hr.db_role}</td>`));
    assert.match((await run(a, 'secrunas', `select current_user::text as u`)).body, /runs as the role .* Commit or Rollback it before changing Run as/);
    await end(a, 'secrunas');
    assert.doesNotMatch((await run(a, 'secrunas', 'select current_user::text as u')).body, new RegExp(`<td>${hr.db_role}</td>`));
    await end(a, 'secrunas');
    assert.equal((await owner.one('select current_user::text as u')).u, (await owner.one('select session_user::text as u')).u, 'the builder\'s pool is untouched');
  });
});

describe('sprint 109 WS-1', () => {
  // the Workspace home (/builder/home): the workspace message (its administrators only, plain text), the reporting
  // timeframe, the release check (administrators only; never asks the network in tests), the /builder preference
  const DEV = 'sec109dev';
  let ws: number;
  let other: number;
  let otherApp: number;
  const signIn = async (username: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    const res = await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username });
    assert.equal(res.statusCode, 303);
    assert.equal(res.headers.location, '/builder/home');
    await b.get('/builder/home');
    return b;
  };
  const message = async (id: number) => (await owner.one('select message from meta.workspace where id = $1', [id])).message;
  before(async () => {
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    await owner.query(`delete from meta.workspace where name in ('Sec109 Own', 'Sec109 Other')`);
    ws = (await owner.one(`insert into meta.workspace (name, message) values ('Sec109 Own', 'own') returning id`)).id;
    other = (await owner.one(`insert into meta.workspace (name, message) values ('Sec109 Other', 'other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username, is_admin) values ($1, $2, false)', [ws, DEV]);
    await owner.query(`delete from meta.app where alias = 'sec109x'`);
    otherApp = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('sec109x', 'Sec109 secret app', 'none', 'hr_app') returning id`)).id;
    await owner.query('insert into meta.workspace_app (app_id, workspace_id) values ($1, $2)', [otherApp, other]);
    await owner.query(`insert into meta.activity_log (app_id, page_no, username, event) values ($1, 1, 'sec109_reader', 'page_view')`, [otherApp]);
  });
  after(async () => {
    await owner.query('delete from meta.activity_log where app_id = $1', [otherApp]);
    await owner.query('delete from meta.app where id = $1', [otherApp]);
    await owner.query(`delete from meta.workspace where id = any($1::int[])`, [[ws, other]]);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`delete from meta.setting where name = 'release_check'`);
  });

  test('a developer who is not the workspace\'s administrator cannot change its message (nor another workspace\'s); no edit form', async () => {
    const d = await signIn(DEV);
    const home = (await d.get('/builder/home')).body;
    assert.match(home, /<p class="wh-message-text">own<\/p>/);
    assert.doesNotMatch(home, /action="\/builder\/home\/message"/);
    for (const id of [ws, other, 1]) {
      const res = await d.post('/builder/home/message', { __csrf: d.lastCsrf, workspace: String(id), message: 'hacked' });
      assert.equal(res.statusCode, 403, `workspace ${id}`);
    }
    assert.equal(await message(ws), 'own');
    assert.equal(await message(other), 'other');
    assert.equal((await d.post('/builder/home/message', { __csrf: d.lastCsrf, workspace: '1 or 1=1', message: 'x' })).statusCode, 400);
    // another workspace's applications and users never show
    assert.doesNotMatch(home, /Sec109 secret app|sec109_reader/);
    // nor its preference for /builder
    assert.equal((await d.post(`/builder/workspaces/${ws}/preferences`, { __csrf: d.lastCsrf, builder_home: 'home' })).statusCode, 403);
    assert.equal((await owner.one('select builder_home from meta.workspace where id = $1', [ws])).builder_home, null);
  });

  test('CSRF: the message, the timeframe and the release check need the session\'s token', async () => {
    const a = await signIn('admin');
    await a.post('/builder/home/message', { __csrf: 'forged', workspace: String(ws), message: 'forged' });
    assert.equal(await message(ws), 'own');
    await a.post('/builder/home/message', { workspace: String(ws), message: 'forged' });
    assert.equal(await message(ws), 'own');
    const tf = (await owner.one(`select home_timeframe from meta.developer where username = 'admin'`)).home_timeframe;
    await a.post('/builder/home/timeframe', { __csrf: 'forged', timeframe: tf === 'hour' ? 'week' : 'hour' });
    assert.equal((await owner.one(`select home_timeframe from meta.developer where username = 'admin'`)).home_timeframe, tf);
    await owner.query(`delete from meta.setting where name = 'release_check'`);
    await a.post('/builder/home/release-check', { __csrf: 'forged', check: 'off' });
    assert.ok(!(await owner.one(`select 1 from meta.setting where name = 'release_check'`)));
  });

  test('the message is plain text: markup is escaped on the Workspace home and the App Builder', async () => {
    const a = await signIn('admin');
    await a.post('/builder/workspace', { __csrf: a.lastCsrf, workspace: String(ws) });
    await a.get('/builder/home');
    const xss = '<script>alert(1)</script><img src=x onerror=alert(2)> "quoted"';
    assert.equal((await a.post('/builder/home/message', { __csrf: a.lastCsrf, workspace: String(ws), message: xss })).statusCode, 303);
    for (const url of ['/builder/home', '/builder/apps']) {
      const body = (await a.get(url)).body;
      assert.ok(!body.includes('<script>alert(1)') && !body.includes('<img src=x'), url);
      assert.match(body, /&lt;script&gt;alert\(1\)&lt;\/script&gt;&lt;img src=x onerror=alert\(2\)&gt;/);
    }
    // the textarea can't be closed early either
    await a.post('/builder/home/message', { __csrf: a.lastCsrf, workspace: String(ws), message: '</textarea><b>x</b>' });
    assert.match((await a.get('/builder/home')).body, /&lt;\/textarea&gt;&lt;b&gt;x&lt;\/b&gt;<\/textarea>/);
    await owner.query(`update meta.workspace set message = 'own' where id = $1`, [ws]);
  });

  test('usernames in Top users are escaped; an unknown timeframe is refused', async () => {
    const a = await signIn('admin');
    await a.post('/builder/workspace', { __csrf: a.lastCsrf, workspace: String(other) });
    await owner.query(`insert into meta.activity_log (app_id, page_no, username, event) values ($1, 1, '<img src=x onerror=alert(3)>', 'page_view')`, [otherApp]);
    const body = (await a.get('/builder/home')).body;
    assert.ok(!body.includes('<img src=x onerror=alert(3)>'));
    assert.match(body, /&lt;img src=x onerror=alert\(3\)&gt;/);
    assert.equal((await a.post('/builder/home/timeframe', { __csrf: a.lastCsrf, timeframe: "day'; drop table meta.app; --" })).statusCode, 400);
    assert.equal((await a.post('/builder/home/timeframe', { __csrf: a.lastCsrf, timeframe: '__proto__' })).statusCode, 400);
  });

  test('only administrators turn the release check on; a non-administrator sees no form; no network in tests', async () => {
    await owner.query(`delete from meta.setting where name = 'release_check'`);
    const d = await signIn(DEV);
    assert.doesNotMatch((await d.get('/builder/home')).body, /action="\/builder\/home\/release-check"/);
    for (const check of ['on', 'now', 'default'])
      assert.equal((await d.post('/builder/home/release-check', { __csrf: d.lastCsrf, check })).statusCode, 403);
    assert.ok(!(await owner.one(`select 1 from meta.setting where name = 'release_check'`)));
    assert.equal((await d.get('/builder/instance')).statusCode, 403);
    const a = await signIn('admin');
    assert.equal((await a.post('/builder/home/release-check', { __csrf: a.lastCsrf, check: 'bogus' })).statusCode, 400);
    // turned on without PGKILN_RELEASE_URL under the test runner: nothing is asked, nothing is announced
    const { cachedRelease, resetReleaseCache } = await import('../src/release-check.ts');
    resetReleaseCache();
    delete process.env.PGKILN_RELEASE_URL;
    await a.post('/builder/home/release-check', { __csrf: a.lastCsrf, check: 'on' });
    assert.equal(cachedRelease(), null);
    assert.doesNotMatch((await a.get('/builder/home')).body, /is available/);
    await a.post('/builder/home/release-check', { __csrf: a.lastCsrf, check: 'default' });
  });

  test('sign-in still only follows builder paths; the Workspace home needs a developer', async () => {
    assert.equal((await new Browser().get('/builder/home')).statusCode, 302);
    const b = new Browser();
    await b.get('/builder/login');
    const res = await b.post('/builder/login', { __csrf: b.lastCsrf, username: DEV, password: DEV, next: '//evil.example/builder' });
    assert.equal(res.headers.location, '/builder/home');
    // an application's end user is no developer
    const u = await as('scott');
    assert.equal((await u.get('/builder/home')).statusCode, 302);
  });
});

describe('sprint 110 WS-2', () => {
  // A reporting application on the HR dataset "hr" (examples/hr/hr_63_datasets.sql): king administrator,
  // scott editor, allen viewer (no role).
  const ALIAS = 'sec110-reports';
  const ROLE = 'app_sec110_reports';
  let id110 = 0;
  let rid = 0;
  const P = () => `dr${rid}_`;
  const user = async (name: string) => {
    const b = new Browser();
    assert.equal((await b.login(name, name, ALIAS)).statusCode, 303, `login as ${name}`);
    await b.get(`/a/${ALIAS}/1`);
    return b;
  };
  const dev = async () => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username: 'admin', password: 'admin' });
    return b;
  };
  const drop = async () => {
    await owner.query('delete from meta.app where alias = $1', [ALIAS]);
    if ((await owner.query('select 1 from pg_roles where rolname = $1', [ROLE])).rowCount) {
      await owner.query(`drop owned by ${ROLE}`);
      await owner.query(`drop role ${ROLE}`);
    }
    await owner.query(`delete from meta.dataset where name like 'sec110%'`);
  };
  const save = (b: Browser, name: string, params: string, extra: Record<string, string> = {}) =>
    b.post(`/a/${ALIAS}/1/reporter/${rid}/save`, { __csrf: b.lastCsrf, params, name, mode: 'save', ...extra });

  before(async () => {
    await drop();
    const { checkNewApp } = await import('../src/builder/newapp.ts');
    const { createReportingApp } = await import('../src/reporting-app.ts');
    const { workspaceDatasets } = await import('../src/datasets.ts');
    const sets = (await workspaceDatasets(owner, 1)).filter((d) => d.name === 'hr');
    const checked = await checkNewApp({ name: 'Sec 110', alias: ALIAS, schema: 'hr', authentication: 'app_users', admin_user: 'king' }, 1);
    id110 = (await owner.tx((c) => createReportingApp(c, checked, sets))).id;
    rid = (await owner.one(`select r.id from meta.region r join meta.page p on p.id = r.page_id where p.app_id = $1 and r.type = 'data_reporter'`, [id110])).id;
    await owner.query(`insert into meta.app_access (app_id, account_id, roles) select $1, id, $3 from meta.account where username = $2`, [id110, 'scott', '{editor}']);
    await owner.query(`insert into meta.app_access (app_id, account_id, roles) select $1, id, '{}' from meta.account where username = $2`, [id110, 'allen']);
  });
  after(drop);

  test('a viewer sees no unpublished report, and can neither save, publish, unpublish nor delete', async () => {
    const scott = await user('scott');
    assert.equal((await save(scott, 'Sec draft', `${P()}src=hr&${P()}col=ename`)).statusCode, 303);
    assert.equal((await save(scott, 'Sec published', `${P()}src=hr&${P()}col=ename`)).statusCode, 303);
    const draft = (await owner.one('select id from meta.data_report where app_id = $1 and name = $2', [id110, 'Sec draft'])).id;
    const pub = (await owner.one('select id from meta.data_report where app_id = $1 and name = $2', [id110, 'Sec published'])).id;
    await scott.get(`/a/${ALIAS}/1`);
    assert.equal((await scott.post(`/a/${ALIAS}/1/reporter/${rid}/publish`, { __csrf: scott.lastCsrf, rep: String(pub), mode: 'publish' })).statusCode, 303);

    const allen = await user('allen');
    const home = await allen.get(`/a/${ALIAS}/1`);
    assert.doesNotMatch(home.body, /Sec draft/);
    assert.match(home.body, /Sec published/);
    assert.match((await allen.get(`/a/${ALIAS}/1?${P()}open=${draft}`)).body, /That report is not available/);
    assert.equal((await allen.get(`/a/${ALIAS}/reports/${draft}`)).statusCode, 404, 'no stable URL for an unpublished report');
    // no saving (not even under a new name), no publishing, no unpublishing or deleting someone else's
    assert.equal((await save(allen, 'Mine', `${P()}src=hr&${P()}col=ename`)).statusCode, 403);
    assert.equal(await owner.one('select 1 from meta.data_report where app_id = $1 and name = $2', [id110, 'Mine']), undefined);
    assert.equal((await allen.post(`/a/${ALIAS}/1/reporter/${rid}/publish`, { __csrf: allen.lastCsrf, rep: String(pub), mode: 'unpublish' })).statusCode, 403);
    assert.equal((await allen.post(`/a/${ALIAS}/1/reporter/${rid}/delete`, { __csrf: allen.lastCsrf, rep: String(pub) })).statusCode, 403);
    await allen.post(`/a/${ALIAS}/1/reporter/${rid}/publish`, { __csrf: allen.lastCsrf, rep: String(draft), mode: 'publish' });
    assert.equal((await owner.one('select shared from meta.data_report where id = $1', [draft])).shared, false);
    // ad-hoc definitions in the URL don't run for a viewer
    assert.doesNotMatch((await allen.get(`/a/${ALIAS}/1?${P()}src=hr&${P()}col=sal`)).body, /reporter-editor|<th scope="col" class="num">Salary/);
    // an editor may not unpublish or delete another editor's report; an administrator may
    const king = await user('king');
    assert.equal((await save(king, 'King report', `${P()}src=hr&${P()}col=ename`, { shared: 'true' })).statusCode, 303);
    const kr = (await owner.one('select id, shared from meta.data_report where app_id = $1 and name = $2', [id110, 'King report']));
    assert.equal(kr.shared, true);
    assert.equal((await scott.post(`/a/${ALIAS}/1/reporter/${rid}/publish`, { __csrf: scott.lastCsrf, rep: String(kr.id), mode: 'unpublish' })).statusCode, 403);
    assert.equal((await scott.post(`/a/${ALIAS}/1/reporter/${rid}/delete`, { __csrf: scott.lastCsrf, rep: String(kr.id) })).statusCode, 403);
    assert.equal((await king.post(`/a/${ALIAS}/1/reporter/${rid}/delete`, { __csrf: king.lastCsrf, rep: String(pub) })).statusCode, 303);
    assert.equal(await owner.one('select 1 from meta.data_report where id = $1', [pub]), undefined);
    // a stable URL of another application's report doesn't open it here
    assert.equal((await allen.get(`/a/hr/reports/${kr.id}`)).statusCode, 404);
  });

  test('editors and viewers of a reporting application can\'t reach the builder\'s datasets', async () => {
    const scott = await user('scott');
    for (const url of ['/builder/reporter', '/builder/reporter/datasets/new?schema=hr', '/builder/reporter/export', '/builder/reporter/apps/new'])
      assert.equal((await scott.get(url)).headers.location, '/builder/login', url);
    const before = (await owner.one('select count(*)::int as n from meta.dataset')).n;
    const res = await scott.post('/builder/reporter/datasets', { __csrf: scott.lastCsrf, schema: 'hr', name: 'sec110_x', tables: 'emp' });
    assert.notEqual(res.statusCode, 200);
    assert.equal((await owner.one('select count(*)::int as n from meta.dataset')).n, before);
  });

  test('injection: identifiers come from the catalog and are quoted; values are literals; a tampered dataset only fails', async () => {
    const a = await dev();
    // the builder's form: a made-up column reference and an injected filter value
    await a.get('/builder/reporter/datasets/new?schema=hr');
    assert.equal((await a.post('/builder/reporter/datasets', { __csrf: a.lastCsrf, schema: 'hr', name: 'sec110_inj', tables: ['emp', 'x"; drop table hr.emp; --'] })).statusCode, 303);
    const row = await owner.one(`select id from meta.dataset where name = 'sec110_inj'`);
    await a.get(`/builder/reporter/datasets/${row.id}`);
    await a.post(`/builder/reporter/datasets/${row.id}`, {
      __csrf: a.lastCsrf, label: 'Inj', t0_alias: 't1',
      c0_ref: 't1.ename', c0_on: 'true', c0_name: 'ename',
      c1_ref: 't1.ename" from hr.emp; --', c1_on: 'true', c1_name: 'evil',
      c2_ref: 't1.sal', c2_on: 'true', c2_name: 'Robert"); drop',
      f0_col: 't1.job', f0_op: 'eq', f0_value: "x' or '1'='1",
      f1_col: 't1.job', f1_op: '; drop table hr.emp', f1_value: '1',
      new_table: 'pg_authid',
    });
    const d = await owner.one('select * from meta.dataset where id = $1', [row.id]);
    assert.deepEqual(d.columns.map((c: any) => c.name), ['ename']);
    assert.deepEqual(d.tables.map((t: any) => t.table), ['emp']);
    assert.deepEqual(d.filters, [{ table: 't1', column: 'job', op: 'eq', value: "x' or '1'='1" }]);
    // a schema the workshop may not use, and pgkiln's own
    for (const schema of ['meta', 'pg_catalog', 'information_schema']) {
      await a.post('/builder/reporter/datasets', { __csrf: a.lastCsrf, schema, name: 'sec110_meta', tables: 'app' });
      assert.equal(await owner.one(`select 1 from meta.dataset where name = 'sec110_meta'`), undefined, schema);
    }
    // a dataset row changed behind the builder's back: still quoted, the report fails without running anything else
    await owner.query(`insert into meta.dataset (workspace_id, name, label, schema_name, tables, columns, created_by) values
      (1, 'sec110_bad', 'Bad', 'hr', '[{"alias": "t1", "table": "emp\\"; drop table hr.dept; --"}]', '[{"name": "x", "table": "t1", "column": "ename"}]', 'test')`);
    const cfg = (await owner.one('select config from meta.region where id = $1', [rid])).config;
    await owner.query('update meta.region set config = $2 where id = $1', [rid, { ...cfg, sources: [...cfg.sources, { id: 'bad', dataset: 'sec110_bad' }, { id: 'evil', dataset: 'x"; --' }] }]);
    const scott = await user('scott');
    const res = await scott.get(`/a/${ALIAS}/1?${P()}src=bad`);
    assert.equal(res.statusCode, 200);
    assert.match(res.body, /alert-error/);
    assert.ok(await owner.one(`select to_regclass('hr.dept') as t`).then((r) => r.t), 'hr.dept is still there');
    // report parameters: an unknown column, an injected value
    const ok = await scott.get(`/a/${ALIAS}/1?${P()}src=hr&${P()}col=${encodeURIComponent('ename"; --')}&${P()}fc=ename&${P()}fo=eq&${P()}fv=${encodeURIComponent("x' or 1=1 --")}`);
    assert.equal(ok.statusCode, 200);
    assert.doesNotMatch(ok.body, /alert-error/);
    await owner.query('update meta.region set config = $2 where id = $1', [rid, cfg]);
    // the region settings keep only known authorization schemes and datasets of the workspace
    const { mergeReporterSettings } = await import('../src/builder/reporter.ts');
    const m = await mergeReporterSettings({}, { edit_authz: 'NOPE', admin_authz: 'ADMIN', new_dataset: 'other' }, { authz: new Set(['ADMIN']), datasets: new Set(['hr']) });
    assert.equal(m.config.edit_authz, undefined);
    assert.equal(m.config.admin_authz, 'ADMIN');
    assert.equal(m.config.sources, undefined);
  });

  test('CSRF: every new POST needs the token', async () => {
    const scott = await user('scott');
    const pub = await owner.one(`select id from meta.data_report where app_id = $1 and name = 'Sec draft'`, [id110]);
    for (const [path, form] of [['save', { params: `${P()}src=hr`, name: 'csrf' }], ['publish', { rep: String(pub.id), mode: 'publish' }], ['pin', { rep: String(pub.id), mode: 'pin' }], ['delete', { rep: String(pub.id) }]] as const)
      assert.equal((await scott.post(`/a/${ALIAS}/1/reporter/${rid}/${path}`, { __csrf: 'forged', ...form })).statusCode, 403, path);
    assert.ok(await owner.one('select 1 from meta.data_report where id = $1', [pub.id]));
    const a = await dev();
    const ds = await owner.one(`select id from meta.dataset where name = 'hr'`);
    assert.equal((await a.post('/builder/reporter/datasets', { __csrf: 'forged', schema: 'hr', name: 'sec110_csrf', tables: 'emp' })).statusCode, 403);
    assert.equal((await a.post(`/builder/reporter/datasets/${ds.id}`, { __csrf: 'forged', label: 'Hacked' })).statusCode, 403);
    assert.equal((await a.post(`/builder/reporter/datasets/${ds.id}/delete`, { __csrf: 'forged' })).statusCode, 403);
    assert.equal((await a.post('/builder/reporter/import', { __csrf: 'forged', text: '{"datasets": []}' })).statusCode, 403);
    assert.equal((await a.post('/builder/reporter/apps', { __csrf: 'forged', name: 'X', alias: 'sec110-x', admin_user: 'king', datasets: 'hr' })).statusCode, 403);
    assert.equal(await owner.one(`select 1 from meta.app where alias = 'sec110-x'`), undefined);
    assert.equal((await owner.one(`select label from meta.dataset where id = $1`, [ds.id])).label, 'HR');
  });
});

describe('sprint 111 WS-4', () => {
  // AI agents and tools (migration 121): SQL tools are read-only and run as the app role through RLS; navigate tools link
  // only to pages the user may open (pgkiln builds the checksum); an agent's authorization scheme; model output escaped;
  // AI service keys never reach a page, a log or an export. Against the scripted AI mock (no real API calls).
  const SVC = 'HR_ASSISTANT';
  let mock: any;
  let saved: { ai_agents: unknown; ai_tools: unknown };
  let regionId: number;
  let regionConfig: unknown;
  const calls = () => mock.seen.filter((r: any) => r.path === '/claude/v1/messages');
  const setAgent = async (agent: Record<string, unknown>, tools: Record<string, unknown>[]) =>
    owner.query('update meta.app set ai_agents = $2, ai_tools = $3 where id = $1', [appId, JSON.stringify([{ name: 'SEC_AGENT', service: SVC, ...agent }]), JSON.stringify(tools)]);
  const ask = async (b: Browser, message: string) => {
    await b.get('/a/hr/46');
    return b.post(`/a/hr/46/assistant/${regionId}/send`, { __csrf: b.lastCsrf, message, params: '' });
  };
  const lastResult = () => calls().at(-1).body.messages.at(-1).content[0];
  before(async () => {
    const { startScriptMock } = await import('./ai-script-mock.ts');
    process.env.PGKILN_SECRET_KEY ??= 'test-only-secret-key-0123456789abcdef';
    const { encryptSecret } = await import('../src/secrets.ts');
    mock = await startScriptMock();
    saved = (await owner.one('select ai_agents, ai_tools from meta.app where id = $1', [appId]))!;
    const r = await owner.one(`select r.id, r.config from meta.region r join meta.page p on p.id = r.page_id where p.app_id = $1 and p.page_no = 46 and r.type = 'ai_assistant'`, [appId]);
    regionId = r!.id;
    regionConfig = r!.config;
    await owner.query(`update meta.region set config = '{"agent": "SEC_AGENT"}' where id = $1`, [regionId]);
    await owner.query('delete from meta.ai_service where name = $1', [SVC]);
    const s = await owner.one(`insert into meta.ai_service (name, provider, model, base_url, api_key_enc) values ($1, 'anthropic', 'claude-opus-5-5', $2, $3) returning id`,
      [SVC, `${mock.base}/claude`, encryptSecret('sk-ant-sec111-SECRET')]);
    await owner.query('insert into meta.app_ai_service (app_id, service_id) values ($1, $2)', [appId, s!.id]);
  });
  after(async () => {
    await owner.query('update meta.app set ai_agents = $2, ai_tools = $3 where id = $1', [appId, JSON.stringify(saved.ai_agents), JSON.stringify(saved.ai_tools)]);
    await owner.query('update meta.region set config = $2 where id = $1', [regionId, JSON.stringify(regionConfig)]);
    await owner.query('delete from meta.ai_conversation where region_id = $1', [regionId]);
    await owner.query('delete from meta.ai_service where name = $1', [SVC]);
    await mock.close();
  });

  test('an SQL tool can\'t write: functions that change data and data-modifying WITH fail, nothing changes', async () => {
    await setAgent({ tools: ['raise', 'purge'] }, [
      { name: 'raise', type: 'sql', description: 'd', sql: 'select hr.give_raise(7369, 50) as sal' },
      { name: 'purge', type: 'sql', description: 'd', sql: 'with d as (delete from hr.leave_request returning 1) select count(*) from d' },
    ]);
    const sal = (await owner.one('select sal from hr.emp where empno = 7369'))!.sal;
    const leave = (await owner.one('select count(*)::int as n from hr.leave_request'))!.n;
    mock.script = [{ tools: [{ name: 'raise', input: {} }] }, { tools: [{ name: 'purge', input: {} }] }, { text: 'No.' }];
    const b = await as('king');
    assert.equal((await ask(b, 'raise SMITH')).statusCode, 303);
    const [, second, third] = calls().slice(-3);
    assert.equal(second.body.messages.at(-1).content[0].is_error, true);
    assert.equal(third.body.messages.at(-1).content[0].is_error, true);
    assert.equal((await owner.one('select sal from hr.emp where empno = 7369'))!.sal, sal);
    assert.equal((await owner.one('select count(*)::int as n from hr.leave_request'))!.n, leave);
    const log = (await owner.query(`select tool, status from meta.ai_tool_call where app_id = $1 and agent = 'SEC_AGENT' order by id desc limit 2`, [appId])).rows;
    assert.deepEqual(log.map((x) => x.status), ['error', 'error']);
  });

  test('an SQL tool runs as the application\'s role with row level security; the model can\'t set :APP_USER', async () => {
    await setAgent({ tools: ['who'] }, [
      { name: 'who', type: 'sql', description: 'd', parameters: { N: { type: 'integer', optional: true } },
        sql: 'select current_user as role, :APP_USER as app_user, (select count(*) from hr.leave_request where empno <> hr.current_empno())::int as others' },
    ]);
    const { aiToolProblems } = await import('../src/runtime/ai-agents.ts');
    assert.ok(aiToolProblems({ name: 'x', type: 'sql', description: 'd', sql: 'select 1', parameters: { APP_USER: { type: 'string' } } }).length);
    await owner.query(`insert into hr.leave_request (empno, start_date, end_date, days, reason) values (7499, '2026-11-02', '2026-11-03', 2, 'SEC111 allen')`);
    try {
      mock.script = [{ tools: [{ name: 'who', input: { N: null } }] }, { tools: [{ name: 'who', input: { APP_USER: 'king' } }] }, { text: 'ok' }];
      await ask(await as('scott'), 'who am I');
      const [, second, third] = calls().slice(-3);
      const rows = JSON.parse(second.body.messages.at(-1).content[0].content).rows;
      assert.deepEqual(rows, [{ role: 'hr_app', app_user: 'scott', others: 0 }]);
      assert.equal(third.body.messages.at(-1).content[0].is_error, true);
      assert.match(third.body.messages.at(-1).content[0].content, /Unknown argument "APP_USER"/);
    } finally {
      await owner.query(`delete from hr.leave_request where reason = 'SEC111 allen'`);
    }
  });

  test('a navigate tool links only to pages the user may open, with item values of that page, checksum built by pgkiln', async () => {
    await setAgent({ tools: ['go'] }, [{ name: 'go', type: 'navigate', description: 'd', pages: [3, 2] }]);
    mock.script = [
      { tools: [{ name: 'go', input: { page: 3, label: 'Open', items: [{ name: 'P3_EMPNO', value: '7839' }] } }] },
      { tools: [{ name: 'go', input: { page: 2, label: 'List', items: [{ name: 'P3_EMPNO', value: '7839' }] } }] },
      { tools: [{ name: 'go', input: { page: 99, label: 'x', items: [] } }] },
      { text: 'Sorry.' },
    ];
    const scott = await as('scott');
    await ask(scott, 'open KING');
    const four = calls().slice(-4);
    assert.deepEqual(four[0].body.tools[0].input_schema.properties.page.enum, [2], 'page 3 (MANAGER) is not offered to scott');
    const results = four.slice(1).map((c: any) => c.body.messages.at(-1).content[0]);
    assert.ok(results.every((r: any) => r.is_error === true));
    assert.match(results[0].content, /may not open page 3/);
    assert.match(results[1].content, /Page 2 has no item P3_EMPNO/);
    assert.doesNotMatch((await scott.get('/a/hr/46')).body, /assistant-links/);
    assert.equal((await owner.one(`select status from meta.ai_tool_call where app_id = $1 and tool = 'go' and username = 'scott' order by id limit 1 offset 0`, [appId]))!.status, 'refused');
    // a manager gets the link; the model's values go in as they are (no &ITEM. substitution), bound to the user
    mock.script = [{ tools: [{ name: 'go', input: { page: 3, label: 'Open <img src=x onerror=alert(1)>', items: [{ name: 'p3_empno', value: '&APP_USER.' }] } }] }, { text: '<script>alert(1)</script> **done**' }];
    const king = await as('king');
    await ask(king, 'open it');
    const page = (await king.get('/a/hr/46')).body;
    const cs = urlChecksum(appId, 3, 'king', { P3_EMPNO: '&APP_USER.' });
    assert.ok(page.includes(`href="/a/hr/3?P3_EMPNO=%26APP_USER.&amp;cs=${cs}"`), 'the URL pgkiln built');
    assert.match(page, />Open &lt;img src=x onerror=alert\(1\)&gt;<\/a>/);
    assert.match(page, /&lt;script&gt;alert\(1\)&lt;\/script&gt; <strong>done<\/strong>/);
    assert.doesNotMatch(page, /<img src=x|<script>alert/);
    // scott can't open king's link (page authorization, and the checksum is bound to king)
    assert.notEqual((await scott.get(`/a/hr/3?P3_EMPNO=7839&cs=${urlChecksum(appId, 3, 'king', { P3_EMPNO: '7839' })}`)).statusCode, 200);
  });

  test('an agent\'s authorization scheme: other users see a message, their questions are refused before any AI call', async () => {
    await setAgent({ authz: 'ADMIN', tools: [] }, []);
    const b = await as('scott');
    const body = (await b.get('/a/hr/46')).body;
    assert.match(body, /You may not use this assistant/);
    assert.doesNotMatch(body, /name="message"/);
    const before = calls().length;
    const res = await b.post(`/a/hr/46/assistant/${regionId}/send`, { __csrf: b.lastCsrf, message: 'hi', params: '' });
    assert.equal(res.statusCode, 403);
    assert.equal(calls().length, before, 'no call to the AI service');
    // an unknown agent: not set up, no call either
    await owner.query(`update meta.region set config = '{"agent": "NO_SUCH_AGENT"}' where id = $1`, [regionId]);
    try {
      const k = await as('king');
      assert.match((await k.get('/a/hr/46')).body, /not set up yet/);
      await ask(k, 'hi');
      assert.equal(calls().length, before);
    } finally {
      await owner.query(`update meta.region set config = '{"agent": "SEC_AGENT"}' where id = $1`, [regionId]);
    }
  });

  test('a javascript tool\'s arguments reach the page escaped, once', async () => {
    await setAgent({ tools: ['js'] }, [{ name: 'js', type: 'javascript', description: 'd', action: 'demo', parameters: { T: { type: 'string' } } }]);
    mock.script = [{ tools: [{ name: 'js', input: { T: '"><script>alert(1)</script>' } }] }, { text: 'ok' }];
    const b = await as('king');
    await ask(b, 'x');
    const page = (await b.get('/a/hr/46')).body;
    assert.ok(page.includes('data-ai-args="{&quot;T&quot;:&quot;\\&quot;&gt;&lt;script&gt;alert(1)&lt;/script&gt;&quot;}"'));
    assert.doesNotMatch(page, /<script>alert/);
  });

  test('keys never leave the server: not in builder pages, the tool call log, an export or the runtime role\'s reach', async () => {
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    const svc = (await owner.one('select id from meta.ai_service where name = $1', [SVC]))!.id;
    for (const url of ['/builder/ai', `/builder/ai/${svc}`, `/builder/apps/${appId}/ai`, `/builder/apps/${appId}/ai-agents`, `/builder/apps/${appId}/ai-agents/agent?name=SEC_AGENT`]) {
      const res = await dev.get(url);
      assert.equal(res.statusCode, 200, url);
      assert.doesNotMatch(res.body, /sk-ant-sec111-SECRET|v1:[A-Za-z0-9+/]{20}/, url);
    }
    assert.doesNotMatch(JSON.stringify((await owner.query('select * from meta.ai_tool_call where app_id = $1', [appId])).rows), /sk-ant-sec111-SECRET/);
    assert.doesNotMatch(JSON.stringify((await owner.one(`select meta.export_app('hr') as d`))!.d), /sk-ant-sec111-SECRET|api_key_enc/);
    for (const sql of ['select count(*) from meta.ai_tool_call', 'select api_key_enc from meta.ai_service'])
      await assert.rejects(runtime.query(sql), /permission denied/, sql);
    // the key only goes to the provider, in its header
    assert.equal(calls().at(-1).headers['x-api-key'], 'sk-ant-sec111-SECRET');
  });

  test('the builder\'s agent and tool forms need a developer and the CSRF token, and check what they save', async () => {
    const user = await as('scott');
    assert.equal((await user.get(`/builder/apps/${appId}/ai-agents`)).statusCode, 302);
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    const before = JSON.stringify((await owner.one('select ai_agents, ai_tools from meta.app where id = $1', [appId]))!);
    assert.equal((await dev.post(`/builder/apps/${appId}/ai-agents/tool`, { name: 'x', type: 'sql', description: 'd', sql: 'select 1' })).statusCode, 403);
    assert.equal((await dev.post(`/builder/apps/${appId}/ai-agents/agent/delete`, { name: 'SEC_AGENT' })).statusCode, 403);
    await dev.get(`/builder/apps/${appId}/ai-agents/tool`);
    const bads: Record<string, string>[] = [{ type: 'function', function: 'hr.x(); drop table hr.emp; --' }, { type: 'sql', sql: 'update hr.emp set sal = 0' }, { type: 'javascript', action: 'alert(1)' }];
    for (const bad of bads)
      assert.equal((await dev.post(`/builder/apps/${appId}/ai-agents/tool`, { __csrf: dev.lastCsrf, original: '', name: 'bad', description: 'd', ...bad })).statusCode, 422, JSON.stringify(bad));
    assert.equal(JSON.stringify((await owner.one('select ai_agents, ai_tools from meta.app where id = $1', [appId]))!), before);
  });
});

describe('sprint 112 WS-5', () => {
  // "Ask in your own words": the phrase parser and the AI answer only set the report's own settings over its
  // shown columns; chips are edited and removed through a CSRF-checked form whose fields are checked again
  let region: number;
  let oldConfig: unknown;
  let mock: Awaited<ReturnType<typeof import('./ai-mock.ts').startAiMock>>;
  const SERVICE = 'T_WS5_SEC';
  const k = (x: string) => `r${region}_${x}`;
  const at = (res: { headers: Record<string, unknown> }) => new URL(res.headers.location as string, 'http://x');
  const ask = async (b: Browser, question: string, params = '') => {
    await b.get('/a/hr/2');
    return b.post(`/a/hr/2/report/${region}/ask`, { __csrf: b.lastCsrf, question, params });
  };
  const chips = async (b: Browser, form: Record<string, string>) => {
    await b.get('/a/hr/2');
    return b.post(`/a/hr/2/report/${region}/chips`, { __csrf: b.lastCsrf, ...form });
  };
  const setConfig = (extra: Record<string, unknown>) =>
    owner.query('update meta.region set config = $2 where id = $1', [region, JSON.stringify({ ...(oldConfig as object), ...extra })]);

  before(async () => {
    const r = await owner.one(`select r.id, r.config from meta.region r join meta.page p on p.id = r.page_id where p.app_id = $1 and p.page_no = 2 and r.type = 'report'`, [appId]);
    region = r.id;
    oldConfig = r.config;
    mock = await (await import('./ai-mock.ts')).startAiMock();
    process.env.PGKILN_SECRET_KEY ??= 'test-only-secret-key-0123456789abcdef';
    const { encryptSecret } = await import('../src/secrets.ts');
    await owner.query(`delete from meta.ai_service where name = $1`, [SERVICE]);
    const svc = (await owner.one(`insert into meta.ai_service (name, provider, model, base_url, api_key_enc, effort) values ($1, 'anthropic', 'claude-opus-5-5', $2, $3, 'medium') returning id`,
      [SERVICE, `${mock.base}/claude`, encryptSecret('sk-ant-sec')])).id;
    await owner.query(`insert into meta.app_ai_service (app_id, service_id) values ($1, $2)`, [appId, svc]);
  });
  after(async () => {
    await owner.query('update meta.region set config = $2 where id = $1', [region, JSON.stringify(oldConfig)]);
    await owner.query(`delete from meta.ai_service where name = $1`, [SERVICE]);
    await mock.close();
  });

  test('the parser never sets anything on a hidden column', async () => {
    await setConfig({ hidden: ['sal'], ai_filter: {} });
    try {
      const b = await as('king');
      for (const q of ['salary over 3000', 'sort by salary', 'sum of salary by department', 'bonus is 10% of salary', 'highlight salary over 1 in red', 'chart of salary by job', 'sal > 1']) {
        const loc = at(await ask(b, q));
        assert.ok(![...loc.searchParams.entries()].some(([, v]) => /\bsal\b/.test(v)), `${q}: ${loc.search}`);
        assert.equal(loc.searchParams.get(k('s')), null, q);
      }
      // a value lookup never reads a hidden column either
      await setConfig({ hidden: ['job'], ai_filter: {} });
      const loc = at(await ask(b, 'only clerks'));
      assert.equal(loc.searchParams.getAll(k('f')).length, 0);
    } finally {
      await setConfig({});
    }
  });

  test('the AI answer: only shown columns, whitelisted operators, functions, colors and chart types; expressions checked', async () => {
    await setConfig({ hidden: ['sal'], ai_filter: { service: SERVICE } });
    try {
      const b = await as('king');
      mock.answer = JSON.stringify({
        reset: false,
        filters: [{ column: 'sal', operator: 'gt', value: '0' }, { column: 'job', operator: 'raw_sql', value: '1' }, { column: 'job', operator: 'eq', value: "x' or 1=1 --" }],
        highlights: [{ column: 'sal', operator: 'gt', value: '1', color: 'red' }, { column: 'job', operator: 'eq', value: 'CLERK', color: 'red;background:url(x)' }],
        search: '', sort_column: 'sal', sort_descending: true, control_break: 'sal',
        aggregates: [{ function: 'sum', column: 'sal' }, { function: 'sum); drop table hr.emp; --', column: 'empno' }],
        group_by: ['sal', 'job'], group_functions: [{ function: 'max', column: 'sal' }],
        pivot: { row: 'job', column: 'department', function: 'sum', value: 'sal' },
        chart: { type: 'pie); --', label: 'job', function: 'count', value: 'empno' },
        computed_columns: [{ name: 'leak', expression: 'sal * 1' }, { name: 'evil', expression: "empno); delete from hr.emp; --" }, { name: 'slow', expression: 'pg_sleep(5)' }, { name: 'ok', expression: 'empno * 2' }],
      });
      const before = mock.seen.length;
      const loc = at(await ask(b, 'anything'));
      const schema = mock.seen[before].body.output_config.format.schema;
      assert.ok(!schema.properties.filters.items.properties.column.enum.includes('sal'), 'hidden columns are not offered');
      assert.doesNotMatch(mock.seen[before].body.system, /- sal:/);
      assert.deepEqual(loc.searchParams.getAll(k('f')), ["job|eq|x' or 1=1 --"]);
      assert.deepEqual(loc.searchParams.getAll(k('h')), ['job|eq|yellow|CLERK'], 'an unknown color falls back to yellow');
      assert.equal(loc.searchParams.get(k('s')), null);
      assert.equal(loc.searchParams.get(k('b')), null);
      assert.deepEqual(loc.searchParams.getAll(k('a')), []);
      assert.deepEqual(loc.searchParams.getAll(k('g')), ['job']);
      assert.deepEqual(loc.searchParams.getAll(k('ga')), []);
      assert.equal(loc.searchParams.get(k('pv')), null);
      assert.equal(loc.searchParams.get(k('ch')), null);
      assert.deepEqual(loc.searchParams.getAll(k('c')), ['ok|empno * 2']);
      // the value is a literal: the report runs, nothing is matched, nothing is deleted
      const n = (await owner.one('select count(*)::int as n from hr.emp')).n;
      const page = await b.get(`${loc.pathname}${loc.search}`);
      assert.equal(page.statusCode, 200);
      assert.equal((await owner.one('select count(*)::int as n from hr.emp')).n, n);
    } finally {
      await setConfig({});
    }
  });

  test('values are query parameters or escaped literals', async () => {
    const b = await as('king');
    const n = (await owner.one('select count(*)::int as n from hr.emp')).n;
    for (const q of ["only o'brien'); delete from hr.emp; --", "name is x'; drop table hr.emp; --", 'job contains %_\\', 'bonus is pg_sleep(5)', "x is 'a' || (select password from meta.account limit 1)"]) {
      const res = await ask(b, q);
      assert.equal(res.statusCode, 303, q);
      const loc = at(res);
      assert.ok(!loc.searchParams.getAll(k('c')).some((c) => /sleep|select/i.test(c)), q);
      assert.equal((await b.get(`${loc.pathname}${loc.search}`)).statusCode, 200, q);
    }
    assert.equal((await owner.one('select count(*)::int as n from hr.emp')).n, n);
  });

  test('chip edits: columns, operators, functions, colors, chart types and expressions are checked; tampered forms are refused', async () => {
    await setConfig({ hidden: ['sal'], ai_filter: {} });
    try {
      const b = await as('king');
      const params = new URLSearchParams([[k('f'), 'job|eq|CLERK'], [k('h'), 'job|eq|red|CLERK'], [k('a'), 'count|empno'], [k('ch'), 'bar|job|count|empno'], [k('c'), 'x|empno*2']]).toString();
      const keys = { k0: 'f:job|eq|CLERK', k1: 'a:count|empno', k2: 'h:job|eq|red|CLERK', k3: 'c:x|empno*2', k4: 'ch:bar|job|count|empno' };
      const refused = async (form: Record<string, string>, why: string) => assert.equal((await chips(b, { params, ...keys, ...form })).statusCode, 403, why);
      await refused({ edit: '0', e0_a: 'sal', e0_b: 'gt', e0_c: '0' }, 'a hidden column');
      await refused({ edit: '0', e0_a: 'nope', e0_b: 'eq', e0_c: '0' }, 'an unknown column');
      await refused({ edit: '0', e0_a: 'job', e0_b: 'raw', e0_c: '0' }, 'an unknown operator');
      await refused({ edit: '1', e1_a: 'sum(empno)); --', e1_b: 'empno' }, 'an unknown function');
      await refused({ edit: '2', e2_a: 'job', e2_b: 'eq', e2_c: 'x', e2_d: 'red;x' }, 'an unknown color');
      await refused({ edit: '4', e4_a: 'pie); --', e4_b: 'job', e4_c: 'count', e4_d: 'empno' }, 'an unknown chart type');
      await refused({ edit: '0', k0: 'f:job|eq|MANAGER', e0_a: 'job', e0_b: 'eq', e0_c: 'x' }, 'a chip key that is not the chip');
      await refused({ remove: '9' }, 'a chip that is not there');
      await refused({ remove: '-1' }, 'a negative index');
      // a computed column that uses a hidden column or an unknown function: a message, no change
      for (const expr of ['sal * 2', 'pg_sleep(5)', "empno); delete from hr.emp; --"]) {
        const res = await chips(b, { params, ...keys, edit: '3', e3_a: 'x', e3_b: expr });
        assert.equal(res.statusCode, 303, expr);
        assert.deepEqual(at(res).searchParams.getAll(k('c')), ['x|empno*2'], expr);
      }
      // no CSRF token, or another user's session: refused
      assert.equal((await b.post(`/a/hr/2/report/${region}/chips`, { params, ...keys, remove: '0' })).statusCode, 403);
      assert.equal((await b.post(`/a/hr/2/report/${region}/ask`, { question: 'salary over 1', params: '' })).statusCode, 403);
      const res = await chips(b, { params, ...keys, remove: '0' });
      assert.equal(res.statusCode, 303);
      assert.deepEqual(at(res).searchParams.getAll(k('f')), []);
    } finally {
      await setConfig({});
    }
  });

  test('a report without "ai_filter", a region of another page and signed-out users are refused', async () => {
    const b = await as('king');
    await setConfig({ ai_filter: undefined });
    try {
      assert.equal((await ask(b, 'salary over 1')).statusCode, 403);
    } finally {
      await setConfig({});
    }
    const other = (await owner.one(`select r.id from meta.region r join meta.page p on p.id = r.page_id where p.app_id = $1 and p.page_no = 38 and r.type = 'report'`, [appId])).id;
    await b.get('/a/hr/2');
    assert.equal((await b.post(`/a/hr/2/report/${other}/ask`, { __csrf: b.lastCsrf, question: 'x', params: '' })).statusCode, 403);
    const anon = new Browser();
    const res = await anon.post(`/a/hr/2/report/${region}/chips`, { __csrf: 'x', undo: '1', params: '' });
    assert.notEqual(res.statusCode, 303);
  });

  test('the box and chips render escaped, without inline styles or scripts', async () => {
    const b = await as('king');
    const body = (await b.get(`/a/hr/2?${new URLSearchParams([[k('f'), 'job|eq|<img src=x onerror=alert(1)>'], [k('c'), 'y|"<script>"']])}`)).body;
    assert.ok(!body.includes('<img src=x onerror=alert(1)>'));
    assert.ok(!body.includes('<script>"'));
    assert.doesNotMatch(body.slice(body.indexOf('class="ai-filter"'), body.indexOf('class="ai-filter"') + 20000), /style="|onclick=/);
  });
});

describe('sprint 113 WS-3', () => {
  // Team Development (/builder/team, migration 122): issues, labels, milestones, templates and saved views are of the
  // developer's current workspace only; assignees and @mentions are the workspace's developers; links only to its
  // applications; every POST needs the session's CSRF token; Markdown and names are escaped; colours from a palette.
  const DEV = 'sec113dev';
  const OTHER = 'sec113other';
  let wsA: number;
  let wsB: number;
  let appB: number;
  let appA: number;
  let issueB: number;
  let labelB: number;
  let groupB: number;
  let milestoneB: number;
  let templateB: number;
  let viewB: number;
  let feedbackB: number;
  let commentB: number;
  const signIn = async (username: string, ws?: number) => {
    const b = new Browser();
    await b.get('/builder/login');
    const res = await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username });
    assert.equal(res.statusCode, 303);
    await b.get('/builder/home');
    if (ws) assert.equal((await b.post('/builder/workspace', { __csrf: b.lastCsrf, workspace: String(ws) })).statusCode, 303);
    await b.get('/builder/team');
    return b;
  };
  const snapshot = async () => (await owner.one(`select row_to_json(i)::text as j,
      (select count(*) from meta.team_issue_comment c where c.issue_id = i.id)::int as comments,
      (select count(*) from meta.team_issue_label l where l.issue_id = i.id)::int as labels from meta.team_issue i where i.id = $1`, [issueB]));
  before(async () => {
    for (const u of [DEV, OTHER]) await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [u]);
    await owner.query(`delete from meta.app where alias in ('sec113a', 'sec113b')`);
    await owner.query(`delete from meta.workspace where name in ('Sec113 A', 'Sec113 B')`);
    wsA = (await owner.one(`insert into meta.workspace (name) values ('Sec113 A') returning id`)).id;
    wsB = (await owner.one(`insert into meta.workspace (name) values ('Sec113 B') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = any($1::text[])', [[DEV, OTHER]]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2), ($3, $4)', [wsA, DEV, wsB, OTHER]);
    appA = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('sec113a', 'Sec113 A app', 'none', 'hr_app') returning id`)).id;
    appB = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('sec113b', 'Sec113 B app', 'none', 'hr_app') returning id`)).id;
    await owner.query('insert into meta.workspace_app (app_id, workspace_id) values ($1, $2), ($3, $4)', [appA, wsA, appB, wsB]);
    await owner.query(`insert into meta.page (app_id, page_no, name, title) values ($1, 1, 'Home', 'Home'), ($2, 1, 'Home', 'Home')`, [appA, appB]);
    groupB = (await owner.one(`insert into meta.team_label_group (workspace_id, name) values ($1, 'Secret group') returning id`, [wsB])).id;
    labelB = (await owner.one(`insert into meta.team_label (workspace_id, group_id, name, color) values ($1, $2, 'Secret label', 'red') returning id`, [wsB, groupB])).id;
    milestoneB = (await owner.one(`insert into meta.team_milestone (workspace_id, name) values ($1, 'Secret milestone') returning id`, [wsB])).id;
    templateB = (await owner.one(`insert into meta.team_template (workspace_id, kind, name, body) values ($1, 'issue', 'Secret template', 'secret body') returning id`, [wsB])).id;
    issueB = (await owner.one(`insert into meta.team_issue (workspace_id, title, body, app_id, page_no, created_by) values ($1, 'Secret issue', 'secret text', $2, 1, $3) returning id`, [wsB, appB, OTHER])).id;
    await owner.query('insert into meta.team_issue_label (issue_id, label_id) values ($1, $2)', [issueB, labelB]);
    viewB = (await owner.one(`insert into meta.team_view (workspace_id, username, name, query) values ($1, $2, 'Secret view', '') returning id`, [wsB, OTHER])).id;
    feedbackB = (await owner.one(`insert into meta.feedback (app_id, page_no, username, kind, body) values ($1, 1, 'someone', 'problem', 'secret feedback') returning id`, [appB])).id;
    commentB = (await owner.one(`insert into meta.dev_comment (app_id, page_no, author, body) values ($1, 1, $2, 'secret comment') returning id`, [appB, OTHER])).id;
  });
  after(async () => {
    await owner.query(`delete from meta.app where alias in ('sec113a', 'sec113b')`);
    await owner.query('delete from meta.workspace where id = any($1::int[])', [[wsA, wsB]]);
    await owner.query('delete from meta.developer where username = any($1::text[])', [[DEV, OTHER]]);
  });

  test('another workspace\'s issues, labels, milestones, templates and views can be neither read nor changed', async () => {
    const d = await signIn(DEV);
    const before = await snapshot();
    const list = (await d.get('/builder/team?status=all')).body;
    assert.doesNotMatch(list, /Secret/);
    assert.doesNotMatch((await d.get(`/builder/team?label=${labelB}&status=all`)).body, /Secret issue/);
    assert.doesNotMatch((await d.get('/builder/team/board?status=all')).body, /Secret/);
    assert.doesNotMatch((await d.get('/builder/team/labels')).body, /Secret/);
    assert.doesNotMatch((await d.get('/builder/team/milestones')).body, /Secret/);
    assert.doesNotMatch((await d.get('/builder/team/templates')).body, /Secret/);
    assert.doesNotMatch((await d.get(`/builder/team/issues/new?template=${templateB}&app=${appB}`)).body, /secret body|Sec113 B app/);
    assert.equal((await d.get(`/builder/team/issues/${issueB}`)).statusCode, 404);
    const csrf = d.lastCsrf;
    for (const [url, form] of [
      [`/builder/team/issues/${issueB}`, { title: 'hacked', body: '' }],
      [`/builder/team/issues/${issueB}/status`, { status: 'closed' }],
      [`/builder/team/issues/${issueB}/comments`, { body: 'hacked' }],
      [`/builder/team/issues/${issueB}/move`, { by: 'label', group: String(groupB), to: '' }],
      [`/builder/team/issues/${issueB}/delete`, {}],
      [`/builder/team/labels/${labelB}`, { name: 'hacked', color: 'blue', group: '' }],
      [`/builder/team/milestones/${milestoneB}`, { name: 'hacked', status: 'closed' }],
      [`/builder/team/templates/${templateB}`, { name: 'hacked', kind: 'issue', body: '' }],
      [`/builder/team/templates/${templateB}/delete`, {}],
      [`/builder/team/views/${viewB}/delete`, {}],
      ['/builder/team/from-feedback', { feedback: String(feedbackB) }],
      ['/builder/team/from-comment', { comment: String(commentB) }],
    ] as [string, Record<string, string>][]) {
      const res = await d.post(url, { __csrf: csrf, ...form });
      assert.equal(res.statusCode, 404, url);
    }
    assert.deepEqual(await snapshot(), before);
    assert.equal((await owner.one('select name from meta.team_label where id = $1', [labelB])).name, 'Secret label');
    assert.equal((await owner.one('select name from meta.team_milestone where id = $1', [milestoneB])).name, 'Secret milestone');
    assert.ok(await owner.one('select 1 from meta.team_template where id = $1', [templateB]));
    assert.ok(await owner.one('select 1 from meta.team_view where id = $1', [viewB]));
    assert.equal((await owner.one('select count(*)::int as n from meta.team_issue where feedback_id = $1 or dev_comment_id = $2', [feedbackB, commentB])).n, 0);
    // deleting labels, groups and milestones: the workspace's administrators only (and never another workspace's)
    const own = (await owner.one(`insert into meta.team_label (workspace_id, name) values ($1, 'Own label') returning id`, [wsA])).id;
    assert.equal((await d.post(`/builder/team/labels/${own}/delete`, { __csrf: csrf })).statusCode, 403);
    const admin = await signIn('admin', wsA);
    assert.equal((await admin.post(`/builder/team/labels/${labelB}/delete`, { __csrf: admin.lastCsrf })).statusCode, 404, 'not of the current workspace');
    assert.equal((await admin.post(`/builder/team/groups/${groupB}/delete`, { __csrf: admin.lastCsrf })).statusCode, 404);
    assert.equal((await admin.post(`/builder/team/milestones/${milestoneB}/delete`, { __csrf: admin.lastCsrf })).statusCode, 404);
    // an issue is deleted by its author or a workspace administrator
    const theirs = (await owner.one(`insert into meta.team_issue (workspace_id, title, created_by) values ($1, 'Not yours', 'admin') returning id`, [wsA])).id;
    assert.equal((await d.post(`/builder/team/issues/${theirs}/delete`, { __csrf: csrf })).statusCode, 403);
    assert.ok(await owner.one('select 1 from meta.team_issue where id = $1', [theirs]));
  });

  test('labels, a milestone, assignees, mentions and the application link come from the current workspace only', async () => {
    const d = await signIn(DEV);
    const csrf = d.lastCsrf;
    const count = async () => (await owner.one('select count(*)::int as n from meta.team_issue where workspace_id = $1', [wsA])).n;
    const n0 = await count();
    for (const [form, why] of [
      [{ labels: String(labelB) }, 'label'],
      [{ milestone: String(milestoneB) }, 'milestone'],
      [{ assignees: OTHER }, 'assignee'],
      [{ assignees: 'admin\'; drop table x;--' }, 'assignee text'],
      [{ app: String(appB) }, 'application'],
      [{ app: String(appA), page: '99' }, 'page'],
      [{ app: '1 or 1=1' }, 'application text'],
    ] as [Record<string, string>, string][]) {
      const res = await d.post('/builder/team/issues', { __csrf: csrf, title: `Bad ${why}`, body: '', ...form });
      assert.equal(res.statusCode, 303, why);
      assert.equal(await count(), n0, `${why}: refused`);
    }
    // the database refuses a mix-up too
    await assert.rejects(owner.query(`insert into meta.team_issue (workspace_id, title, milestone_id, created_by) values ($1, 'x', $2, 'admin')`, [wsA, milestoneB]), /another workspace/);
    await assert.rejects(owner.query(`insert into meta.team_label (workspace_id, group_id, name) values ($1, $2, 'x')`, [wsA, groupB]), /another workspace/);
    // a label in another workspace's group, and a move to another workspace's label
    assert.equal((await d.post('/builder/team/labels', { __csrf: csrf, name: 'Sneaky', color: 'red', group: String(groupB) })).statusCode, 400);
    const ok = await d.post('/builder/team/issues', { __csrf: csrf, title: 'Fine', body: `Hi @${OTHER} and @admin`, app: String(appA), page: '1' });
    const id = Number(/issues\/(\d+)$/.exec(String(ok.headers.location))?.[1]);
    assert.ok(id);
    assert.equal((await d.post(`/builder/team/issues/${id}/move`, { __csrf: csrf, by: 'label', group: String(groupB), to: String(labelB) })).statusCode, 400);
    assert.equal((await d.post(`/builder/team/issues/${id}/move`, { __csrf: csrf, by: 'milestone', to: String(milestoneB) })).statusCode, 400);
    // a developer of another workspace is never mentioned (nor highlighted); an administrator of the installation is
    await d.post(`/builder/team/issues/${id}/comments`, { __csrf: csrf, body: `@${OTHER} look` });
    assert.deepEqual((await owner.query('select username from meta.team_mention where issue_id = $1 order by 1', [id])).rows.map((r) => r.username), ['admin']);
    assert.doesNotMatch((await d.get(`/builder/team/issues/${id}`)).body, new RegExp(`class="mention">@${OTHER}`));
    // a saved view keeps known filters only
    await d.post('/builder/team/views', { __csrf: d.lastCsrf, name: 'Odd', query: 'status=closed&q=x&evil=<script>&assignee=me' });
    assert.equal((await owner.one(`select query from meta.team_view where workspace_id = $1 and username = $2 and name = 'Odd'`, [wsA, DEV])).query, 'status=closed&assignee=me&q=x');
  });

  test('CSRF: every Team Development POST needs the session\'s token', async () => {
    const a = await signIn('admin', wsA);
    const own = (await owner.one(`insert into meta.team_issue (workspace_id, title, created_by) values ($1, 'CSRF target', 'admin') returning id`, [wsA])).id;
    const lab = (await owner.one(`insert into meta.team_label (workspace_id, name) values ($1, 'CSRF label') returning id`, [wsA])).id;
    const ms = (await owner.one(`insert into meta.team_milestone (workspace_id, name) values ($1, 'CSRF ms') returning id`, [wsA])).id;
    const grp = (await owner.one(`insert into meta.team_label_group (workspace_id, name) values ($1, 'CSRF group') returning id`, [wsA])).id;
    const tpl = (await owner.one(`insert into meta.team_template (workspace_id, kind, name) values ($1, 'response', 'CSRF tpl') returning id`, [wsA])).id;
    const view = (await owner.one(`insert into meta.team_view (workspace_id, username, name) values ($1, 'admin', 'CSRF view') returning id`, [wsA])).id;
    const fb = (await owner.one(`insert into meta.feedback (app_id, username, kind, body) values ($1, 'x', 'idea', 'csrf') returning id`, [appA])).id;
    const cm = (await owner.one(`insert into meta.dev_comment (app_id, author, body) values ($1, 'admin', 'csrf') returning id`, [appA])).id;
    const posts: [string, Record<string, string>][] = [
      ['/builder/team/issues', { title: 'CSRF new' }],
      [`/builder/team/issues/${own}`, { title: 'CSRF changed' }],
      [`/builder/team/issues/${own}/status`, { status: 'closed' }],
      [`/builder/team/issues/${own}/comments`, { body: 'csrf' }],
      [`/builder/team/issues/${own}/move`, { by: 'milestone', to: String(ms) }],
      [`/builder/team/issues/${own}/delete`, {}],
      ['/builder/team/views', { name: 'CSRF view 2' }],
      [`/builder/team/views/${view}/delete`, {}],
      ['/builder/team/mentions/seen', {}],
      ['/builder/team/labels', { name: 'CSRF l2', color: 'red' }],
      [`/builder/team/labels/${lab}`, { name: 'CSRF l3', color: 'red' }],
      [`/builder/team/labels/${lab}/delete`, {}],
      ['/builder/team/groups', { name: 'CSRF g2' }],
      [`/builder/team/groups/${grp}/delete`, {}],
      ['/builder/team/milestones', { name: 'CSRF m2' }],
      [`/builder/team/milestones/${ms}`, { name: 'CSRF m3' }],
      [`/builder/team/milestones/${ms}/delete`, {}],
      ['/builder/team/templates', { name: 'CSRF t2', kind: 'issue' }],
      [`/builder/team/templates/${tpl}`, { name: 'CSRF t3', kind: 'issue' }],
      [`/builder/team/templates/${tpl}/delete`, {}],
      ['/builder/team/setup', { lang: 'en', labels: 'true' }],
      ['/builder/team/from-feedback', { feedback: String(fb) }],
      ['/builder/team/from-comment', { comment: String(cm) }],
    ];
    const state = async () => JSON.stringify((await owner.query(`select
        (select json_agg(i order by id) from meta.team_issue i where workspace_id = $1) as i,
        (select json_agg(l order by id) from meta.team_label l where workspace_id = $1) as l,
        (select json_agg(g order by id) from meta.team_label_group g where workspace_id = $1) as g,
        (select json_agg(m order by id) from meta.team_milestone m where workspace_id = $1) as m,
        (select json_agg(t order by id) from meta.team_template t where workspace_id = $1) as t,
        (select json_agg(v order by id) from meta.team_view v where workspace_id = $1) as v,
        (select count(*) from meta.team_issue_comment c join meta.team_issue i on i.id = c.issue_id where i.workspace_id = $1) as c`, [wsA])).rows[0]);
    const s0 = await state();
    for (const [url, form] of posts) {
      assert.equal((await a.post(url, { __csrf: 'forged', ...form })).statusCode, 403, `${url} (forged token)`);
      assert.equal((await a.post(url, form)).statusCode, 403, `${url} (no token)`);
    }
    assert.equal(await state(), s0);
  });

  test('titles, bodies, comments, label names and templates are escaped; Markdown is made safe; label colours from the palette', async () => {
    const a = await signIn('admin', wsA);
    const evil = '<script>alert(1)</script><img src=x onerror=alert(2)>';
    assert.equal((await a.post('/builder/team/labels', { __csrf: a.lastCsrf, name: '<b>L</b>', color: 'red' })).statusCode, 303);
    const lab = (await owner.one(`select id from meta.team_label where workspace_id = $1 and name = '<b>L</b>'`, [wsA])).id;
    for (const color of ['red;background:url(//x)', 'chartreuse', '"><script>']) {
      assert.equal((await a.post(`/builder/team/labels/${lab}`, { __csrf: a.lastCsrf, name: 'x', color })).statusCode, 400, color);
      assert.equal((await a.post('/builder/team/labels', { __csrf: a.lastCsrf, name: 'y', color })).statusCode, 400, color);
    }
    await assert.rejects(owner.query(`update meta.team_label set color = 'pink' where id = $1`, [lab]));
    await a.post('/builder/team/milestones', { __csrf: a.lastCsrf, name: '<i>M</i>', status: 'open' });
    await a.post('/builder/team/templates', { __csrf: a.lastCsrf, name: '<u>T</u>', kind: 'issue', title: evil, body: evil });
    const res = await a.post('/builder/team/issues', { __csrf: a.lastCsrf, title: evil, body: `${evil}\n\n[x](javascript:alert(3)) **ok**`, labels: String(lab) });
    const id = Number(/issues\/(\d+)$/.exec(String(res.headers.location))?.[1]);
    assert.ok(id);
    await a.post(`/builder/team/issues/${id}/comments`, { __csrf: a.lastCsrf, body: `${evil} [y](javascript:alert(4))` });
    const pages = [
      (await a.get(`/builder/team/issues/${id}`)).body, (await a.get('/builder/team')).body, (await a.get('/builder/team/board')).body,
      (await a.get('/builder/team/labels')).body, (await a.get('/builder/team/milestones')).body, (await a.get('/builder/team/templates')).body,
      (await a.get(`/builder/team/issues/new?template=${(await owner.one(`select id from meta.team_template where workspace_id = $1 and name = '<u>T</u>'`, [wsA])).id}`)).body,
    ];
    for (const p of pages) {
      assert.doesNotMatch(p, /<script>alert|<img src=x|<b>L<\/b>|<i>M<\/i>|<u>T<\/u>|href="javascript:/);
    }
    assert.match(pages[0], /&lt;script&gt;alert\(1\)&lt;\/script&gt;/);
    assert.match(pages[0], /<strong>ok<\/strong>/, 'Markdown still renders');
    assert.match(pages[3], /&lt;b&gt;L&lt;\/b&gt;/);
  });

  test('application users and signed-out visitors cannot reach Team Development', async () => {
    const u = await as('demo');
    for (const url of ['/builder/team', `/builder/team/issues/${issueB}`, '/builder/team/board', '/builder/team/labels', '/builder/team/setup']) {
      const res = await u.get(url);
      assert.equal(res.statusCode, 302, url);
      assert.match(String(res.headers.location), /^\/builder\/login/);
    }
    const res = await u.post('/builder/team/issues', { __csrf: u.lastCsrf, title: 'from an app user' });
    assert.notEqual(res.statusCode, 303);
    assert.equal((await owner.one(`select count(*)::int as n from meta.team_issue where title = 'from an app user'`)).n, 0);
    assert.equal((await new Browser().get('/builder/team')).statusCode, 302);
    // a developer without a workspace gets no Team Development
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ('sec113none', meta.hash_password('sec113none'), false) on conflict do nothing`);
    await owner.query(`delete from meta.workspace_member where username = 'sec113none'`);
    try {
      const n = new Browser();
      await n.get('/builder/login');
      await n.post('/builder/login', { __csrf: n.lastCsrf, username: 'sec113none', password: 'sec113none' });
      assert.equal((await n.get('/builder/team')).statusCode, 403);
      assert.equal((await n.get(`/builder/team/issues/${issueB}`)).statusCode, 403);
    } finally {
      await owner.query(`delete from meta.developer where username = 'sec113none'`);
    }
  });
});

describe('sprint 114 WS-6', () => {
  // (123) workflows and approvals: migrating running instances, custom outcomes, task events, drafts, the SVG export.
  // The HR example's SALARY_CHANGE (part 67): version 2 active, version 3 in development with a draft step.
  const DEV = 'sec114dev';
  const WS = 'Sec114 ws';
  let defId = 0;
  let salBefore = '';
  const dev = async (user = 'admin', password = 'admin') => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username: user, password });
    return b;
  };
  const inApp = (user: string, sql: string, params: unknown[] = [], app = appId) =>
    owner.tx(async (c) => {
      await c.query(`select set_config('pgkiln.app_id', $1, true), set_config('pgkiln.app_user', $2, true)`, [String(app), user]);
      return (await c.query(sql, params)).rows[0];
    });
  const settle = async (id: string) => {
    const { runWorkflows } = await import('../src/workflow.ts');
    for (let i = 0; i < 20; i++) {
      await runWorkflows();
      if ((await owner.one('select state from meta.workflow where id = $1', [id]))?.state !== 'active') return;
    }
  };
  const cleanup = async () => {
    await owner.query(`delete from meta.task where app_id = $1 and (definition_id in (select id from meta.task_definition where app_id = $1 and name in ('SALARY_DECISION', 'SEC114_EVENTS'))
                         or workflow_id in (select id from meta.workflow where name = 'SALARY_CHANGE'))`, [appId]);
    await owner.query(`delete from meta.workflow where app_id = $1 and name = 'SALARY_CHANGE'`, [appId]);
    await owner.query(`delete from meta.workflow_definition where app_id = $1 and name = 'SEC114_XSS'`, [appId]);
    await owner.query(`delete from meta.task_definition where app_id = $1 and name = 'SEC114_EVENTS'`, [appId]);
    await owner.query(`delete from meta.app where alias = 'sec114-copy'`);
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('delete from meta.workspace where name = $1', [WS]);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    if (salBefore) await owner.query('update hr.emp set sal = $1 where empno = 7499', [salBefore]);
  };
  /** A running SALARY_CHANGE instance at APPROVE, as if started under version 1. */
  const v1Instance = async () => {
    const id = (await inApp('blake', `select meta.start_workflow('SALARY_CHANGE', '7499', '{"ENAME": "Allen", "NEW_SAL": 1700}') as id`)).id as string;
    await settle(id);
    await owner.query(`update meta.workflow w set version = '1', steps = (select x->'steps' from meta.workflow_definition d, jsonb_array_elements(d.inactive_versions) x
                        where d.id = w.definition_id and x->>'version' = '1') where w.id = $1`, [id]);
    return id;
  };
  const state = (id: string) => owner.one('select version, current_step, steps, state from meta.workflow where id = $1', [id]);

  before(async () => {
    defId = (await owner.one(`select id from meta.workflow_definition where app_id = $1 and name = 'SALARY_CHANGE'`, [appId])).id;
    salBefore = (await owner.one('select sal::text from hr.emp where empno = 7499')).sal;
    await cleanup();
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false)`, [DEV]);
    // the developer works in the new workspace only
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    const ws = (await owner.one('insert into meta.workspace (name) values ($1) returning id', [WS])).id;
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [ws, DEV]);
  });
  after(cleanup);

  test('migration: developers of the application only, with CSRF; unmapped steps and other applications\' workflows are refused', async () => {
    const id = await v1Instance();
    const url = `/builder/apps/${appId}/shared/workflow_definition/${defId}/migrate`;
    const form = { to: '2', wf: id, 'm.APPROVE': 'APPROVE' };
    // not a developer: the application's own users, and nobody
    const king = await as('king');
    for (const b of [new Browser(), king]) {
      assert.equal((await b.get(url)).headers.location, '/builder/login');
      assert.equal((await b.post(url, { __csrf: b.lastCsrf, ...form })).headers.location, '/builder/login');
    }
    // a developer of another workspace: the application doesn't exist
    const outsider = await dev(DEV, DEV);
    assert.equal((await outsider.get(url)).statusCode, 404);
    await outsider.get('/builder');
    assert.equal((await outsider.post(url, { __csrf: outsider.lastCsrf, ...form })).statusCode, 404);
    // CSRF
    const a = await dev();
    await a.get(url);
    assert.equal((await a.post(url, { __csrf: 'forged', ...form })).statusCode, 403);
    assert.equal((await state(id)).version, '1');
    // the definition through another application's URL
    assert.equal((await a.post(`/builder/apps/${appId + 100000}/shared/workflow_definition/${defId}/migrate`, { __csrf: a.lastCsrf, ...form })).statusCode, 404);
    // no mapping (or a mapping to a step that doesn't exist, or a smuggled name): nothing moves
    for (const m of ['', 'NOPE', 'APPROVE"; drop table meta.workflow; --'])
      await a.post(url, { __csrf: a.lastCsrf, ...form, 'm.APPROVE': m });
    assert.deepEqual([(await state(id)).version, (await state(id)).current_step], ['1', 'APPROVE']);
    // a workflow of another application (a copy of HR) in the list: nothing moves, not even the own one
    const copy = (await owner.one(`select meta.import_app(meta.export_app('hr'), 'sec114-copy') as id`)).id;
    const foreign = (await inApp('blake', `select meta.start_workflow('SALARY_CHANGE', '7499', '{"ENAME": "Allen", "NEW_SAL": 1}') as id`, [], copy)).id;
    await owner.query(`update meta.workflow set version = '1' where id = $1`, [foreign]);
    await a.post(url, { __csrf: a.lastCsrf, ...form, wf: [id, foreign] });
    assert.equal((await state(id)).version, '1');
    assert.equal((await state(foreign)).version, '1');
    const rows = (await owner.query(`select workflow_id::text, problem from meta.migrate_workflows($1, '2', $2::bigint[], '{"APPROVE": "APPROVE"}', false, 'x')`, [defId, [id, foreign]])).rows;
    assert.deepEqual(rows.map((r) => [r.workflow_id, r.problem]), [[id, null], [String(foreign), 'not an instance of this workflow']]);
    // the function is the owner's: applications can't call it
    assert.equal((await owner.one(`select has_function_privilege('pgkiln_runtime', 'meta.migrate_workflows(int, text, bigint[], jsonb, boolean, text)', 'execute') as ok`)).ok, false);
    assert.equal((await owner.one(`select has_function_privilege('hr_app', 'meta.migrate_workflows(int, text, bigint[], jsonb, boolean, text)', 'execute') as ok`)).ok, false);
    // the right request moves it
    assert.equal((await a.post(url, { __csrf: a.lastCsrf, ...form })).statusCode, 303);
    assert.deepEqual([(await state(id)).version, (await state(id)).current_step], ['2', 'APPROVE']);
  });

  test('outcomes come from the task definition only: unknown ones, injected ones and the type\'s own are refused', async () => {
    // king is also a named owner, so meta.complete_task from SQL (without a session's roles) gets past the rights check
    const t = (await inApp('blake', `select meta.create_task('SALARY_DECISION', '7499', '{"ENAME": "Allen", "NEW_SAL": 1}', array['king']) as id`)).id as string;
    const king = await as('king');
    const post = async (b: Browser, action: string) => {
      await b.get('/a/hr/14');
      return b.post(`/a/hr/tasks/${t}`, { __csrf: b.lastCsrf, next: '/a/hr/14', action });
    };
    for (const action of ['outcome:maybe', 'outcome:cancelled', 'outcome:expired', 'approve', 'reject', 'complete', "outcome:yes' or '1'='1", 'outcome:<b>x</b>', 'outcome:'])
      await post(king, action);
    assert.deepEqual(await owner.one('select state, outcome from meta.task where id = $1', [t]), { state: 'unassigned', outcome: null });
    assert.equal((await owner.one(`select count(*)::int as n from meta.task_event where task_id = $1 and event <> 'created'`, [t])).n, 0);
    // someone who may not act on it: refused, whatever the outcome
    await post(await as('allen'), 'outcome:yes');
    await post(await as('blake'), 'outcome:yes');
    assert.equal((await owner.one('select state from meta.task where id = $1', [t])).state, 'unassigned');
    // CSRF
    await king.get('/a/hr/14');
    await king.post(`/a/hr/tasks/${t}`, { __csrf: 'forged', next: '/a/hr/14', action: 'outcome:yes' });
    assert.equal((await owner.one('select state from meta.task where id = $1', [t])).state, 'unassigned');
    // the database refuses an outcome the definition doesn't have, from SQL too
    await assert.rejects(inApp('king', `select meta.complete_task($1, 'maybe')`, [t]), /cannot end as maybe/);
    await post(king, 'outcome:YES');
    assert.deepEqual(await owner.one('select state, outcome from meta.task where id = $1', [t]), { state: 'completed', outcome: 'yes' });
  });

  test('event SQL runs as the application\'s role: after the commit (complete) and in the request (fail)', async () => {
    const { runTaskHooks } = await import('../src/task-events.ts');
    await owner.query(`insert into meta.task_definition (app_id, name, type, subject, owner_roles, action_code, events) values ($1, 'SEC114_EVENTS', 'action', 'sec114 &N.', '{admin}',
      'select 1 / (:N::int - 2)',
      '[{"on": "complete", "type": "sql", "code": "delete from meta.task_hook"}, {"on": "fail", "type": "sql", "code": "delete from meta.task where app_id = :TASK_ID::int * 0 + 1"}]')`, [appId]);
    const create = async (n: number) => (await inApp('blake', `select meta.create_task('SEC114_EVENTS', null, $1) as id`, [{ N: n }])).id as string;
    const king = await as('king');
    const t1 = await create(1);
    await king.get('/a/hr/14');
    await king.post(`/a/hr/tasks/${t1}`, { __csrf: king.lastCsrf, next: '/a/hr/14', action: 'complete' });
    assert.equal((await owner.one('select state from meta.task where id = $1', [t1])).state, 'completed');
    const before = (await owner.one('select count(*)::int as n from meta.task_hook')).n;
    await runTaskHooks();
    const h = await owner.one(`select error from meta.task_hook where task_id = $1 and event = 'complete'`, [t1]);
    assert.match(h.error, /permission denied for table task_hook/);
    assert.ok((await owner.one('select count(*)::int as n from meta.task_hook')).n >= before, 'nothing was deleted');
    // fail: the fail SQL can't touch pgkiln's tables either; the request fails as a whole
    const tasks = (await owner.one('select count(*)::int as n from meta.task where app_id = $1', [appId])).n;
    const t2 = await create(2);
    await king.get('/a/hr/14');
    await king.post(`/a/hr/tasks/${t2}`, { __csrf: king.lastCsrf, next: '/a/hr/14', action: 'complete' });
    assert.equal((await owner.one('select state from meta.task where id = $1', [t2])).state, 'unassigned');
    assert.equal((await owner.one('select count(*)::int as n from meta.task where app_id = $1', [appId])).n, tasks + 1);
    // the outbox and the account addresses are closed to applications
    for (const f of ['meta.task_addresses(bigint, boolean, boolean)']) assert.equal((await owner.one(`select has_function_privilege('hr_app', $1, 'execute') as ok`, [f])).ok, false, f);
    assert.equal((await owner.one(`select has_table_privilege('hr_app', 'meta.task_hook', 'select') as ok`)).ok, false);
  });

  test('draft versions can\'t be activated: not in the builder, not with SQL, not into the active steps', async () => {
    const a = await dev();
    const url = `/builder/apps/${appId}/shared?c=workflow_definition-${defId}`;
    await a.get(url);
    await a.post(`/builder/apps/${appId}/shared/workflow_definition/${defId}/versions`, { __csrf: a.lastCsrf, action: 'activate' });
    const d = await owner.one('select version, dev_version from meta.workflow_definition where id = $1', [defId]);
    assert.deepEqual(d, { version: '2', dev_version: '3' });
    await assert.rejects(owner.query('select meta.activate_workflow_version($1)', [defId]), /draft steps/);
    await assert.rejects(owner.query('update meta.workflow_definition set steps = dev_steps where id = $1', [defId]), /workflow_definition_no_draft/);
    assert.equal((await owner.one(`select has_function_privilege('hr_app', 'meta.activate_workflow_version(int)', 'execute') as ok`)).ok, false);
    // a migration doesn't reach a development version either
    await assert.rejects(owner.query(`select * from meta.migrate_workflows($1, '3', '{1}', '{}', false, 'x')`, [defId]), /has no version 3 to migrate to/);
  });

  test('the SVG export: developers only, a file (attachment, sandboxed), labels escaped', async () => {
    const bad = '</text><script>alert(1)</script><text>';
    await owner.query(`insert into meta.workflow_definition (app_id, name, title, steps) values ($1, 'SEC114_XSS', 'x', $2)`, [appId, JSON.stringify([
      { name: `A${bad}`, type: 'switch', cases: [{ when: `1 = 1 ${bad}`, next: 'B' }, { outcome: `<img src=x onerror=alert(1)>`, next: 'B' }] },
      { name: 'B', type: 'draft_x' },
      { name: 'C', type: 'send_mail', to: 'x@example.com', template: `<script>alert(2)</script>` },
      { name: `D\u0001\u0008]]>`, type: 'end' },
    ])]);
    const id = (await owner.one(`select id from meta.workflow_definition where app_id = $1 and name = 'SEC114_XSS'`, [appId])).id;
    const url = `/builder/apps/${appId}/shared/workflow_definition/${id}/diagram.svg`;
    assert.equal((await new Browser().get(url)).headers.location, '/builder/login');
    assert.equal((await (await as('king')).get(url)).headers.location, '/builder/login');
    assert.equal((await (await dev(DEV, DEV)).get(url)).statusCode, 404);
    const a = await dev();
    assert.equal((await a.get(`/builder/apps/${appId + 100000}/shared/workflow_definition/${id}/diagram.svg`)).statusCode, 404);
    const res = await a.get(url);
    assert.equal(res.statusCode, 200);
    assert.match(String(res.headers['content-disposition']), /^attachment; filename="sec114_xss-v1\.svg"$/);
    assert.match(String(res.headers['content-security-policy']), /default-src 'none'.*sandbox/);
    assert.equal(res.headers['x-content-type-options'], 'nosniff');
    assert.doesNotMatch(res.body, /<script|<img|onerror=alert\(1\)>/i);
    assert.match(res.body, /&lt;\/text&gt;&lt;script&gt;alert\(1\)&lt;\/script&gt;/);
    assert.doesNotMatch(res.body, /[\u0001\u0008]/, 'no control characters in the XML');
    // well-formed: every tag the export opens it closes
    assert.equal((res.body.match(/<text\b/g) ?? []).length, (res.body.match(/<\/text>/g) ?? []).length);
  });
});

describe('sprint 115 WS-11', () => {
  // HR page 47 (examples/hr/hr_68_component_details.sql): the popup LOV's endless paging, the wait
  // popup's message, menu entries that run dynamic actions
  let pageId: number;
  const made: number[] = [];
  const meta47 = (body: string) => JSON.parse(/<script type="application\/json" id="pgkiln-meta">([\s\S]*?)<\/script>/.exec(body)![1]);
  before(async () => {
    pageId = (await owner.one('select id from meta.page where app_id = $1 and page_no = 47', [appId])).id;
  });
  after(async () => {
    for (const id of made) await owner.query('delete from meta.dynamic_action where id = $1', [id]);
    await owner.query(`update meta.button set menu = $2 where page_id = $1 and name = 'ACTIONS'`, [pageId, JSON.stringify([
      { label: 'Count employees', action: 'COUNT', icon: 'users' }, { label: 'Say hello', action: 'HELLO', icon: 'bell' }, { label: 'Pick an employee', page: 26, icon: 'search' }])]);
  });

  test('the popup LOV search: CSRF, a page size and a page number capped, the term a bind', async () => {
    const b = await as('king');
    await b.get('/a/hr/47');
    assert.equal((await b.post('/a/hr/47/lov/P47_REF/search', { __csrf: 'wrong', q: '', p: '0' })).statusCode, 403);
    const big = await b.post('/a/hr/47/lov/P47_REF/search', { __csrf: b.lastCsrf, q: '', p: '0', n: '100000' });
    assert.equal(JSON.parse(big.body).rows.length, 100, 'at most 100 a page');
    const far = await b.post('/a/hr/47/lov/P47_REF/search', { __csrf: b.lastCsrf, q: '', p: '999999999999' });
    assert.equal(far.statusCode, 200);
    assert.deepEqual(JSON.parse(far.body).rows, []);
    const inj = await b.post('/a/hr/47/lov/P47_REF/search', { __csrf: b.lastCsrf, q: `%' or 1=1 --`, p: '0' });
    assert.equal(inj.statusCode, 200);
    assert.deepEqual(JSON.parse(inj.body).rows, []);
    const anon = new Browser();
    await anon.get('/a/hr/47');
    assert.notEqual((await anon.post('/a/hr/47/lov/P47_REF/search', { __csrf: anon.lastCsrf, q: '', p: '1' })).statusCode, 200);
  });

  test('a wait popup message cannot break out of the page data (it is shown as text)', async () => {
    made.push((await owner.one(`insert into meta.dynamic_action (page_id, seq, name, event, trigger_element, action, message)
      values ($1, 990, 'sec wait', 'click', 'CHECK', 'wait_popup', $2) returning id`, [pageId, '</script><script>alert(1)</script><img src=x onerror=alert(2)>'])).id);
    const body = (await (await as('king')).get('/a/hr/47')).body;
    assert.ok(!body.includes('<script>alert(1)'));
    assert.ok(!body.includes('<img src=x onerror'));
    assert.equal(meta47(body).das.find((d: any) => d.id === made.at(-1)).message, '</script><script>alert(1)</script><img src=x onerror=alert(2)>');
  });

  test('a menu_entry dynamic action with an authorization the user lacks is neither sent nor run', async () => {
    const id = (await owner.one(`insert into meta.dynamic_action (page_id, seq, name, event, trigger_element, action, code, affected_items, authz)
      values ($1, 991, 'sec menu', 'menu_entry', 'COUNT', 'execute_sql', 'select ''leak'' as p47_result', 'P47_RESULT', 'ADMIN') returning id`, [pageId])).id;
    made.push(id);
    const allen = await as('allen');
    const body = (await allen.get('/a/hr/47')).body;
    assert.ok(!meta47(body).das.some((d: any) => d.id === id));
    const res = await allen.post(`/a/hr/47/da/${id}`, { __csrf: allen.lastCsrf });
    assert.equal(res.statusCode, 403);
    assert.doesNotMatch(res.body, /leak/);
    const king = await as('king');
    await king.get('/a/hr/47');
    assert.equal(JSON.parse((await king.post(`/a/hr/47/da/${id}`, { __csrf: king.lastCsrf })).body).items.P47_RESULT, 'leak');
  });

  test('menu entries: an entry the user may not use is left out; labels are escaped; the database refuses a crafted action', async () => {
    await owner.query(`update meta.button set menu = $2 where page_id = $1 and name = 'ACTIONS'`, [pageId, JSON.stringify([
      { label: '<img src=x onerror=alert(1)>', action: 'HELLO' }, { label: 'Admins only', action: 'COUNT', authz: 'ADMIN' }])]);
    const allen = (await (await as('allen')).get('/a/hr/47')).body;
    assert.ok(!allen.includes('<img src=x onerror'));
    assert.match(allen, /data-menu-entry="HELLO">&lt;img src=x onerror=alert\(1\)&gt;/);
    assert.ok(!allen.includes('data-menu-entry="COUNT"'), 'not for allen');
    assert.match((await (await as('king')).get('/a/hr/47')).body, /data-menu-entry="COUNT"/);
    for (const action of ['X" onclick="alert(1)', 'x', 'A B', '', 'A'.repeat(61)])
      await assert.rejects(owner.query(`update meta.button set menu = $2 where page_id = $1 and name = 'ACTIONS'`, [pageId, JSON.stringify([{ label: 'x', action }])]), /button_menu_ok|check constraint/, action);
  });
});

describe('sprint 116 WS-12', () => {
  // The App Builder list's Updated by, working copies and lock (meta.app_change, migration 125): recorded only for a
  // builder POST that passed developer() (sign-in, CSRF, workspace, locks) and succeeded; names are escaped; the
  // table is closed to the runtime and not exported.
  const DEV = 'sec116dev';
  let wsB: number;
  let appA: number;
  let appB: number;
  let pageA: number;
  let pageB: number;
  const signIn = async (username: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    assert.equal((await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username })).statusCode, 303);
    await b.get('/builder/apps?view=report');
    return b;
  };
  const changedBy = async (id: number) => (await owner.one('select updated_by from meta.app_change where app_id = $1', [id]))?.updated_by;
  const region = (b: Browser, page: number, csrf = b.lastCsrf) =>
    b.post(`/builder/pages/${page}/c/region`, { __csrf: csrf, title: 'sec116', type: 'static', columns: '12', template: 'standard', config: '' });
  before(async () => {
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [DEV]);
    await owner.query(`delete from meta.app where alias in ('sec116a', 'sec116b')`);
    await owner.query(`delete from meta.workspace where name = 'Sec116 B'`);
    wsB = (await owner.one(`insert into meta.workspace (name) values ('Sec116 B') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values (1, $1)', [DEV]);
    appA = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('sec116a', 'Sec116 A', 'none', 'hr_app') returning id`)).id;
    appB = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('sec116b', 'Sec116 B', 'none', 'hr_app') returning id`)).id;
    await owner.query('insert into meta.workspace_app (app_id, workspace_id) values ($1, $2)', [appB, wsB]);
    pageA = (await owner.one(`insert into meta.page (app_id, page_no, name, title) values ($1, 1, 'Home', 'Home') returning id`, [appA])).id;
    pageB = (await owner.one(`insert into meta.page (app_id, page_no, name, title) values ($1, 1, 'Home', 'Home') returning id`, [appB])).id;
  });
  after(async () => {
    await owner.query(`delete from meta.app where alias in ('sec116a', 'sec116b')`);
    await owner.query(`delete from meta.workspace where name = 'Sec116 B'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
  });

  test('no record without sign-in, with a forged CSRF token, for another workspace or past another developer\'s lock', async () => {
    const anon = new Browser();
    await anon.get('/builder/login');
    assert.equal((await region(anon, pageA, anon.lastCsrf)).statusCode, 302);
    const dev = await signIn(DEV);
    assert.equal((await region(dev, pageA, 'forged')).statusCode, 403);
    assert.equal((await region(dev, pageB)).statusCode, 404);
    assert.equal((await dev.post('/builder/working-copies', { __csrf: dev.lastCsrf, main_app_id: String(appB), name: 'x' })).statusCode, 404);
    await owner.query(`insert into meta.builder_lock (app_id, page_no, locked_by) values ($1, 0, 'admin')`, [appA]);
    await region(dev, pageA);
    assert.equal(await changedBy(appA), undefined);
    assert.equal(await changedBy(appB), undefined);
    await owner.query('delete from meta.builder_lock where app_id = $1', [appA]);
    assert.equal((await region(dev, pageA)).statusCode, 303);
    assert.equal(await changedBy(appA), DEV);
  });

  test('builder POSTs that neither change nor create an application record nothing', async () => {
    const dev = await signIn(DEV);
    // pinning an application or switching workspaces is not a change, whatever the request names or where it redirects
    await owner.query('delete from meta.app_change where app_id = $1', [appA]);
    await dev.post('/builder/pins', { __csrf: dev.lastCsrf, app: String(appA) });
    await dev.post('/builder/workspace', { __csrf: dev.lastCsrf, workspace: '1' });
    assert.equal(await changedBy(appA), undefined);
  });

  test('names are escaped in the report, the cards and the lock label; another workspace\'s application is not listed', async () => {
    const evil = '<img src=x onerror=alert(1)>';
    await owner.query(`insert into meta.app_change (app_id, updated_by) values ($1, $2) on conflict (app_id) do update set updated_by = $2`, [appA, evil]);
    await owner.query(`insert into meta.app_change (app_id, updated_by) values ($1, 'secret-b-dev') on conflict (app_id) do update set updated_by = 'secret-b-dev'`, [appB]);
    await owner.query(`insert into meta.builder_lock (app_id, page_no, locked_by) values ($1, 0, $2)`, [appA, `${evil}"x`]);
    const dev = await signIn(DEV);
    for (const view of ['report', 'grid']) {
      const body = (await dev.get(`/builder/apps?q=sec116&view=${view}`)).body;
      assert.ok(!body.includes('<img src=x'), view);
      assert.ok(body.includes('&lt;img src=x onerror=alert(1)&gt;'), view);
      assert.ok(!body.includes('secret-b-dev') && !body.includes('Sec116 B'), view);
    }
    assert.match((await dev.get('/builder/apps?q=sec116&view=report')).body, /aria-label="Locked by &lt;img src=x onerror=alert\(1\)&gt;&quot;x"/);
    await owner.query('delete from meta.builder_lock where app_id = $1', [appA]);
    await dev.get('/builder/apps?view=report');
  });

  test('meta.app_change is closed to the runtime and is not part of an export', async () => {
    await assert.rejects(runtime.query('select * from meta.app_change'), /permission denied/);
    assert.ok(!JSON.stringify((await owner.one(`select meta.export_app('sec116a') as d`)).d).includes('updated_by'));
  });
});

describe('sprint 117 WS-10', () => {
  // Theme Roller: the navigation appearance (Pillar Light / Dark) and the header strip colours.
  // Only keys of a fixed list and #rrggbb reach the page (a <body> class, the nonce'd <style>).
  let original: unknown;
  const dev = async () => {
    const d = new Browser();
    await d.get('/builder/login');
    await d.post('/builder/login', { __csrf: d.lastCsrf, username: 'admin', password: 'admin' });
    await d.get(`/builder/apps/${appId}/theme`);
    return d;
  };
  const theme = async () => (await owner.one('select theme from meta.app where id = $1', [appId])).theme;
  before(async () => {
    original = await theme();
  });
  after(async () => {
    await owner.query('update meta.app set theme = $2 where id = $1', [appId, JSON.stringify(original)]);
  });

  test('only a developer with a valid CSRF token changes the appearance', async () => {
    await owner.query(`update meta.app set theme = theme - 'appearance' where id = $1`, [appId]);
    const anon = new Browser();
    await anon.get('/builder/login');
    const r = await anon.post(`/builder/apps/${appId}/theme/settings`, { __csrf: anon.lastCsrf, appearance: 'pillar_dark' });
    assert.notEqual(r.statusCode, 200);
    const king = await as('king');
    await king.post(`/builder/apps/${appId}/theme/settings`, { __csrf: king.lastCsrf, appearance: 'pillar_dark' });
    const d = await dev();
    const bad = await d.post(`/builder/apps/${appId}/theme/settings`, { __csrf: 'wrong', appearance: 'pillar_dark' });
    assert.equal(bad.statusCode, 403);
    assert.equal((await theme()).appearance, undefined, 'nothing changed');
    await d.post(`/builder/apps/${appId}/theme/settings`, { __csrf: d.lastCsrf, appearance: 'pillar_dark' });
    assert.equal((await theme()).appearance, 'pillar_dark');
  });

  test('appearance and strip values outside the fixed lists are refused on save', async () => {
    const d = await dev();
    await owner.query(`update meta.app set theme = theme - 'appearance' - 'strip' where id = $1`, [appId]);
    for (const appearance of ['toString', '__proto__', 'pillar_dark" onload="x', 'default'])
      await d.post(`/builder/apps/${appId}/theme/settings`, { __csrf: d.lastCsrf, appearance });
    for (const strip of ['red', '#fff;}body{display:none', 'url(https://evil.example/x)'])
      await d.post(`/builder/apps/${appId}/theme/settings`, { __csrf: d.lastCsrf, strip, strip_own: 'true' });
    const t = await theme();
    assert.equal(t.appearance, undefined);
    assert.equal(t.strip, undefined);
    // a style's appearance and strip go through parseStyle
    await d.post(`/builder/apps/${appId}/theme/styles`, { __csrf: d.lastCsrf, name: 'Sec117', appearance: 'constructor' });
    await d.post(`/builder/apps/${appId}/theme/styles`, { __csrf: d.lastCsrf, name: 'Sec117', strip: '#000;}*{x:y', strip_own: 'true' });
    assert.ok(!JSON.stringify((await theme()).styles ?? []).includes('Sec117'));
  });

  test('a hand-edited theme cannot put markup or CSS into the page', async () => {
    await owner.query('update meta.app set theme = $2 where id = $1', [appId, JSON.stringify({
      ...(original as object), appearance: 'pillar_dark"><script>alert(1)</script>', strip: '#000;}body{display:none}',
      strip_dark: 'red', styles: [{ name: 'Evil', appearance: 'x" onmouseover="alert(1)', strip: '&P1_X.' }], style: 'Evil' })]);
    const body = (await (await as('king')).get('/a/hr/1')).body;
    assert.ok(!body.includes('<script>alert(1)'));
    assert.ok(!body.includes('onmouseover'));
    assert.ok(!body.includes('display:none}'));
    assert.doesNotMatch(body, /<body[^>]*nav-pillar/, 'unknown appearances are ignored');
    const css = /<style nonce="[^"]+" id="pgkiln-css">([\s\S]*?)<\/style>/.exec(body)?.[1] ?? '';
    assert.doesNotMatch(css, /--strip/);
  });

  test('a strip colour from an item is used only when the value is #rrggbb', async () => {
    await owner.query('update meta.app set theme = $2 where id = $1', [appId, JSON.stringify({
      ...(original as object), styles: [{ name: 'Item strip', appearance: 'pillar_light', strip: '&APP_SEC117.' }], style: 'Item strip' })]);
    const king = await as('king');
    const page = (await king.get('/a/hr/1')).body;
    assert.match(page, /<body[^>]*class="[^"]*nav-pillar nav-pillar-light/);
    const css = /<style nonce="[^"]+" id="pgkiln-css">([\s\S]*?)<\/style>/.exec(page)?.[1] ?? '';
    assert.doesNotMatch(css, /--strip/, 'no value, no strip');
  });
});

describe('sprint 118 WS-9', () => {
  // Administration → Mail queue (who sees which mail, Retry / Purge only in scope), a workspace's own mail service
  // (workspace administrators only, write-only secret, no base or token URL, its SMTP host checked like a web request),
  // and a workspace's network access list, enforced on the server on every outgoing path: it only narrows the
  // installation's list, redirects and the response cache don't escape it, and refusals are logged.
  const http = () => import('node:http');
  const WSA = 'Sec118 A';
  const WSB = 'Sec118 B';
  const ADMIN_A = 'sec118admina';
  const ADMIN_B = 'sec118adminb';
  const DEV_A = 'sec118deva';
  let wsA: number;
  let wsB: number;
  let appA: number;
  let appB: number;
  let server: import('node:http').Server;
  let base = '';
  let port = 0;
  const hits: string[] = [];
  const env = { allowed: process.env.PGKILN_REST_ALLOWED_HOSTS, priv: process.env.PGKILN_REST_PRIVATE_HOSTS };
  const signIn = async (username: string, ws?: number) => {
    const b = new Browser();
    await b.get('/builder/login');
    assert.equal((await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username })).statusCode, 303);
    await b.get('/builder/home');
    if (ws) assert.equal((await b.post('/builder/workspace', { __csrf: b.lastCsrf, workspace: String(ws) })).statusCode, 303);
    await b.get('/builder/home');
    return b;
  };
  const restrict = (ws: number, hosts: string[] | null) =>
    owner.query('update meta.workspace set network_restricted = $2, network_hosts = $3 where id = $1', [ws, hosts !== null, hosts ?? []]);
  const source = (over: Record<string, unknown> = {}) => ({
    id: 0, app_id: appA, name: 'SEC118', url: `${base}/data`, method: 'GET', credential: null, headers: {}, body: null, row_selector: null,
    params: [], columns: [], cache_seconds: 0, timeout_s: 5, max_rows: 10, ...over,
  }) as any;

  before(async () => {
    const { createServer } = await http();
    server = createServer((req, res) => {
      hits.push(req.url!);
      if (req.url === '/away') {
        res.writeHead(302, { location: `http://localhost:${port}/data` });
        return res.end();
      }
      if (req.url === '/token') {
        res.writeHead(200, { 'content-type': 'application/json' });
        return res.end('{"access_token":"t","expires_in":60}');
      }
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end('{"items":[{"v":1}],"openapi":"3.0.0","info":{"title":"x","version":"1"},"paths":{}}');
    });
    await new Promise<void>((r) => server.listen(0, '127.0.0.1', r));
    port = (server.address() as import('node:net').AddressInfo).port;
    base = `http://127.0.0.1:${port}`;
    process.env.PGKILN_REST_ALLOWED_HOSTS = '127.0.0.1,localhost';
    process.env.PGKILN_REST_PRIVATE_HOSTS = '127.0.0.1,localhost';
    for (const u of [ADMIN_A, ADMIN_B, DEV_A]) await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [u]);
    await owner.query(`delete from meta.app where alias in ('sec118a', 'sec118b')`);
    await owner.query('delete from meta.workspace where name = any($1)', [[WSA, WSB]]);
    wsA = (await owner.one(`insert into meta.workspace (name) values ($1) returning id`, [WSA])).id;
    wsB = (await owner.one(`insert into meta.workspace (name) values ($1) returning id`, [WSB])).id;
    await owner.query('delete from meta.workspace_member where username = any($1::text[])', [[ADMIN_A, ADMIN_B, DEV_A]]);
    await owner.query('insert into meta.workspace_member (workspace_id, username, is_admin) values ($1, $2, true), ($1, $3, false), ($4, $5, true)', [wsA, ADMIN_A, DEV_A, wsB, ADMIN_B]);
    appA = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('sec118a', 'Sec118 A app', 'none', 'hr_app') returning id`)).id;
    appB = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('sec118b', 'Sec118 B app', 'none', 'hr_app') returning id`)).id;
    await owner.query('insert into meta.workspace_app (app_id, workspace_id) values ($1, $2), ($3, $4)', [appA, wsA, appB, wsB]);
    for (const [a, subject] of [[appA, 'Sec118 mail of A'], [appB, 'Sec118 secret mail of B']] as const)
      await owner.query(`insert into meta.mail_queue (app_id, to_addresses, subject, body_text, status, attempts, message, last_attempt_at)
                         values ($1, '{x@example.com}', $2, 'body text never shown', 'error', 5, '550 5.1.1 refused for ' || $2, now())`, [a, subject]);
  });
  after(async () => {
    server.close();
    process.env.PGKILN_REST_ALLOWED_HOSTS = env.allowed;
    process.env.PGKILN_REST_PRIVATE_HOSTS = env.priv;
    if (env.allowed === undefined) delete process.env.PGKILN_REST_ALLOWED_HOSTS;
    if (env.priv === undefined) delete process.env.PGKILN_REST_PRIVATE_HOSTS;
    await owner.query(`delete from meta.app where alias in ('sec118a', 'sec118b')`);
    await owner.query('delete from meta.workspace where id = any($1::int[])', [[wsA, wsB]]);
    await owner.query('delete from meta.developer where username = any($1::text[])', [[ADMIN_A, ADMIN_B, DEV_A]]);
  });

  test('mail queue: an administrator sees every workspace, a workspace administrator only theirs, a developer nothing; no bodies', async () => {
    const admin = await signIn('admin');
    const all = (await admin.get('/builder/mail-queue')).body;
    assert.match(all, /Sec118 mail of A/);
    assert.match(all, /Sec118 secret mail of B/);
    assert.doesNotMatch(all, /body text never shown/);
    const a = await signIn(ADMIN_A, wsA);
    for (const url of ['/builder/mail-queue', `/builder/mail-queue?ws=${wsB}`, `/builder/mail-queue?app=${appB}`, '/builder/mail-queue?period=168']) {
      const body = (await a.get(url)).body;
      if (!url.includes('app=')) assert.match(body, /Sec118 mail of A/, url);
      assert.doesNotMatch(body, /secret mail of B|Sec118 B app|sec118b/, url);
    }
    const dev = await signIn(DEV_A, wsA);
    const res = await dev.get('/builder/mail-queue');
    assert.equal(res.statusCode, 403);
    assert.doesNotMatch(res.body, /Sec118 mail of A/);
    const mb = (await owner.one(`select id from meta.mail_queue where app_id = $1`, [appB])).id;
    assert.equal((await dev.post(`/builder/mail-queue/${mb}/purge`, { __csrf: dev.lastCsrf })).statusCode, 403);
    assert.equal((await dev.post('/builder/mail-queue/purge', { __csrf: dev.lastCsrf })).statusCode, 403);
  });

  test('mail queue: Retry and Purge only in scope, with the session\'s CSRF token', async () => {
    const mb = (await owner.one(`select id from meta.mail_queue where app_id = $1`, [appB])).id;
    const a = await signIn(ADMIN_A, wsA);
    await a.get('/builder/mail-queue');
    assert.equal((await a.post(`/builder/mail-queue/${mb}/retry`, { __csrf: a.lastCsrf })).statusCode, 404);
    assert.equal((await a.post(`/builder/mail-queue/${mb}/purge`, { __csrf: a.lastCsrf })).statusCode, 404);
    // bulk: ?ws= and ?app= of another workspace are ignored for a workspace administrator
    await a.post(`/builder/mail-queue/purge?ws=${wsB}&app=${appB}`, { __csrf: a.lastCsrf });
    await a.post(`/builder/mail-queue/retry?ws=${wsB}`, { __csrf: a.lastCsrf });
    const b = await owner.one('select status from meta.mail_queue where id = $1', [mb]);
    assert.equal(b?.status, 'error', 'B\'s mail is untouched');
    // (the bulk retry acted on A's own failed mail: set it back)
    const ma = (await owner.one(`select id from meta.mail_queue where app_id = $1`, [appA])).id;
    assert.equal((await owner.one('select status from meta.mail_queue where id = $1', [ma])).status, 'queued');
    await owner.query(`update meta.mail_queue set status = 'error' where id = $1`, [ma]);
    assert.equal((await a.post(`/builder/mail-queue/${ma}/retry`, { __csrf: 'forged' })).statusCode, 403);
    assert.equal((await a.post(`/builder/mail-queue/${ma}/purge`, {})).statusCode, 403);
    assert.equal((await owner.one('select status from meta.mail_queue where id = $1', [ma])).status, 'error');
    assert.equal((await a.post(`/builder/mail-queue/${ma}/retry`, { __csrf: a.lastCsrf })).statusCode, 303);
    assert.equal((await owner.one('select status from meta.mail_queue where id = $1', [ma])).status, 'queued');
    await owner.query(`update meta.mail_queue set status = 'cancelled' where id = $1`, [ma]);
  });

  test('a workspace\'s mail service: its administrators only; the secret is write-only and never exported; no SSRF through it', async () => {
    const a = await signIn(ADMIN_A, wsA);
    const dev = await signIn(DEV_A, wsA);
    const b = await signIn(ADMIN_B, wsB);
    assert.equal((await dev.get(`/builder/workspaces/${wsA}/mail`)).statusCode, 403);
    assert.equal((await b.get(`/builder/workspaces/${wsA}/mail`)).statusCode, 403);
    const form = { provider: 'smtp', host: 'smtp.example.com', port: '587', security: 'starttls', auth: 'password', username: 'u@example.com', senders: '@example.com', enabled: 'true', secret: 'Sec118-SMTP-password' };
    assert.equal((await b.post(`/builder/workspaces/${wsA}/mail`, { __csrf: b.lastCsrf, ...form })).statusCode, 403);
    assert.equal((await dev.post(`/builder/workspaces/${wsA}/mail`, { __csrf: dev.lastCsrf, ...form })).statusCode, 403);
    await a.get(`/builder/workspaces/${wsA}/mail`);
    assert.equal((await a.post(`/builder/workspaces/${wsA}/mail`, { __csrf: 'forged', ...form })).statusCode, 403);
    assert.equal((await a.post(`/builder/workspaces/${wsA}/mail`, { __csrf: a.lastCsrf, ...form, base_url: 'http://169.254.169.254/', token_url: 'http://169.254.169.254/t' })).statusCode, 303);
    const svc = await owner.one('select * from meta.mail_service where workspace_id = $1', [wsA]);
    assert.ok(svc, 'saved');
    assert.ok(!('base_url' in svc.settings) && !('token_url' in svc.settings));
    const page = (await a.get(`/builder/workspaces/${wsA}/mail`)).body;
    assert.doesNotMatch(page, /Sec118-SMTP-password/);
    assert.doesNotMatch(page, new RegExp(svc.secret_enc.slice(0, 20).replace(/[+/]/g, '.')));
    // another workspace's administrator can't delete it; the workspace export and the admin list never carry the secret
    assert.equal((await b.post(`/builder/workspaces/${wsA}/mail/delete`, { __csrf: b.lastCsrf })).statusCode, 403);
    const { exportWorkspace } = await import('../src/workspace-export.ts');
    const doc = JSON.stringify(await exportWorkspace(wsA));
    assert.doesNotMatch(doc, /Sec118-SMTP-password|secret_enc|smtp\.example\.com|network_hosts/);
    const admin = await signIn('admin');
    assert.doesNotMatch((await admin.get('/builder/mail')).body, /Sec118-SMTP-password/);
    // the check uses this workspace's stored secret only, never another service's (service_id is ignored)
    const other = (await owner.one(`insert into meta.mail_service (name, provider, settings, senders, secret_enc) values ('SEC118_INST', 'smtp', '{"host":"127.0.0.1","port":1}', '{@example.com}', $1) returning id`,
      [(await import('../src/secrets.ts')).encryptSecret('installation-secret')])).id;
    try {
      await a.get(`/builder/workspaces/${wsA}/mail`);
      const r = await a.request('POST', `/builder/workspaces/${wsA}/mail/check`, { __csrf: a.lastCsrf, provider: 'graph', tenant_id: 't', client_id: 'c', senders: '@example.com', service_id: String(other), check: 'connection' });
      assert.match(r.body, /client secret is required/);
    } finally {
      await owner.query('delete from meta.mail_service where id = $1', [other]);
    }
    // a base or token URL written in SQL is refused when sending; a private SMTP address too
    const { serviceSettings } = await import('../src/mail/mail.ts');
    await assert.rejects(serviceSettings({ ...svc, settings: { ...svc.settings, base_url: 'http://169.254.169.254' } }), /no base URL/);
    await assert.rejects(serviceSettings({ ...svc, provider: 'graph', settings: { token_url: 'http://169.254.169.254/t' } }), /no token URL/);
    process.env.PGKILN_REST_ALLOWED_HOSTS = '*';
    try {
      for (const host of ['10.0.0.1', '169.254.169.254', '::ffff:127.0.0.2', 'metadata.google.internal.invalid'])
        await assert.rejects(serviceSettings({ ...svc, settings: { ...svc.settings, host } }), /private|no address|not valid/, host);
    } finally {
      process.env.PGKILN_REST_ALLOWED_HOSTS = '127.0.0.1,localhost';
    }
    await assert.rejects(serviceSettings({ ...svc, settings: { ...svc.settings, host: 'smtp.example.com' } }), /allow-list/);
    await owner.query('delete from meta.mail_service where id = $1', [svc.id]);
  });

  test('network access: only the workspace\'s administrators (or administrators) read and change its list', async () => {
    const a = await signIn(ADMIN_A, wsA);
    const b = await signIn(ADMIN_B, wsB);
    const dev = await signIn(DEV_A, wsA);
    assert.equal((await dev.get('/builder/network')).statusCode, 403);
    assert.equal((await dev.post('/builder/network', { __csrf: dev.lastCsrf, ws: String(wsA), restricted: 'false', hosts: '' })).statusCode, 403);
    assert.equal((await b.get(`/builder/network?ws=${wsA}`)).statusCode, 403);
    assert.equal((await b.post('/builder/network', { __csrf: b.lastCsrf, ws: String(wsA), restricted: 'true', hosts: '' })).statusCode, 403);
    await a.get('/builder/network');
    assert.equal((await a.post('/builder/network', { __csrf: 'forged', ws: String(wsA), restricted: 'true', hosts: '' })).statusCode, 403);
    assert.equal((await owner.one('select network_restricted from meta.workspace where id = $1', [wsA])).network_restricted, false);
    // entries are hosts only: no scheme, path, wildcard-all, injection
    for (const hosts of ['*', 'http://x', 'x/y', 'a.example.com\'; drop table meta.app; --', '<script>'])
      await a.post('/builder/network', { __csrf: a.lastCsrf, ws: String(wsA), restricted: 'true', hosts });
    assert.equal((await owner.one('select network_restricted from meta.workspace where id = $1', [wsA])).network_restricted, false);
    // the refusals of another workspace are not shown
    await owner.query(`insert into meta.network_refusal (workspace_id, app_id, what, host, list) values ($1, $2, 'test', 'b-secret.example', 'workspace')`, [wsB, appB]);
    assert.doesNotMatch((await a.get(`/builder/network?ws=${wsA}`)).body, /b-secret\.example/);
    // the private hosts of the installation are for administrators
    assert.doesNotMatch((await a.get('/builder/network')).body, /Private hosts/);
  });

  test('every outgoing path is narrowed by the workspace\'s list, on the server', async () => {
    const ws = await import('../src/websources.ts');
    const wr = await import('../src/webrequests.ts');
    const { putObject } = await import('../src/objectstore.ts');
    const { encryptSecret } = await import('../src/secrets.ts');
    await restrict(wsA, ['api.example.com']);
    // refusals are written next to the call (never in its way): wait for them
    const refusedNow = async (what: string) => {
      for (let i = 0; i < 25; i++) {
        if (await owner.one(`select 1 from meta.network_refusal where workspace_id = $1 and list = 'workspace' and strpos(what, $2) > 0 and at > now() - interval '1 minute'`, [wsA, what])) return;
        await new Promise((r) => setTimeout(r, 40));
      }
      assert.fail(`no refusal for ${what}`);
    };
    const before = hits.length;
    const NARROW = /network access list of workspace Sec118 A/;
    // REST data source (regions, the assistant, synchronisation), write-back, invoke API (pages, workflows, automations)
    await assert.rejects(ws.fetchSource(source(), {}), NARROW);
    await refusedNow('REST data source SEC118');
    await assert.rejects(ws.callOperation(source({ operations: { insert: { path: '' } } }), 'insert', { v: 1 }), NARROW);
    await assert.rejects(ws.invoke(appA, { url: `${base}/data` }, () => undefined, 'invoke_api'), NARROW);
    await refusedNow('invoke_api');
    await assert.rejects(ws.call({ appId: appA, url: `${base}/data` }), NARROW);
    // meta.web_request and meta.web_request_source (the scheduler's pass; the page-process path is the same execute())
    await owner.query(`insert into meta.rest_source (app_id, name, url, params, columns) values ($1, 'SEC118_SRC', $2, '[]', '[]')`, [appA, `${base}/data`]);
    let r = await wr.execute(appA, { id: '0', source: null, params: null, url: `${base}/data`, method: 'GET', headers: {}, body: null, credential: null, timeout_s: 5 });
    assert.match(r.message ?? '', NARROW);
    r = await wr.execute(appA, { id: '0', source: 'SEC118_SRC', params: {}, url: null, method: 'GET', headers: {}, body: null, credential: null, timeout_s: 5 });
    assert.match(r.message ?? '', NARROW);
    // an OAuth2 credential's token endpoint: refused before any token is asked for, also when only the token host is off the list
    const cred = { id: 0, app_id: appA, name: 'SEC118_OAUTH', type: 'oauth2', username: 'c', header_name: null, token_url: `http://localhost:${port}/token`, scope: null, valid_for: [], secret_enc: encryptSecret('s') } as any;
    await restrict(wsA, [`127.0.0.1:${port}`]);
    await assert.rejects(ws.call({ appId: appA, url: `${base}/data`, credential: cred }), /The host localhost:\d+ is not on the network access list/);
    await refusedNow('token endpoint of web credential SEC118_OAUTH');
    // object storage (file items)
    await owner.query(`insert into meta.web_credential (app_id, name, type, username, scope, secret_enc, valid_for) values ($1, 'SEC118_S3', 'aws_sigv4', 'AKID', 'eu-test-1', $2, '{}')`, [appA, encryptSecret('x')]);
    await assert.rejects(putObject(appA, { url: `http://localhost:${port}/bucket`, credential: 'SEC118_S3' }, 'a.txt', Buffer.from('x'), 'text/plain'), NARROW);
    await refusedNow('object storage');
    // redirects to a host off the list: the second hop is refused
    const n = hits.length;
    await assert.rejects(ws.call({ appId: appA, url: `${base}/away` }), /The host localhost:\d+ is not on the network access list/);
    assert.equal(hits.length, n + 1);
    // the response cache does not outlive a narrowed list
    await restrict(wsA, null);
    await ws.fetchSource(source({ id: 991180, cache_seconds: 600 }), {});
    await restrict(wsA, ['api.example.com']);
    await assert.rejects(ws.fetchSource(source({ id: 991180, cache_seconds: 600 }), {}), NARROW);
    // the builder's Test of a REST data source, and a REST source catalog read from a URL
    await restrict(wsA, ['api.example.com']);
    const a = await signIn(ADMIN_A, wsA);
    const sid = (await owner.one(`select id from meta.rest_source where app_id = $1 and name = 'SEC118_SRC'`, [appA])).id;
    const shared = `/builder/apps/${appA}/shared?c=rest_source-${sid}`;
    await a.get(shared);
    assert.equal((await a.post(`/builder/apps/${appA}/rest-sources/${sid}/test`, { __csrf: a.lastCsrf })).statusCode, 303);
    assert.match((await a.get(shared)).body, /network access list of workspace Sec118 A/);
    await refusedNow('(builder test)');
    await a.get('/builder/rest-catalogs');
    const hitsBefore = hits.length;
    await a.post('/builder/rest-catalogs/import', { __csrf: a.lastCsrf, url: `${base}/openapi.json` });
    assert.match((await a.get('/builder/rest-catalogs')).body, /network access list of workspace Sec118 A/);
    await refusedNow('REST source catalog');
    // other workspaces keep the installation's list
    assert.equal((await ws.call({ appId: appB, url: `${base}/data` })).status, 200);
    // nothing of workspace A reached the server: only B's call and the cached-before fetch and the first redirect hop
    assert.equal(hits.slice(before).filter((h) => h === '/openapi.json').length, 0);
    assert.equal(hits.length, hitsBefore + 1);
    // the workspace's list can't widen the installation's
    await restrict(wsA, ['evil.example', '169.254.169.254', '10.0.0.1']);
    for (const u of ['http://evil.example/', 'http://169.254.169.254/latest/meta-data/', 'http://10.0.0.1/'])
      await assert.rejects(ws.call({ appId: appA, url: u }), /allow-list|private/, u);
    await restrict(wsA, null);
  });

  test('a REST source catalog URL is read only after the developer is checked', async () => {
    const n = hits.length;
    const anon = new Browser();
    await anon.get('/builder/login');
    await anon.post('/builder/rest-catalogs/import', { __csrf: anon.lastCsrf, url: `${base}/openapi.json` });
    await anon.post('/builder/rest-catalogs/1/import', { __csrf: anon.lastCsrf, url: `${base}/openapi.json` });
    assert.equal(hits.length, n, 'no request without a signed-in developer');
  });
});

describe('sprint 119 WS-13', () => {
  // SQL Workshop › a table › Security: GRANT / REVOKE and a masking view, so only a developer with a valid CSRF token
  // may post it, only for tables of the workspace's schemas, and names and roles reach SQL quoted (src/datasec.ts).
  const T = 'ds119sec';
  const dev = async () => {
    const d = new Browser();
    await d.get('/builder/login');
    await d.post('/builder/login', { __csrf: d.lastCsrf, username: 'admin', password: 'admin' });
    await d.ownerConnection(); // (sprint 185) a masking view makes a role: the Owner connection (developer logins can't)
    await d.get(`/builder/sql/objects/security?o=public.${T}`);
    return d;
  };
  before(async () => {
    await owner.query(`drop table if exists public.${T} cascade; create table public.${T} (id int primary key, secret text); grant select on public.${T} to hr_app`);
  });
  after(async () => {
    await owner.query(`drop table if exists public.${T} cascade`);
    if ((await owner.query(`select from pg_roles where rolname = 'public_masking'`)).rowCount) await owner.query('drop owned by public_masking; drop role public_masking');
  });

  test('signed out, without the CSRF token, or on pgkiln\'s own schema: nothing changes', async () => {
    const form = { ref: `public.${T}`, shown_roles: '', 'g.0.s.0': 'on', mode: 'apply' };
    const anon = new Browser();
    const r = await anon.post('/builder/sql/objects/security', form);
    assert.ok([302, 303, 403].includes(r.statusCode), String(r.statusCode));
    const d = await dev();
    assert.equal((await d.post('/builder/sql/objects/security', form)).statusCode, 403, 'no CSRF token');
    assert.equal((await owner.one(`select has_column_privilege('hr_app', 'public.${T}', 'secret', 'select') as ok`)).ok, true);
    assert.equal((await d.get('/builder/sql/objects/security?o=meta.app')).statusCode, 404);
    assert.equal((await d.get('/builder/sql/objects/security?o=pg_catalog.pg_authid')).statusCode, 404);
  });

  test('view names and application roles that could break out of their quotes are refused or quoted', async () => {
    const d = await dev();
    const bad = await d.post('/builder/sql/objects/security', {
      __csrf: d.lastCsrf, ref: `public.${T}`, shown_roles: '', 'g.0.s.0': 'on', 'g.0.s.1': 'on', mode: 'apply',
      view: 'on', view_name: 'v"; drop table x; --', roles: "boss'); drop table x; --",
    });
    assert.equal(bad.statusCode, 200);
    assert.match(bad.body, /needs a name of letters/);
    assert.match(bad.body, /is not a valid application role/);
    assert.equal((await owner.query(`select from pg_class where relname like 'v%drop%'`)).rowCount, 0);
    const ok = await d.post('/builder/sql/objects/security', {
      __csrf: d.lastCsrf, ref: `public.${T}`, shown_roles: 'team lead', 'g.0.s.0': 'on', mode: 'apply',
      view: 'on', view_name: `${T}_masked`, roles: 'team lead', 'm.1.mask': 'stars', 'm.1.see.0': 'on',
    });
    assert.equal(ok.statusCode, 303, ok.body);
    const def = (await owner.one(`select pg_get_viewdef('public.${T}_masked'::regclass) as d`)).d;
    assert.match(def, /has_role\('team lead'::text\)/);
    assert.equal((await owner.one(`select has_column_privilege('hr_app', 'public.${T}', 'secret', 'select') as ok`)).ok, false);
  });
});

describe('sprint 120 WS-8', () => {
  // The App Gallery's sample and utility apps (src/builder/gallery.ts): sample apps run shipped SQL as the owner, so only
  // administrators install them, with the CSRF token, and only entries of gallery.json (by key, never a path); utility
  // apps are blueprints any developer creates in their own workspace after the review; an installed sample is edited
  // only from its own workspace.
  const DEV = 'sec120_dev';
  const DEV_PW = 'Sec120-dev-password!';
  let ws: number;
  let g: typeof import('./gallery-samples.ts');
  const sample = (key: string) => g.SAMPLES.find((x) => x.key === key)!;
  const signIn = async (username: string, password: string) => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    await b.submit('/builder/login', { username, password });
    await b.get('/builder/gallery');
    return b;
  };
  const cleanup = async () => {
    for (const x of g.SAMPLES) await g.dropSample(x);
    for (const x of g.BLUEPRINTS.filter((b) => b.kind === 'utilities')) await g.dropBlueprintApp(x);
    await owner.query(`delete from meta.account where username = 'sec120_owner'`);
    await owner.query(`delete from meta.workspace where name = 'Sec120 Other'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
  };
  before(async () => {
    g = await import('./gallery-samples.ts');
    await cleanup();
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false)`, [DEV, DEV_PW]);
    ws = (await owner.one(`insert into meta.workspace (name) values ('Sec120 Other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2), ($1, $3) on conflict do nothing', [ws, DEV, 'admin']);
  });
  after(async () => {
    await cleanup();
  });

  test('only administrators install sample apps, with the CSRF token; nothing runs otherwise', async () => {
    const d = await signIn(DEV, DEV_PW);
    assert.equal((await d.submit('/builder/gallery/samples/sample-dynamic-actions', {})).statusCode, 403, 'a developer');
    const a = await signIn('admin', 'admin');
    assert.equal((await a.post('/builder/gallery/samples/sample-dynamic-actions', {})).statusCode, 403, 'no CSRF token');
    a.lastCsrf = 'wrong';
    assert.equal((await a.submit('/builder/gallery/samples/sample-dynamic-actions', {})).statusCode, 403, 'a wrong CSRF token');
    assert.equal(await owner.one(`select 1 as ok from meta.app where alias = 'sample-dynamic-actions'`), undefined);
    assert.equal((await owner.query(`select from pg_namespace where nspname = $1`, [sample('sample-dynamic-actions').schema])).rowCount, 0, 'no schema');
    assert.equal((await d.post('/builder/gallery/utilities/lookup-lists', {})).statusCode, 403, 'utility: no CSRF token');
    const anon = new FileBrowser(app);
    assert.notEqual((await anon.post('/builder/gallery/samples/sample-charts', {})).statusCode, 303);
    assert.equal(await owner.one(`select 1 as ok from meta.app where alias = 'sample-charts'`), undefined);
    // application users never reach the gallery
    const king = await as('king');
    assert.notEqual((await king.get('/builder/gallery?tab=utilities')).statusCode, 200);
    assert.notEqual((await king.post('/builder/gallery/utilities/lookup-lists', { __csrf: king.lastCsrf })).statusCode, 200);
  });

  test('keys only name entries of gallery.json, of their own kind; never a path', async () => {
    const a = await signIn('admin', 'admin');
    for (const url of ['/builder/gallery/utilities/nope', '/builder/gallery/utilities/contacts', '/builder/gallery/starters/lookup-lists',
      '/builder/gallery/utilities/..%2Fstarters%2Fcontacts', '/builder/gallery/utilities/%2e%2e', '/builder/gallery/samples/samples%2Fsample-charts',
      '/builder/gallery/samples/sample-charts.sql', '/builder/gallery/samples/lookup-lists', '/builder/gallery/samples/team-tasks'])
      assert.equal((await a.submit(url, {})).statusCode, 404, url);
    // the search is text, escaped, and the tab one of four
    assert.match((await a.get('/builder/gallery?tab=../../etc&q=%22%3E%3Cimg%20src%3Dx%3E')).body, /value="&quot;&gt;&lt;img src=x&gt;"[\s\S]*aria-current="page">Sample Apps/);
  });

  test('a sample is installed into the administrator\'s current workspace and edited only from there', async () => {
    const a = await signIn('admin', 'admin');
    assert.equal((await a.submit('/builder/gallery/samples/sample-dynamic-actions', {})).statusCode, 303);
    const da = await owner.one<{ id: number; ws: number }>(`select id, meta.app_workspace(id) as ws from meta.app where alias = 'sample-dynamic-actions'`);
    assert.equal(da?.ws, 1);
    // the developer of the other workspace: installed, but no Edit, and the App Builder refuses it
    const d = await signIn(DEV, DEV_PW);
    const page = (await d.get('/builder/gallery')).body;
    assert.match(page, /Sample Dynamic Actions<\/h2>[\s\S]*?Installed[\s\S]*?in another workspace/);
    assert.doesNotMatch(page, new RegExp(`href="/builder/apps/${da!.id}"`));
    assert.notEqual((await d.get(`/builder/apps/${da!.id}`)).statusCode, 200);
    // the administrator switches to the other workspace: the next sample goes there
    await a.get('/builder');
    assert.equal((await a.submit('/builder/workspace', { workspace: String(ws) })).statusCode, 303);
    await a.get('/builder/gallery');
    assert.equal((await a.submit('/builder/gallery/samples/sample-reporting', {})).statusCode, 303);
    const rep = await owner.one<{ id: number; ws: number }>(`select id, meta.app_workspace(id) as ws from meta.app where alias = 'sample-reporting'`);
    assert.equal(rep?.ws, ws);
    assert.match((await d.get('/builder/gallery')).body, new RegExp(`href="/builder/apps/${rep!.id}"`), 'its own workspace edits it');
  });

  test('a developer creates a utility app in their own workspace, only after the review', async () => {
    const d = await signIn(DEV, DEV_PW);
    await d.get('/builder/gallery?tab=utilities');
    const review = await d.submit('/builder/gallery/utilities/lookup-lists', {});
    assert.equal(review.statusCode, 200);
    assert.equal(await owner.one(`select 1 as ok from meta.app where alias = 'lookup-lists'`), undefined, 'nothing before the review is confirmed');
    const form = (await import('./helpers.ts')).formFields(/<form method="post" action="\/builder\/blueprints\/create">[\s\S]*?<\/form>/.exec(review.body)![0]);
    // a changed blueprint is not the one the review showed
    const forged = await d.submit('/builder/blueprints/create', { ...form, spec: form.spec.replace('"lookup_lists"', '"meta"'), admin_user: 'sec120_owner', admin_password: 'Sec120-owner-password-1!' });
    assert.notEqual(forged.statusCode, 303);
    assert.equal(await owner.one(`select 1 as ok from meta.app where alias = 'lookup-lists'`), undefined);
    const made = await d.submit('/builder/blueprints/create', { ...form, admin_user: 'sec120_owner', admin_password: 'Sec120-owner-password-1!' });
    assert.equal(made.statusCode, 303, made.body.slice(0, 300));
    assert.equal((await owner.one(`select meta.app_workspace(id) as ws from meta.app where alias = 'lookup-lists'`)).ws, ws);
  });
});


describe('sprint 121 WS-7', () => {
  // The builder's language (src/builder/i18n.ts, language.ts): only the known codes are accepted from the sign-in
  // page's links (?lang=), the cookie and the status bar's menu (a CSRF-checked post); a developer's choice is theirs
  // alone; translated texts are plain text, escaped like any value, and tx.rich() escapes its message and parameters.
  const A = 'sec121_a';
  const B = 'sec121_b';
  const PW = 'Sec121-dev-password!';
  const stored = async (u: string) => (await owner.one<{ language: string | null }>('select language from meta.developer where username = $1', [u]))?.language ?? null;
  const signIn = async (username: string, b = new FileBrowser(app)) => {
    await b.get('/builder/login');
    assert.equal((await b.submit('/builder/login', { username, password: PW })).statusCode, 303);
    await b.get('/builder/apps');
    return b;
  };
  before(async () => {
    await owner.query('delete from meta.developer where username = any($1)', [[A, B]]);
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($3), true), ($2, meta.hash_password($3), true)`, [A, B, PW]);
  });
  after(async () => {
    await owner.query('delete from meta.session where app_id is null and username = any($1)', [[A, B]]);
    await owner.query('delete from meta.developer where username = any($1)', [[A, B]]);
  });

  test('the sign-in page ignores unknown and malicious language codes, in the link and in the cookie', async () => {
    for (const lang of ['xx', 'DE', 'de-DE', '__proto__', 'constructor', '%22%3E%3Cscript%3Ealert(1)%3C%2Fscript%3E', 'de%00', '..%2F..%2Fetc', 'de&lang=fr']) {
      const b = new FileBrowser(app);
      const r = await b.get(`/builder/login?lang=${lang}`);
      assert.equal(r.statusCode, 200, lang);
      if (lang === 'de&lang=fr') continue; // two values: ignored too (not a string) – checked below
      assert.match(r.body, /<html lang="en"/, lang);
      assert.equal(b.cookies.get('pgkiln_blang'), undefined, `${lang}: no cookie`);
      assert.ok(!r.body.includes('<script>alert(1)'), lang);
    }
    const two = new FileBrowser(app);
    const r2 = await two.get('/builder/login?lang=de&lang=fr');
    assert.match(r2.body, /<html lang="en"/, 'a repeated parameter is not a language');
    for (const cookie of ['"><script>alert(1)</script>', 'xx', 'de;', '__proto__']) {
      const b = new FileBrowser(app);
      b.cookies.set('pgkiln_blang', encodeURIComponent(cookie));
      const r = await b.get('/builder/login');
      assert.match(r.body, /<html lang="en"/, cookie);
      assert.ok(!r.body.includes('<script>alert(1)'), cookie);
    }
  });

  test('the language menu: CSRF checked, only known codes, stored for the signed-in developer only', async () => {
    await owner.query(`update meta.developer set language = 'fr' where username = $1`, [B]);
    const a = await signIn(A);
    // without (or with a wrong) CSRF token: refused, nothing stored
    assert.equal((await a.post('/builder/language', { language: 'de' })).statusCode, 403);
    assert.equal((await a.post('/builder/language', { __csrf: 'forged', language: 'de' })).statusCode, 403);
    assert.equal(await stored(A), null);
    // signed out: to the sign-in page, nothing stored
    const anon = new FileBrowser(app);
    await anon.get('/builder/login');
    assert.equal((await anon.submit('/builder/language', { language: 'de' })).statusCode, 302);
    for (const bad of ['xx', 'DE', "de'; update meta.developer set is_admin = true --", '<script>', '', 'de\u0000']) {
      await a.get('/builder/apps');
      assert.equal((await a.submit('/builder/language', { language: bad })).statusCode, 400, bad);
    }
    assert.equal(await stored(A), null);
    await a.get('/builder/apps');
    assert.equal((await a.submit('/builder/language', { language: 'de' })).statusCode, 303);
    assert.equal(await stored(A), 'de');
    assert.equal(await stored(B), 'fr', "another developer's choice is not touched");
    // the developer's own session follows; the other developer's sessions don't
    const b = await signIn(B);
    assert.match((await b.get('/builder/apps')).body, /<html lang="fr"/);
    assert.match((await a.get('/builder/apps')).body, /<html lang="de"/);
    // a post naming another developer changes nothing about them
    await a.get('/builder/apps');
    await a.submit('/builder/language', { language: 'es', username: B, developer: B });
    assert.equal(await stored(B), 'fr');
    assert.equal(await stored(A), 'es');
    // the column itself refuses anything but a language code
    await assert.rejects(owner.query(`update meta.developer set language = 'x<y' where username = $1`, [A]));
  });

  test('a language chosen on the sign-in page by one visitor is stored only for the developer who then signs in', async () => {
    await owner.query(`update meta.developer set language = 'fr' where username = $1`, [B]);
    await owner.query(`update meta.developer set language = null where username = $1`, [A]);
    // a visitor chooses Deutsch, then A signs in on that device: A gets Deutsch
    const device = new FileBrowser(app);
    await device.get('/builder/login?lang=de');
    await signIn(A, device);
    assert.equal(await stored(A), 'de');
    // after A signs out, B signs in on the same device without choosing: B keeps their own language
    await device.get('/builder/apps');
    await device.submit('/builder/logout', {});
    await signIn(B, device);
    assert.equal(await stored(B), 'fr');
    assert.match((await device.get('/builder/apps')).body, /<html lang="fr"/);
  });

  test('translated texts with parameters are escaped', async () => {
    const { translatorFor } = await import('../src/builder/i18n.ts');
    const { html } = await import('../src/html.ts');
    const x = '<img src=x onerror=alert(1)>';
    for (const lang of ['en', 'de', 'fr', 'es', 'nl', 'pt'] as const) {
      const tx = translatorFor(lang);
      const plain = String(html`<span title="${tx('ab.edit', { name: x })}">${tx('ab.locked_by', { user: x })}</span>`);
      assert.ok(!plain.includes('<img'), `${lang}: html escapes a translated text`);
      // rich: the message and string parameters escaped, Raw parameters kept
      const rich = String(tx.rich('weak.banner', { link: html`<a href="/builder/developers">${x}</a>` }));
      assert.ok(rich.includes('<a href="/builder/developers">&lt;img'), `${lang}: the Raw link kept, its text escaped`);
      assert.ok(!String(tx.rich('ab.none_yet', { create: x, import: '"><b>' })).includes('<img') && !String(tx.rich('ab.none_yet', { create: x, import: '"><b>' })).includes('<b>'), lang);
    }
    // on a page: a flash message with a parameter from the URL, in German
    await owner.query(`update meta.developer set language = 'de' where username = $1`, [A]);
    const a = await signIn(A);
    const hr = await owner.one<{ id: number }>(`select id from meta.app where alias = 'hr'`);
    await a.get(`/builder/apps/${hr!.id}/goto?page=${encodeURIComponent('<script>alert(1)</script>')}`);
    const page = (await a.get(`/builder/apps/${hr!.id}`)).body;
    assert.match(page, /<html lang="de"/);
    assert.ok(page.includes('&lt;script&gt;alert(1)&lt;/script&gt;'), 'the parameter escaped in the translated message');
    assert.ok(!page.includes('<script>alert(1)'));
  });
});

describe('sprint 122 WS-5', () => {
  // "Ask in your own words" sets facets, and smart filters read a typed phrase: the facets are only
  // those of filter regions the user sees, on the report's own columns; values reach SQL as parameters.
  let report: number;
  let pageId: number;
  const made: number[] = [];
  before(async () => {
    const r = await owner.one<{ id: number; page_id: number }>(`select r.id, r.page_id from meta.region r join meta.page p on p.id = r.page_id join meta.app a on a.id = p.app_id where a.alias = 'hr' and p.page_no = 2 and r.type = 'report' and r.config ? 'ai_filter'`);
    report = r!.id;
    pageId = r!.page_id;
    const add = async (config: object, condition: string | null = null) =>
      made.push((await owner.one<{ id: number }>(`insert into meta.region (page_id, seq, title, type, config, condition) values ($1, 1, 'Filter', 'smart_filters', $2, $3) returning id`, [pageId, JSON.stringify({ report, ...config }), condition]))!.id);
    await add({ ask: true, facets: [{ column: 'job' }, { column: 'sal', type: 'range', custom: true }] });
    // a hidden region's facets may not be set by Ask
    await add({ facets: [{ column: 'department' }] }, 'false');
  });
  after(async () => {
    await owner.query('delete from meta.region where id = any($1)', [made]);
  });
  const signIn = async () => {
    const b = new FileBrowser(app);
    await b.login('king');
    await b.get('/a/hr/2');
    return b;
  };

  test('Ask sets only facets of regions the user sees; the rest stays a checked report filter', async () => {
    const b = await signIn();
    const res = await b.submit(`/a/hr/2/report/${report}/ask`, { question: 'clerks in sales', params: '' });
    assert.equal(res.statusCode, 303);
    const u = new URL(res.headers.location as string, 'http://x');
    assert.deepEqual(u.searchParams.getAll(`r${report}_x_job`), ['CLERK']);
    assert.deepEqual(u.searchParams.getAll(`r${report}_x_department`), [], 'the hidden region\'s facet is not set');
    assert.deepEqual(u.searchParams.getAll(`r${report}_f`), ['department|eq|SALES']);
  });

  test('a typed phrase: values are bound, not SQL; nothing outside the region\'s facets; text escaped', async () => {
    const b = await signIn();
    const before = (await owner.one<{ n: number }>('select count(*)::int as n from hr.emp'))!.n;
    for (const q of [`job is clerk'; delete from hr.emp; --`, `salary at least 1 or 1=1`, `<img src=x onerror=alert(1)> clerks`, `department is SALES`]) {
      const page = (await b.get(`/a/hr/2?r${report}_q=${encodeURIComponent(q)}`));
      assert.equal(page.statusCode, 200, q);
      assert.ok(!page.body.includes('<img src=x'), q);
      const href = page.body.match(/sf-understood[\s\S]*?href="([^"]+)"/)?.[1]?.replace(/&amp;/g, '&');
      if (href) {
        const u = new URL(href, 'http://x');
        const facets = [...u.searchParams.keys()].filter((n) => /^r\d+_(x|xn|rg|rf|rt)_/.test(n));
        assert.ok(facets.every((n) => /_(job|sal)$/.test(n)), `${q}: ${facets}`);
        for (const v of u.searchParams.getAll(`r${report}_rf_sal`)) assert.match(v, /^-?\d+(\.\d+)?$/, q);
      }
    }
    assert.equal((await owner.one<{ n: number }>('select count(*)::int as n from hr.emp'))!.n, before);
  });
});

describe('sprint 126: two-factor sign-in for developers', () => {
  const U1 = 'sec126_a';
  const U2 = 'sec126_b';
  const PW = 'Sec126-password!';
  before(async () => {
    await owner.query('delete from meta.developer where username = any($1)', [[U1, U2]]);
    for (const u of [U1, U2]) await owner.query('insert into meta.developer (username, password_hash) values ($1, meta.hash_password($2))', [u, PW]);
    await owner.query(`insert into meta.developer_factor (username, kind, name, secret_enc) values ($1, 'totp', 'Phone', 'x')`, [U2]);
  });
  after(async () => {
    await owner.query('delete from meta.developer where username = any($1)', [[U1, U2]]);
  });
  const signIn = async (u: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username: u, password: PW });
    return b;
  };

  test('the Security page\'s forms need the CSRF token', async () => {
    const b = await signIn(U1);
    await b.get('/builder/security');
    for (const url of ['/builder/security/totp/start', '/builder/security/codes', '/builder/instance/mfa', '/builder/developers/reset-2fa',
      '/builder/security/passkey/options', '/builder/security/passkey', '/builder/security/forget-browsers', '/builder/workspaces/1/mfa',
      '/builder/workspaces/1/sso', '/builder/developers/break-glass', '/builder/developers/identity/1/unlink', '/builder/security/link/x', '/builder/users/providers/1/builder',
      '/builder/users/1/reset-2fa'])
      assert.equal((await b.post(url, { __csrf: 'forged' })).statusCode, 403, url);
  });

  test('(sprint 128) a workspace\'s two-factor rule: workspace administrators only; passkey sign-in needs the page\'s token', async () => {
    const U3 = 'sec128_c';
    await owner.query('delete from meta.developer where username = $1', [U3]);
    await owner.query('insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false)', [U3, PW]);
    const b = await signIn(U3);
    await b.get('/builder/security');
    const res = await b.post('/builder/workspaces/1/mfa', { __csrf: b.lastCsrf, required: 'true' });
    assert.equal(res.statusCode, 403);
    assert.equal((await owner.one<{ since: string | null }>('select mfa_required_since as since from meta.workspace where id = 1'))!.since, null);
    const c = new Browser();
    await c.get('/builder/login');
    assert.equal((await c.post('/builder/login/passkey/options', { __csrf: 'forged' })).statusCode, 403);
    const r = await c.post('/builder/login/passkey', { __csrf: 'forged', credentialId: 'x' });
    assert.equal(r.statusCode, 303);
    assert.notEqual((await c.get('/builder/apps')).statusCode, 200);
    await owner.query('delete from meta.developer where username = $1', [U3]);
  });

  test('(sprint 129) builder single sign-on: break-glass, provider settings, the workspace rule and others\' identities need the right role', async () => {
    const U3 = 'sec129_c';
    const OTHER = 'sec129_other';
    await owner.query('delete from meta.developer where username = any($1)', [[U3, OTHER]]);
    await owner.query(`delete from meta.auth_provider where name = 'sec129'`);
    await owner.query('insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false), ($3, meta.hash_password($2), true)', [U3, PW, OTHER]);
    const p = await owner.one<{ id: number }>(`insert into meta.auth_provider (name, display_name, issuer, client_id) values ('sec129', 'Sec 129', 'https://idp.example.org', 'x') returning id`);
    const i = await owner.one<{ id: number }>(`insert into meta.developer_identity (provider_id, subject, username) values ($1, 'sub-other', $2) returning id`, [p!.id, OTHER]);
    const b = await signIn(U3);
    await b.get('/builder/security');
    assert.equal((await b.post('/builder/developers/break-glass', { __csrf: b.lastCsrf, username: U3, break_glass: 'true' })).statusCode, 403);
    assert.notEqual((await b.post(`/builder/users/providers/${p!.id}/builder`, { __csrf: b.lastCsrf, builder: 'true', builder_auto_create: 'true' })).statusCode, 302);
    assert.equal((await b.post('/builder/workspaces/1/sso', { __csrf: b.lastCsrf, sso_only: 'true' })).statusCode, 403);
    assert.equal((await b.post(`/builder/developers/identity/${i!.id}/unlink`, { __csrf: b.lastCsrf })).statusCode, 404);
    // a provider that does not sign developers in can't be started or linked
    assert.equal((await b.get('/builder/sso/sec129')).statusCode, 404);
    assert.equal((await b.post('/builder/security/link/sec129', { __csrf: b.lastCsrf })).statusCode, 404);
    const row = await owner.one<{ builder: boolean; auto: boolean }>('select builder, builder_auto_create as auto from meta.auth_provider where id = $1', [p!.id]);
    assert.deepEqual(row, { builder: false, auto: false });
    assert.equal((await owner.one<{ sso_only: boolean }>('select sso_only from meta.workspace where id = 1'))!.sso_only, false);
    assert.equal((await owner.one<{ break_glass: boolean }>('select break_glass from meta.developer where username = $1', [U3]))!.break_glass, false);
    assert.ok(await owner.one('select 1 from meta.developer_identity where id = $1', [i!.id]));
    await owner.query(`delete from meta.auth_provider where name = 'sec129'`);
    await owner.query('delete from meta.developer where username = any($1)', [[U3, OTHER]]);
  });

  test('a developer can\'t remove another developer\'s factor', async () => {
    const b = await signIn(U1);
    await b.get('/builder/security');
    const f = await owner.one<{ id: number }>('select id from meta.developer_factor where username = $1', [U2]);
    const res = await b.post(`/builder/security/factor/${f!.id}/delete`, { __csrf: b.lastCsrf, [`password_${f!.id}`]: PW });
    assert.equal(res.statusCode, 404);
    assert.ok(await owner.one('select 1 from meta.developer_factor where id = $1', [f!.id]));
  });

  test('the password step alone gives no session; the second step throttles guessing', async () => {
    const b = await signIn(U2);
    assert.notEqual((await b.get('/builder/apps')).statusCode, 200);
    let last = '';
    for (let i = 0; i < 12; i++) {
      await b.get('/builder/login/2fa');
      const r = await b.post('/builder/login/2fa', { __csrf: b.lastCsrf, code: String(100000 + i) });
      last = String(r.headers.location);
    }
    assert.equal(last, '/builder/login', 'too many wrong codes end the pending sign-in');
    assert.notEqual((await b.get('/builder/apps')).statusCode, 200);
  });
});

describe('(sprint 130, SEC-3) two-factor sign-in for application users', () => {
  const ids = async () => (await owner.query<{ id: number; username: string }>(`select id, username from meta.account where username in ('king', 'scott')`)).rows;
  const clear = async () => {
    const all = (await ids()).map((r) => r.id);
    await owner.query('delete from meta.account_factor where account_id = any($1)', [all]);
    await owner.query('delete from meta.account_recovery_code where account_id = any($1)', [all]);
    await owner.query(`insert into meta.activity_log (username, event, detail) values ('king', 'login_unlocked', 'test'), ('scott', 'login_unlocked', 'test')`);
  };
  before(async () => {
    process.env.PGKILN_SECRET_KEY ??= 'test-only-secret-key-0123456789abcdef';
    await clear();
    const { addAccountTotp } = await import('../src/account-mfa.ts');
    for (const r of await ids()) await addAccountTotp(r.id, 'Phone', 'JBSWY3DPEHPK3PXP', 1);
    await owner.query(`update meta.app set mfa = 'optional', mfa_roles = '{}' where id = $1`, [appId]);
  });
  after(async () => {
    await owner.query(`update meta.app set mfa = 'off', mfa_roles = '{}' where id = $1`, [appId]);
    await clear();
  });

  test('the password alone gives no session: pages, AJAX and other browsers see nobody', async () => {
    const b = new Browser();
    const res = await b.login('king');
    assert.equal(res.headers.location, '/a/hr/login/2fa');
    const page = await b.get('/a/hr/2');
    assert.equal(page.statusCode, 302);
    assert.match(String(page.headers.location), /\/a\/hr\/login/);
    assert.equal((await b.get('/a/hr/account')).statusCode, 302);
    assert.equal((await owner.one(`select count(*)::int as n from meta.session where app_id = $1 and username = 'king' and state ? '__MFA'`, [appId])).n, 0, 'the pending sign-in is in a signed-out session');
    const other = new Browser();
    assert.equal((await other.get('/a/hr/login/2fa')).statusCode, 410);
  });

  test('the second step needs the page\'s CSRF token, and a forged one ends it', async () => {
    const b = new Browser();
    await b.login('king');
    await b.get('/a/hr/login/2fa');
    assert.equal((await b.post('/a/hr/login/2fa', { __csrf: 'forged', code: '123456' })).statusCode, 410);
    assert.equal((await b.get('/a/hr/login/2fa')).statusCode, 410, 'nothing pending any more');
  });

  test('My account: the forms need the CSRF token, and a user can\'t remove another account\'s app', async () => {
    await owner.query(`update meta.app set mfa = 'off' where id = $1`, [appId]);
    const scott = await as('scott');
    await owner.query(`update meta.app set mfa = 'optional' where id = $1`, [appId]);
    await scott.get('/a/hr/account');
    const king = (await ids()).find((r) => r.username === 'king')!;
    const f = await owner.one<{ id: number }>('select id from meta.account_factor where account_id = $1', [king.id]);
    await scott.post(`/a/hr/account/2fa/${f!.id}/delete`, { __csrf: scott.lastCsrf, code: 'abcde-fghjk' });
    assert.ok(await owner.one('select 1 from meta.account_factor where id = $1', [f!.id]), 'not scott\'s app');
    const before = (await owner.one<{ state: Record<string, unknown> }>(`select state from meta.session where app_id = $1 and username = 'scott' order by created_at desc limit 1`, [appId]))!.state;
    assert.equal(before.__TOTP_NEW, undefined);
    const res = await scott.post('/a/hr/account/2fa/start', { __csrf: 'forged' });
    assert.equal(res.statusCode, 303);
    const after = (await owner.one<{ state: Record<string, unknown> }>(`select state from meta.session where app_id = $1 and username = 'scott' order by created_at desc limit 1`, [appId]))!.state;
    assert.equal(after.__TOTP_NEW, undefined, 'a forged form starts nothing');
    await scott.post('/a/hr/account/2fa/codes', { __csrf: 'forged' });
    assert.equal((await owner.one<{ n: number }>(`select count(*)::int as n from meta.account_recovery_code r join meta.account a on a.id = r.account_id where a.username = 'scott'`))!.n, 0);
  });

  test('a remembered sign-in without the second step doesn\'t stand in for it', async () => {
    const { carriesSecondStep } = await import('../src/account-mfa.ts');
    const a = { authentication: 'app_users', mfa: 'optional' as const, mfa_roles: [] };
    assert.equal(await carriesSecondStep(a, 'king', [], 'password'), false);
    assert.equal(await carriesSecondStep(a, 'king', [], 'ldap:corp'), false);
    assert.equal(await carriesSecondStep(a, 'king', [], 'password+2fa'), true);
    assert.equal(await carriesSecondStep(a, 'king', [], 'sso:entra'), true, 'the identity provider decides');
    assert.equal(await carriesSecondStep({ ...a, mfa: 'off' }, 'king', [], 'password'), true);
  });
});

describe('(sprint 131, SEC-3 part 2) passkeys, e-mail codes, step-up and API tokens for application users', () => {
  const SCHEME = 'T_S131_SEC';
  const SECRET = 'JBSWY3DPEHPK3PXP';
  let oldAuthz: string | null = null;
  const ids = async () => (await owner.query<{ id: number; username: string }>(`select id, username from meta.account where username in ('king', 'scott')`)).rows;
  const clear = async () => {
    const all = (await ids()).map((r) => r.id);
    await owner.query('delete from meta.account_factor where account_id = any($1)', [all]);
    await owner.query('delete from meta.account_recovery_code where account_id = any($1)', [all]);
    await owner.query(`delete from meta.mail_queue where template = 'SIGNIN_CODE'`);
    await owner.query(`insert into meta.activity_log (username, event, detail) values ('king', 'login_unlocked', 'test'), ('scott', 'login_unlocked', 'test')`);
  };
  const code = async (offset = 0) => {
    const { stepNow, totpAt, unbase32 } = await import('../src/mfa.ts');
    return totpAt(unbase32(SECRET), stepNow() + offset);
  };
  /** king through password and code; the browser is signed in with a fresh second step */
  const kingIn = async () => {
    // each 30-second step is accepted once: let this sign-in use the current one again
    await owner.query(`update meta.account_factor set last_step = null where account_id = (select id from meta.account where username = 'king')`);
    const b = new Browser();
    await b.login('king');
    await b.get('/a/hr/login/2fa');
    const r = await b.post('/a/hr/login/2fa', { __csrf: b.lastCsrf, code: await code() });
    assert.equal(r.statusCode, 303);
    return b;
  };
  before(async () => {
    process.env.PGKILN_SECRET_KEY ??= 'test-only-secret-key-0123456789abcdef';
    await clear();
    const { addAccountTotp } = await import('../src/account-mfa.ts');
    const { stepNow } = await import('../src/mfa.ts');
    for (const r of await ids()) await addAccountTotp(r.id, 'Phone', SECRET, stepNow() - 10);
    await owner.query(`update meta.app set mfa = 'optional', mfa_roles = '{}', mfa_email = true where id = $1`, [appId]);
    await owner.query('delete from meta.authz_scheme where app_id = $1 and name = $2', [appId, SCHEME]);
    await owner.query(`insert into meta.authz_scheme (app_id, name, type, value, mfa_minutes) values ($1, $2, 'sql', 'true', 10)`, [appId, SCHEME]);
    oldAuthz = (await owner.one('select authz from meta.page where app_id = $1 and page_no = 2', [appId])).authz;
  });
  after(async () => {
    await owner.query('update meta.page set authz = $2 where app_id = $1 and page_no = 2', [appId, oldAuthz]);
    await owner.query('delete from meta.authz_scheme where app_id = $1 and name = $2', [appId, SCHEME]);
    await owner.query(`update meta.app set mfa = 'off', mfa_roles = '{}', mfa_email = false, api_self_tokens = false where id = $1`, [appId]);
    await clear();
  });

  test('step-up: ?next= never leaves the application, and a signed-out visit creates nothing', async () => {
    assert.equal((await new Browser().get('/a/hr/login/2fa?next=%2Fa%2Fhr%2F2')).statusCode, 410, 'nobody: no step-up');
    const b = await kingIn();
    await b.get(`/a/hr/login/2fa?next=${encodeURIComponent('https://evil.example/x')}`);
    const r = await b.post('/a/hr/login/2fa', { __csrf: b.lastCsrf, code: await code(1) });
    assert.equal(r.statusCode, 303);
    assert.match(String(r.headers.location), /^\/a\/hr\//);
    const { safeNext } = await import('../src/runtime/signin.ts');
    for (const next of ['//evil.example/x', '/a/other/1', 'javascript:alert(1)', '/\\evil.example'])
      assert.match(safeNext({ alias: 'hr', home_page: 1 } as never, next), /^\/a\/hr\//, next);
  });

  test('step-up: a negated scheme or an anonymous user is never sent to the second step', async () => {
    const { onlyStepUpMissing } = await import('../src/runtime/authz.ts');
    const ctx = { user: 'king', roles: [], session: { state: {} }, app: { authz_schemes: [{ name: SCHEME, type: 'role', value: 'x', error_message: '', mfa_minutes: 10 }] } } as never;
    assert.equal(await onlyStepUpMissing(ctx, `!${SCHEME}`), false);
    assert.equal(await onlyStepUpMissing({ ...(ctx as object), user: 'nobody' } as never, SCHEME), false);
    assert.equal(await onlyStepUpMissing(ctx, SCHEME), false, 'not the role: refused, not asked');
    await assert.rejects(owner.query('update meta.authz_scheme set mfa_minutes = 0 where app_id = $1 and name = $2', [appId, SCHEME]));
    await assert.rejects(owner.query('update meta.authz_scheme set mfa_minutes = 5000 where app_id = $1 and name = $2', [appId, SCHEME]));
  });

  test('step-up: a remembered or SSO session without a recent second step is asked; regions behind the scheme stay hidden', async () => {
    await owner.query('update meta.page set authz = $2 where app_id = $1 and page_no = 2', [appId, SCHEME]);
    try {
      const b = await kingIn();
      assert.equal((await b.get('/a/hr/2')).statusCode, 200);
      await owner.query(`update meta.session set state = state - '__MFA_AT' where app_id = $1 and username = 'king'`, [appId]);
      const r = await b.get('/a/hr/2');
      assert.equal(r.statusCode, 303);
      assert.match(String(r.headers.location), /^\/a\/hr\/login\/2fa\?next=/);
      // a POST to the page is not processed either
      const p = await b.post('/a/hr/2', { __csrf: b.lastCsrf, __request: 'SAVE' });
      assert.equal(p.statusCode, 303);
      assert.match(String(p.headers.location), /^\/a\/hr\/login\/2fa\?next=/);
    } finally {
      await owner.query('update meta.page set authz = $2 where app_id = $1 and page_no = 2', [appId, oldAuthz]);
    }
  });

  test('e-mail codes: CSRF, the per-hour limit across sign-ins, and wrong codes count as failed sign-ins', async () => {
    await owner.query(`update meta.account set email = coalesce(email, 'king@example.com') where username = 'king'`);
    const b = new Browser();
    await b.login('king');
    await b.get('/a/hr/login/2fa');
    assert.equal((await b.post('/a/hr/login/2fa/email', { __csrf: 'forged' })).statusCode, 410);
    assert.equal((await new Browser().post('/a/hr/login/2fa/email', { __csrf: 'x' })).statusCode, 410);
    const { EMAIL_CODES_PER_HOUR } = await import('../src/account-mfa.ts');
    for (let i = 0; i < EMAIL_CODES_PER_HOUR; i++)
      await owner.query(`insert into meta.mail_queue (app_id, username, from_address, to_addresses, subject, body_text, template, status)
                         values ($1, 'king', 'hr@example.com', '{king@example.com}', 's', 'b', 'SIGNIN_CODE', 'cancelled')`, [appId]);
    const c = new Browser();
    await c.login('king');
    await c.get('/a/hr/login/2fa');
    assert.equal((await c.post('/a/hr/login/2fa/email', { __csrf: c.lastCsrf })).statusCode, 429, 'no more this hour, whatever the sign-in');
    const before = (await owner.one(`select count(*)::int as n from meta.activity_log where username = 'king' and event = 'login_failed'`)).n;
    assert.equal((await c.post('/a/hr/login/2fa', { __csrf: c.lastCsrf, code: '123456' === (await code()) ? '654321' : '123456' })).statusCode, 401);
    assert.equal((await owner.one(`select count(*)::int as n from meta.activity_log where username = 'king' and event = 'login_failed'`)).n, before + 1);
    await owner.query(`delete from meta.mail_queue where template = 'SIGNIN_CODE'`);
    await owner.query(`insert into meta.activity_log (username, event, detail) values ('king', 'login_unlocked', 'test')`);
  });

  test('passkeys: no options without a pending step, and another account\'s passkey is refused', async () => {
    assert.equal((await new Browser().post('/a/hr/login/2fa/passkey/options', { __csrf: 'x' })).statusCode, 403);
    assert.equal((await new Browser().post('/a/hr/login/2fa/passkey/new/options', { __csrf: 'x' })).statusCode, 403);
    const { Authenticator } = await import('./authenticator.ts');
    const { accountId, addAccountPasskey } = await import('../src/account-mfa.ts');
    const { coseToJwk, cborDecode, parseAuthData, unb64url } = await import('../src/webauthn.ts');
    // scott's passkey, stored as the server would
    const key = new Authenticator();
    const att = key.create('c');
    const [obj] = cborDecode(unb64url(att.attestationObject)) as [Map<string, Buffer>, number];
    const auth = parseAuthData(obj.get('authData')!);
    const { alg, jwk } = coseToJwk(auth.publicKey as never);
    await addAccountPasskey((await accountId('scott'))!, 'Scott key', { credentialId: key.id.toString('base64url'), jwk, alg, signCount: 0, rpId: 'localhost', transports: [] });
    const b = new Browser();
    await b.login('king');
    await b.get('/a/hr/login/2fa');
    assert.equal((await b.post('/a/hr/login/2fa/passkey/options', { __csrf: b.lastCsrf })).statusCode, 404, 'king has no passkey');
    const r = await b.post('/a/hr/login/2fa/passkey', { __csrf: b.lastCsrf, ...key.get('anything') });
    assert.equal(r.statusCode, 401);
    assert.equal((await b.get('/a/hr/2')).statusCode, 302, 'still signed out');
  });

  test('API tokens: CSRF and the application setting are checked; the builder refuses users who must use 2FA', async () => {
    const { issueApiToken } = await import('../src/api.ts');
    process.env.API_JWT_SECRET ??= 'ci-only-api-secret-not-for-production-0123456789';
    await owner.query(`update meta.app set api_self_tokens = true, mfa = 'required' where id = $1`, [appId]);
    try {
      await assert.rejects(issueApiToken(appId, 'KING', 1), /requires two-factor sign-in/, 'whatever the case of the name');
      const b = await kingIn();
      await b.get('/a/hr/account');
      const forged = await b.post('/a/hr/account/token', { __csrf: 'forged', hours: '1' });
      assert.equal(forged.statusCode, 303);
      assert.doesNotMatch((await b.get('/a/hr/account')).body, /id="api_token"/);
      assert.equal((await new Browser().post('/a/hr/account/token', { __csrf: 'x' })).statusCode, 302, 'signed out: to the sign-in page');
    } finally {
      await owner.query(`update meta.app set api_self_tokens = false, mfa = 'optional' where id = $1`, [appId]);
    }
  });
});

describe('(sprint 132, SEC-4) the identity provider did multi-factor sign-in', () => {
  const NAME = 'sec132';
  let id: number;
  before(async () => {
    await owner.query('delete from meta.auth_provider where name = $1', [NAME]);
    id = (await owner.one(`insert into meta.auth_provider (name, display_name, issuer, client_id) values ($1, 'Sec 132', 'https://idp.example.test', 'c') returning id`, [NAME])).id;
  });
  after(() => owner.query('delete from meta.auth_provider where name = $1', [NAME]));

  test('the provider form: CSRF checked; values capped and de-duplicated; an over-long request refused', async () => {
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    await dev.get(`/builder/users/providers/${id}`);
    const base = { display_name: 'Sec 132', issuer: 'https://idp.example.test', client_id: 'c', enabled: 'true' };
    await dev.post(`/builder/users/providers/${id}`, { __csrf: 'forged', ...base, mfa_required: 'true' });
    assert.equal((await owner.one('select mfa_required from meta.auth_provider where id = $1', [id])).mfa_required, false, 'forged CSRF');
    const many = Array.from({ length: 30 }, (_, i) => `v${i}`).join(' ');
    await dev.get(`/builder/users/providers/${id}`);
    await dev.post(`/builder/users/providers/${id}`, { __csrf: dev.lastCsrf, ...base, mfa_required: 'true', mfa_request: ' urn:a   urn:b ', mfa_values: `mfa mfa ${many}` });
    const r = await owner.one('select mfa_required, mfa_request, mfa_values from meta.auth_provider where id = $1', [id]);
    assert.equal(r.mfa_required, true);
    assert.equal(r.mfa_request, 'urn:a urn:b');
    assert.equal(r.mfa_values.length, 20);
    assert.equal(r.mfa_values.filter((v: string) => v === 'mfa').length, 1);
    await assert.rejects(owner.query('update meta.auth_provider set mfa_request = $2 where id = $1', [id, 'x'.repeat(501)]));
  });

  test('a step-up result needs a second factor, a fresh sign-in and an identity linked to an active account', async () => {
    const { stepUpResult } = await import('../src/sso.ts');
    const p = { id, mfa_values: ['mfa'] };
    const pending = { app_id: appId, next: null, stepup_session: '00000000-0000-0000-0000-000000000000' };
    const acc = (await owner.one(`select id from meta.account where username = 'king'`)).id;
    await owner.query('insert into meta.account_identity (provider_id, subject, account_id) values ($1, $2, $3)', [id, 'king-sub', acc]);
    try {
      await assert.rejects(stepUpResult(p, pending, 'king-sub', false, Date.now()), /did not confirm a second factor/);
      await assert.rejects(stepUpResult(p, pending, 'king-sub', true, null), /did not ask you to sign in again/);
      await assert.rejects(stepUpResult(p, pending, 'king-sub', true, Date.now() - 3600_000), /did not ask you to sign in again/);
      await assert.rejects(stepUpResult(p, pending, 'someone-else', true, Date.now()), /not linked/);
      assert.equal((await stepUpResult(p, pending, 'king-sub', true, Date.now())).username, 'king');
      await owner.query(`update meta.account set active = false where id = $1`, [acc]);
      await assert.rejects(stepUpResult(p, pending, 'king-sub', true, Date.now()), /not linked/, 'a disabled account');
    } finally {
      await owner.query(`update meta.account set active = true where id = $1`, [acc]);
      await owner.query('delete from meta.account_identity where provider_id = $1', [id]);
    }
  });

  test('the runtime role reads neither the provider settings nor pending step-ups', async () => {
    await assert.rejects(runtime.query('select mfa_values from meta.auth_provider'));
    await assert.rejects(runtime.query('select stepup_session from meta.sso_pending'));
  });
});

describe('(sprint 133, SEC-6) lockout checks and the instance key', () => {
  const DEV = 'sec133_dev';
  const PW = 'Sec133-password!';
  let saved: string | undefined;
  before(async () => {
    saved = (await owner.one(`select value from meta.setting where name = 'secret_key_backup'`))?.value;
    await owner.query(`delete from meta.setting where name = 'secret_key_backup'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query('insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false)', [DEV, PW]);
  });
  after(async () => {
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    if (saved === undefined) await owner.query(`delete from meta.setting where name = 'secret_key_backup'`);
    else await owner.query(`insert into meta.setting (name, value) values ('secret_key_backup', $1) on conflict (name) do update set value = excluded.value`, [saved]);
  });
  const signIn = async (username: string, password: string) => {
    const b = new Browser();
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password });
    return b;
  };

  test('only an administrator confirms a key backup, with the CSRF token', async () => {
    const dev = await signIn(DEV, PW);
    await dev.get('/builder/apps');
    const r = await dev.post('/builder/instance/key-backup', { __csrf: dev.lastCsrf });
    assert.equal(r.statusCode, 403);
    assert.equal((await dev.get('/builder/instance')).statusCode, 403);
    assert.doesNotMatch((await dev.get('/builder/home')).body, /Lockout checks that need attention/, 'only administrators see the count');
    const admin = await signIn('admin', 'admin');
    await admin.get('/builder/instance');
    await admin.post('/builder/instance/key-backup', { __csrf: 'forged' });
    assert.equal(await owner.one(`select 1 from meta.setting where name = 'secret_key_backup'`), undefined, 'forged CSRF');
  });

  test('the checks escape what they show, and never show the key', async () => {
    await owner.query(`insert into meta.developer_factor (username, kind, name, credential_id, public_key, alg, rp_id) values ($1, 'passkey', 'Key', 'sec133-cred', '{}', -7, '<b>evil</b>.example')`, [DEV]);
    try {
      const page = (await (await signIn('admin', 'admin')).get('/builder/instance')).body;
      assert.match(page, /&lt;b&gt;evil&lt;\/b&gt;\.example/);
      assert.doesNotMatch(page, /<b>evil<\/b>/);
      if (process.env.PGKILN_SECRET_KEY) assert.ok(!page.includes(process.env.PGKILN_SECRET_KEY));
    } finally {
      await owner.query('delete from meta.developer_factor where username = $1', [DEV]);
    }
  });

  test('the runtime role can read no encrypted secret', async () => {
    const { encryptedColumns } = await import('../src/instance-checks.ts');
    for (const c of await encryptedColumns())
      await assert.rejects(runtime.query(`select "${c.column}" from "${c.schema}"."${c.table}" limit 1`), Error, `${c.table}.${c.column}`);
  });
});

describe('sprint 134 SEC-5', () => {
  // Five more builder languages, two of them with a region subtag (zh-CN, zh-TW): the codes are matched exactly
  // (no case folding, no prefix match), in the sign-in link, the cookie and the status bar's menu; every text of
  // every language reaches the page escaped, like the six earlier ones.
  const A = 'sec134_a';
  const PW = 'Sec134-dev-password!';
  const stored = async (u: string) => (await owner.one<{ language: string | null }>('select language from meta.developer where username = $1', [u]))?.language ?? null;
  before(async () => {
    await owner.query('delete from meta.developer where username = $1', [A]);
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false)`, [A, PW]);
  });
  after(async () => {
    await owner.query('delete from meta.session where app_id is null and username = $1', [A]);
    await owner.query('delete from meta.developer where username = $1', [A]);
  });

  test('only the exact codes: zh-CN and zh-TW, not zh, zh-cn, ZH-TW, zh-Hans or ja-JP', async () => {
    for (const lang of ['zh', 'zh-cn', 'ZH-TW', 'zh-Hans', 'zh-TW%00', 'ja-JP', 'ko-KR', 'it-IT']) {
      const b = new FileBrowser(app);
      const r = await b.get(`/builder/login?lang=${lang}`);
      assert.match(r.body, /<html lang="en"/, lang);
      assert.equal(b.cookies.get('pgkiln_blang'), undefined, `${lang}: no cookie`);
      const c = new FileBrowser(app);
      c.cookies.set('pgkiln_blang', lang);
      assert.match((await c.get('/builder/login')).body, /<html lang="en"/, `${lang} as a cookie`);
    }
    const ok = new FileBrowser(app);
    assert.match((await ok.get('/builder/login?lang=zh-CN')).body, /<html lang="zh-CN"/);
    assert.equal(ok.cookies.get('pgkiln_blang'), 'zh-CN');
    // the menu refuses near-misses and stores an exact code
    await ok.submit('/builder/login', { username: A, password: PW });
    assert.equal(await stored(A), 'zh-CN');
    for (const bad of ['zh-cn', 'zh', 'ja-JP', 'KO']) {
      await ok.get('/builder/apps');
      assert.equal((await ok.submit('/builder/language', { language: bad })).statusCode, 400, bad);
    }
    assert.equal(await stored(A), 'zh-CN');
    await ok.get('/builder/apps');
    assert.equal((await ok.submit('/builder/language', { language: 'ko' })).statusCode, 303);
    assert.equal(await stored(A), 'ko');
  });

  test('every text of the new languages is escaped on the page (plain text, not markup)', async () => {
    const { builderTranslator } = await import('../src/builder/i18n.ts');
    const { html } = await import('../src/html.ts');
    for (const lang of ['it', 'zh-CN', 'zh-TW', 'ja', 'ko'] as const) {
      const own = { 'wh.summary': '<img src=x onerror=alert(1)>', 'ab.count': '{n} <b>' };
      const tx = builderTranslator(lang, own);
      assert.equal(String(html`<h2>${tx('wh.summary')}</h2>`), '<h2>&lt;img src=x onerror=alert(1)&gt;</h2>', lang);
      assert.equal(String(tx.rich('ab.count', { n: '<i>' })), '&lt;i&gt; &lt;b&gt;', lang);
    }
  });
});

describe('sprint 135 AP-2', () => {
  // Full-text search configurations: the search text only ever as a parameter of websearch_to_tsquery; the text
  // search configuration a name checked against pg_ts_config (and still a parameter at run time, a quoted literal
  // in Table Properties' DDL); the queries as the application's role (row level security applies, to the
  // suggestions too); ts_headline's output escaped, only its own markers become <mark>.
  const S = 'sec135';
  let pageId: number;
  let region: number;
  let report: number;
  const results = (body: string) => /<div class="search-results" id="R\d+_results" aria-live="polite">([\s\S]*?)<\/div>\s*(?:<\/div>|<\/section>)/.exec(body)?.[1] ?? '';
  before(async () => {
    pageId = (await owner.one('select id from meta.page where app_id = $1 and page_no = 1', [appId])).id;
    await owner.query(`drop schema if exists ${S} cascade; create schema ${S}; grant usage on schema ${S} to hr_app;
      create table ${S}.doc (id int primary key, owner_name text not null, title text not null, body text,
        tsv tsvector generated always as (to_tsvector('english', title || ' ' || coalesce(body, ''))) stored);
      create index doc_tsv_idx on ${S}.doc using gin (tsv);
      alter table ${S}.doc enable row level security;
      create policy doc_own on ${S}.doc for select using (lower(owner_name) = lower(meta.app_user()));
      grant select on ${S}.doc to hr_app;
      insert into ${S}.doc values
        (1, 'king', 'King running notes', 'Running shoes for the king'),
        (2, 'allen', 'Allen running notes', 'Running shoes and a zeppelin for allen'),
        (3, 'king', '<img src=x onerror=alert(1)> running', E'<script>alert(1)</script> shoes \\uE000evil\\uE001 </mark><mark>');`);
    await owner.query(`delete from meta.search_config where app_id = $1 and name like 'SEC135%'`, [appId]);
    await owner.query(`insert into meta.search_config (app_id, name, label, source_type, source, search_type, fts_vector, fts_config, title_column, description_column, did_you_mean)
      values ($1, 'SEC135_DOCS', 'Docs', 'table', '${S}.doc', 'fulltext', 'tsv', 'english', 'title', 'body', true)`, [appId]);
    region = (await owner.one(`insert into meta.region (page_id, seq, title, type, config) values ($1, 997, 'Search', 'search', '{"configs": ["SEC135_DOCS"]}') returning id`, [pageId])).id;
    report = (await owner.one(`insert into meta.region (page_id, seq, title, type, source, config) values ($1, 996, 'Sec135 report', 'report', 'select id, title, tsv from ${S}.doc', '{"hidden": ["tsv"], "fulltext": "tsv"}') returning id`, [pageId])).id;
  });
  after(async () => {
    await owner.query('delete from meta.region where id = any($1)', [[region, report]]);
    await owner.query(`delete from meta.search_config where app_id = $1 and name like 'SEC135%'`, [appId]);
    await owner.query(`drop schema if exists ${S} cascade`);
  });

  test('the search text is a parameter: SQL and tsquery syntax are only words', async () => {
    const b = await as('king');
    for (const q of [`'); drop table ${S}.doc; --`, `running' or '1'='1`, `!!! & | :* <-> ((`, '"unterminated', '$1 $2::regconfig', '\\', 'a'.repeat(500)]) {
      const r = await b.get(`/a/hr/1?s${region}=${encodeURIComponent(q)}&r${report}_q=${encodeURIComponent(q)}`);
      assert.equal(r.statusCode, 200, q);
      assert.doesNotMatch(r.body, /alert-error/, q);
    }
    assert.ok(await owner.one(`select to_regclass('${S}.doc') as t`).then((x) => x.t), 'the table is still there');
  });

  test('the text search configuration: refused by the database unless a plain name, never interpolated', async () => {
    for (const bad of [`english'; drop table ${S}.doc; --`, 'English', 'pg_catalog.english', 'a b'])
      await assert.rejects(owner.query(`update meta.search_config set fts_config = $2 where app_id = $1 and name = 'SEC135_DOCS'`, [appId, bad]), /fts_config_check/, bad);
    // a plain name that is no configuration: the application language's is used, nothing fails
    await owner.query(`update meta.search_config set fts_config = 'no_such_config' where app_id = $1 and name = 'SEC135_DOCS'`, [appId]);
    try {
      const b = await as('king');
      assert.match(results((await b.get(`/a/hr/1?s${region}=runs`)).body), /King <mark>running<\/mark> notes/);
    } finally {
      await owner.query(`update meta.search_config set fts_config = 'english' where app_id = $1 and name = 'SEC135_DOCS'`, [appId]);
    }
    // a report's fulltext_config is checked the same way
    await owner.query(`update meta.region set config = config || $2::jsonb where id = $1`, [report, JSON.stringify({ fulltext_config: `english'::regconfig, 'x') or true or tsv @@ to_tsquery('` })]);
    try {
      const b = await as('king');
      const r = await b.get(`/a/hr/1?r${report}_q=zzzz`);
      assert.doesNotMatch(r.body, /alert-error/);
      assert.doesNotMatch(r.body, /King running notes/, 'no row matches zzzz');
    } finally {
      await owner.query(`update meta.region set config = config - 'fulltext_config' where id = $1`, [report]);
    }
  });

  test('Table Properties › Add full-text search: names and the configuration from the catalog only', async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.submit('/builder/login', { username: 'admin', password: 'admin' })).statusCode, 303);
    await owner.query(`create table ${S}.page (id int primary key, title text)`);
    const base = { o: `${S}.page`, 'c.0.name': 'title', 'c.0.use': 'on', 'c.0.w': 'A', config: 'english', column: 'search_vector', index: 'page_sv_idx', mode: 'apply' };
    await b.get(`/builder/sql/objects/fulltext?o=${S}.page`);
    for (const [k, v, msg] of [
      ['config', `english'::regconfig, title)) stored; drop table ${S}.doc; --`, /is not a text search configuration/],
      ['column', 'x tsvector; drop table x', /is not a valid name/],
      ['index', 'i on x; drop table x', /is not a valid name/],
    ] as const) {
      const r = await b.submit('/builder/sql/objects/fulltext', { ...base, [k]: v });
      assert.equal(r.statusCode, 200, k);
      assert.match(r.body, msg, k);
    }
    // a weight outside A–D and a column the table doesn't have don't reach the DDL
    const w = (await b.submit('/builder/sql/objects/fulltext', { ...base, mode: 'preview', 'c.0.w': `A'); drop table x; --`, 'c.1.name': 'id); drop table x; --', 'c.1.use': 'on' })).body;
    assert.match(w, /setweight\(to_tsvector\(&#39;english&#39;::regconfig, coalesce\(title::text, &#39;&#39;\)\), &#39;B&#39;\)\) stored;/);
    assert.doesNotMatch(w, /drop table/);
    assert.equal((await owner.one(`select count(*)::int as n from pg_attribute where attrelid = '${S}.page'::regclass and attname in ('search_vector', 'x')`)).n, 0);
    assert.ok(await owner.one(`select to_regclass('${S}.doc') as t`).then((x) => x.t));
    // only a usable table: not pgkiln's own, not a made-up one; developers only; CSRF
    assert.equal((await b.get('/builder/sql/objects/fulltext?o=meta.app')).statusCode, 404);
    assert.equal((await b.get(`/builder/sql/objects/fulltext?o=${S}.nope`)).statusCode, 404);
    assert.notEqual((await new Browser().get(`/builder/sql/objects/fulltext?o=${S}.page`)).statusCode, 200);
    assert.equal((await b.post('/builder/sql/objects/fulltext', { ...base })).statusCode, 403);
    assert.equal((await owner.one(`select count(*)::int as n from pg_attribute where attrelid = '${S}.page'::regclass and attname = 'search_vector'`)).n, 0);
  });

  test('row level security applies to results, report searches and suggestions', async () => {
    const king = await as('king');
    const allen = await as('allen');
    const k = results((await king.get(`/a/hr/1?s${region}=running`)).body);
    assert.match(k, /King <mark>running<\/mark> notes/);
    assert.doesNotMatch(k, /Allen/);
    const a = results((await allen.get(`/a/hr/1?s${region}=running`)).body);
    assert.match(a, /Allen <mark>running<\/mark> notes/);
    assert.doesNotMatch(a, /King/);
    assert.doesNotMatch((await king.get(`/a/hr/1?r${report}_q=zeppelin`)).body, /Allen running notes/);
    // "did you mean" reads the words as the user: allen's zeppelin is never suggested to king
    const installed = !!(await owner.one(`select 1 as x from pg_extension where extname = 'pg_trgm'`));
    const created = !installed && (await owner.query(`create extension pg_trgm schema ${S}`).then(() => true, () => false));
    if (created) await owner.query(`grant usage on schema ${S} to public`);
    try {
      if (installed || created) {
        assert.match(results((await allen.get(`/a/hr/1?s${region}=zepelin`)).body), /Did you mean: <a [^>]*>zeppelin<\/a>/);
        assert.doesNotMatch(results((await king.get(`/a/hr/1?s${region}=zepelin`)).body), /zeppelin/);
      }
    } finally {
      if (created) await owner.query('drop extension if exists pg_trgm');
    }
  });

  test('ts_headline output is escaped; only its markers become <mark>, not the data\'s', async () => {
    const b = await as('king');
    const r = results((await b.get(`/a/hr/1?s${region}=${encodeURIComponent('running shoes')}`)).body);
    assert.match(r, /&lt;img src=x onerror=alert\(1\)&gt; <mark>running<\/mark>/);
    // (a fragment leaves the data's tags out; HighlightAll keeps them, as text)
    assert.match(r, /<span class="search-description">[^<]*alert\(1\)[^<]*<mark>shoes<\/mark> evil[^<]*<\/span>/);
    assert.doesNotMatch(r, /<script|<img|<mark>evil/);
    assert.doesNotMatch(r, /[]/);
  });
});

const HAS_PGVECTOR_136 = !!(await owner.one(`select 1 as x from pg_extension where extname = 'vector'`));
describe('sprint 136 AP-1', () => {
  // Vector search and Retrieve tools: the search text only reaches the embedding service and then the query as a
  // parameter (a vector literal of numbers); the queries run as the application's role, so row level security
  // decides what is found and what the model is given; provider keys stay with the AI service (write-only, never
  // exported, not readable by the runtime role); meta.embed runs a function provider as the caller and never calls
  // an AI service from SQL; names that reach SQL are plain identifiers checked by the database and the builder;
  // model output and found rows are escaped.
  const S = 'sec136';
  const env = { ...process.env };
  const HAS = HAS_PGVECTOR_136;
  const NEEDS = HAS ? {} : { skip: 'pgvector is not installed' };
  const KEY = 'sk-sec136-embedding-secret';
  const DEV = 'sec136_dev';
  const DEV_PW = 'Sec136-dev-password!';
  let pageId: number;
  let region: number;
  let r49: number;
  let mock: Awaited<ReturnType<typeof import('./ai-script-mock.ts').startScriptMock>>;
  let saved: { vector_providers: unknown; ai_tools: unknown; ai_agents: unknown };
  const results = (body: string) => /<div class="search-results" id="R\d+_results" aria-live="polite">([\s\S]*?)<\/div>\s*(?:<\/div>|<\/section>)/.exec(body)?.[1] ?? '';
  const embCalls = () => mock.seen.filter((r) => r.path.endsWith('/embeddings')).length;

  before(async () => {
    process.env.PGKILN_SECRET_KEY = 'security-test-secret-key-0123456789abcdef';
    process.env.EMBEDDINGS = 'off';
    const { startScriptMock } = await import('./ai-script-mock.ts');
    const { encryptSecret } = await import('../src/secrets.ts');
    mock = await startScriptMock();
    pageId = (await owner.one('select id from meta.page where app_id = $1 and page_no = 1', [appId])).id;
    saved = (await owner.one('select vector_providers, ai_tools, ai_agents from meta.app where id = $1', [appId]))!;
    await owner.query(`delete from meta.ai_service where name in ('SEC136_SVC', 'HR_ASSISTANT')`);
    const svc = (await owner.one(`insert into meta.ai_service (name, provider, model, base_url, api_key_enc) values ('SEC136_SVC', 'openai_compatible', 'm', $1, $2) returning id`,
      [`${mock.base}/openai/v1`, encryptSecret(KEY)])).id;
    const chat = (await owner.one(`insert into meta.ai_service (name, provider, model, base_url, api_key_enc) values ('HR_ASSISTANT', 'anthropic', 'claude-opus-5-5', $1, $2) returning id`,
      [`${mock.base}/claude`, encryptSecret('sk-ant-sec136')])).id;
    await owner.query('insert into meta.app_ai_service (app_id, service_id) values ($1, $2), ($1, $3)', [appId, svc, chat]);
    await owner.query(`drop schema if exists ${S} cascade; create schema ${S}; grant usage on schema ${S} to hr_app;
      create function ${S}.secret_embed(t text) returns real[] language sql as $f$ select array_fill(0.5::real, array[8]) $f$;
      revoke execute on function ${S}.secret_embed(text) from public;`);
    await owner.query(`update meta.app set vector_providers = vector_providers || $2::jsonb where id = $1`, [appId, JSON.stringify([
      { name: 'SEC136_EMB', type: 'ai_service', service: 'SEC136_SVC', model: 'mock-embed', dimensions: 8 },
      { name: 'SEC136_SECRET', type: 'function', function: `${S}.secret_embed`, dimensions: 8 },
    ])]);
    if (HAS) {
      await owner.query(`create table ${S}.doc (id int primary key, owner_name text not null, title text not null, body text, embedding vector(8));
        alter table ${S}.doc enable row level security;
        create policy doc_own on ${S}.doc for select using (lower(owner_name) = lower(meta.app_user()));
        grant select on ${S}.doc to hr_app;
        insert into ${S}.doc (id, owner_name, title, body) values
          (1, 'king', 'King relocation notes', 'Relocate to another city: the new house'),
          (2, 'allen', 'Allen relocation secret', 'Relocate, house, city, settle for allen'),
          (3, 'king', '<img src=x onerror=alert(1)> moving', '<script>alert(1)</script> house city');
        update ${S}.doc set embedding = translate(hr.policy_embedding(title || ' ' || body)::text, '{}', '[]')::vector;`);
      await owner.query(`delete from meta.search_config where app_id = $1 and name like 'SEC136%'`, [appId]);
      await owner.query(`insert into meta.search_config (app_id, name, label, source_type, source, search_type, vector_provider, vector_column, title_column, description_column)
        values ($1, 'SEC136_VEC', 'Docs', 'table', '${S}.doc', 'vector', 'SEC136_EMB', 'embedding', 'title', 'body')`, [appId]);
      region = (await owner.one(`insert into meta.region (page_id, seq, title, type, config) values ($1, 995, 'Search', 'search', '{"configs": ["SEC136_VEC"]}') returning id`, [pageId])).id;
      r49 = (await owner.one(`select r.id from meta.region r join meta.page p on p.id = r.page_id where p.app_id = $1 and p.page_no = 49 and r.type = 'ai_assistant'`, [appId])).id;
    }
    await owner.query(`delete from meta.developer where username = $1`, [DEV]);
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false)`, [DEV, DEV_PW]);
  });

  after(async () => {
    if (region) await owner.query('delete from meta.region where id = $1', [region]);
    await owner.query(`delete from meta.search_config where app_id = $1 and name like 'SEC136%'`, [appId]);
    await owner.query('update meta.app set vector_providers = $2, ai_tools = $3, ai_agents = $4 where id = $1',
      [appId, JSON.stringify(saved.vector_providers), JSON.stringify(saved.ai_tools), JSON.stringify(saved.ai_agents)]);
    await owner.query(`delete from meta.embedding_queue where provider like 'SEC136%'`);
    await owner.query(`drop schema if exists ${S} cascade`);
    await owner.query(`delete from meta.ai_service where name in ('SEC136_SVC', 'HR_ASSISTANT')`);
    await owner.query(`delete from meta.ai_conversation where app_id = $1`, [appId]);
    await owner.query(`delete from meta.session where username = $1 and app_id is null`, [DEV]);
    await owner.query(`delete from meta.developer where username = $1`, [DEV]);
    await mock.close();
    for (const k of ['PGKILN_SECRET_KEY', 'EMBEDDINGS']) if (env[k] === undefined) delete process.env[k];
    else process.env[k] = env[k];
  });

  test('vector search: the text is a parameter, row level security decides what is found, results escaped', NEEDS, async () => {
    const king = await as('king');
    const allen = await as('allen');
    for (const q of [`'); drop table ${S}.doc; --`, `relocate' or '1'='1`, '$1::text', '[1,2,3]', '\\', 'a'.repeat(500)]) {
      const r = await king.get(`/a/hr/1?s${region}=${encodeURIComponent(q)}`);
      assert.equal(r.statusCode, 200, q);
      assert.doesNotMatch(r.body, /alert-error/, q);
    }
    assert.ok(await owner.one(`select to_regclass('${S}.doc') as t`).then((x) => x.t), 'the table is still there');
    const k = results((await king.get(`/a/hr/1?s${region}=${encodeURIComponent('time off for a family move')}`)).body);
    assert.match(k, /King relocation notes/);
    assert.doesNotMatch(k, /Allen/);
    assert.match(k, /&lt;img src=x onerror=alert\(1\)&gt; moving/);
    assert.match(k, /&lt;script&gt;alert\(1\)&lt;\/script&gt;/);
    assert.doesNotMatch(k, /<script|<img/);
    const a = results((await allen.get(`/a/hr/1?s${region}=${encodeURIComponent('time off for a family move')}`)).body);
    assert.match(a, /Allen relocation secret/);
    assert.doesNotMatch(a, /King/);
  });

  test('Retrieve: the model gets only the rows the user may read; its answer is escaped', NEEDS, async () => {
    const tools = [...(saved.ai_tools as any[]), { name: 'sec_docs', type: 'retrieve', search_config: 'SEC136_VEC', description: 'Docs.' }];
    const agents = (saved.ai_agents as any[]).map((g) => (g.name === 'POLICY_AGENT' ? { ...g, tools: ['sec_docs'] } : g));
    await owner.query('update meta.app set ai_tools = $2, ai_agents = $3 where id = $1', [appId, JSON.stringify(tools), JSON.stringify(agents)]);
    const f = new FileBrowser(app);
    assert.equal((await f.login('king')).statusCode, 303);
    await f.get('/a/hr/49');
    mock.script = [{ tools: [{ name: 'sec_docs', input: { QUERY: 'relocation house city' } }] }, { text: 'See <img src=x onerror=alert(1)> and <b>this</b>.' }];
    const before = mock.seen.length;
    await f.submit(`/a/hr/49/assistant/${r49}/send`, { message: 'Where do I move?', params: '' });
    const calls = mock.seen.slice(before).filter((r) => r.path === '/claude/v1/messages');
    const given = calls[1].body.messages.at(-1).content[0].content as string;
    assert.match(given, /King relocation notes/);
    assert.doesNotMatch(given, /Allen/, 'allen\'s row never reaches the model');
    const page = (await f.get('/a/hr/49')).body;
    assert.match(page, /See &lt;img src=x onerror=alert\(1\)&gt; and/);
    assert.doesNotMatch(page, /<img src=x/);
    // a Retrieve tool's arguments: only QUERY; the configuration a plain name (definitions are checked)
    const { aiToolProblems } = await import('../src/runtime/ai-agents.ts');
    assert.ok(aiToolProblems({ name: 'x', type: 'retrieve', description: 'd', search_config: `SEC136_VEC'; drop table x; --` }).length);
  });

  test('provider keys: write-only, never exported or shown, not readable by the runtime role', async () => {
    const doc = JSON.stringify((await owner.one(`select meta.export_app('hr') as d`)).d);
    assert.match(doc, /SEC136_EMB/, 'the provider travels with the application');
    assert.ok(!doc.includes(KEY) && !doc.includes('api_key_enc'));
    for (const t of ['ai_service', 'embedding_queue'])
      await assert.rejects(runtime.query(`select * from meta.${t}`), /permission denied/, t);
    const def = (await owner.one(`select meta.vector_provider('SEC136_EMB', $1) as d`, [appId])).d;
    assert.deepEqual(Object.keys(def).sort(), ['dimensions', 'model', 'name', 'service', 'type']);
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.submit('/builder/login', { username: 'admin', password: 'admin' })).statusCode, 303);
    const page = (await b.get(`/builder/apps/${appId}/vector-providers/provider?name=SEC136_EMB`)).body;
    assert.doesNotMatch(page, new RegExp(KEY));
    // a Claude service can't be a provider's service (no embeddings): the call is refused before any request
    const { embedTexts } = await import('../src/ai/embeddings.ts');
    const n = embCalls();
    await assert.rejects(embedTexts({ name: 'X', type: 'ai_service', service: 'HR_ASSISTANT', model: 'm', dimensions: 8 }, ['x'], { appId }), /Claude has no embeddings API/);
    // an application that may not use the service can't embed with it
    const other = (await owner.one(`insert into meta.app (alias, name, db_role) values ('sec136-other', 'Sec136 other', 'hr_app') returning id`)).id;
    try {
      await assert.rejects(embedTexts({ name: 'X', type: 'ai_service', service: 'SEC136_SVC', model: 'm', dimensions: 8 }, ['x'], { appId: other }), /may not use AI service SEC136_SVC/);
    } finally {
      await owner.query('delete from meta.app where id = $1', [other]);
    }
    assert.equal(embCalls(), n);
  });

  test('meta.embed: a function provider as the caller (its grants apply); an AI service is never called from SQL', async () => {
    const asApp = (sql: string, params: unknown[] = []) => runtime.tx(async (c) => {
      await c.query(`select set_config('pgkiln.app_id', $1, true)`, [String(appId)]);
      await c.query('set local role hr_app');
      return (await c.query(sql, params)).rows;
    });
    await assert.rejects(asApp(`select meta.embed('x', 'SEC136_SECRET')`), /permission denied for function secret_embed/);
    assert.equal((await owner.one(`select cardinality(meta.embed('x', 'SEC136_SECRET', $1)) as n`, [appId])).n, 8, 'the owner may');
    if (HAS) assert.equal((await asApp(`select cardinality(meta.embed('relocation', 'POLICY_EMBEDDINGS')) as n`))[0].n, 8, 'the HR stand-in is granted to hr_app');
    const n = embCalls();
    await assert.rejects(asApp(`select meta.embed('x', 'SEC136_EMB')`), /which the pgkiln server calls/);
    assert.equal(embCalls(), n, 'no request from SQL');
    // a function name stored past the builder is checked again before it is called
    await owner.query(`update meta.app set vector_providers = vector_providers || $2::jsonb where id = $1`,
      [appId, JSON.stringify([{ name: 'SEC136_EVIL', type: 'function', function: `${S}.secret_embed($1); drop schema ${S} cascade; --`, dimensions: 8 }])]);
    await assert.rejects(owner.query(`select meta.embed('x', 'SEC136_EVIL', $1)`, [appId]), /is schema\.name/);
    assert.ok(await owner.one(`select to_regnamespace('${S}') as s`).then((x) => x.s));
    // the queue: trigger functions can't be called directly, the runtime role can't write the queue, bad trigger arguments are refused
    await assert.rejects(asApp('select meta.embedding_enqueue()'), /trigger functions can only be called as triggers/);
    await assert.rejects(runtime.query(`insert into meta.embedding_queue (app_id, provider, tbl, vector_column, key_column, source_columns, key_value) values ($1, 'X', 1, 'e', 'id', '{t}', '1')`, [appId]), /permission denied/);
    await owner.query(`create table ${S}.t (id int primary key, body text);
      create trigger bad after insert on ${S}.t for each row execute function meta.embedding_enqueue('${appId}', 'SEC136_EMB', 'e; drop table x', 'id', 'body')`);
    await assert.rejects(owner.query(`insert into ${S}.t values (1, 'x')`), /the arguments are app id, provider, vector column/);
  });

  test('identifiers: the database refuses anything but plain names in vector search configurations', async () => {
    const ins = (cols: Record<string, unknown>) => owner.query(
      `insert into meta.search_config (app_id, name, label, source_type, source, search_type, vector_provider, vector_column, key_column, distance, min_similarity, title_column)
       values ($1, 'SEC136_X', 'X', 'table', 'hr.policy', $2, $3, $4, $5, $6, $7, 'title')`,
      [appId, cols.search_type ?? 'vector', cols.vector_provider ?? 'SEC136_EMB', cols.vector_column ?? 'embedding', cols.key_column ?? 'id', cols.distance ?? 'cosine', cols.min_similarity ?? null]);
    for (const [k, v, re] of [
      ['vector_column', 'embedding) or true; --', /vector_column_check/],
      ['key_column', 'id; drop table x', /key_column_check/],
      ['vector_provider', 'sec136_emb', /vector_provider_check/],
      ['distance', 'manhattan', /distance_check/],
      ['min_similarity', 5, /min_similarity_check/],
      ['search_type', 'semantic', /search_type_check/],
    ] as const) await assert.rejects(ins({ [k]: v }), re, k);
    await assert.rejects(owner.query(`insert into meta.search_config (app_id, name, label, source_type, source, search_type, title_column) values ($1, 'SEC136_Y', 'Y', 'table', 'hr.policy', 'vector', 'title')`, [appId]), /search_config_vector_check/);
  });

  test('Table Properties › Add vector column: names from the catalog only, providers of the workspace; developers only; CSRF', NEEDS, async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.submit('/builder/login', { username: 'admin', password: 'admin' })).statusCode, 303);
    await owner.query(`create table ${S}.page (id int primary key, title text)`);
    await b.get(`/builder/sql/objects/vector?o=${S}.page`);
    const base = { o: `${S}.page`, provider: `${appId}:SEC136_EMB`, keep: 'queue', 'c.0.name': 'title', 'c.0.use': 'on', distance: 'cosine', column: 'embedding', index: 'page_embedding_idx', mode: 'apply' };
    for (const [k, v, msg] of [
      ['column', 'x vector; drop table x', /is not a valid name/],
      ['index', 'i on x; drop table x', /is not a valid name/],
      ['provider', `${appId}:NO_SUCH`, /Choose a vector provider/],
      ['provider', `${appId}:SEC136_EMB'); drop table x; --`, /Choose a vector provider/],
    ] as const) {
      const r = await b.submit('/builder/sql/objects/vector', { ...base, [k]: v });
      assert.equal(r.statusCode, 200, k);
      assert.match(r.body, msg, `${k}: ${v}`);
    }
    // a distance outside the list and a column the table doesn't have don't reach the DDL
    const w = (await b.submit('/builder/sql/objects/vector', { ...base, mode: 'preview', distance: `cosine); drop table x; --`, 'c.1.name': 'id); drop table x; --', 'c.1.use': 'on' })).body;
    assert.match(w, /using hnsw \(embedding vector_cosine_ops\);/);
    assert.doesNotMatch(w, /drop table/);
    assert.equal((await owner.one(`select count(*)::int as n from pg_attribute where attrelid = '${S}.page'::regclass and attname = 'embedding'`)).n, 0);
    assert.equal((await b.get('/builder/sql/objects/vector?o=meta.app')).statusCode, 404);
    assert.equal((await b.get(`/builder/sql/objects/vector?o=${S}.nope`)).statusCode, 404);
    assert.equal((await b.submit('/builder/sql/objects/vector', { o: `${S}.page`, column: 'title', mode: 'backfill' })).statusCode, 404, 'only a column a trigger keeps');
    assert.notEqual((await new Browser().get(`/builder/sql/objects/vector?o=${S}.page`)).statusCode, 200);
    assert.equal((await b.post('/builder/sql/objects/vector', { ...base })).statusCode, 403);
  });

  test('only administrators create the pgvector extension', async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.submit('/builder/login', { username: DEV, password: DEV_PW })).statusCode, 303);
    const page = (await b.get('/builder/vector-providers')).body;
    assert.doesNotMatch(page, /action="\/builder\/vector-providers\/extension"/);
    assert.equal((await b.submit('/builder/vector-providers/extension', {})).statusCode, 403);
    assert.equal((await b.post('/builder/vector-providers/extension', {})).statusCode, 403, 'CSRF');
  });
});

describe('sprint 137 AP-3', () => {
  // Create page (the grid of page types, Add feature, Create page as copy): developers only, CSRF on every post;
  // a page is copied only from an application of the same workspace; a dashboard only charts tables the
  // application's role can read; features never install twice and check their input; the Configuration page's
  // functions switch only configurable build options, only for the application's administrators and only as its
  // own role; the activity report by mail only for the application's automations and administrators.
  const DEV = 'sec137_dev';
  const DEV_PW = 'Sec137-dev-password!';
  let otherWs: number;
  let otherApp: number;
  const admin = async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.submit('/builder/login', { username: 'admin', password: 'admin' })).statusCode, 303);
    return b;
  };
  /** In a transaction that is rolled back: as the application's role, with these settings. */
  const asApp = async (settings: Record<string, string>, fn: (q: (sql: string, p?: unknown[]) => Promise<any[]>) => Promise<void>) => {
    const ROLLBACK = new Error('rollback');
    await owner.tx(async (c) => {
      for (const [k, v] of Object.entries(settings)) await c.query('select set_config($1, $2, true)', [k, v]);
      await c.query('set local role hr_app');
      await fn(async (sql, p) => (await c.query(sql, p as unknown[])).rows);
      throw ROLLBACK;
    }).catch((e) => {
      if (e !== ROLLBACK) throw e;
    });
  };

  before(async () => {
    await owner.query(`delete from meta.app where alias = 'sec137-other'`);
    await owner.query(`delete from meta.workspace where name = 'Sec137 Other'`);
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false) on conflict do nothing`, [DEV, DEV_PW]);
    otherWs = (await owner.one(`insert into meta.workspace (name) values ('Sec137 Other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [otherWs, DEV]);
    otherApp = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('sec137-other', 'Sec137 other', 'none', 'hr_app') returning id`)).id;
    await owner.query('insert into meta.workspace_app (workspace_id, app_id) values ($1, $2)', [otherWs, otherApp]);
    await owner.query(`insert into meta.page (app_id, page_no, name, requires_auth) values ($1, 1, 'Secret page', false)`, [otherApp]);
  });
  after(async () => {
    await owner.query(`delete from meta.app where alias = 'sec137-other'`);
    await owner.query(`delete from meta.workspace where name = 'Sec137 Other'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`delete from meta.page where app_id = $1 and page_no between 9370 and 9379`, [appId]);
    await owner.query(`delete from meta.nav_entry where app_id = $1 and target_page between 9370 and 9379`, [appId]);
    await owner.query(`delete from meta.build_option where app_id = $1 and name like 'SEC137%'`, [appId]);
  });

  test('copy page: only from an application of the same workspace; another workspace\'s pages are never offered or copied', async () => {
    const b = await admin();
    const step1 = (await b.get(`/builder/apps/${appId}/create-page?tab=copy`)).body;
    assert.doesNotMatch(step1, /Sec137 other/);
    const step2 = await b.get(`/builder/apps/${appId}/copy-page?from=${otherApp}`);
    assert.equal(step2.statusCode, 303);
    for (const from of [String(otherApp), `${otherApp} or 1=1`, '-1', ''])
      await b.submit(`/builder/apps/${appId}/copy-page`, { from, page: '1', new_page: '9370', name: 'Stolen' });
    assert.equal(await owner.one('select 1 as x from meta.page where app_id = $1 and page_no = 9370', [appId]), undefined);
    // the other workspace's developer can't open or change this application, nor copy its pages into theirs
    const d = new FileBrowser(app);
    await d.get('/builder/login');
    await d.submit('/builder/login', { username: DEV, password: DEV_PW });
    await d.get('/builder/apps');
    assert.equal((await d.get(`/builder/apps/${appId}/create-page`)).statusCode, 404);
    assert.equal((await d.submit(`/builder/apps/${appId}/copy-page`, { from: String(appId), page: '1', new_page: '9371', name: 'x' })).statusCode, 404);
    assert.equal((await d.submit(`/builder/apps/${appId}/features/feedback`, {})).statusCode, 404);
    await d.get(`/builder/apps/${otherApp}/create-page?tab=copy`);
    await d.submit(`/builder/apps/${otherApp}/copy-page`, { from: String(appId), page: '1', new_page: '5', name: 'HR home' });
    assert.equal(await owner.one('select 1 as x from meta.page where app_id = $1 and page_no = 5', [otherApp]), undefined);
    // map keys of unknown kinds are ignored; a mapping to a name the target lacks is refused
    await b.get(`/builder/apps/${appId}/copy-page?from=${appId}&page=1`);
    const r = await b.submit(`/builder/apps/${appId}/copy-page`, { from: String(appId), page: '1', new_page: '9372', name: 'Copy', 'map:pg_authid:x': 'y', 'map:lov:x\'; drop table x; --': 'z' });
    assert.equal(r.statusCode, 303);
    assert.ok(await owner.one('select 1 as x from meta.page where app_id = $1 and page_no = 9372', [appId]));
    await assert.rejects(owner.query(`select meta.copy_page($1, 3, $1, 9373, null, '{"lov:JOBS": "NO_SUCH_LOV"}')`, [appId]), /has no lov NO_SUCH_LOV/);
    // the functions are the owner's: the runtime and application roles can't call them
    for (const role of ['pgkiln_runtime', 'hr_app'])
      assert.equal((await owner.one(`select has_function_privilege($1, 'meta.copy_page(int, int, int, int, text, jsonb)', 'execute') as x`, [role])).x, false, role);
    assert.equal((await b.post(`/builder/apps/${appId}/copy-page`, { from: String(appId), page: '1', new_page: '9374', name: 'x' })).statusCode, 403, 'CSRF');
  });

  test('add feature: CSRF, developers only, unknown features 404, never twice, addresses checked', async () => {
    const b = await admin();
    await b.get(`/builder/apps/${appId}/features/email`);
    assert.equal((await b.post(`/builder/apps/${appId}/features/email`, { report_to: 'x@example.com' })).statusCode, 403, 'CSRF');
    assert.equal((await b.get(`/builder/apps/${appId}/features/nope`)).statusCode, 404);
    assert.equal((await b.submit(`/builder/apps/${appId}/features/__proto__`, {})).statusCode, 404);
    for (const to of ['a@example.com\r\nBcc: evil@example.com', 'a@example.com; evil@example.com', '<script>@x.y'])
      await b.submit(`/builder/apps/${appId}/features/email`, { report_to: to });
    assert.equal(await owner.one(`select 1 as x from meta.automation where app_id = $1 and name = 'EMAIL_REPORTING'`, [appId]), undefined);
    // feedback is on in HR already: refused, nothing changes
    const twice = await b.submit(`/builder/apps/${appId}/features/feedback`, {});
    assert.match((await b.get(twice.headers.location as string)).body, /installed in this application already/);
    const anon = new FileBrowser(app);
    assert.notEqual((await anon.get(`/builder/apps/${appId}/create-page`)).statusCode, 200);
    assert.notEqual((await anon.post(`/builder/apps/${appId}/features/access`, {})).statusCode, 303);
  });

  test('dashboard and the other page types: only tables the application can read; identifiers checked', async () => {
    const b = await admin();
    await b.get(`/builder/apps/${appId}/wizard?kind=dashboard`);
    const r = await b.submit(`/builder/apps/${appId}/wizard`, { kind: 'dashboard', report_page: '9375', tables: ['meta.app', 'pg_catalog.pg_authid', 'meta.account'] });
    assert.match((await b.get(r.headers.location as string)).body, /Choose at least one table the application can read/);
    assert.equal(await owner.one('select 1 as x from meta.page where app_id = $1 and page_no = 9375', [appId]), undefined);
    const gen = (kind: string, table: string | null, o: Record<string, unknown>) =>
      owner.query(`select meta.generate_page('hr', $1, $2::regclass, 9376, $3::jsonb)`, [kind, table, JSON.stringify(o)]);
    await assert.rejects(gen('tree', 'meta.account', {}), /can't be generated on meta.account/);
    await assert.rejects(gen('timeline', 'pg_catalog.pg_authid', {}), /can't be generated/);
    await assert.rejects(gen('tree', 'hr.emp', { label_column: 'ename) from hr.emp; drop table x; --' }), /is not a column of hr.emp/);
    await assert.rejects(gen('comments', 'hr.emp', { comment: 'job', user: '"ename"' }), /is not a column/);
    await assert.rejects(gen('data_load', 'hr.emp', { definition: "X'; drop table x; --" }), /upper case letters/);
    await assert.rejects(gen('search', null, { configs: ["X') or true --"] }), /no search configuration/);
    // tasks and workflows: only the known contexts reach the region
    await gen('tasks', null, { context: '<script>' });
    assert.equal((await owner.one(`select r.config->>'context' as c from meta.region r join meta.page p on p.id = r.page_id where p.app_id = $1 and p.page_no = 9376`, [appId])).c, 'my');
  });

  test('configuration options: only as the application\'s role, for its administrators, only configurable options', async () => {
    await owner.query(`insert into meta.build_option (app_id, name, status, configurable) values ($1, 'SEC137_ON', 'exclude', true), ($1, 'SEC137_FIXED', 'include', false)`, [appId]);
    // has_role reads the session's roles: a session of king (admin) and of allen (none)
    const session = async (user: string, roles: string[]) =>
      (await owner.one(`insert into meta.session (token_hash, app_id, username, roles) values (encode(gen_random_bytes(16), 'hex'), $1, $2, $3) returning id`, [appId, user, roles])).id as string;
    const sessions = { king: await session('king', ['admin', 'manager']), allen: await session('allen', []) };
    const settings = (user: 'king' | 'allen') => ({ 'pgkiln.app_id': String(appId), 'pgkiln.app_user': user, 'pgkiln.session_id': sessions[user] });
    await asApp(settings('king'), async (q) => {
      assert.deepEqual((await q(`select name, enabled from meta.configurable_options() where name like 'SEC137%'`)), [{ name: 'SEC137_ON', enabled: false }]);
      assert.equal((await q(`select meta.set_configurable_options('SEC137_ON') as n`))[0].n, 1);
      await q('reset role');
      assert.equal((await q(`select meta.build_option_on($1, 'SEC137_ON') as x`, [appId]))[0].x, true);
    });
    await asApp(settings('king'), async (q) => {
      await assert.rejects(q(`select meta.set_configurable_options('SEC137_ON:SEC137_FIXED')`), /only configurable build options/);
    });
    await asApp(settings('allen'), async (q) => {
      await assert.rejects(q(`select meta.set_configurable_options('SEC137_ON')`), /for the application's administrators/);
    });
    await asApp(settings('allen'), async (q) => {
      await assert.rejects(q(`select * from meta.configurable_options()`), /for the application's administrators/);
    });
    // another application's role (or the runtime's own) can't claim HR
    await owner.tx(async (c) => {
      await c.query(`select set_config('pgkiln.app_id', $1, true), set_config('pgkiln.app_user', 'king', true), set_config('pgkiln.session_id', $2, true)`, [String(appId), sessions.king]);
      await c.query('set local role pgkiln_runtime');
      await assert.rejects(c.query(`select meta.set_configurable_options('SEC137_ON')`), /outside the application's own database role/);
    }).catch((e) => {
      if (!/outside|current transaction is aborted/.test(String(e))) throw e;
    });
    assert.equal((await owner.one(`select status from meta.build_option where app_id = $1 and name = 'SEC137_ON'`, [appId])).status, 'exclude');
    // an export made before 137 has no "configurable": the trigger fills false
    await owner.query(`insert into meta.build_option select (jsonb_populate_record(null::meta.build_option, '{"app_id": ${appId}, "name": "SEC137_OLD", "status": "include"}'::jsonb || jsonb_build_object('id', nextval('meta.build_option_id_seq')))).*`);
    assert.equal((await owner.one(`select configurable from meta.build_option where app_id = $1 and name = 'SEC137_OLD'`, [appId])).configurable, false);
    // the application user's name alone (no session with the role) is not enough
    await asApp({ 'pgkiln.app_id': String(appId), 'pgkiln.app_user': 'king' }, async (q) => {
      await assert.rejects(q(`select meta.set_configurable_options('SEC137_ON')`), /for the application's administrators/);
    });
    await owner.query('delete from meta.session where id = any($1)', [Object.values(sessions)]);
  });

  test('the activity report by mail: only the application\'s automations and administrators', async () => {
    await asApp({ 'pgkiln.app_id': String(appId), 'pgkiln.app_user': 'allen' }, async (q) => {
      await assert.rejects(q(`select meta.send_activity_report('x@example.com', 7)`), /for the application's automations and administrators/);
    });
    // an automation of another application doesn't count
    const foreign = (await owner.one(`insert into meta.automation (app_id, name) values ($1, 'SEC137') returning id`, [otherApp])).id;
    await asApp({ 'pgkiln.app_id': String(appId), 'pgkiln.automation_id': String(foreign) }, async (q) => {
      await assert.rejects(q(`select meta.send_activity_report('x@example.com', 7)`), /for the application's automations and administrators/);
    });
    const own = (await owner.one(`insert into meta.automation (app_id, name, enabled) values ($1, 'SEC137', false) returning id`, [appId])).id;
    try {
      await asApp({ 'pgkiln.app_id': String(appId), 'pgkiln.automation_id': String(own) }, async (q) => {
        // past the check: the mail itself needs the application's mail service, or is sent
        await q('savepoint s137');
        await q(`select meta.send_activity_report('x@example.com', 7)`).catch((e) => assert.match(String(e), /meta\.send_mail/));
        await q('rollback to savepoint s137');
        assert.equal((await q(`select meta.send_activity_report('', 7) as x`))[0].x, null, 'no addresses: nothing is sent');
      });
    } finally {
      await owner.query('delete from meta.automation where id = $1', [own]);
    }
    assert.equal((await owner.one(`select has_function_privilege('pgkiln_runtime', 'meta.page_shared_refs(int, int)', 'execute') as x`)).x, false);
  });
});

describe('sprint 138 AP-5', () => {
  const DEV = 'sec138_dev';
  const DEV_PW = 'Sec138-dev-password!';
  const S = 'sec138';
  let hr: number;
  let otherWs: number;
  let region: number;
  const signIn = async (username: string, password: string) => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.submit('/builder/login', { username, password })).statusCode, 303);
    return b;
  };
  before(async () => {
    hr = (await owner.one(`select id from meta.app where alias = 'hr'`)).id;
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false) on conflict do nothing`, [DEV, DEV_PW]);
    otherWs = (await owner.one(`insert into meta.workspace (name) values ('Sec138 Other') returning id`)).id;
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [otherWs, DEV]);
    await owner.query(`drop schema if exists ${S} cascade; create schema ${S}; create table ${S}.keep (id int primary key)`);
    const page = (await owner.one('select id from meta.page where app_id = $1 and page_no = 1', [hr])).id;
    // a fragment that tries to end the parsed function and run a statement of its own
    region = (await owner.one(`insert into meta.region (page_id, seq, title, type, source) values ($1, 991, 'Sec138', 'report', $2) returning id`,
      [page, `select 1 from hr.emp; end; drop table ${S}.keep; create function pg_temp.x() returns void language sql begin atomic select 1`])).id;
  });
  after(async () => {
    await owner.query('delete from meta.region where id = $1', [region]);
    await owner.query(`delete from meta.workspace where name = 'Sec138 Other'`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`delete from meta.ui_default where schema_name = $1 or (schema_name = 'hr' and table_name = 'dept')`, [S]);
    await owner.query(`drop schema if exists ${S} cascade`);
  });

  test('developers only; another workspace\'s application doesn\'t exist; CSRF on every post', async () => {
    for (const url of [`/builder/apps/${hr}/utilities`, `/builder/apps/${hr}/utilities/dependencies`, `/builder/apps/${hr}/utilities/history`, `/builder/apps/${hr}/utilities/upgrade`, '/builder/ui-defaults', '/builder/icons'])
      assert.notEqual((await new FileBrowser(app).get(url)).statusCode, 200, url);
    const d = await signIn(DEV, DEV_PW);
    for (const url of [`/builder/apps/${hr}/utilities`, `/builder/apps/${hr}/utilities/dependencies`, `/builder/apps/${hr}/utilities/history`, `/builder/apps/${hr}/utilities/upgrade`])
      assert.equal((await d.get(url)).statusCode, 404, url);
    await d.get('/builder/icons');
    assert.equal((await d.submit(`/builder/apps/${hr}/utilities/upgrade`, { rule: 'nav_appearance' })).statusCode, 404);
    const a = await signIn('admin', 'admin');
    assert.equal((await a.post(`/builder/apps/${hr}/utilities/upgrade`, { rule: 'nav_appearance' })).statusCode, 403, 'CSRF');
    assert.equal((await a.post('/builder/ui-defaults', { schema: 'hr', table: 'dept', 'c.0.name': 'dname', 'c.0.label': 'X' })).statusCode, 403, 'CSRF');
    assert.equal(await owner.one(`select 1 as ok from meta.ui_default where schema_name = 'hr' and table_name = 'dept'`), undefined);
  });

  test('object dependencies: a statement is parsed alone, as the application\'s role, and never run', async () => {
    const { appDependencies } = await import('../src/builder/dependencies.ts');
    const deps = await appDependencies(hr);
    assert.ok(await owner.one(`select 1 as ok from pg_class where oid = to_regclass('${S}.keep')`), 'the table is still there');
    assert.ok(deps.unscanned.some((u) => u.entry?.id === region && /multiple commands|syntax/i.test(u.message)), 'reported as not scanned');
  });

  test('change history: filters are parameters, a change of another application isn\'t shown', async () => {
    const a = await signIn('admin', 'admin');
    for (const q of [`?q=${encodeURIComponent("%' or 1=1 --")}`, '?from=2026-01-01%27', '?page=1;drop', '?dev=%27', '?c=1%20or%201=1'])
      assert.equal((await a.get(`/builder/apps/${hr}/utilities/history${q}`)).statusCode, 200, q);
    const other = (await owner.one(`select id from meta.app where id <> $1 order by id limit 1`, [hr]))?.id;
    if (other) {
      const id = (await owner.one(`insert into meta.component_change (app_id, component, label, op, before, after, changed_by) values ($1, 'app', 'Sec138 secret change', 'changed', '{"app.yaml": "a"}', '{"app.yaml": "b"}', 'x') returning id`, [other])).id;
      assert.doesNotMatch((await a.get(`/builder/apps/${hr}/utilities/history?c=${id}`)).body, /Sec138 secret change/);
      await owner.query('delete from meta.component_change where id = $1', [id]);
    }
    // a label with markup is escaped
    const id = (await owner.one(`insert into meta.component_change (app_id, component, label, op, before, after, changed_by) values ($1, 'app', '<img src=x onerror=alert(1)>', 'changed', '{"app.yaml": "<script>a</script>"}', '{"app.yaml": "b"}', '<b>x</b>') returning id`, [hr])).id;
    const body = (await a.get(`/builder/apps/${hr}/utilities/history?c=${id}`)).body;
    assert.doesNotMatch(body, /<img src=x|<script>a|<b>x<\/b>/);
    await owner.query('delete from meta.component_change where id = $1', [id]);
  });

  test('UI defaults: tables of the catalog only, known columns only, masks checked, values escaped', async () => {
    const a = await signIn('admin', 'admin');
    assert.equal((await a.get('/builder/ui-defaults?schema=meta&table=app')).body.includes('name="c.0.name"'), false, 'not pgkiln\'s own schema');
    await a.get('/builder/ui-defaults?schema=hr&table=dept');
    for (const [schema, table] of [['meta', 'app'], ['hr', 'nope'], ['hr', "dept'; drop table x; --"], ['pg_catalog', 'pg_authid']])
      assert.equal((await a.submit('/builder/ui-defaults', { schema, table, 'c.0.name': 'id', 'c.0.label': 'X' })).statusCode, 404, `${schema}.${table}`);
    await a.submit('/builder/ui-defaults', { schema: 'hr', table: 'dept', 'c.0.name': 'no_such_column', 'c.0.label': 'X', 'c.1.name': 'dname', 'c.1.format_mask': "9'); drop table x; --" });
    assert.equal(await owner.one(`select 1 as ok from meta.ui_default where schema_name = 'hr' and table_name = 'dept'`), undefined);
    await assert.rejects(owner.query(`insert into meta.ui_default (schema_name, table_name, column_name, format_mask) values ('hr', 'dept', 'dname', '9<script>')`), /format_mask_check/);
    await assert.rejects(owner.query(`insert into meta.ui_default (schema_name, table_name, column_name, alignment) values ('hr', 'dept', 'dname', 'left')`), /alignment_check/);
    await a.submit('/builder/ui-defaults', { schema: 'hr', table: 'dept', 'c.1.name': 'dname', 'c.1.label': '<script>alert(1)</script>' });
    const page = (await a.get('/builder/ui-defaults?schema=hr&table=dept')).body;
    assert.doesNotMatch(page, /<script>alert/);
    assert.match(page, /&lt;script&gt;alert/);
  });

  test('upgrade application: only candidates found again are changed', async () => {
    const a = await signIn('admin', 'admin');
    await a.get(`/builder/apps/${hr}/utilities/upgrade`);
    const other = await owner.one(`select i.id, i.type from meta.item i join meta.page p on p.id = i.page_id where p.app_id = $1 and i.type = 'text' limit 1`, [hr]);
    for (const key of [`date_picker:${other.id}`, `popup_lov:${other.id} or 1=1`, `nav_appearance:app'; drop table x; --`])
      await a.submit(`/builder/apps/${hr}/utilities/upgrade`, { key });
    assert.equal((await owner.one('select type from meta.item where id = $1', [other.id])).type, other.type);
    await a.submit(`/builder/apps/${hr}/utilities/upgrade`, { rule: 'no_such_rule' });
    assert.equal((await owner.one('select type from meta.item where id = $1', [other.id])).type, other.type);
  });
});

describe('sprint 139 AP-6', () => {
  const DEV = 'sec139_dev';
  const DEV_PW = 'Sec139-dev-password!';
  let hrWs: number;
  const signIn = async (username: string, password: string) => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.submit('/builder/login', { username, password })).statusCode, 303);
    return b;
  };
  const otel = () => owner.query<{ name: string; value: string }>(`select name, value from meta.setting where name like 'otel\\_%' or name like 'metrics\\_%' order by name`).then((r) => r.rows);
  before(async () => {
    process.env.PGKILN_SECRET_KEY ??= 'test-only-secret-key-0123456789abcdef';
    hrWs = (await owner.one(`select meta.app_workspace(id) as ws from meta.app where alias = 'hr'`)).ws;
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false) on conflict do nothing`, [DEV, DEV_PW]);
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [hrWs, DEV]);
  });
  after(async () => {
    const { refreshTelemetry } = await import('../src/telemetry/config.ts');
    await owner.query(`delete from meta.setting where name like 'otel\\_%' or name like 'metrics\\_%'; delete from meta.instance_setting where name in ('otel_headers_enc', 'metrics_token_hash')`);
    await owner.query(`update meta.workspace set telemetry = 'instance', telemetry_endpoint = null, telemetry_headers_enc = null, telemetry_values = false`);
    await owner.query('delete from meta.workspace_member where username = $1', [DEV]);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await refreshTelemetry(true);
  });

  test('only administrators see or change the instance\'s OpenTelemetry; CSRF checked', async () => {
    const before = await otel();
    const d = await signIn(DEV, DEV_PW);
    assert.equal((await d.get('/builder/telemetry')).statusCode, 403);
    assert.doesNotMatch((await d.get('/builder/utilities')).body, /href="\/builder\/telemetry"/);
    for (const url of ['/builder/telemetry', '/builder/telemetry/token', '/builder/telemetry/test'])
      assert.equal((await d.submit(url, { enabled: 'true', endpoint: 'http://evil.example:4318', action: 'new' })).statusCode, 403, url);
    const a = await signIn('admin', 'admin');
    await a.get('/builder/telemetry');
    assert.equal((await a.post('/builder/telemetry', { enabled: 'true', endpoint: 'http://evil.example:4318' })).statusCode, 403, 'no CSRF token');
    assert.deepEqual(await otel(), before);
  });

  test('collector URLs: http(s) only, no credentials; headers are write-only and encrypted', async () => {
    const { saveInstanceTelemetry, saveWorkspaceTelemetry, refreshTelemetry } = await import('../src/telemetry/config.ts');
    for (const endpoint of ['javascript:alert(1)', 'file:///etc/passwd', 'http://user:pw@collector:4318', 'http://collector:4318/#x', 'not a url'])
      assert.match((await saveInstanceTelemetry({ enabled: 'true', endpoint })) ?? '', /Collector URL/, endpoint);
    assert.equal(await saveInstanceTelemetry({ enabled: 'false', endpoint: 'http://127.0.0.1:9', headers: 'authorization=Bearer sec139-collector-token' }), null);
    const stored = (await owner.one(`select value from meta.instance_setting where name = 'otel_headers_enc'`)).value;
    assert.equal(await owner.one(`select 1 as x from meta.setting where name like '%\\_enc' or name like '%\\_hash'`), undefined, 'secrets out of meta.setting (the runtime role reads it)');
    assert.doesNotMatch(stored, /sec139-collector-token/);
    const a = await signIn('admin', 'admin');
    const page = (await a.get('/builder/telemetry')).body;
    assert.match(page, /authorization/);
    assert.doesNotMatch(page, /sec139-collector-token/);
    // the database refuses a bad workspace endpoint even past the builder
    await assert.rejects(owner.query(`update meta.workspace set telemetry = 'own', telemetry_endpoint = 'javascript:alert(1)' where id = $1`, [hrWs]), /telemetry_endpoint_ok/);
    await assert.rejects(owner.query(`update meta.workspace set telemetry = 'own', telemetry_endpoint = null where id = $1`, [hrWs]), /workspace_telemetry_own/);
    assert.match((await saveWorkspaceTelemetry(hrWs, { mode: 'own', endpoint: 'http://u:p@x.example' })) ?? '', /Collector URL/);
    assert.match((await saveWorkspaceTelemetry(hrWs, { mode: 'nonsense' })) ?? '', /Unknown/);
    await refreshTelemetry(true);
  });

  test('a workspace\'s own collector: its administrators only, and through the allow-lists', async () => {
    const d = await signIn(DEV, DEV_PW);
    assert.equal((await d.get(`/builder/workspaces/${hrWs}/telemetry`)).statusCode, 403, 'a member, not an administrator');
    assert.equal((await d.submit(`/builder/workspaces/${hrWs}/telemetry`, { mode: 'off' })).statusCode, 403);
    assert.equal((await owner.one('select telemetry from meta.workspace where id = $1', [hrWs])).telemetry, 'instance');
    // an address the installation's allow-list doesn't have is refused when sending (a workspace administrator is not an instance one)
    const { saveWorkspaceTelemetry } = await import('../src/telemetry/config.ts');
    const { sendTest } = await import('../src/telemetry/export.ts');
    const saved = [process.env.PGKILN_REST_ALLOWED_HOSTS, process.env.PGKILN_REST_PRIVATE_HOSTS];
    process.env.PGKILN_REST_ALLOWED_HOSTS = 'otlp.example.com';
    delete process.env.PGKILN_REST_PRIVATE_HOSTS;
    try {
      assert.equal(await saveWorkspaceTelemetry(hrWs, { mode: 'own', endpoint: 'http://169.254.169.254' }), null);
      assert.match((await sendTest(hrWs)) ?? 'sent', /not|allow|refused|private|permitted/i);
    } finally {
      [process.env.PGKILN_REST_ALLOWED_HOSTS, process.env.PGKILN_REST_PRIVATE_HOSTS] = saved;
      if (saved[0] === undefined) delete process.env.PGKILN_REST_ALLOWED_HOSTS;
      if (saved[1] === undefined) delete process.env.PGKILN_REST_PRIVATE_HOSTS;
      await saveWorkspaceTelemetry(hrWs, { mode: 'instance' });
    }
  });

  test('/metrics: off by default, then an administrator or the token only', async () => {
    const { saveInstanceTelemetry } = await import('../src/telemetry/config.ts');
    await saveInstanceTelemetry({ enabled: 'false', prometheus: 'false' });
    assert.equal((await app.inject({ url: '/metrics' })).statusCode, 404);
    await saveInstanceTelemetry({ enabled: 'false', prometheus: 'true' });
    assert.equal((await app.inject({ url: '/metrics' })).statusCode, 401);
    const d = await signIn(DEV, DEV_PW);
    assert.equal((await d.get('/metrics')).statusCode, 401, 'a developer who is not an administrator');
    for (const auth of ['Bearer ', 'Bearer x', 'Basic YWRtaW46YWRtaW4=', `Bearer ${'a'.repeat(5000)}`])
      assert.equal((await app.inject({ url: '/metrics', headers: { authorization: auth } })).statusCode, 401, auth.slice(0, 20));
    const a = await signIn('admin', 'admin');
    const body = (await a.get('/metrics')).body;
    assert.doesNotMatch(body, /king|admin|sec139/i, 'no user names in labels');
    await saveInstanceTelemetry({ enabled: 'false', prometheus: 'false' });
  });

  test('the browser relay: only a token the server signed, for that application, recent, small', async () => {
    const { saveInstanceTelemetry } = await import('../src/telemetry/config.ts');
    await saveInstanceTelemetry({ enabled: 'true', endpoint: 'http://127.0.0.1:9', browser: 'true', traces: 'true' });
    const post = (payload: string, alias = 'hr', type = 'application/json') => app.inject({ method: 'POST', url: `/a/${alias}/telemetry`, payload, headers: { 'content-type': type } });
    const forged = `${'a'.repeat(32)}.${'b'.repeat(16)}.${Math.floor(Date.now() / 1000)}.${signText('other-scope', 'x')}`;
    assert.equal((await post(JSON.stringify({ t: forged, spans: [{ k: 'load', start: Date.now(), dur: 1 }] }))).statusCode, 403);
    const ts = Math.floor(Date.now() / 1000);
    const forOther = `${'a'.repeat(32)}.${'b'.repeat(16)}.${ts}.${signText('otel-browser', `${'a'.repeat(32)}.${'b'.repeat(16)}.${ts}.other`)}`;
    assert.equal((await post(JSON.stringify({ t: forOther, spans: [] }))).statusCode, 403, 'signed for another application');
    assert.equal((await post(JSON.stringify({ t: forOther, spans: [] }), 'other')).statusCode, 204, 'the same token where it belongs');
    for (const t of [null, 42, '', '../../x', `${forOther}<script>`, { t: 1 }])
      assert.equal((await post(JSON.stringify({ t, spans: [] }))).statusCode, 403, String(t));
    assert.equal((await post('{not json')).statusCode, 400);
    assert.equal((await post(JSON.stringify({ t: forOther, spans: [], pad: 'x'.repeat(40_000) }), 'other')).statusCode, 413);
    await saveInstanceTelemetry({ enabled: 'false', browser: 'false' });
  });
});

describe('sprint 140 AP-4', () => {
  const A = 'sec140';
  const XSS = `<img src=x onerror=alert(1)>"'&`;
  let id: number;
  let pid: number;
  const rid: Record<string, number> = {};
  const signIn = async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.submit('/builder/login', { username: 'admin', password: 'admin' })).statusCode, 303);
    return b;
  };
  const region = async (title: string, type: string, source: string | null, config: object = {}, position: string | null = null) =>
    (await owner.one(`insert into meta.region (page_id, seq, title, type, source, config, position) values ($1, (select coalesce(max(seq), 0) + 10 from meta.region where page_id = $1), $2, $3, $4, $5, $6) returning id`,
      [pid, title, type, source, JSON.stringify(config), position])).id as number;
  before(async () => {
    await owner.query('delete from meta.app where alias = $1', [A]);
    id = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ($1, 'Sec140', 'none', 'hr_app') returning id`, [A])).id;
    await owner.query(`insert into meta.page (app_id, page_no, name, title, requires_auth) values ($1, 1, $2, 'Home', false)`, [id, `Home ${XSS}`]);
    pid = (await owner.one(`insert into meta.page (app_id, page_no, name, title, requires_auth, parent_page, help) values ($1, 2, 'Two', $2, false, 1, $3) returning id`,
      [id, 'Two &P2_ONE.', `<script>alert(1)</script> [x](javascript:alert(1)) **&P2_ONE.**`])).id;
    rid.form = await region('Form', 'static', '');
    // a list that leaves values out (n = 4 is not offered), and display values with markup
    const lov = `select case n when 1 then '${XSS.replace(/'/g, "''")}' else 'Value ' || n end as d, n::text as r from generate_series(1, 3) n`;
    await owner.query(`insert into meta.item (page_id, region_id, seq, name, label, type, lov) values
      ($1, $2, 10, 'P2_SHUTTLE', 'Shuttle', 'shuttle', $3), ($1, $2, 20, 'P2_ONE', 'One', 'select_one', $3), ($1, $2, 30, 'P2_MANY', 'Many', 'select_many', $3),
      ($1, $2, 40, 'P2_RO', 'Read-only', 'shuttle', $3)`, [pid, rid.form, lov]);
    await owner.query(`update meta.item set readonly_condition = 'true', default_value = '1:2' where page_id = $1 and name = 'P2_RO'`, [pid]);
    await owner.query(`insert into meta.button (page_id, region_id, seq, name, label, action) values ($1, $2, 10, 'SAVE', 'Save', 'submit')`, [pid, rid.form]);
    // an application's text message replaces a runtime text: it is escaped where it lands (attributes)
    await owner.query(`insert into meta.text_message (app_id, name, language, text) values ($1, 'shuttle.move', 'en', $2), ($1, 'region.no_help', 'en', $2)`, [id, `Move" onclick="alert(1)`]);
    rid.crumb = await region(`Trail ${XSS}`, 'breadcrumb', null, {}, 'breadcrumb');
    rid.help = await region('Help', 'help_text', null);
    rid.table = await region('Classic', 'classic_report', `select '${XSS.replace(/'/g, "''")}' as "${'<b>h</b>'}", 2 as n`);
    for (const t of ['value_pairs', 'badges', 'media_list'])
      rid[t] = await region(t, 'classic_report', `select '${XSS.replace(/'/g, "''")}' as title, '${XSS.replace(/'/g, "''")}' as description`, { report_template: t, headings: { title: XSS } });
  });
  after(async () => {
    await owner.query('delete from meta.app where alias = $1', [A]);
  });

  test('a value its list of values doesn\'t offer is refused for a shuttle, a select one and a select many', async () => {
    for (const [name, values] of [['P2_SHUTTLE', ['1', '4']], ['P2_ONE', '4'], ['P2_MANY', ['2', '4']], ['P2_ONE', "1' or '1'='1"], ['P2_MANY', '1:4']] as [string, string | string[]][]) {
      const b = new Browser();
      await b.get(`/a/${A}/2`);
      const res = await b.post(`/a/${A}/2`, { __csrf: b.lastCsrf, __request: 'SAVE', [name]: values });
      assert.equal(res.statusCode, 422, `${name} ${values}`);
      assert.match(res.body, new RegExp(`id="${name}_error"`), `${name} ${values}`);
    }
    // the values it offers pass; a read-only item ignores what is posted
    const b = new Browser();
    await b.get(`/a/${A}/2`);
    const ok = await b.post(`/a/${A}/2`, { __csrf: b.lastCsrf, __request: 'SAVE', P2_SHUTTLE: ['3', '1'], P2_ONE: '2', P2_MANY: ['1', '3'], P2_RO: '4' });
    assert.equal(ok.statusCode, 303, ok.body);
    // without the CSRF token nothing is taken
    assert.equal((await b.post(`/a/${A}/2`, { __request: 'SAVE', P2_ONE: '1' })).statusCode, 403);
    // the cascading list of values endpoint: only an item with cascade_parents, with the token
    assert.equal((await b.post(`/a/${A}/2/lov/P2_SHUTTLE`, { __csrf: b.lastCsrf })).statusCode, 403);
  });

  test('display values, texts and data are escaped in the new items and regions', async () => {
    const b = new Browser();
    const page = (await b.get(`/a/${A}/2`)).body;
    assert.doesNotMatch(page, /<img src=x/);
    assert.doesNotMatch(page, /onerror=alert\(1\)>/);
    assert.doesNotMatch(page, /" onclick="alert/);
    assert.match(page, /<option value="1" data-i="0">&lt;img src=x onerror=alert\(1\)&gt;&quot;&#39;&amp;<\/option>/);
    assert.match(page, /data-move-label="Move&quot; onclick=&quot;alert\(1\)"/);
    // read-only: the display values of the chosen values, escaped
    assert.match(page, /<div class="display-value" id="P2_RO">&lt;img src=x onerror=alert\(1\)&gt;&quot;&#39;&amp;, Value 2<\/div>/);
    // the breadcrumb: page names and the region title
    assert.match(page, /aria-label="Trail &lt;img src=x onerror=alert\(1\)&gt;&quot;&#39;&amp;"/);
    assert.match(page, /<a href="\/a\/sec140\/1">Home &lt;img src=x onerror=alert\(1\)&gt;&quot;&#39;&amp;<\/a>/);
    // the classic report: headings and cells, in each template
    assert.match(page, />&lt;B&gt;h&lt;\/b&gt;<span class="sort-ind"/);
    for (const t of ['value_pairs', 'badges', 'media_list']) {
      const section = new RegExp(`<section[^>]* id="R${rid[t]}"[\\s\\S]*?</section>`).exec(page)![0];
      assert.doesNotMatch(section, /<img/, t);
      assert.match(section, /&lt;img src=x/, t);
    }
  });

  test('the help text: Markdown without HTML or script links; item values stay text', async () => {
    const b = new Browser();
    await b.get(`/a/${A}/2`);
    // a value the list offers whose display value has markup; the substitution uses the value itself
    await b.post(`/a/${A}/2`, { __csrf: b.lastCsrf, __request: 'SAVE', P2_ONE: '1' });
    await owner.query(`update meta.item set lov = $2 where page_id = $1 and name = 'P2_ONE'`, [pid, `select '<i>x</i>' as d, '[a](javascript:alert(2))<script>' as r`]);
    try {
      const b2 = new Browser();
      await b2.get(`/a/${A}/2`);
      assert.equal((await b2.post(`/a/${A}/2`, { __csrf: b2.lastCsrf, __request: 'SAVE', P2_ONE: '[a](javascript:alert(2))<script>' })).statusCode, 303);
      const page = (await b2.get(`/a/${A}/2`)).body;
      const help = new RegExp(`<section[^>]* id="R${rid.help}"[\\s\\S]*?</section>`).exec(page)![0];
      assert.doesNotMatch(help, /<script>|href=|<a /);
      assert.match(help, /&lt;script&gt;alert\(1\)&lt;\/script&gt;/);
      assert.match(help, /<strong>\[a\]\(javascript:alert\(2\)\)&lt;script&gt;<\/strong>/);
      // the page title (the breadcrumb's current page) with the same value, escaped
      assert.match(page, /<span aria-current="page">Two \[a\]\(javascript:alert\(2\)\)&lt;script&gt;<\/span>/);
    } finally {
      await owner.query(`update meta.item set lov = (select lov from meta.item where page_id = $1 and name = 'P2_SHUTTLE') where page_id = $1 and name = 'P2_ONE'`, [pid]);
    }
    // no help text: the "no help" text (an application's own text message), escaped
    await owner.query(`update meta.page set help = null where id = $1`, [pid]);
    assert.match((await new Browser().get(`/a/${A}/2`)).body, /<p class="muted help-text-none">Move&quot; onclick=&quot;alert\(1\)<\/p>/);
  });

  test('the page help text: developers only, with the token, at most 20,000 characters', async () => {
    const form = { page_no: '2', name: 'Two', title: 'Two', mode: 'normal', protection: 'checksum', help: 'x'.repeat(30_000) };
    assert.notEqual((await new Browser().post(`/builder/pages/${pid}`, form)).statusCode, 303);
    const d = await signIn();
    await d.get(`/builder/apps/${id}/pages/2`);
    assert.equal((await d.post(`/builder/pages/${pid}`, form)).statusCode, 403, 'without the CSRF token');
    assert.equal((await owner.one('select help from meta.page where id = $1', [pid])).help, null);
    const res = await d.submit(`/builder/pages/${pid}`, form);
    assert.ok([302, 303].includes(res.statusCode), res.body);
    assert.equal((await owner.one('select length(help) as n from meta.page where id = $1', [pid])).n, 20_000);
    await assert.rejects(owner.query(`update meta.page set help = repeat('x', 20001) where id = $1`, [pid]), /check/);
  });
});

describe('sprint 141 AP-7', () => {
  // Static workspace files, remote servers and workspace web credentials: the workspace's administrators manage
  // them, its developers only see them, another workspace's never reach a page or an application; uploaded files
  // keep the static files' types and headers; a server's URL passes every outgoing check (private addresses stay
  // refused unless allowed); secrets are write-only and the runtime role reads none of these tables.
  process.env.PGKILN_SECRET_KEY ??= 'test-only-secret-key-0123456789abcdef';
  const ADMIN_A = 'sec141admina';
  const ADMIN_B = 'sec141adminb';
  const DEV_A = 'sec141deva';
  let wsA: number;
  let wsB: number;
  let appA: number;
  let appB: number;
  let server: import('node:http').Server;
  let base = '';
  const auth: (string | undefined)[] = [];
  const env = { allowed: process.env.PGKILN_REST_ALLOWED_HOSTS, priv: process.env.PGKILN_REST_PRIVATE_HOSTS };
  const signIn = async (username: string, ws?: number) => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username })).statusCode, 303);
    await b.get('/builder/home');
    if (ws) assert.equal((await b.post('/builder/workspace', { __csrf: b.lastCsrf, workspace: String(ws) })).statusCode, 303);
    await b.get('/builder/home');
    return b;
  };

  before(async () => {
    const { createServer } = await import('node:http');
    server = createServer((req, res) => {
      auth.push(req.headers.authorization);
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end('[{"v":1}]');
    });
    await new Promise<void>((r) => server.listen(0, '127.0.0.1', r));
    base = `http://127.0.0.1:${(server.address() as import('node:net').AddressInfo).port}`;
    for (const u of [ADMIN_A, ADMIN_B, DEV_A]) await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [u]);
    await owner.query(`delete from meta.app where alias in ('sec141a', 'sec141b')`);
    await owner.query(`delete from meta.workspace where name in ('Sec141 A', 'Sec141 B')`);
    wsA = (await owner.one(`insert into meta.workspace (name) values ('Sec141 A') returning id`)).id;
    wsB = (await owner.one(`insert into meta.workspace (name) values ('Sec141 B') returning id`)).id;
    await owner.query('insert into meta.workspace_member (workspace_id, username, is_admin) values ($1, $2, true), ($1, $3, false), ($4, $5, true)', [wsA, ADMIN_A, DEV_A, wsB, ADMIN_B]);
    for (const [alias, w] of [['sec141a', wsA], ['sec141b', wsB]] as const) {
      const id = (await owner.one(`insert into meta.app (alias, name, authentication, home_page, db_role) values ($1, $1, 'none', 1, 'hr_app') returning id`, [alias])).id;
      await owner.query(`insert into meta.page (app_id, page_no, name, requires_auth) values ($1, 1, 'Home', false)`, [id]);
      await owner.query('insert into meta.workspace_app (app_id, workspace_id) values ($1, $2)', [id, w]);
      if (alias === 'sec141a') appA = id;
      else appB = id;
    }
    process.env.PGKILN_REST_ALLOWED_HOSTS = '127.0.0.1';
    process.env.PGKILN_REST_PRIVATE_HOSTS = '127.0.0.1';
  });
  after(async () => {
    server.close();
    process.env.PGKILN_REST_ALLOWED_HOSTS = env.allowed;
    process.env.PGKILN_REST_PRIVATE_HOSTS = env.priv;
    if (env.allowed === undefined) delete process.env.PGKILN_REST_ALLOWED_HOSTS;
    if (env.priv === undefined) delete process.env.PGKILN_REST_PRIVATE_HOSTS;
    await owner.query(`delete from meta.app where alias in ('sec141a', 'sec141b')`);
    await owner.query('delete from meta.workspace where id = any($1::int[])', [[wsA, wsB]]);
    await owner.query('delete from meta.developer where username = any($1::text[])', [[ADMIN_A, ADMIN_B, DEV_A]]);
  });

  test('the workspace\'s administrators manage files, servers and credentials; its developers only see them; CSRF', async () => {
    const a = await signIn(ADMIN_A, wsA);
    const dev = await signIn(DEV_A, wsA);
    for (const url of ['/builder/workspace-files', '/builder/remote-servers', '/builder/workspace-credentials']) {
      const page = await dev.get(url);
      assert.equal(page.statusCode, 200, url);
      assert.match(page.body, /the workspace(&#39;|')s administrators change them/, url);
      assert.doesNotMatch(page.body, /action="\/builder\/(workspace-files\/upload|remote-servers"|workspace-credentials")/, url);
    }
    const posts: [string, Record<string, string>][] = [
      ['/builder/remote-servers', { static_id: 'SEC141', name: 'x', base_url: base }],
      ['/builder/workspace-credentials', { name: 'SEC141_KEY', type: 'bearer', secret: 'Sec141-secret-value' }],
      ['/builder/workspace-files/save', { name: 'a.css', content: 'body{}' }],
    ];
    for (const [url, form] of posts) assert.equal((await dev.post(url, { __csrf: dev.lastCsrf, ...form })).statusCode, 403, `developer ${url}`);
    const up = await dev.upload('/builder/workspace-files/upload', {}, { file: { name: 'a.css', type: 'text/css', data: Buffer.from('x') } });
    assert.equal(up.statusCode, 403);
    await a.get('/builder/remote-servers');
    for (const [url, form] of posts) assert.equal((await a.post(url, { __csrf: 'forged', ...form })).statusCode, 403, `forged ${url}`);
    assert.equal((await owner.one('select count(*)::int as n from meta.remote_server where workspace_id = $1', [wsA])).n, 0);
    assert.equal((await owner.one('select count(*)::int as n from meta.workspace_file where workspace_id = $1', [wsA])).n, 0);
    for (const [url, form] of posts) assert.equal((await a.post(url, { __csrf: a.lastCsrf, ...form })).statusCode, 303, `admin ${url}`);
    assert.equal((await owner.one('select count(*)::int as n from meta.remote_server where workspace_id = $1', [wsA])).n, 1);
    assert.equal((await owner.one('select count(*)::int as n from meta.workspace_credential where workspace_id = $1', [wsA])).n, 1);
    assert.equal((await owner.one('select count(*)::int as n from meta.workspace_file where workspace_id = $1', [wsA])).n, 1);
    // a developer of the workspace can't delete either
    const sid = (await owner.one('select id from meta.remote_server where workspace_id = $1', [wsA])).id;
    assert.equal((await dev.post(`/builder/remote-servers/${sid}/delete`, { __csrf: dev.lastCsrf })).statusCode, 403);
    assert.equal((await dev.post('/builder/workspace-files/delete', { __csrf: dev.lastCsrf, name: 'a.css' })).statusCode, 403);
    // an AI service's remote server: installation administrators only
    const ai = (await owner.one(`insert into meta.ai_service (name, provider, model, base_url) values ('SEC141_AI', 'openai', 'm', 'https://api.example.com') returning id`)).id;
    try {
      assert.equal((await a.post(`/builder/ai/${ai}/server`, { __csrf: a.lastCsrf, server_id: String(sid) })).statusCode, 403);
      assert.equal((await owner.one('select server_id from meta.ai_service where id = $1', [ai])).server_id, null);
    } finally {
      await owner.query('delete from meta.ai_service where id = $1', [ai]);
    }
  });

  test('another workspace\'s server, credential and file are never shown, changed, used or served', async () => {
    const b = await signIn(ADMIN_B, wsB);
    // the pages list B's own only
    for (const url of ['/builder/workspace-files', '/builder/remote-servers', '/builder/workspace-credentials']) {
      const body = (await b.get(url)).body;
      assert.doesNotMatch(body, /SEC141|a\.css|Sec141 A/, url);
    }
    // B's administrator can't switch to A, nor reach A's rows by id or name
    await b.post('/builder/workspace', { __csrf: b.lastCsrf, workspace: String(wsA) });
    assert.doesNotMatch((await b.get('/builder/remote-servers')).body, /SEC141/);
    const sid = (await owner.one('select id from meta.remote_server where workspace_id = $1', [wsA])).id;
    const cid = (await owner.one('select id from meta.workspace_credential where workspace_id = $1', [wsA])).id;
    await b.post(`/builder/remote-servers/${sid}/delete`, { __csrf: b.lastCsrf });
    await b.post('/builder/remote-servers', { __csrf: b.lastCsrf, id: String(sid), static_id: 'SEC141', name: 'hijacked', base_url: 'https://evil.example.com' });
    await b.post('/builder/workspace-credentials', { __csrf: b.lastCsrf, id: String(cid), name: 'SEC141_KEY', type: 'bearer', secret: 'replaced' });
    await b.post(`/builder/workspace-credentials/${cid}/delete`, { __csrf: b.lastCsrf });
    await b.post('/builder/workspace-files/delete', { __csrf: b.lastCsrf, name: 'a.css' });
    assert.deepEqual(await owner.one('select name, base_url from meta.remote_server where id = $1', [sid]), { name: 'x', base_url: base });
    const { decryptSecret } = await import('../src/secrets.ts');
    assert.equal(decryptSecret((await owner.one('select secret_enc from meta.workspace_credential where id = $1', [cid])).secret_enc), 'Sec141-secret-value');
    assert.ok(await owner.one(`select 1 from meta.workspace_file where workspace_id = $1 and name = 'a.css'`, [wsA]));
    assert.equal((await b.get('/builder/workspace-files/file/a.css')).statusCode, 404);
    // B's application: A's file is not served nor linked, A's server and credential are not found
    assert.equal((await b.get('/a/sec141b/workspace-files/a.css')).statusCode, 404);
    assert.equal((await b.get('/a/sec141a/workspace-files/a.css')).statusCode, 200);
    await owner.query(`update meta.app set static_includes = '{#WORKSPACE_FILES#a.css}' where id = $1`, [appB]);
    assert.doesNotMatch((await b.get('/a/sec141b/1')).body, /a\.css/);
    const ws = await import('../src/websources.ts');
    await assert.rejects(ws.loadCredential(appB, 'SEC141_KEY'), /does not exist/);
    await owner.query(`insert into meta.rest_source (app_id, name, url, server) values ($1, 'STEAL', '/x', 'SEC141')`, [appB]);
    await assert.rejects(ws.loadSource(appB, 'STEAL'), /does not exist in this application's workspace/);
    // and a REST source of A on its server signs with A's credential
    await owner.query(`insert into meta.rest_source (app_id, name, url, server, credential) values ($1, 'MINE', '/x', 'SEC141', 'SEC141_KEY')`, [appA]);
    await ws.fetchSource(await ws.loadSource(appA, 'MINE'), {});
    assert.equal(auth.at(-1), 'Bearer Sec141-secret-value');
    // the versions function gives an application its own workspace's files only
    const v = (await runtime.query('select meta.workspace_file_versions($1) as v', [appB])).rows[0].v;
    assert.deepEqual(v, {});
  });

  test('uploaded files: the static files\' types, sizes and headers; never HTML; a sandboxed preview', async () => {
    const a = await signIn(ADMIN_A, wsA);
    await a.get('/builder/workspace-files');
    const svg = Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>');
    await a.upload('/builder/workspace-files/upload', {}, { file: [
      { name: 'evil.html', type: 'text/html', data: Buffer.from('<script>alert(1)</script>') },
      { name: '../up.css', type: 'text/css', data: Buffer.from('x') },
      { name: 'big.css', type: 'text/css', data: Buffer.alloc(5 * 1024 * 1024 + 10, 0x20) },
      { name: 'pic.svg', type: 'image/svg+xml', data: svg },
    ] });
    // (a path is cut to its last part, as for static application files)
    const names = (await owner.query('select name from meta.workspace_file where workspace_id = $1 order by name', [wsA])).rows.map((r) => r.name);
    assert.deepEqual(names, ['a.css', 'pic.svg', 'up.css']);
    await assert.rejects(owner.query(`insert into meta.workspace_file (workspace_id, name, mime, content) values ($1, 'x.html', 'text/html', '')`, [wsA]), /check/);
    await assert.rejects(owner.query(`insert into meta.workspace_file (workspace_id, name, mime, content) values ($1, 'x.css', 'text/css', $2)`, [wsA, Buffer.alloc(5 * 1024 * 1024 + 1)]), /check/);
    await a.get('/builder/workspace-files?new=1');
    await a.post('/builder/workspace-files/save', { __csrf: a.lastCsrf, name: 'page.html', content: '<script>alert(1)</script>' });
    assert.ok(!(await owner.one(`select 1 from meta.workspace_file where workspace_id = $1 and name = 'page.html'`, [wsA])));
    // served to the application: an SVG can't run its script; nothing is sniffed
    const res = await a.get('/a/sec141a/workspace-files/pic.svg');
    assert.equal(res.headers['content-type'], 'image/svg+xml');
    assert.match(String(res.headers['content-security-policy']), /default-src 'none'.*sandbox/);
    assert.equal(res.headers['x-content-type-options'], 'nosniff');
    // the builder's preview is sandboxed too, for every type
    for (const n of ['pic.svg', 'a.css']) {
      const p = await a.get(`/builder/workspace-files/file/${n}`);
      assert.equal(p.statusCode, 200);
      assert.match(String(p.headers['content-security-policy']), /sandbox/, n);
    }
    // the names in a page's list: no paths or other types
    const { parseIncludes } = await import('../src/builder/static-files.ts');
    assert.deepEqual(parseIncludes('#WORKSPACE_FILES#../x.css #WORKSPACE_FILES#x.html #WORKSPACE_FILES#a/b.css "><script> #WORKSPACE_FILES#a.css'), ['#WORKSPACE_FILES#a.css']);
  });

  test('a server\'s URL passes every outgoing check: private addresses, the allow-list, the workspace\'s list; env names', async () => {
    const ws = await import('../src/websources.ts');
    // 127.0.0.1 is allowed above; refused once it is not a private host the installation allows
    process.env.PGKILN_REST_ALLOWED_HOSTS = '*';
    delete process.env.PGKILN_REST_PRIVATE_HOSTS;
    try {
      ws.clearResponseCache();
      await assert.rejects(ws.fetchSource(await ws.loadSource(appA, 'MINE'), {}), /private|loopback|not allowed|refused/i);
      await owner.query(`update meta.remote_server set base_url = 'http://169.254.169.254' where workspace_id = $1`, [wsA]);
      await assert.rejects(ws.fetchSource(await ws.loadSource(appA, 'MINE'), {}), /private|link-local|not allowed|refused/i);
    } finally {
      process.env.PGKILN_REST_ALLOWED_HOSTS = '127.0.0.1';
      process.env.PGKILN_REST_PRIVATE_HOSTS = '127.0.0.1';
      await owner.query(`update meta.remote_server set base_url = $2 where workspace_id = $1`, [wsA, base]);
    }
    // the workspace's network access list applies to the server's host
    await owner.query('update meta.workspace set network_restricted = true, network_hosts = $2 where id = $1', [wsA, ['api.example.com']]);
    try {
      ws.clearResponseCache();
      await assert.rejects(ws.fetchSource(await ws.loadSource(appA, 'MINE'), {}), /network access list/i);
    } finally {
      await owner.query(`update meta.workspace set network_restricted = false, network_hosts = '{}' where id = $1`, [wsA]);
    }
    // the path can't climb out of the server or name another host
    for (const url of ['//evil.example.com/x', '/a/../../x', 'https://evil.example.com/x', '@evil.example.com'])
      assert.ok(ws.sourceProblems({ server: 'SEC141', url, params: [], columns: [] }).length, url);
    await assert.rejects(owner.query(`insert into meta.rest_source (app_id, name, url, server) values ($1, 'BAD', 'evil.example.com/x', 'SEC141')`, [appA]), /check/);
    // only PGKILN_SERVER_ variables: no other part of the server's environment becomes a URL
    const a = await signIn(ADMIN_A, wsA);
    await a.get('/builder/remote-servers?new=1');
    await a.post('/builder/remote-servers', { __csrf: a.lastCsrf, static_id: 'ENVY', name: 'x', env_var: 'DATABASE_URL' });
    assert.ok(!(await owner.one(`select 1 from meta.remote_server where static_id = 'ENVY'`)));
    await assert.rejects(owner.query(`insert into meta.remote_server (workspace_id, static_id, name, env_var) values ($1, 'ENVY', 'x', 'PGKILN_SECRET_KEY')`, [wsA]), /check/);
    const { serverUrl } = await import('../src/remote-servers.ts');
    assert.equal(serverUrl({ static_id: 'X', base_url: null, env_var: 'DATABASE_URL' }).url, null);
  });

  test('secrets: write-only, never exported, and the runtime role reads none of the new tables', async () => {
    const a = await signIn(ADMIN_A, wsA);
    const row = await owner.one('select id, secret_enc from meta.workspace_credential where workspace_id = $1', [wsA]);
    for (const url of ['/builder/workspace-credentials', `/builder/workspace-credentials?edit=${row.id}`]) {
      const body = (await a.get(url)).body;
      assert.doesNotMatch(body, /Sec141-secret-value/);
      assert.ok(!body.includes(row.secret_enc.slice(3, 30)), url);
    }
    const { exportWorkspace } = await import('../src/workspace-export.ts');
    assert.doesNotMatch(JSON.stringify(await exportWorkspace(wsA)), /Sec141-secret-value|secret_enc|password_enc|refresh_token_enc|"v1:/);
    for (const t of ['workspace_credential', 'remote_server', 'workspace_file'])
      await assert.rejects(runtime.query(`select * from meta.${t} limit 1`), /permission denied/, t);
    const { encryptedColumns } = await import('../src/instance-checks.ts');
    const cols = (await encryptedColumns()).map((c) => `${c.table}.${c.column}`);
    for (const c of ['secret_enc', 'password_enc', 'refresh_token_enc']) assert.ok(cols.includes(`workspace_credential.${c}`), c);
  });
});

describe('sprint 142 AP-8', () => {
  // JSON sources and document views: the builder's pages only for the application's workspace and with CSRF; only
  // json columns of tables the workshop connection may use; the views are security_invoker and their triggers write
  // as the caller (its grants and the table's row level security apply); names are checked and paths are literals,
  // in the views' DDL and in a report's JSON path columns.
  const ADMIN_B = 'sec142adminb';
  let wsA: number;
  let wsB: number;
  let appA: number;
  let hrId: number;
  const signIn = async (username: string, ws?: number) => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.post('/builder/login', { __csrf: b.lastCsrf, username, password: username === 'admin' ? 'admin' : username })).statusCode, 303);
    await b.get('/builder/home');
    if (ws) assert.equal((await b.post('/builder/workspace', { __csrf: b.lastCsrf, workspace: String(ws) })).statusCode, 303);
    await b.get('/builder/home');
    return b;
  };

  before(async () => {
    hrId = (await owner.one(`select id from meta.app where alias = 'hr'`)).id;
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), false) on conflict do nothing`, [ADMIN_B]);
    await owner.query(`delete from meta.app where alias = 'sec142a'`);
    await owner.query(`delete from meta.workspace where name in ('Sec142 A', 'Sec142 B')`);
    wsA = (await owner.one(`insert into meta.workspace (name) values ('Sec142 A') returning id`)).id;
    wsB = (await owner.one(`insert into meta.workspace (name) values ('Sec142 B') returning id`)).id;
    appA = (await owner.one(`insert into meta.app (alias, name, authentication, home_page, json_sources, db_role) values ('sec142a', 'sec142a', 'none', 1, $1, 'hr_app') returning id`,
      [JSON.stringify([{ name: 'EMP_PROFILE', schema: 'hr', table: 'emp', key: ['empno'], column: 'profile', view: 'emp_profile', columns: [], arrays: [] }])])).id;
    await owner.query('insert into meta.workspace_app (app_id, workspace_id) values ($1, $2)', [appA, wsA]);
    await owner.query('insert into meta.workspace_member (workspace_id, username, is_admin) values ($1, $2, true)', [wsB, ADMIN_B]);
    await owner.query('drop table if exists hr.sec142_doc cascade');
    await owner.query(`do $$ begin if exists (select from pg_roles where rolname = 'sec142_writer') then drop owned by sec142_writer; drop role sec142_writer; end if; end $$`);
  });
  after(async () => {
    await owner.query('drop table if exists hr.sec142_doc cascade');
    await owner.query(`do $$ begin if exists (select from pg_roles where rolname = 'sec142_writer') then drop owned by sec142_writer; drop role sec142_writer; end if; end $$`);
    await owner.query(`delete from meta.app where alias = 'sec142a'`);
    await owner.query('delete from meta.workspace where id = any($1::int[])', [[wsA, wsB]]);
    await owner.query('delete from meta.developer where username = $1', [ADMIN_B]);
  });

  test('another workspace\'s developer reaches none of an application\'s JSON source pages; posts need the CSRF token', async () => {
    const b = await signIn(ADMIN_B, wsB);
    for (const url of [`/builder/apps/${appA}/json-sources`, `/builder/apps/${appA}/json-sources/source?name=EMP_PROFILE`])
      assert.equal((await b.get(url)).statusCode, 404, url);
    for (const url of ['views', 'page', 'source', 'source/delete'])
      assert.equal((await b.submit(`/builder/apps/${appA}/json-sources/${url}`, { name: 'EMP_PROFILE', mode: 'apply', page_no: '9990' })).statusCode, 404, url);
    assert.equal(((await owner.one('select json_sources from meta.app where id = $1', [appA])).json_sources as unknown[]).length, 1);
    assert.equal((await owner.one('select count(*)::int as n from meta.page where app_id = $1', [appA])).n, 0);
    const admin = await signIn('admin');
    await admin.get(`/builder/apps/${appA}/json-sources`);
    assert.equal((await admin.post(`/builder/apps/${appA}/json-sources/source/delete`, { name: 'EMP_PROFILE' })).statusCode, 403, 'CSRF');
    assert.equal((await admin.post(`/builder/apps/${appA}/json-sources/views`, { name: 'EMP_PROFILE', mode: 'apply' })).statusCode, 403, 'CSRF');
    assert.equal(((await owner.one('select json_sources from meta.app where id = $1', [appA])).json_sources as unknown[]).length, 1);
  });

  test('only json columns of tables the workshop may use; Document view refuses pgkiln\'s and the system\'s tables', async () => {
    const admin = await signIn('admin');
    await admin.get(`/builder/apps/${hrId}/json-sources/source`);
    for (const source of ['meta.app.json_sources', 'pg_catalog.pg_class.relacl', 'hr.emp.ename'])
      assert.equal((await admin.submit(`/builder/apps/${hrId}/json-sources/source`, { mode: 'propose', name: 'SEC142', source, view: 'sec142_v' })).statusCode, 422, source);
    for (const o of ['meta.app', 'pg_catalog.pg_class', 'information_schema.tables'])
      assert.equal((await admin.get(`/builder/sql/objects/document?o=${o}`)).statusCode, 404, o);
  });

  test('the views run as the caller: a role with UPDATE on the view but not on the table writes nothing; RLS hides rows from the view and its writes', async () => {
    const { jsonSourceDdl } = await import('../src/json-sources.ts');
    await owner.query('create table hr.sec142_doc (id int primary key, owner text not null, doc jsonb)');
    await owner.query(`insert into hr.sec142_doc values (1, 'sec142_writer', '{"t": "mine"}'), (2, 'other', '{"t": "theirs"}')`);
    await owner.query('alter table hr.sec142_doc enable row level security');
    await owner.query(`create policy own on hr.sec142_doc using (owner = current_user)`);
    for (const d of jsonSourceDdl({ name: 'SEC142', schema: 'hr', table: 'sec142_doc', key: ['id'], column: 'doc', view: 'sec142_v', columns: [{ name: 't', path: ['t'], type: 'text' }], arrays: [] }, { app: 'hr', grants: [], replace: false }))
      await owner.query(d);
    await owner.query('create role sec142_writer nologin');
    await owner.query('grant usage on schema hr to sec142_writer');
    await owner.query('grant select, update on hr.sec142_v to sec142_writer');
    await owner.query('grant select on hr.sec142_doc to sec142_writer');
    const asWriter = <T>(sql: string) => owner.tx(async (c) => {
      await c.query('set local role sec142_writer');
      return (await c.query(sql)) as unknown as T;
    });
    // reading: only the row the policy shows
    assert.deepEqual(((await asWriter<{ rows: { id: number }[] }>('select id from hr.sec142_v')).rows).map((r) => r.id), [1]);
    // writing without UPDATE on the table: refused by the table's grants, not the view's
    await assert.rejects(asWriter(`update hr.sec142_v set t = 'x' where id = 1`), /permission denied for table sec142_doc/);
    await owner.query('grant update on hr.sec142_doc to sec142_writer');
    await asWriter(`update hr.sec142_v set t = 'changed' where id = 1`);
    // a row the policy hides is not found (the trigger's UPDATE runs under the policy too)
    const hidden = await asWriter<{ rowCount: number }>(`update hr.sec142_v set t = 'stolen' where id = 2`);
    assert.equal(hidden.rowCount, 0);
    assert.deepEqual((await owner.query('select id, doc from hr.sec142_doc order by id')).rows, [{ id: 1, doc: { t: 'changed' } }, { id: 2, doc: { t: 'theirs' } }]);
    // calling the trigger function with a description of its own changes nothing beyond the caller's rights
    assert.equal((await owner.one(`select prosecdef from pg_proc where oid = 'meta.json_array_write'::regproc`)).prosecdef, false);
    assert.equal((await owner.one(`select prosecdef from pg_proc where oid = 'meta.json_document_write'::regproc`)).prosecdef, false);
  });

  test('names are checked and paths are literals: in the views\' DDL and in JSON path columns', async () => {
    const { jsonSourceDdl, jsonSourceProblems, withJsonColumns } = await import('../src/json-sources.ts');
    const evil = `x'); drop table hr.emp; --`;
    assert.ok(jsonSourceProblems({ name: 'SEC142B', schema: 'hr', table: 'sec142_doc', key: ['id'], column: 'doc', view: 'v"; drop table hr.emp; --', columns: [{ name: 'a"b', path: ['a'], type: 'text' }], arrays: [] }).length >= 2);
    for (const d of jsonSourceDdl({ name: 'SEC142B', schema: 'hr', table: 'sec142_doc', key: ['id'], column: 'doc', view: 'sec142_v2', columns: [{ name: 'e', path: [evil, '"q"'], type: 'integer' }], arrays: [] }, { app: 'hr', grants: [], replace: false }))
      await owner.query(d);
    await owner.query(`update hr.sec142_v2 set e = 5 where id = 1`);
    assert.deepEqual((await owner.one('select doc from hr.sec142_doc where id = 1')).doc, { t: 'changed', [evil]: { '"q"': 5 } });
    assert.equal((await owner.one('select e from hr.sec142_v2 where id = 1')).e, 5);
    const sql = withJsonColumns({ config: { json_columns: [{ name: 'e', column: 'profile', path: evil }, { name: 'c', column: 'profile" , (select 1) as "x', path: 'a' }] } }, 'select empno, profile from hr.emp');
    await assert.rejects(owner.query(sql), /column .* does not exist/);
    const ok = withJsonColumns({ config: { json_columns: [{ name: 'e', column: 'profile', path: evil }] } }, 'select empno, profile from hr.emp');
    assert.ok((await owner.query(ok)).rows.every((r) => r.e === null));
    assert.ok((await owner.one(`select to_regclass('hr.emp') is not null as ok`)).ok, 'hr.emp is still there');
  });
});

describe('sprint 143 AP-9', () => {
  // The interactive report's new filter operators and column order: every value of "is one of", "is between" and
  // "is in" reaches the SQL as a literal or a fixed period expression (never as text of the query); hidden columns
  // stay out of filters, the column order and the downloads; values and column names are escaped where they show.
  const A = 'sec143';
  const SCHEMA = 'sec143';
  const ROLE = 'pgkiln_sec143';
  const XSS = `<img src=x onerror=alert(1)>"'&`;
  let id: number;
  let rid: number;
  const get = (q: string) => new FileBrowser(app).get(`/a/${A}/1?${q}`);
  const f = (k: string) => `r${rid}_${k}`;
  const filter = (col: string, op: string, value: string) => `${f('f')}=${encodeURIComponent(`${col}|${op}|${value}`)}`;
  const rows = (body: string) => [...body.matchAll(/<td class="num" data-label="Id">(\d+)<\/td>/g)].length;
  before(async () => {
    await owner.query('delete from meta.app where alias = $1', [A]);
    await owner.query(`drop schema if exists ${SCHEMA} cascade`);
    await owner.query(`drop owned by ${ROLE}`).catch(() => undefined);
    await owner.query(`drop role if exists ${ROLE}`);
    await owner.query(`create role ${ROLE} nologin`);
    await owner.query(`grant ${ROLE} to pgkiln_runtime`);
    await owner.query(`create schema ${SCHEMA};
      create table ${SCHEMA}.t (id int primary key, name text, secret text, d date);
      insert into ${SCHEMA}.t values (1, 'a', 'top', '2020-01-01'), (2, $$${XSS}$$, 'top', '2020-01-02'), (3, 'c', 'low', '2020-01-03');
      grant usage on schema ${SCHEMA} to ${ROLE}; grant select on ${SCHEMA}.t to ${ROLE};`);
    id = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ($1, 'Sec143', 'none', $2) returning id`, [A, ROLE])).id;
    const pid = (await owner.one(`insert into meta.page (app_id, page_no, name, requires_auth) values ($1, 1, 'Home', false) returning id`, [id])).id;
    rid = (await owner.one(`insert into meta.region (page_id, seq, title, type, source, config) values ($1, 10, 'T', 'report', $2, '{"hidden": ["secret"]}') returning id`,
      [pid, `select id, name, secret, d from ${SCHEMA}.t`])).id;
  });
  after(async () => {
    await owner.query('delete from meta.app where alias = $1', [A]);
    await owner.query(`drop schema if exists ${SCHEMA} cascade`);
    await owner.query(`drop owned by ${ROLE}`);
    await owner.query(`drop role if exists ${ROLE}`);
  });

  test('list values, bounds and periods are literals: quotes and SQL in them find nothing and break nothing', async () => {
    const dropper = `a'); delete from ${SCHEMA}.t; --`;
    for (const q of [
      filter('name', 'in', JSON.stringify(["a') or true --", "x' or '1'='1"])),
      filter('name', 'in', "a') or (true"),
      filter('name', 'not_in', JSON.stringify([dropper])),
      filter('d', 'between', JSON.stringify(["2020-01-01'::date or true or '", ''])),
      filter('id', 'between', '["1) or (1=1", "2"]'),
    ]) {
      const res = await get(q);
      assert.equal(res.statusCode, 200, q);
      assert.ok(rows(res.body) <= 3, q);
      assert.doesNotMatch(res.body, /syntax error/i, q);
    }
    assert.equal(rows((await get(filter('name', 'in', JSON.stringify(["a') or true --"])))).body), 0);
    assert.equal(rows((await get(filter('name', 'not_in', JSON.stringify([dropper])))).body), 3);
    assert.equal((await owner.one(`select count(*)::int as n from ${SCHEMA}.t`)).n, 3, 'the rows are still there');
    // a period is one of the fixed names; anything else is no filter
    for (const v of ['today) or (true', "last_7_days'", 'constructor', 'toString'])
      assert.equal(rows((await get(filter('d', 'period', v))).body), 3, v);
  });

  test('a hidden column is never filtered on, ordered, downloaded or offered', async () => {
    // "secret = top" would leave two rows: the filter on a hidden column is left out
    assert.equal(rows((await get(filter('secret', 'in', '["top"]'))).body), 3);
    assert.equal(rows((await get(filter('secret', 'between', '["top","top"]'))).body), 3);
    const ordered = await get(`${f('o')}=secret&${f('o')}=name`);
    assert.doesNotMatch(ordered.body, /data-col="secret"|data-col-name="secret"|>top</);
    const csv = await get(`${f('o')}=secret&${f('csv')}=1`);
    assert.doesNotMatch(csv.body, /secret|top/i);
    // a move names a shown column, or changes nothing
    const res = await get(`${f('o')}=name&${f('o')}=id&${f('od')}=${encodeURIComponent('["id","name"]')}&${f('mv')}=usecret`);
    assert.equal(res.statusCode, 302);
    assert.deepEqual(new URL(String(res.headers.location), 'http://x').searchParams.getAll(f('o')), ['name', 'id']);
  });

  test('values in chips and names in the column order are escaped', async () => {
    const body = (await get(filter('name', 'in', JSON.stringify([XSS])))).body;
    assert.equal(rows(body), 1);
    assert.doesNotMatch(body, /<img src=x onerror/);
    assert.match(body, /<span class="chip">Name is one of &lt;img src=x onerror=alert\(1\)&gt;/);
    const between = (await get(filter('d', 'between', JSON.stringify([XSS, ''])))).body;
    assert.doesNotMatch(between, /<img src=x onerror/);
    const order = (await get(`${f('o')}=${encodeURIComponent(XSS)}&${f('o')}=name`)).body;
    assert.doesNotMatch(order, /<img src=x onerror/);
    // an unknown name changes nothing: the columns stay in the report's order after the named one
    assert.deepEqual([...order.matchAll(/<th scope="col"[^>]*data-col="([^"]+)"/g)].map((m) => m[1]), ['name', 'id', 'd']);
  });
});

describe('sprint 144 AP-10', () => {
  // `pgkiln advise` and the MCP tools advise_app, working_copy and lock_app: an export is only planned, never run
  // (process code, supporting objects and plug-in SQL that would change data change nothing), and its import is
  // always rolled back, also when it fails; working copy names and lock notes are checked or limited.
  const A = 'sec144';
  let doc: any;
  const callTool = async (name: string, args: Record<string, unknown>) => {
    const { handle } = await import('../src/cli/mcp.ts');
    const r: any = await handle({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name, arguments: args } });
    return { text: r.result.content[0].text as string, error: !!r.result.isError };
  };
  before(async () => {
    await owner.query(`delete from meta.app where alias like 'sec144%'`);
    await owner.query(`create table if not exists public.sec144_t (n int); delete from public.sec144_t; insert into public.sec144_t values (1)`);
    const id = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ($1, 'Sec144', 'none', 'hr_app') returning id`, [A])).id;
    const pid = (await owner.one(`insert into meta.page (app_id, page_no, name, requires_auth) values ($1, 1, 'Home', false) returning id`, [id])).id;
    await owner.query(`insert into meta.process (page_id, seq, name, type, code) values ($1, 10, 'Wipe', 'sql', 'delete from public.sec144_t; do $$ begin delete from public.sec144_t; end $$')`, [pid]);
    await owner.query(`insert into meta.supporting_script (app_id, seq, name, script) values ($1, 10, 'drop', 'drop table public.sec144_t')`, [id]);
    doc = (await owner.one('select meta.export_app($1) as doc', [A])).doc;
    await owner.query(`delete from meta.app where alias = $1`, [A]);
  });
  after(async () => {
    await owner.query(`delete from meta.app where alias like 'sec144%'`);
    await owner.query(`drop table if exists public.sec144_t`);
  });

  test('an export is planned in a transaction that is rolled back: its code never runs, nothing stays', async () => {
    const { mkdtempSync, writeFileSync, rmSync } = await import('node:fs');
    const { join } = await import('node:path');
    const { tmpdir } = await import('node:os');
    const dir = mkdtempSync(join(tmpdir(), 'sec144-'));
    try {
      const file = join(dir, 'app.json');
      writeFileSync(file, JSON.stringify(doc));
      const apps = (await owner.one(`select count(*)::int as n from meta.app`)).n;
      const r = await callTool('advise_app', { path: file });
      assert.equal(r.error, false, r.text);
      assert.match(r.text, /Page 1 needs no sign-in, and its process Wipe writes data/);
      assert.equal((await owner.one(`select count(*)::int as n from public.sec144_t`)).n, 1, 'the process was planned, not run');
      assert.ok(await owner.one(`select to_regclass('public.sec144_t') is not null as ok`), 'supporting objects never run');
      assert.equal((await owner.one(`select count(*)::int as n from meta.app`)).n, apps);
      assert.equal((await owner.one(`select count(*)::int as n from meta.app where alias like 'advise-%'`)).n, 0);
      // a broken export: an error, and still nothing stays
      const bad = join(dir, 'bad.json');
      writeFileSync(bad, JSON.stringify({ ...doc, pages: [{ page_no: 'x' }] }));
      assert.equal((await callTool('advise_app', { path: bad })).error, true);
      assert.equal((await owner.one(`select count(*)::int as n from meta.app`)).n, apps);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  test('working copy names are checked, lock notes are cut; unknown applications and actions are errors', async () => {
    await owner.query(`insert into meta.app (alias, name, authentication, db_role) values ('sec144b', 'Sec144b', 'none', 'hr_app')`);
    for (const name of ["x'; drop table meta.app; --", '../../etc', '', 'a'.repeat(41)])
      assert.equal((await callTool('working_copy', { action: 'create', alias: 'sec144b', name })).error, true, name);
    assert.equal((await owner.one(`select count(*)::int as n from meta.working_copy w join meta.app a on a.id = w.main_app_id where a.alias = 'sec144b'`)).n, 0);
    assert.equal((await callTool('working_copy', { action: 'create', alias: "sec144b' or '1'='1", name: 'x' })).error, true);
    assert.equal((await callTool('working_copy', { action: 'drop', alias: 'sec144b' })).error, true);
    assert.equal((await callTool('lock_app', { alias: 'sec144b', page: 'x' })).error, true);
    assert.equal((await callTool('lock_app', { alias: 'sec144b', note: 'n'.repeat(2000), developer: 'admin' })).error, false);
    assert.equal((await owner.one(`select length(note) as n from meta.builder_lock l join meta.app a on a.id = l.app_id where a.alias = 'sec144b'`)).n, 500);
    assert.equal((await callTool('lock_app', { alias: 'sec144b', unlock: true })).error, true, "MCP can't unlock admin's lock without force");
  });
});

describe('sprint 147 offline advise: an untrusted export is read as data', () => {
  test('odd shapes and __proto__ keys neither throw nor pollute; no app is a clean error', async () => {
    const { adviseDoc, rowsOfDoc } = await import('../src/builder/advisor.ts');
    const hostile = JSON.parse(`{
      "format": "pgkiln/2",
      "app": {"alias": "x", "login_page": "1 or 1=1", "json_sources": [null, 5, {"__proto__": {"polluted": true}, "name": "J"}], "__proto__": {"polluted": true}},
      "pages": [null, "page", {"page_no": 1, "name": "P", "__proto__": {"polluted": true}, "regions": "not a list", "items": [null, 7, {"name": "P1_A", "type": "text", "__proto__": {"polluted": true}}],
                 "processes": [{"name": "W", "type": "sql", "code": "delete from meta.app"}]}],
      "lovs": {"not": "a list"}, "authz_schemes": [1, "x", null], "build_options": null
    }`);
    const r = await adviseDoc(hostile);
    assert.ok(Array.isArray(r.findings));
    assert.equal(({} as any).polluted, undefined, 'Object.prototype untouched');
    assert.ok(r.findings.some((f) => /Page 1 or 1=1 doesn't exist/.test(f.message)), 'the login page is compared as a value, never run');
    assert.ok(r.findings.some((f) => /needs no sign-in, and its process W writes data/.test(f.message)));
    assert.throws(() => rowsOfDoc({ pages: [] }), /not an application export/);
    assert.throws(() => rowsOfDoc(null), /not an application export/);
    assert.equal(rowsOfDoc({ app: {}, pages: 'x' }).pages.length, 0);
  });
});

describe('sprint 148 streamed AI answers: the same checks as the form, text that stays text', () => {
  let mock: Awaited<ReturnType<typeof import('./ai-script-mock.ts').startScriptMock>>;
  let hr: number;
  let region: number;
  let otherRegion: number;
  const SERVICE = 'HR_ASSISTANT';
  before(async () => {
    process.env.PGKILN_SECRET_KEY ??= 'test-only-secret-key-0123456789abcdef';
    const { startScriptMock } = await import('./ai-script-mock.ts');
    const { encryptSecret } = await import('../src/secrets.ts');
    mock = await startScriptMock();
    hr = (await owner.one(`select id from meta.app where alias = 'hr'`)).id;
    await owner.query(`delete from meta.ai_service where name = $1`, [SERVICE]);
    const s = (await owner.one(`insert into meta.ai_service (name, provider, model, base_url, api_key_enc) values ($1, 'anthropic', 'claude-opus-5-5', $2, $3) returning id`,
      [SERVICE, `${mock.base}/claude`, encryptSecret('sk-sec148')])).id;
    await owner.query(`insert into meta.app_ai_service (app_id, service_id) values ($1, $2)`, [hr, s]);
    region = (await owner.one(`select r.id from meta.region r join meta.page p on p.id = r.page_id where p.app_id = $1 and p.page_no = 38 and r.type = 'ai_assistant'`, [hr])).id;
    otherRegion = (await owner.one(`select r.id from meta.region r join meta.page p on p.id = r.page_id where p.app_id = $1 and p.page_no = 38 and r.type <> 'ai_assistant' limit 1`, [hr])).id;
  });
  after(async () => {
    await owner.query(`delete from meta.ai_conversation where region_id = $1`, [region]);
    await owner.query(`delete from meta.ai_service where name = $1`, [SERVICE]);
    await mock.close();
  });
  const post = (b: FileBrowser, form: Record<string, string>, id = region) => app.inject({
    method: 'POST', url: `/a/hr/38/assistant/${id}/send`, payload: new URLSearchParams(form).toString(),
    headers: { cookie: [...b.cookies].map(([k, v]) => `${k}=${v}`).join('; '), 'content-type': 'application/x-www-form-urlencoded', accept: 'text/event-stream' },
  });

  test('no CSRF token, no sign-in, a region that is not an assistant: refused before any stream or AI call', async () => {
    const b = new FileBrowser(app);
    await b.login('scott');
    await b.get('/a/hr/38');
    const calls = mock.seen.length;
    const noCsrf = await post(b, { message: 'hi', params: '' });
    assert.equal(noCsrf.statusCode, 403);
    assert.doesNotMatch(String(noCsrf.headers['content-type']), /event-stream/);
    const wrong = await post(b, { __csrf: b.lastCsrf, message: 'hi', params: '' }, otherRegion);
    assert.equal(wrong.statusCode, 403);
    const anon = new FileBrowser(app);
    await anon.get('/a/hr/login');
    const signedOut = await post(anon, { __csrf: anon.lastCsrf, message: 'hi', params: '' });
    assert.notEqual(signedOut.statusCode, 200);
    assert.doesNotMatch(String(signedOut.headers['content-type'] ?? ''), /event-stream/);
    assert.equal(mock.seen.length, calls, 'the model was never asked');
  });

  test('HTML in an answer: JSON strings in an event stream (nosniff), escaped on the page', async () => {
    mock.script = [{ text: '<img src=x onerror=alert(1)> and </script><script>alert(2)</script>' }];
    const b = new FileBrowser(app);
    await b.login('scott');
    await b.get('/a/hr/38');
    const res = await post(b, { __csrf: b.lastCsrf, message: 'hi', params: '' });
    assert.match(String(res.headers['content-type']), /^text\/event-stream/);
    assert.equal(res.headers['x-content-type-options'], 'nosniff');
    for (const line of res.body.split('\n').filter((l) => l.startsWith('data: '))) assert.doesNotThrow(() => JSON.parse(line.slice(6)), 'every data line is JSON');
    const page = (await b.get('/a/hr/38')).body;
    assert.match(page, /&lt;img src=x onerror=alert\(1\)&gt;/);
    assert.doesNotMatch(page, /<img src=x onerror/);
    assert.doesNotMatch(page, /<script>alert\(2\)/);
  });
});

