describe('sprint 175 ETags of REST module answers (DA-11)', () => {
  let king = '';
  let allen = '';
  const get = (path: string, headers: Record<string, string> = {}) => app.inject({ method: 'GET', url: `/a/hr/rest/hr/${path}`, headers });
  before(async () => {
    const { issueApiToken } = await import('../src/api.ts');
    const appId = (await owner.one(`select id from meta.app where alias = 'hr'`))!.id;
    king = (await issueApiToken(appId, 'king', 1)).token;
    allen = (await issueApiToken(appId, 'allen', 1)).token;
  });

  test('a tag is no credential: without a token 401, with a bad token 401, whatever If-None-Match says', async () => {
    const tag = String((await get('emp/7839', { authorization: `Bearer ${king}` })).headers.etag);
    assert.match(tag, /^"[A-Za-z0-9_-]{32}"$/);
    for (const value of [tag, '*', `W/${tag}`]) {
      const anonymous = await get('emp/7839', { 'if-none-match': value });
      assert.equal(anonymous.statusCode, 401, value);
      assert.equal(anonymous.headers.etag, undefined);
      assert.equal((await get('emp/7839', { authorization: 'Bearer nonsense', 'if-none-match': value })).statusCode, 401, value);
    }
  });

  test('304 only for what the caller may read: the handler runs first (roles, row level security, 404)', async () => {
    const mine = await get('emp/7839', { authorization: `Bearer ${king}` });
    const tag = String(mine.headers.etag);
    // another account, with king's tag: the same answer as without it, unless its own row is that very content
    const plain = await get('emp/7839', { authorization: `Bearer ${allen}` });
    const tagged = await get('emp/7839', { authorization: `Bearer ${allen}`, 'if-none-match': tag });
    if (plain.statusCode === 200 && plain.body === mine.body) assert.equal(tagged.statusCode, 304);
    else assert.equal(tagged.statusCode, plain.statusCode);
    // a handler for managers and administrators stays refused for an employee; a missing row stays 404
    const refused = await get('payroll/10', { authorization: `Bearer ${allen}` });
    assert.equal((await get('payroll/10', { authorization: `Bearer ${allen}`, 'if-none-match': '*' })).statusCode, refused.statusCode);
    assert.ok(refused.statusCode === 403 || refused.statusCode === 404, String(refused.statusCode));
    assert.equal((await get('emp/1', { authorization: `Bearer ${king}`, 'if-none-match': '*' })).statusCode, 404);
  });

  test('304 carries no content; the header is not echoed; a very long header is ignored', async () => {
    const tag = String((await get('emp/7839', { authorization: `Bearer ${king}` })).headers.etag);
    const same = await get('emp/7839', { authorization: `Bearer ${king}`, 'if-none-match': `"<script>alert(175)</script>", ${tag}` });
    assert.equal(same.statusCode, 304);
    assert.equal(same.rawPayload.length, 0);
    assert.equal(same.headers.etag, tag);
    const long = await get('emp/7839', { authorization: `Bearer ${king}`, 'if-none-match': `${'"x", '.repeat(900)}${tag}` });
    assert.equal(long.statusCode, 200);
    assert.equal(long.headers.etag, tag);
  });
});

describe('sprint 175 header parameters of REST handlers (DA-11)', () => {
  let appId = 0;
  let id = 0;
  let king = '';
  const evil = '<img src=x onerror=alert(175)>';
  before(async () => {
    const { issueApiToken } = await import('../src/api.ts');
    appId = (await owner.one(`select id from meta.app where alias = 'hr'`))!.id;
    king = (await issueApiToken(appId, 'king', 1)).token;
    await owner.query(`delete from meta.rest_module where app_id = $1 and name = 'sec175'`, [appId]);
    id = (await owner.one(`insert into meta.rest_module (app_id, name, title, handlers) values ($1, 'sec175', 'sec175', $2) returning id`, [appId, JSON.stringify([
      { method: 'GET', path: 'echo', type: 'item', source: 'select :X_TRACE as trace, :APP_USER as username', params: [{ name: 'x_trace', in: 'header' }] },
      // stored past the builder's check: the runtime still never binds a credential header
      { method: 'GET', path: 'leak', type: 'item', source: 'select :AUTHORIZATION as a, :COOKIE as c', params: [{ name: 'authorization', in: 'header' }, { name: 'cookie', in: 'header' }] },
    ])]))!.id;
  });
  after(async () => {
    await owner.query(`delete from meta.rest_module where app_id = $1 and name = 'sec175'`, [appId]);
  });
  const get = (path: string, headers: Record<string, string> = {}) => app.inject({ method: 'GET', url: `/a/hr/rest/sec175/${path}`, headers: { authorization: `Bearer ${king}`, ...headers } });

  test('a credential header is never bound, and :APP_USER stays the server\'s', async () => {
    const leak = await get('leak', { cookie: 'pgkiln_session=secret' });
    assert.ok(!leak.body.includes(king), 'the token is not in the answer');
    assert.ok(!leak.body.includes('secret'), 'the cookie is not in the answer');
    const { handlerProblems } = await import('../src/runtime/rest.ts');
    assert.match(handlerProblems([{ method: 'GET', path: 'x', type: 'item', source: 'select 1', params: [{ name: 'authorization', in: 'header' }] }]).join(' '), /credentials/);
    assert.match(handlerProblems([{ method: 'GET', path: 'x', type: 'item', source: 'select 1', params: [{ name: 'app_user', in: 'header' }] }]).join(' '), /set by the server/);
    // a header named like a built-in does not set it
    assert.equal((await get('echo', { 'app-user': 'admin', 'x-trace': 't' })).json().username, 'king');
  });

  test('the value is bound, not SQL; without a token the header changes nothing (401)', async () => {
    const res = await get('echo', { 'x-trace': `x' || (select password_hash from meta.account limit 1) || '` });
    assert.equal(res.json().trace, `x' || (select password_hash from meta.account limit 1) || '`);
    assert.equal((await app.inject({ method: 'GET', url: '/a/hr/rest/sec175/echo', headers: { 'x-trace': 't' } })).statusCode, 401);
  });

  test('Try it: CSRF, the header value is escaped in the page and stays one header line', async () => {
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    await dev.get(`/builder/sql/rest/modules/${id}/handler?t=echo&m=GET`);
    assert.equal((await dev.post(`/builder/sql/rest/modules/${id}/try`, { __csrf: 'forged', t: 'echo', m: 'GET', as: 'king', h_x_trace: 'x' })).statusCode, 403);
    const tried = await dev.post(`/builder/sql/rest/modules/${id}/try`, { __csrf: dev.lastCsrf, t: 'echo', m: 'GET', as: 'king', h_x_trace: `${evil}\r\nx-injected: 1` });
    assert.equal(tried.statusCode, 200);
    assert.doesNotMatch(tried.body, /<img src=x/);
    assert.match(tried.body, /&lt;img src=x onerror=alert\(175\)&gt; x-injected: 1/);
    // a field that is not one of the handler's header parameters is not sent as a header
    const other = await dev.post(`/builder/sql/rest/modules/${id}/try`, { __csrf: dev.lastCsrf, t: 'echo', m: 'GET', as: '', h_authorization: `Bearer ${king}` });
    assert.match(other.body, /401/);
  });
});

describe('sprint 176 share links for query results (DA-3)', () => {
  const DEV = 'sec176_dev';
  const PW = 'Sec176-dev-password!';
  const evil = '<img src=x onerror=alert(176)>';
  let other = 0;
  const theirs = 'T'.repeat(32);
  before(async () => {
    await owner.query(`delete from meta.developer where username = $1`, [DEV]);
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false)`, [DEV, PW]);
    other = (await owner.one(`insert into meta.workspace (name) values ('sec176 other') returning id`))!.id;
    await owner.query(`insert into meta.sql_share (workspace_id, token, title, sql, created_by) values ($1, $2, 'sec176 theirs', 'select 176 as secret_of_theirs', 'x')`, [other, theirs]);
    await owner.query('create table if not exists public.sec176_rows (n int)');
  });
  after(async () => {
    await owner.query(`delete from meta.sql_share where title like 'sec176%' or sql like '%sec176%'`);
    await owner.query(`delete from meta.workspace where name = 'sec176 other'`);
    await owner.query(`delete from meta.developer where username = $1`, [DEV]);
    await owner.query('drop table if exists public.sec176_rows');
  });
  const signIn = async (username = 'admin', password = 'admin') => {
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username, password });
    await dev.get('/builder/sql/worksheet');
    return dev;
  };
  const tokenOf = async (title: string) => (await owner.one(`select token from meta.sql_share where title = $1`, [title]))!.token as string;

  test('CSRF and a developer session are needed; another workspace\'s link is not found, by any route', async () => {
    const dev = await signIn();
    assert.equal((await dev.post('/builder/sql/shared', { __csrf: 'forged', query: 'select 1 as sec176' })).statusCode, 403);
    assert.equal(await owner.one(`select 1 as x from meta.sql_share where sql = 'select 1 as sec176'`), undefined);
    assert.equal((await dev.get(`/builder/sql/shared/${theirs}`)).statusCode, 404);
    for (const action of ['stop', 'save', 'worksheet'])
      assert.equal((await dev.post(`/builder/sql/shared/${theirs}`, { __csrf: dev.lastCsrf, action, title: 'sec176 taken' })).statusCode, 404, action);
    assert.equal((await owner.one(`select title from meta.sql_share where token = $1`, [theirs]))!.title, 'sec176 theirs');
    assert.doesNotMatch((await dev.get('/builder/sql/shared')).body, /sec176 theirs/);
    // an application user and a visitor are sent to the builder's sign-in: the token alone opens nothing
    await dev.post('/builder/sql/shared', { __csrf: dev.lastCsrf, query: 'select 176 as sec176_secret', title: 'sec176 mine' });
    const mine = await tokenOf('sec176 mine');
    const king = await as('king');
    assert.equal((await king.get(`/builder/sql/shared/${mine}`)).headers.location, '/builder/login');
    const visitor = await app.inject({ method: 'GET', url: `/builder/sql/shared/${mine}` });
    assert.equal(visitor.statusCode, 302);
    assert.doesNotMatch(visitor.body, /sec176_secret/);
  });

  test('only the maker or an administrator changes or stops a link; a forged request does neither', async () => {
    const admin = await signIn();
    await admin.post('/builder/sql/shared', { __csrf: admin.lastCsrf, query: 'select 1 as sec176_keep', title: 'sec176 keep' });
    const token = await tokenOf('sec176 keep');
    const dev = await signIn(DEV, PW);
    assert.equal((await dev.get(`/builder/sql/shared/${token}`)).statusCode, 200);
    assert.equal((await dev.post(`/builder/sql/shared/${token}`, { __csrf: dev.lastCsrf, action: 'stop' })).statusCode, 403);
    assert.equal((await dev.post(`/builder/sql/shared/${token}`, { __csrf: dev.lastCsrf, action: 'save', title: 'sec176 taken', days: '90' })).statusCode, 403);
    assert.equal((await admin.post(`/builder/sql/shared/${token}`, { __csrf: 'forged', action: 'stop' })).statusCode, 403);
    const row = (await owner.one(`select title, round(extract(epoch from expires_at - created_at) / 86400)::int as days from meta.sql_share where token = $1`, [token]))!;
    assert.deepEqual(row, { title: 'sec176 keep', days: 7 });
    // the number of days is one of the list: anything else is seven
    await admin.post('/builder/sql/shared', { __csrf: admin.lastCsrf, query: 'select 2 as sec176_days', title: 'sec176 days', days: '99999' });
    assert.equal((await owner.one(`select round(extract(epoch from expires_at - created_at) / 86400)::int as d from meta.sql_share where title = 'sec176 days'`))!.d, 7);
  });

  test('the shared statement is one SELECT and runs read-only, as the reader', async () => {
    const dev = await signIn();
    for (const query of ['insert into public.sec176_rows values (1) returning n', 'select 1 as sec176; drop table public.sec176_rows', 'drop table public.sec176_rows'])
      assert.equal((await dev.post('/builder/sql/shared', { __csrf: dev.lastCsrf, query })).headers.location, '/builder/sql/worksheet', query);
    assert.equal((await owner.one(`select count(*)::int as n from meta.sql_share where sql like '%sec176_rows%'`))!.n, 0);
    // a stored statement that writes (put there past the route) fails in the read-only transaction and changes nothing
    const sneaky = 'S'.repeat(32);
    await owner.query(`insert into meta.sql_share (token, title, sql, created_by) values ($1, 'sec176 sneaky', 'with x as (insert into public.sec176_rows values (176) returning n) select n from x', 'admin')`, [sneaky]);
    const page = await dev.get(`/builder/sql/shared/${sneaky}`);
    assert.equal(page.statusCode, 200);
    assert.match(page.body, /alert-error/);
    assert.equal((await owner.one('select count(*)::int as n from public.sec176_rows'))!.n, 0);
  });

  test('titles, column names, values and the query are escaped on the link\'s page and in the list', async () => {
    const dev = await signIn();
    await dev.post('/builder/sql/shared', { __csrf: dev.lastCsrf, query: `select '${evil}' as "${evil}", 'sec176' as tag`, title: `sec176 ${evil}` });
    const token = await tokenOf(`sec176 ${evil}`);
    for (const url of [`/builder/sql/shared/${token}`, '/builder/sql/shared']) {
      const body = (await dev.get(url)).body;
      assert.doesNotMatch(body, /<img src=x/, url);
      assert.match(body, /&lt;img src=x onerror=alert\(176\)&gt;/, url);
    }
  });
});

describe('sprint 176 response headers of PL/pgSQL REST handlers (DA-11)', () => {
  let appId = 0;
  let king = '';
  before(async () => {
    const { issueApiToken } = await import('../src/api.ts');
    appId = (await owner.one(`select id from meta.app where alias = 'hr'`))!.id;
    king = (await issueApiToken(appId, 'king', 1)).token;
    await owner.query(`delete from meta.rest_module where app_id = $1 and name = 'sec176'`, [appId]);
    await owner.query(`insert into meta.rest_module (app_id, name, title, handlers) values ($1, 'sec176', 'sec176', $2)`, [appId, JSON.stringify([
      // the value comes from the caller: a line break would start a header of the caller's own
      { method: 'GET', path: 'echo', type: 'plpgsql', source: `begin perform meta.rest_header('X-Echo', :V); perform meta.rest_reply('{"ok": true}'); end` },
      // the setting written without the function: the runtime holds it to the same rules
      { method: 'GET', path: 'raw', type: 'plpgsql', source: `begin perform set_config('pgkiln_rest.headers', '{"set-cookie": "pgkiln_session=stolen", "content-type": "text/html", "access-control-allow-origin": "*", "x-split": "a\\r\\nSet-Cookie: b=c", "x-fine": "kept"}', true); perform meta.rest_reply('{"ok": true}'); end` },
    ])]);
  });
  after(async () => {
    await owner.query(`delete from meta.rest_module where app_id = $1 and name = 'sec176'`, [appId]);
  });
  const get = (path: string) => app.inject({ method: 'GET', url: `/a/hr/rest/sec176/${path}`, headers: { authorization: `Bearer ${king}` } });

  test('a value with a line break is refused: no header of the caller\'s own, no second response', async () => {
    const res = await get(`echo?v=${encodeURIComponent('a\r\nSet-Cookie: pgkiln_session=evil')}`);
    assert.equal(res.statusCode, 400);
    assert.equal(res.headers['set-cookie'], undefined);
    assert.equal(res.headers['x-echo'], undefined);
    assert.equal((await get('echo?v=fine')).headers['x-echo'], 'fine');
  });

  test('a handler cannot set a cookie, the content type or a CORS header, with or without the function', async () => {
    const res = await get('raw');
    assert.equal(res.statusCode, 200);
    assert.equal(res.headers['set-cookie'], undefined);
    assert.match(String(res.headers['content-type']), /^application\/json/);
    assert.equal(res.headers['access-control-allow-origin'], undefined);
    assert.equal(res.headers['x-split'], undefined);
    assert.equal(res.headers['x-fine'], 'kept');
    for (const name of ['Set-Cookie', 'Strict-Transport-Security', 'Cross-Origin-Opener-Policy', 'WWW-Authenticate', 'Sec-Fetch-Site', 'Proxy-Authenticate'])
      await assert.rejects(owner.query('select meta.rest_header($1, $2)', [name, 'x']), /set by the server/, name);
    // without a token the handler does not run: no header from it
    const anon = await app.inject({ method: 'GET', url: '/a/hr/rest/sec176/echo?v=x' });
    assert.equal(anon.statusCode, 401);
    assert.equal(anon.headers['x-echo'], undefined);
  });
});

describe('sprint 177 the web request outbox and inbound webhooks', () => {
  const SECRET = 'sec177-signing-secret-never-shown';
  const ENV = ['PGKILN_SECRET_KEY', 'PGKILN_REST_ALLOWED_HOSTS', 'PGKILN_REST_PRIVATE_HOSTS', 'QUEUE_RETRY_S'];
  const saved: Record<string, string | undefined> = {};
  let hr = 0;
  let otherWs = 0;
  let otherApp = 0;
  let theirRequest = '';
  let theirEvent = '';
  let mock: import('node:http').Server;
  let mockBase = '';
  let hits = 0;
  let answer = 200;
  let wr: typeof import('../src/webrequests.ts');
  let wh: typeof import('../src/webhooks.ts');
  let hmac: (body: string | Buffer, secret?: string) => string;
  let stripe: (body: string, t?: number, secret?: string) => string;

  const asHr = <T>(fn: (q: (sql: string, params?: unknown[]) => Promise<any[]>) => Promise<T>, appId = hr, role = 'hr_app') =>
    runtime.tx(async (c) => {
      await c.query(`select set_config('pgkiln.app_id', $1, true), set_config('pgkiln.app_user', 'king', true)`, [String(appId)]);
      await c.query(`set local role ${role}`);
      return fn(async (sql, params = []) => (await c.query(sql, params)).rows);
    });
  const post = (path: string, payload: string | Buffer, headers: Record<string, string | string[]> = {}) =>
    app.inject({ method: 'POST', url: `/a/hr/rest/sec177/${path}`, payload, headers: { 'content-type': 'application/json', ...headers } });
  const events = async () => (await owner.query(`select * from meta.webhook_event where app_id = $1 and module = 'sec177' order by id`, [hr])).rows;
  const ran = async () => (await owner.query('select * from sec177.ran order by id')).rows;
  const signIn = async () => {
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    await dev.get('/builder/sql/rest/requests');
    return dev;
  };

  before(async () => {
    for (const k of ENV) saved[k] = process.env[k];
    process.env.PGKILN_SECRET_KEY = 'security-test-secret-key-0123456789abcdef';
    process.env.PGKILN_REST_ALLOWED_HOSTS = '127.0.0.1';
    process.env.PGKILN_REST_PRIVATE_HOSTS = '127.0.0.1';
    process.env.QUEUE_RETRY_S = '0';
    const { createHmac } = await import('node:crypto');
    const http = await import('node:http');
    const { encryptSecret } = await import('../src/secrets.ts');
    wr = await import('../src/webrequests.ts');
    wh = await import('../src/webhooks.ts');
    hmac = (body, secret = SECRET) => createHmac('sha256', secret).update(body).digest('hex');
    stripe = (body, t = Math.floor(Date.now() / 1000), secret = SECRET) => `t=${t},v1=${createHmac('sha256', secret).update(`${t}.${body}`).digest('hex')}`;
    mock = http.createServer((req, res) => {
      req.resume();
      req.on('end', () => {
        hits++;
        res.writeHead(answer, { 'content-type': 'text/plain' });
        res.end('ok');
      });
    });
    await new Promise<void>((r) => mock.listen(0, '127.0.0.1', r));
    mockBase = `http://127.0.0.1:${(mock.address() as import('node:net').AddressInfo).port}`;
    hr = (await owner.one(`select id from meta.app where alias = 'hr'`))!.id;
    await owner.query(`delete from meta.app where alias = 'sec177-other'`);
    await owner.query(`delete from meta.workspace where name = 'sec177 other'`);
    await owner.query('drop schema if exists sec177 cascade');
    await owner.query('drop role if exists sec177_bypass');
    await owner.query('create schema sec177');
    await owner.query('grant usage on schema sec177 to hr_app');
    await owner.query('create table sec177.ran (id serial primary key, what text, who text, role text, login text)');
    await owner.query('grant select, insert on sec177.ran to hr_app');
    await owner.query('grant usage on sequence sec177.ran_id_seq to hr_app');
    await owner.query(`create function sec177.done(p_id bigint) returns void language sql as
      $$ insert into sec177.ran (what, who, role, login) values ('callback ' || (meta.web_response(p_id)->>'status'), meta.app_user(), current_user, session_user) $$`);
    await owner.query(`create function sec177.owner_only(p_id bigint) returns void language sql as $$ insert into sec177.ran (what) values ('owner only') $$`);
    await owner.query('revoke execute on function sec177.owner_only(bigint) from public');
    // a role that bypasses row level security, which the runtime could switch to
    await owner.query('create role sec177_bypass nologin bypassrls');
    await owner.query('grant sec177_bypass to pgkiln_runtime');
    await owner.query('grant usage on schema sec177 to sec177_bypass');
    await owner.query('grant select, insert on sec177.ran to sec177_bypass');
    await owner.query('grant usage on sequence sec177.ran_id_seq to sec177_bypass');
    await owner.query(`delete from meta.web_credential where app_id = $1 and name = 'SEC177_HOOK'`, [hr]);
    await owner.query(`insert into meta.web_credential (app_id, name, type, secret_enc) values ($1, 'SEC177_HOOK', 'bearer', $2)`, [hr, encryptSecret(SECRET)]);
    await owner.query(`delete from meta.rest_module where app_id = $1 and name = 'sec177'`, [hr]);
    const block = (kind: string) => `insert into sec177.ran (what, who, role, login) values ('${kind} ' || coalesce(:BODY, ''), meta.app_user(), current_user, session_user)`;
    await owner.query(`insert into meta.rest_module (app_id, name, title, roles, handlers) values ($1, 'sec177', 'sec177', '{}', $2)`, [hr, JSON.stringify([
      { method: 'POST', path: 'hook', type: 'webhook', auth: 'public', source: block('hook'),
        webhook: { scheme: 'hmac-sha256', credential: 'SEC177_HOOK', header: 'X-Hub-Signature-256', prefix: 'sha256=', event_id: 'body:id' } },
      { method: 'POST', path: 'small', type: 'webhook', auth: 'public', source: block('small'), webhook: { scheme: 'hmac-sha256', credential: 'SEC177_HOOK', max_bytes: 100 } },
      { method: 'POST', path: 'stripe', type: 'webhook', auth: 'public', source: block('stripe'), webhook: { scheme: 'stripe', credential: 'SEC177_HOOK', event_id: 'body:id', tolerance_s: 300 } },
      { method: 'POST', path: 'plain', type: 'plpgsql', auth: 'public', source: `perform meta.rest_reply(jsonb_build_object('body', :BODY, 'x', :X), 200)` },
    ])]);
    // another workspace's application, with a queued request and an event of its own
    otherWs = (await owner.one(`insert into meta.workspace (name) values ('sec177 other') returning id`))!.id;
    otherApp = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('sec177-other', 'sec177 other app', 'none', 'hr_app') returning id`))!.id;
    await owner.query(`insert into meta.workspace_app (app_id, workspace_id) values ($1, $2) on conflict (app_id) do update set workspace_id = excluded.workspace_id`, [otherApp, otherWs]);
    theirRequest = (await owner.one(`insert into meta.web_request_log (app_id, url, status, finished_at, message) values ($1, 'https://theirs.example.org/sec177-their-url', 'gave_up', now(), 'sec177 their error') returning id::text`, [otherApp]))!.id;
    theirEvent = (await owner.one(`insert into meta.webhook_event (app_id, module, path, event_key, body, state, error) values ($1, 'theirs', 'hook', 'sec177-their-key', 'sec177 their body', 'failed', 'sec177 their failure') returning id::text`, [otherApp]))!.id;
  });

  after(async () => {
    await owner.query(`delete from meta.app where alias = 'sec177-other'`);
    await owner.query(`delete from meta.workspace where name = 'sec177 other'`);
    await owner.query(`delete from meta.rest_module where app_id = $1 and name = 'sec177'`, [hr]);
    await owner.query(`delete from meta.web_credential where app_id = $1 and name = 'SEC177_HOOK'`, [hr]);
    await owner.query(`delete from meta.webhook_event where app_id = $1 and module = 'sec177'`, [hr]);
    await owner.query(`delete from meta.web_request_log where app_id = $1 and (url like '%sec177%' or url like $2)`, [hr, `${mockBase}%`]);
    await owner.query('drop schema if exists sec177 cascade');
    await owner.query('drop owned by sec177_bypass');
    await owner.query('drop role if exists sec177_bypass');
    mock.close();
    for (const k of ENV) {
      if (saved[k] === undefined) delete process.env[k];
      else process.env[k] = saved[k];
    }
  });

  afterEach(async () => {
    await owner.query(`delete from meta.webhook_event where app_id = $1 and module = 'sec177'`, [hr]);
    await owner.query(`delete from meta.web_request_log where app_id = $1`, [hr]);
    await owner.query('truncate sec177.ran');
    hits = 0;
    answer = 200;
  });

  test('a webhook without a valid signature is answered 401 and nothing is stored or run', async () => {
    const body = '{"id": "e1", "amount": 5}';
    const good = `sha256=${hmac(body)}`;
    const attempts: [string, Record<string, string | string[]>, string | Buffer][] = [
      ['no signature', {}, body],
      ['an empty signature', { 'x-hub-signature-256': '' }, body],
      ['the prefix alone', { 'x-hub-signature-256': 'sha256=' }, body],
      ['without the prefix', { 'x-hub-signature-256': hmac(body) }, body],
      ['another secret', { 'x-hub-signature-256': `sha256=${hmac(body, 'guess')}` }, body],
      ['an empty secret', { 'x-hub-signature-256': `sha256=${hmac(body, '')}` }, body],
      ['a truncated signature', { 'x-hub-signature-256': good.slice(0, -2) }, body],
      ['a signature with more after it', { 'x-hub-signature-256': `${good}00` }, body],
      ['the signature of another body', { 'x-hub-signature-256': good }, '{"id": "e1", "amount": 5000}'],
      ['the body re-serialised', { 'x-hub-signature-256': good }, JSON.stringify(JSON.parse(body))],
      ['the signature in another header', { 'x-signature': good }, body],
      ['the signature as a query parameter is not read', {}, body],
      ['a bearer token instead', { authorization: 'Bearer anything' }, body],
      ['two signature headers', { 'x-hub-signature-256': [good, `sha256=${'0'.repeat(64)}`] }, body],
      ['not hex', { 'x-hub-signature-256': `sha256=${'z'.repeat(64)}` }, body],
    ];
    for (const [what, headers, payload] of attempts) {
      const res = await post(what.includes('query') ? `hook?x-hub-signature-256=${encodeURIComponent(good)}` : 'hook', payload, headers);
      assert.equal(res.statusCode, 401, what);
      assert.doesNotMatch(res.body, new RegExp(hmac(body)), what);
    }
    assert.deepEqual(await events(), []);
    await wh.webhookTick();
    assert.deepEqual(await ran(), []);
    // the refusals are logged with a reason, never with the signature, the secret or the body
    const log = (await owner.query(`select detail from meta.activity_log where app_id = $1 and event = 'webhook_refused' order by id desc limit 15`, [hr])).rows.map((r) => r.detail).join('\n');
    assert.match(log, /REST POST sec177\/hook: (no signature header|signature mismatch|malformed signature)/);
    assert.ok(!log.includes(SECRET) && !log.includes(hmac(body)) && !log.includes('amount'));
    // the same request with the right signature is accepted (upper-case hex too)
    assert.equal((await post('hook', body, { 'x-hub-signature-256': good })).statusCode, 202);
    assert.equal((await post('hook', '{"id": "e2"}', { 'x-hub-signature-256': `sha256=${hmac('{"id": "e2"}').toUpperCase()}` })).statusCode, 202);
    // a credential without a secret never means "unsigned is fine"
    await owner.query(`update meta.web_credential set secret_enc = null where app_id = $1 and name = 'SEC177_HOOK'`, [hr]);
    try {
      assert.equal((await post('hook', '{"id": "e3"}', { 'x-hub-signature-256': `sha256=${hmac('{"id": "e3"}', '')}` })).statusCode, 503);
    } finally {
      const { encryptSecret } = await import('../src/secrets.ts');
      await owner.query(`update meta.web_credential set secret_enc = $2 where app_id = $1 and name = 'SEC177_HOOK'`, [hr, encryptSecret(SECRET)]);
    }
    assert.equal((await events()).length, 2);
  });

  test('replay: an event id is processed once; a Stripe timestamp outside the tolerance is refused', async () => {
    const body = '{"id": "evt_replay", "n": 1}';
    assert.equal((await post('stripe', body, { 'stripe-signature': stripe(body) })).statusCode, 202);
    // the captured request sent again, now and after it was processed
    assert.equal((await post('stripe', body, { 'stripe-signature': stripe(body) })).statusCode, 200);
    await wh.webhookTick();
    assert.equal((await post('stripe', body, { 'stripe-signature': stripe(body) })).statusCode, 200);
    await wh.webhookTick();
    assert.equal((await ran()).length, 1);
    // an old capture (validly signed then), a timestamp from the future, a timestamp changed without re-signing
    const old = Math.floor(Date.now() / 1000) - 3600;
    const b2 = '{"id": "evt_old"}';
    assert.equal((await post('stripe', b2, { 'stripe-signature': stripe(b2, old) })).statusCode, 401);
    assert.equal((await post('stripe', b2, { 'stripe-signature': stripe(b2, old + 7200) })).statusCode, 401);
    assert.equal((await post('stripe', b2, { 'stripe-signature': stripe(b2, old).replace(`t=${old}`, `t=${old + 3600}`) })).statusCode, 401);
    assert.equal((await post('stripe', b2, { 'stripe-signature': `t=${old + 3600}` })).statusCode, 401);
    assert.equal((await post('stripe', b2, { 'stripe-signature': `v1=${hmac(b2)}` })).statusCode, 401);
    // v0 (an older scheme) is never accepted, whatever it holds
    const now = Math.floor(Date.now() / 1000);
    assert.equal((await post('stripe', b2, { 'stripe-signature': stripe(b2, now).replace('v1=', 'v0=') })).statusCode, 401);
    assert.equal((await events()).length, 1);
    // an event id that is no id
    const b3 = `{"id": {"nested": true}}`;
    assert.equal((await post('stripe', b3, { 'stripe-signature': stripe(b3) })).statusCode, 400);
    const b4 = `{"id": "${'x'.repeat(300)}"}`;
    assert.equal((await post('stripe', b4, { 'stripe-signature': stripe(b4) })).statusCode, 400);
    assert.equal((await events()).length, 1);
  });

  test('an oversized body is refused; the raw body route does not open other handlers', async () => {
    const big = `{"id": "big", "pad": "${'x'.repeat(1024 * 1024)}"}`;
    assert.equal((await post('hook', big, { 'x-hub-signature-256': `sha256=${hmac(big)}` })).statusCode, 413);
    const medium = `{"pad": "${'x'.repeat(200)}"}`;
    assert.equal((await post('small', medium, { 'x-signature': hmac(medium) })).statusCode, 413, 'the handler\'s own limit');
    assert.equal((await post('small', '{"a": 1}', { 'x-signature': hmac('{"a": 1}') })).statusCode, 202);
    assert.equal((await events()).length, 1);
    // the webhook content type sent to an ordinary handler: its body is not parsed, nothing else changes
    const res = await post('plain?x=1', '{"x": "from body"}', { 'content-type': 'application/x-pgkiln-webhook' });
    assert.equal(res.statusCode, 200);
    assert.deepEqual(res.json(), { body: null, x: '1' });
    // GET on a webhook path, and a webhook in a disabled module
    assert.equal((await app.inject({ method: 'GET', url: '/a/hr/rest/sec177/hook' })).statusCode, 405);
    await owner.query(`update meta.rest_module set enabled = false where app_id = $1 and name = 'sec177'`, [hr]);
    try {
      assert.equal((await post('small', '{"a": 2}', { 'x-signature': hmac('{"a": 2}') })).statusCode, 404);
    } finally {
      await owner.query(`update meta.rest_module set enabled = true where app_id = $1 and name = 'sec177'`, [hr]);
    }
  });

  test('a webhook\'s block runs as the application\'s role, never as the owner or a role that bypasses row level security', async () => {
    const body = '{"id": "role-1"}';
    assert.equal((await post('hook', body, { 'x-hub-signature-256': `sha256=${hmac(body)}` })).statusCode, 202);
    await wh.webhookTick();
    const [row] = await ran();
    assert.equal(row.role, 'hr_app');
    assert.equal(row.who, 'nobody');
    assert.notEqual(row.login, (await owner.one('select current_user::text as u'))!.u);
    // the application's role changed to one that bypasses RLS, then to pgkiln's owner: the event fails, the block does not run
    const ownerName = (await owner.one('select current_user::text as u'))!.u;
    for (const role of ['sec177_bypass', ownerName]) {
      // (sprint 186) meta.app refuses such a role: one that became powerful after it was saved
      await owner.tx(async (c) => {
        await c.query('alter table meta.app disable trigger app_role_check');
        await c.query('update meta.app set db_role = $2 where id = $1', [hr, role]);
        await c.query('set constraints all immediate'); // the deferred workspace check first: ALTER TABLE refuses pending trigger events
        await c.query('alter table meta.app enable trigger app_role_check');
      });
      try {
        const b = `{"id": "role-${role}"}`;
        assert.equal((await post('hook', b, { 'x-hub-signature-256': `sha256=${hmac(b)}` })).statusCode, 202);
        await wh.webhookTick();
      } finally {
        await owner.query(`update meta.app set db_role = 'hr_app' where id = $1`, [hr]);
      }
    }
    assert.equal((await ran()).length, 1);
    const failed = (await events()).slice(1);
    assert.equal(failed[0].state, 'failed');
    assert.notEqual(failed[1].state, 'done');
    assert.match(failed[0].error, /bypasses row level security/);
    assert.match(failed[1].error, /permission denied|bypasses row level security/);
    // the runtime role cannot read events or the queue itself
    await assert.rejects(runtime.query('select * from meta.webhook_event'), /permission denied/);
    await assert.rejects(runtime.query('select * from meta.web_request_log'), /permission denied/);
    await assert.rejects(asHr((q) => q('select body from meta.webhook_event')), /permission denied/);
  });

  test('a callback name is never run as SQL, and only a function the application\'s role may execute is taken', async () => {
    const names = [
      `sec177.done(1); drop table sec177.ran; --`, `sec177.done'); drop table sec177.ran; --`, `sec177."done"`, `"sec177".done`, 'sec177.done(bigint)',
      'sec177.done, pg_sleep(5)', 'pg_catalog.pg_terminate_backend', 'meta.web_request_done', 'sec177.owner_only', 'sec177.missing', 'done', 'sec177.done.x', 'information_schema.x',
    ];
    for (const name of names)
      await assert.rejects(asHr((q) => q(`select meta.web_request($1, p_callback => $2)`, [`${mockBase}/sec177`, name])), /meta\.web_request: the callback/, name);
    assert.equal((await owner.one(`select count(*)::int as n from meta.web_request_log where app_id = $1`, [hr]))!.n, 0);
    // a row changed behind the function's back: the server checks the name again and calls nothing
    const id = (await asHr((q) => q(`select meta.web_request($1, p_callback => 'sec177.done') as id`, [`${mockBase}/sec177`])))[0].id;
    await owner.query(`update meta.web_request_log set callback = $2 where id = $1`, [id, `sec177.done($1); insert into sec177.ran (what) values ('injected')`]);
    await wr.webRequestTick();
    for (let i = 0; i < 4; i++) {
      await owner.query(`update meta.web_request_log set callback_next_at = now() where id = $1 and callback_state = 'pending'`, [id]);
      await wr.callbackTick();
    }
    let row = (await owner.one('select status, callback_state, callback_error from meta.web_request_log where id = $1', [id]))!;
    assert.deepEqual([row.status, row.callback_state], ['ok', 'failed']);
    assert.match(row.callback_error, /not schema\.function/);
    assert.deepEqual(await ran(), []);
    assert.equal(hits, 1, 'the request itself was sent once');
    // a function the application's role lost the right to execute after queueing: the call fails as that role
    const id2 = (await asHr((q) => q(`select meta.web_request($1, p_callback => 'sec177.done') as id`, [`${mockBase}/sec177`])))[0].id;
    await owner.query(`update meta.web_request_log set callback = 'sec177.owner_only' where id = $1`, [id2]);
    await wr.webRequestTick();
    row = (await owner.one('select status, callback_state, callback_error from meta.web_request_log where id = $1', [id2]))!;
    assert.match(row.callback_error, /permission denied/);
    assert.deepEqual(await ran(), []);
  });

  test('a callback runs as the application\'s role and the queueing user, never as the owner or a role that bypasses row level security', async () => {
    const id = (await asHr((q) => q(`select meta.web_request($1, p_callback => 'sec177.done') as id`, [`${mockBase}/sec177`])))[0].id;
    await wr.webRequestTick();
    const [row] = await ran();
    const ownerName = (await owner.one('select current_user::text as u'))!.u;
    assert.deepEqual([row.what, row.who, row.role], ['callback ok', 'king', 'hr_app']);
    assert.notEqual(row.login, ownerName);
    assert.equal((await owner.one('select callback_state from meta.web_request_log where id = $1', [id]))!.callback_state, 'done');
    for (const role of ['sec177_bypass', ownerName]) {
      const id2 = (await asHr((q) => q(`select meta.web_request($1, p_callback => 'sec177.done') as id`, [`${mockBase}/sec177`])))[0].id;
      // (sprint 186) meta.app refuses such a role: one that became powerful after it was saved
      await owner.tx(async (c) => {
        await c.query('alter table meta.app disable trigger app_role_check');
        await c.query('update meta.app set db_role = $2 where id = $1', [hr, role]);
        await c.query('set constraints all immediate'); // the deferred workspace check first: ALTER TABLE refuses pending trigger events
        await c.query('alter table meta.app enable trigger app_role_check');
      });
      try {
        await wr.webRequestTick();
      } finally {
        await owner.query(`update meta.app set db_role = 'hr_app' where id = $1`, [hr]);
      }
      const r = (await owner.one('select status, callback_state, callback_error from meta.web_request_log where id = $1', [id2]))!;
      assert.equal(r.status, 'ok');
      assert.notEqual(r.callback_state, 'done', role);
      assert.match(r.callback_error, /bypasses row level security|permission denied/, role);
      await owner.query('delete from meta.web_request_log where id = $1', [id2]);
    }
    assert.equal((await ran()).length, 1);
  });

  test('every attempt goes through the allow-list: a retry to a host no longer allowed is refused, not sent', async () => {
    answer = 503;
    process.env.QUEUE_RETRY_S = '60';
    const id = (await asHr((q) => q(`select meta.web_request($1, 'POST', '{}') as id`, [`${mockBase}/sec177`])))[0].id;
    await wr.webRequestTick();
    assert.equal(hits, 1);
    assert.equal((await owner.one('select status from meta.web_request_log where id = $1', [id]))!.status, 'retry');
    // between the attempts the host leaves the allow-list (private addresses are refused again)
    process.env.PGKILN_REST_ALLOWED_HOSTS = 'api.example.org';
    process.env.PGKILN_REST_PRIVATE_HOSTS = '';
    try {
      await owner.query(`update meta.web_request_log set next_attempt_at = now() where id = $1`, [id]);
      await wr.webRequestTick();
    } finally {
      process.env.PGKILN_REST_ALLOWED_HOSTS = '127.0.0.1';
      process.env.PGKILN_REST_PRIVATE_HOSTS = '127.0.0.1';
      process.env.QUEUE_RETRY_S = '0';
    }
    const r = (await owner.one('select status, attempts, message, next_attempt_at from meta.web_request_log where id = $1', [id]))!;
    assert.equal(hits, 1, 'the second attempt never left the server');
    assert.equal(r.status, 'error');
    assert.equal(r.next_attempt_at, null);
    assert.match(r.message, /allow-list|private|network access list/);
    // a URL the queue row was changed to (not http) is not requested either
    const id2 = (await asHr((q) => q(`select meta.web_request($1) as id`, [`${mockBase}/sec177`])))[0].id;
    await owner.query(`update meta.web_request_log set url = 'file:///etc/passwd?sec177' where id = $1`, [id2]);
    await wr.webRequestTick();
    assert.equal((await owner.one('select status from meta.web_request_log where id = $1', [id2]))!.status, 'error');
    // the idempotency header cannot smuggle a second header or replace a credential's
    await assert.rejects(asHr((q) => q(`select meta.web_request($1, p_idempotency_key => E'k\\r\\nX-Evil: 1')`, [`${mockBase}/sec177`])), /printable ASCII/);
    await assert.rejects(asHr((q) => q(`select meta.web_request($1, p_idempotency_key => 'k', p_idempotency_header => E'X-A\\r\\nX-Evil')`, [`${mockBase}/sec177`])), /can't be the header/);
    await assert.rejects(asHr((q) => q(`select meta.web_request($1, p_idempotency_key => 'k', p_idempotency_header => 'Cookie')`, [`${mockBase}/sec177`])), /can't be the header/);
  });

  test('an application reads, cancels and is called back for its own requests only', async () => {
    answer = 503;
    process.env.QUEUE_RETRY_S = '60';
    try {
      const id = (await asHr((q) => q(`select meta.web_request($1) as id`, [`${mockBase}/sec177`])))[0].id;
      await wr.webRequestTick();
      // the other application (same database role) sees nothing of it and cannot cancel it
      assert.equal((await asHr((q) => q('select meta.web_response($1) as r', [id]), otherApp))[0].r, null);
      assert.equal((await asHr((q) => q('select meta.web_request_cancel($1) as ok', [id]), otherApp))[0].ok, false);
      assert.equal((await asHr((q) => q('select meta.web_response($1) as r', [theirRequest])))[0].r, null);
      assert.equal((await asHr((q) => q('select meta.web_request_cancel($1) as ok', [id])))[0].ok, true);
      // the server's own functions do nothing for a request of another transaction
      await asHr((q) => q(`select meta.web_request_done($1, 'ok', 200, null, null, null, null)`, [id]));
      assert.equal((await owner.one('select status from meta.web_request_log where id = $1', [id]))!.status, 'cancelled');
      // without an application nothing is queued
      await assert.rejects(runtime.query(`select meta.web_request($1)`, [`${mockBase}/sec177`]), /no current application/);
    } finally {
      process.env.QUEUE_RETRY_S = '0';
    }
  });

  test('the builder shows a workspace its own queue and events only; changes need CSRF and a developer', async () => {
    const evil = '<img src=x onerror=alert(177)>';
    const mine = (await owner.one(`insert into meta.web_request_log (app_id, url, status, finished_at, message, callback, callback_state, callback_error)
      values ($1, $2, 'gave_up', now(), $3, 'sec177.done', 'failed', $3) returning id::text`, [hr, `https://mine.example.org/sec177/${evil}?api_key=sec177-key-in-query`, `sec177 mine ${evil}`]))!.id;
    const myEvent = (await owner.one(`insert into meta.webhook_event (app_id, module, path, event_key, body, headers, state, error)
      values ($1, 'sec177', 'hook', $2, $3, $4, 'failed', $2) returning id::text`, [hr, `sec177-key ${evil}`, `sec177 my body ${evil}`, JSON.stringify({ 'x-kind': evil })]))!.id;
    const dev = await signIn();
    let page = (await dev.get('/builder/sql/rest/requests')).body;
    assert.match(page, /mine\.example\.org/);
    assert.doesNotMatch(page, /sec177-their-url|sec177 their error/);
    assert.ok(!page.includes(evil) && page.includes('&lt;img src=x'), 'escaped');
    assert.doesNotMatch(page, /sec177-key-in-query/, 'a URL\'s query string is not shown');
    assert.doesNotMatch((await dev.get('/builder/sql/rest/requests?state=gave_up')).body, /sec177-their-url/);
    page = (await dev.get('/builder/sql/rest/events')).body;
    assert.match(page, /sec177-key/);
    assert.doesNotMatch(page, /sec177-their-key|sec177 their failure/);
    assert.ok(!page.includes(evil));
    page = (await dev.get(`/builder/sql/rest/events/${myEvent}`)).body;
    assert.match(page, /sec177 my body/);
    assert.ok(!page.includes(evil));
    assert.ok(!page.includes(SECRET));
    assert.equal((await dev.get(`/builder/sql/rest/events/${theirEvent}`)).statusCode, 404);
    assert.equal((await dev.get(`/builder/sql/rest/events/${theirEvent}%20or%201=1`)).statusCode, 404);
    // another workspace's rows can't be changed, by any action
    for (const action of ['requeue', 'cancel', 'callback']) await dev.post(`/builder/sql/rest/requests/${theirRequest}`, { __csrf: dev.lastCsrf, action });
    await dev.post(`/builder/sql/rest/events/${theirEvent}`, { __csrf: dev.lastCsrf, action: 'reprocess' });
    assert.equal((await owner.one('select status from meta.web_request_log where id = $1', [theirRequest]))!.status, 'gave_up');
    assert.equal((await owner.one('select state from meta.webhook_event where id = $1', [theirEvent]))!.state, 'failed');
    // a forged request changes nothing; neither does an application user or a visitor
    assert.equal((await dev.post(`/builder/sql/rest/requests/${mine}`, { __csrf: 'forged', action: 'requeue' })).statusCode, 403);
    assert.equal((await dev.post(`/builder/sql/rest/events/${myEvent}`, { __csrf: 'forged', action: 'reprocess' })).statusCode, 403);
    const king = await as('king');
    for (const url of ['/builder/sql/rest/requests', '/builder/sql/rest/events', `/builder/sql/rest/events/${myEvent}`]) {
      assert.equal((await king.get(url)).headers.location, '/builder/login', url);
      const visitor = await app.inject({ method: 'GET', url });
      assert.equal(visitor.statusCode, 302, url);
      assert.doesNotMatch(visitor.body, /sec177/);
    }
    assert.equal((await owner.one('select status from meta.web_request_log where id = $1', [mine]))!.status, 'gave_up');
    assert.equal((await owner.one('select state from meta.webhook_event where id = $1', [myEvent]))!.state, 'failed');
    assert.equal((await dev.post(`/builder/sql/rest/requests/${mine}`, { __csrf: dev.lastCsrf, action: 'drop' })).statusCode, 400);
    // the developer's own: re-queue and re-process work
    await dev.post(`/builder/sql/rest/requests/${mine}`, { __csrf: dev.lastCsrf, action: 'requeue' });
    const r = (await owner.one('select status, attempts, callback_state from meta.web_request_log where id = $1', [mine]))!;
    assert.deepEqual(r, { status: 'queued', attempts: 0, callback_state: null });
    await dev.post(`/builder/sql/rest/requests/${mine}`, { __csrf: dev.lastCsrf, action: 'cancel' });
    assert.equal((await owner.one('select status from meta.web_request_log where id = $1', [mine]))!.status, 'cancelled');
    await dev.post(`/builder/sql/rest/events/${myEvent}`, { __csrf: dev.lastCsrf, action: 'reprocess' });
    assert.deepEqual((await owner.one('select state, attempts from meta.webhook_event where id = $1', [myEvent]))!, { state: 'received', attempts: 0 });
  });

  test('the signing secret is not in an export, and a webhook handler travels with its module', async () => {
    const doc = JSON.stringify((await owner.one(`select meta.export_app('hr') as doc`))!.doc);
    assert.ok(!doc.includes(SECRET));
    assert.doesNotMatch(doc, /secret_enc/);
    assert.match(doc, /"type": ?"webhook"/);
    assert.match(doc, /"credential": ?"SEC177_HOOK"/);
    assert.doesNotMatch(doc, /sec177 my body|webhook_event"/);
  });
});

describe('sprint 178 OAuth clients limited to REST modules', () => {
  let hr = 0;
  let cid = 0;
  let clientId = '';
  let dept = '';
  let bearer = '';
  const get = (url: string, token = bearer) => app.inject({ method: 'GET', url, headers: { authorization: `Bearer ${token}` } });
  const limit = (modules: string[] | null) => owner.query('select meta.oauth_limit_client($1, $2)', [clientId, modules]);
  /** The data API's token check, the way PostgREST runs it for a verified token. */
  const dataApi = async (token: string) => {
    const { decodeJwt } = await import('jose');
    const claims = decodeJwt(token);
    const c = await owner.pool.connect();
    try {
      await c.query('begin');
      await c.query(`select set_config('request.jwt.claims', $1, true)`, [JSON.stringify({ role: 'hr_api', ...claims })]);
      await c.query('set local role hr_api');
      await c.query('select meta.api_check()');
      return 'ok';
    } catch (e) {
      return (e as Error).message;
    } finally {
      await c.query('rollback').catch(() => {});
      c.release();
    }
  };

  before(async () => {
    hr = (await owner.one(`select id from meta.app where alias = 'hr'`))!.id;
    await owner.query(`delete from meta.rest_module where app_id = $1 and name like 'sec178%'`, [hr]);
    await owner.query(`delete from meta.api_client where name = 'sec178-client'`);
    await owner.query(`delete from meta.rest_object where app_id = $1 and alias = 'sec178-dept'`, [hr]);
    // hr.dept on AutoREST: the test publishes it itself (alias sec178-dept) unless another test already did
    await owner.query(`insert into meta.rest_object (app_id, schema_name, object_name, alias, methods, auth) values ($1, 'hr', 'dept', 'sec178-dept', '{GET}', 'token') on conflict do nothing`, [hr]);
    dept = (await owner.one(`select alias from meta.rest_object where app_id = $1 and schema_name = 'hr' and object_name = 'dept'`, [hr]))!.alias;
    for (const m of ['sec178a', 'sec178b'])
      await owner.query(`insert into meta.rest_module (app_id, name, title, handlers) values ($1, $2, $2, $3)`,
        [hr, m, JSON.stringify([{ method: 'GET', path: 'who', type: 'sql', source: `select meta.app_user() as who, '${m}' as module` }])]);
    const c = (await owner.one(`select * from meta.oauth_create_client('hr', 'sec178-client', '{manager}', 'sprint 178', 15)`))!;
    clientId = c.client_id;
    cid = (await owner.one('select id from meta.api_client where client_id = $1', [clientId]))!.id;
    const { clientToken } = await import('../src/oauth.ts');
    bearer = (await clientToken(clientId, c.client_secret)).access_token;
  });

  after(async () => {
    await owner.query(`delete from meta.rest_module where app_id = $1 and name like 'sec178%'`, [hr]);
    await owner.query(`delete from meta.rest_object where app_id = $1 and alias = 'sec178-dept'`, [hr]);
    await owner.query(`delete from meta.api_client where name = 'sec178-client'`);
  });

  test('without a limit the client calls every module, AutoREST and the data API, as before', async () => {
    assert.equal((await get('/a/hr/rest/sec178a/who')).statusCode, 200);
    assert.equal((await get('/a/hr/rest/sec178b/who')).statusCode, 200);
    assert.equal((await get(`/a/hr/autorest/${dept}/`)).statusCode, 200);
    assert.equal(await dataApi(bearer), 'ok');
  });

  test('a limit applies to a token issued before it: its modules only, no AutoREST, no data API', async () => {
    await limit(['sec178a']);
    const a = await get('/a/hr/rest/sec178a/who');
    assert.equal(a.statusCode, 200, a.body);
    assert.match(a.body, /client:sec178-client/);
    const b = await get('/a/hr/rest/sec178b/who');
    assert.equal(b.statusCode, 403);
    assert.doesNotMatch(b.body, /sec178b"|client:sec178/);
    assert.equal((await get(`/a/hr/autorest/${dept}/`)).statusCode, 403);
    // (sprint 184) the OpenAPI document of AutoREST: the public objects only, as without a token
    assert.equal((await get('/a/hr/autorest/openapi.json')).statusCode, 200);
    assert.match(await dataApi(bearer), /limited to REST modules/);
    // the limit is not a grant: the module's and the handler's roles still apply
    await owner.query(`update meta.rest_module set roles = '{nobody_has_this}' where app_id = $1 and name = 'sec178a'`, [hr]);
    assert.equal((await get('/a/hr/rest/sec178a/who')).statusCode, 403);
    await owner.query(`update meta.rest_module set roles = '{}' where app_id = $1 and name = 'sec178a'`, [hr]);
  });

  test('a new token of a limited client carries the API role (sprint 184): refused on the data API, works there once the limit is cleared', async () => {
    const { decodeJwt } = await import('jose');
    const { clientToken } = await import('../src/oauth.ts');
    const secret = (await owner.one(`select meta.oauth_rotate_secret($1, make_interval(hours => 0)) as s`, [clientId]))!.s;
    const t = (await clientToken(clientId, secret)).access_token;
    assert.equal(decodeJwt(t).role, 'hr_api');
    assert.match(await dataApi(t), /limited to REST modules/);
    assert.equal((await get('/a/hr/rest/sec178a/who', t)).statusCode, 200);
    assert.equal((await get('/a/hr/rest/sec178b/who', t)).statusCode, 403);
    await limit(null);
    assert.equal((await get('/a/hr/rest/sec178b/who', t)).statusCode, 200);
    assert.equal(await dataApi(t), 'ok');
    assert.equal(decodeJwt((await clientToken(clientId, secret)).access_token).role, 'hr_api');
  });

  test('the builder limits a client to modules of its own application; CSRF and a developer are needed', async () => {
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    const page = await dev.get(`/builder/apps/${hr}/api`);
    assert.match(page.body, new RegExp(`/api/clients/${cid}/modules`));
    const url = `/builder/apps/${hr}/api/clients/${cid}/modules`;
    assert.equal((await dev.post(url, { __csrf: 'forged', modules: 'sec178a' })).statusCode, 403);
    assert.equal((await app.inject({ method: 'POST', url, payload: { modules: 'sec178a' } })).statusCode, 302);
    // (165) the modules by link; null: no limit
    const mods = async () => (await owner.one(`select case when c.module_limit then array(select m.name from meta.api_client_module l join meta.rest_module m on m.id = l.module_id where l.client_id = c.id order by m.name) end as m
                                                 from meta.api_client c where c.id = $1`, [cid]))!.m;
    assert.equal(await mods(), null);
    // a module of no application, and markup: refused and escaped
    await dev.post(url, { __csrf: dev.lastCsrf, modules: 'sec178a, <b>nope</b>' });
    assert.equal(await mods(), null);
    const refused = await dev.get(`/builder/apps/${hr}/api`);
    assert.doesNotMatch(refused.body, /<b>nope<\/b>/);
    await dev.post(url, { __csrf: dev.lastCsrf, modules: 'SEC178A, sec178b, sec178a' });
    assert.deepEqual(await mods(), ['sec178a', 'sec178b']);
    // a client of another application is not found through this one's URL
    await owner.query(`delete from meta.app where alias = 'sec178-other'`);
    const other = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) select 'sec178-other', 'Other', 'none', db_role from meta.app where alias = 'hr' returning id`))!.id;
    try {
      assert.equal((await dev.post(`/builder/apps/${other}/api/clients/${cid}/modules`, { __csrf: dev.lastCsrf, modules: '' })).statusCode, 404);
    } finally {
      await owner.query(`delete from meta.app where id = $1`, [other]);
    }
    assert.deepEqual(await mods(), ['sec178a', 'sec178b']);
    await dev.post(url, { __csrf: dev.lastCsrf, modules: '' });
    assert.equal(await mods(), null);
  });
});

describe('sprint 179 the SQL Workshop tour', () => {
  test('the tour needs a developer, takes only a step number, and leaves SQL Monitor to administrators', async () => {
    for (const url of ['/builder/sql/tour', '/builder/sql/tour?step=3']) {
      const visitor = await app.inject({ method: 'GET', url });
      assert.equal(visitor.statusCode, 302, url);
      assert.equal(visitor.headers.location, '/builder/login');
    }
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    const home = await dev.get('/builder/sql');
    assert.match(home.body, /href="\/builder\/sql\/tour"/);
    const first = await dev.get('/builder/sql/tour');
    assert.equal(first.statusCode, 200);
    assert.match(first.body, /Step 1 of 7/);
    assert.match(first.body, /href="\/builder\/sql\/worksheet"/);
    assert.match(first.body, /aria-current="step">1\. SQL Worksheet/);
    // anything that is no step number: the first step or the last, never echoed
    for (const [step, want] of [['0', 1], ['-4', 1], ['abc', 1], ['99999999999999999999', 7], ['2<script>alert(1)</script>', 2], ['"><img src=x>', 1]] as const) {
      const res = await dev.get(`/builder/sql/tour?step=${encodeURIComponent(step)}`);
      assert.equal(res.statusCode, 200, step);
      assert.match(res.body, new RegExp(`Step ${want} of 7`), step);
      assert.doesNotMatch(res.body, /<script>alert|<img src=x/, step);
    }
    const last = await dev.get('/builder/sql/tour?step=7');
    assert.match(last.body, /href="\/builder\/sql\/monitor"/);
    assert.match(last.body, /class="btn btn-hot" href="\/builder\/sql">Done/);
    assert.doesNotMatch(last.body, /step=8/);
  });
});

describe('sprint 180 the Change Log records DDL of other tools (DA-17)', () => {
  const DEV = 'sec180_dev';
  const PW = 'Sec180-dev-password!';
  const S = 'sec180x';
  const pg = async () => (await import('pg')).default;
  /** DDL from another tool: its own connection, not one of pgkiln's (application_name psql) */
  const psql = async (sql: string, appName = 'psql') => {
    const c = new (await pg()).Client({ connectionString: process.env.DATABASE_URL, application_name: appName });
    await c.connect();
    try {
      return await c.query(sql);
    } finally {
      await c.end();
    }
  };
  const external = async () => (await owner.query(`select name, author, source, object_name, sql from meta.change_set where schema_name = $1 order by seq`, [S])).rows;
  const triggers = async () => (await owner.query(`select evtname from pg_event_trigger where evtname like 'pgkiln_change_log%' order by 1`)).rows.map((r) => r.evtname);
  const superuser = async () => !!(await owner.one(`select rolsuper from pg_roles where rolname = current_user`))!.rolsuper;
  const clean = async () => {
    await owner.query(`drop event trigger if exists pgkiln_change_log_ddl`);
    await owner.query(`drop event trigger if exists pgkiln_change_log_drop`);
    await owner.query(`drop schema if exists ${S} cascade`);
    await owner.query(`delete from meta.change_set where schema_name = $1`, [S]);
    await owner.query(`delete from meta.change_set_counter where schema_name = $1`, [S]);
  };
  const admin = async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username: 'admin', password: 'admin' });
    await b.get('/builder/sql/changes');
    return b;
  };

  before(async () => {
    await clean();
    await owner.query(`create schema ${S}`);
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false) on conflict do nothing`, [DEV, PW]);
  });
  after(async () => {
    await clean();
    await owner.query(`delete from meta.developer where username = $1`, [DEV]);
  });

  test('the functions run as pgkiln\'s owner with a fixed search_path; nobody else may call them', async () => {
    const fns = (await owner.query(
      `select p.proname, p.prosecdef, p.proconfig, has_function_privilege('pgkiln_runtime', p.oid, 'execute') as runtime_may
         from pg_proc p where p.pronamespace = 'meta'::regnamespace and p.proname in ('change_log_ddl', 'change_log_drop', 'change_log_record') order by 1`)).rows;
    assert.equal(fns.length, 3);
    for (const f of fns) {
      assert.equal(f.prosecdef, true, `${f.proname}: never as the superuser who runs the DDL`);
      assert.match(String(f.proconfig), /search_path=pg_catalog, pg_temp/, f.proname);
      assert.equal(f.runtime_may, false, f.proname);
    }
  });

  test('only an administrator turns it on, with the CSRF token, and only when pgkiln connects as a superuser', async (t) => {
    if (!(await superuser())) return t.skip('pgkiln does not connect as a superuser here');
    const d = new FileBrowser(app);
    await d.get('/builder/login');
    await d.post('/builder/login', { __csrf: d.lastCsrf, username: DEV, password: PW });
    const page = await d.get('/builder/sql/changes');
    assert.equal(page.statusCode, 200);
    assert.doesNotMatch(page.body, /action="\/builder\/sql\/changes\/capture"/, 'no button for a developer');
    assert.match(page.body, /create event trigger pgkiln_change_log_ddl/, 'the statements instead');
    assert.equal((await d.submit('/builder/sql/changes/capture', { on: '1' })).statusCode, 403);
    const a = await admin();
    assert.equal((await a.post('/builder/sql/changes/capture', { __csrf: 'forged', on: '1' })).statusCode, 403);
    assert.deepEqual(await triggers(), []);
    assert.match((await a.get('/builder/sql/changes')).body, /action="\/builder\/sql\/changes\/capture"/);
    assert.equal((await a.submit('/builder/sql/changes/capture', { on: '1' })).statusCode, 303);
    assert.deepEqual(await triggers(), ['pgkiln_change_log_ddl', 'pgkiln_change_log_drop']);
    assert.match((await a.get('/builder/sql/changes')).body, /DDL run outside pgkiln/);
  });

  test('DDL of another tool is recorded as data; pgkiln\'s own, rolled back and opted-out DDL is not', async (t) => {
    if (!(await superuser())) return t.skip('pgkiln does not connect as a superuser here');
    if ((await triggers()).length < 2) await owner.query(`create event trigger pgkiln_change_log_ddl on ddl_command_end execute function meta.change_log_ddl();
      create event trigger pgkiln_change_log_drop on sql_drop execute function meta.change_log_drop()`);
    await psql(`create table ${S}.t (id int)`);
    // a name and a comment that look like SQL are kept as text, not run
    await psql(`create table ${S}."x'); drop table ${S}.t; --" (a int)`);
    await psql(`comment on table ${S}.t is '</pre><script>alert(1)</script>'`);
    await psql(`begin; create table ${S}.rolled_back (a int); rollback;`).catch(() => {});
    await psql(`set pgkiln.change_log = 'off'; create table ${S}.quiet (a int);`);
    await psql(`create table ${S}.spoofed (a int)`, 'pgkiln-anything');
    await owner.query(`create table ${S}.own (a int)`);
    await psql(`drop table ${S}.t`);
    const rows = await external();
    assert.deepEqual(rows.map((r) => r.name), ['create_table_t', 'create_table_x_drop_table_sec180x_t', 'comment_t', 'drop_table_t']);
    for (const r of rows) assert.equal(r.source, 'external');
    assert.equal(rows[0].author, (await owner.one('select session_user as u'))!.u);
    assert.equal(rows[1].sql, `create table ${S}."x'); drop table ${S}.t; --" (a int)`);
    assert.ok((await owner.one(`select to_regclass('${S}.quiet') as r`))!.r, 'opted-out DDL still ran');
    // the page shows the SQL escaped
    const body = (await (await admin()).get(`/builder/sql/changes?schema=${S}`)).body;
    assert.match(body, /Another tool/);
    assert.ok(!body.includes('<script>alert(1)</script>'));
    assert.match(body, /&lt;script&gt;alert\(1\)&lt;\/script&gt;/);
  });

  test('turned off from the builder: the triggers are gone and nothing more is recorded', async (t) => {
    if (!(await superuser())) return t.skip('pgkiln does not connect as a superuser here');
    if ((await triggers()).length < 2) await owner.query(`create event trigger pgkiln_change_log_ddl on ddl_command_end execute function meta.change_log_ddl();
      create event trigger pgkiln_change_log_drop on sql_drop execute function meta.change_log_drop()`);
    const a = await admin();
    assert.equal((await a.submit('/builder/sql/changes/capture', { on: '0' })).statusCode, 303);
    assert.deepEqual(await triggers(), []);
    const before = (await external()).length;
    await psql(`create table ${S}.after_off (a int)`);
    assert.equal((await external()).length, before);
  });
});

describe('sprint 181 remote catalogues for the App Gallery (WS-8)', () => {
  const DEV = 'sec181_dev';
  const PW = 'Sec181-dev-password!';
  const rows = async () => (await owner.query(`select * from meta.gallery_source where name like 'SEC181%' order by id`)).rows;
  const login = async (username: string, password: string) => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username, password });
    await b.get('/builder/gallery?tab=starters');
    return b;
  };
  let saved: string | undefined;
  before(async () => {
    saved = process.env.PGKILN_REST_ALLOWED_HOSTS;
    delete process.env.PGKILN_REST_ALLOWED_HOSTS;
    await owner.query(`delete from meta.gallery_source where name like 'SEC181%'`);
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false) on conflict do nothing`, [DEV, PW]);
  });
  after(async () => {
    if (saved !== undefined) process.env.PGKILN_REST_ALLOWED_HOSTS = saved;
    await owner.query(`delete from meta.gallery_source where name like 'SEC181%'`);
    await owner.query(`delete from meta.developer where username = $1`, [DEV]);
  });

  test('only administrators add, refresh, switch off and remove catalogues; the CSRF token is needed', async () => {
    const d = await login(DEV, PW);
    assert.doesNotMatch((await d.get('/builder/gallery?tab=starters')).body, /action="\/builder\/gallery\/sources"/, 'no form for a developer');
    assert.equal((await d.submit('/builder/gallery/sources', { name: 'SEC181 dev', url: 'https://example.com/g.json' })).statusCode, 403);
    assert.equal((await rows()).length, 0);
    const id = (await owner.one(`insert into meta.gallery_source (name, url) values ('SEC181 seeded', 'https://example.com/seed.json') returning id`))!.id;
    for (const action of ['refresh', 'toggle', 'delete'])
      assert.equal((await d.submit(`/builder/gallery/sources/${id}/${action}`, {})).statusCode, 403, action);
    const a = await login('admin', 'admin');
    assert.equal((await a.post('/builder/gallery/sources', { __csrf: 'forged', name: 'SEC181 forged', url: 'https://example.com/f.json' })).statusCode, 403);
    assert.equal((await a.post(`/builder/gallery/sources/${id}/delete`, { __csrf: 'forged' })).statusCode, 403);
    assert.equal((await rows()).length, 1);
    assert.equal((await a.submit(`/builder/gallery/sources/${id}/other`, {})).statusCode, 404);
    assert.equal((await a.submit('/builder/gallery/sources/x1/refresh', {})).statusCode, 404);
    await owner.query(`delete from meta.gallery_source where id = $1`, [id]);
  });

  test('only http(s) URLs without credentials; hosts must be on the server\'s allow-list; entries of another catalogue are not reachable', async () => {
    const a = await login('admin', 'admin');
    for (const url of ['file:///etc/passwd', 'javascript:alert(1)', 'https://user:pw@example.com/g.json', 'not a url'])
      await a.submit('/builder/gallery/sources', { name: 'SEC181 bad', url });
    assert.equal((await rows()).length, 0, 'none of them stored');
    // with no allow-list the server fetches nothing: the catalogue is kept with the reason, and lists no app
    await a.submit('/builder/gallery/sources', { name: 'SEC181 local', url: 'http://127.0.0.1:9/gallery.json' });
    const [src] = await rows();
    assert.match(src.error, /allow-list/);
    assert.deepEqual(src.catalogue, {});
    // an entry key that is not in this catalogue, or a path in the key: 404, nothing fetched
    await owner.query(`update meta.gallery_source set catalogue = $2 where id = $1`, [src.id, JSON.stringify({ starters: [{ key: 'k', title: 'K', icon: 'package', description: '', version: '', url: 'http://127.0.0.1:9/k.json' }] })]);
    const d = await login(DEV, PW);
    assert.equal((await d.submit(`/builder/gallery/remote/${src.id}/starters/other`, {})).statusCode, 404);
    assert.equal((await d.submit(`/builder/gallery/remote/${src.id}/utilities/k`, {})).statusCode, 404);
    assert.equal((await d.submit(`/builder/gallery/remote/${src.id}/starters/..%2Fk`, {})).statusCode, 404);
    // a developer may install a listed one: the fetch is refused by the allow-list, with a message
    const res = await d.submit(`/builder/gallery/remote/${src.id}/starters/k`, {});
    assert.equal(res.statusCode, 303);
    assert.match((await d.get(res.headers.location as string)).body, /could not be fetched: The host 127\.0\.0\.1:9 is not on the server&#39;s allow-list/);
  });
});

describe('sprint 183 Database Users links a role to an isolated workspace (DA-13)', async () => {
  const { ownerUrl, runtimeUrl } = await import('../src/db.ts');
  const { workspacesChanged } = await import('../src/workspace-db.ts');
  const WS = 'SEC183 Iso';
  const ROLE = 'sec183_reader';
  const POWER = 'sec183_power';
  let ws = 0;
  let plain = 0;
  const inWs = async () => (await owner.query(`select workspace_id from meta.workspace_role where role_name = $1`, [ROLE])).rows.map((r) => r.workspace_id);
  const cleanup = async () => {
    await owner.query(`delete from meta.workspace_role where role_name in ($1, $2)`, [ROLE, POWER]);
    await owner.query(`update meta.workspace set isolated = false where name = $1`, [WS]);
    await owner.query(`delete from meta.workspace where name in ($1, 'SEC183 Plain')`, [WS]);
    await owner.query(`drop role if exists ${ROLE}`);
    await owner.query(`drop role if exists ${POWER}`);
    await workspacesChanged();
  };
  const admin = async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username: 'admin', password: 'admin' });
    return b;
  };

  before(async () => {
    await cleanup();
    await owner.query(`create role ${ROLE} nologin`);
    await owner.query(`create role ${POWER} nologin bypassrls`);
    plain = (await owner.one(`insert into meta.workspace (name) values ('SEC183 Plain') returning id`))!.id;
    if (runtimeUrl === ownerUrl) return;
    ws = (await owner.one(`insert into meta.workspace (name) values ($1) returning id`, [WS]))!.id;
    const a = await admin();
    await a.get(`/builder/workspaces/${ws}`);
    assert.equal((await a.submit(`/builder/workspaces/${ws}/isolation`, { isolated: 'true' })).statusCode, 303);
  });
  after(cleanup);

  test('an administrator links a role to an isolated workspace and takes it out again; the page says where it belongs', { skip: runtimeUrl === ownerUrl && 'needs RUNTIME_DATABASE_URL' }, async () => {
    const a = await admin();
    let page = (await a.get(`/builder/db-users/role/${ROLE}`)).body;
    assert.match(page, /Isolated workspace/);
    assert.match(page, new RegExp(`<option value="${ws}">SEC183 Iso</option>`));
    assert.doesNotMatch(page, new RegExp(`<option value="${plain}">`), 'only isolated workspaces are offered');
    assert.equal((await a.submit(`/builder/db-users/role/${ROLE}/workspace`, { workspace: String(ws) })).statusCode, 303);
    assert.deepEqual(await inWs(), [ws]);
    page = (await a.get(`/builder/db-users/role/${ROLE}`)).body;
    assert.match(page, /belongs to the isolated workspace <a href="\/builder\/workspaces\/\d+">SEC183 Iso<\/a>/);
    assert.equal((await a.submit(`/builder/db-users/role/${ROLE}/workspace`, { workspace: String(ws), action: 'remove' })).statusCode, 303);
    assert.deepEqual(await inWs(), []);
  });

  test('refused: a developer who is not an administrator, no CSRF token, a workspace that is not isolated, a powerful role', async () => {
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ('sec183_dev', meta.hash_password('Sec183-dev-password!'), false) on conflict do nothing`);
    try {
      const d = new FileBrowser(app);
      await d.get('/builder/login');
      await d.post('/builder/login', { __csrf: d.lastCsrf, username: 'sec183_dev', password: 'Sec183-dev-password!' });
      await d.get('/builder/home');
      assert.equal((await d.submit(`/builder/db-users/role/${ROLE}/workspace`, { workspace: String(ws || plain) })).statusCode, 403);
    } finally {
      await owner.query(`delete from meta.developer where username = 'sec183_dev'`);
    }
    const a = await admin();
    await a.get(`/builder/db-users/role/${ROLE}`);
    assert.equal((await a.post(`/builder/db-users/role/${ROLE}/workspace`, { __csrf: 'forged', workspace: String(ws || plain) })).statusCode, 403);
    assert.equal((await a.submit(`/builder/db-users/role/${ROLE}/workspace`, { workspace: String(plain) })).statusCode, 404, 'not isolated');
    assert.equal((await a.submit(`/builder/db-users/role/${ROLE}/workspace`, { workspace: 'x' })).statusCode, 404);
    assert.equal((await a.submit(`/builder/db-users/role/no_such_role_183/workspace`, { workspace: String(ws || plain) })).statusCode, 404);
    if (ws) {
      assert.doesNotMatch((await a.get(`/builder/db-users/role/${POWER}`)).body, /Link to workspace/, 'no form for a role that bypasses RLS');
      assert.equal((await a.submit(`/builder/db-users/role/${POWER}/workspace`, { workspace: String(ws) })).statusCode, 403);
    }
    assert.deepEqual(await inWs(), []);
    assert.equal((await owner.query(`select 1 from meta.workspace_role where role_name = $1`, [POWER])).rowCount, 0);
  });
});

describe('sprint 182 the APEX importer (CD-1/CD-4 leftover)', () => {
  const ALIAS = 'sec182-apex';
  const DEV2 = 'sec182_dev';
  const DEV2_PW = 'Sec182-dev-password!';
  const EVIL = `<script>alert(1)</script>`;
  // an "export" whose PL/SQL would do harm if it ran: it is only read
  const EXPORT = `prompt APPLICATION 1 - it's harmless
create table public.sec182_pwned (id int);
begin
  execute immediate 'create table public.sec182_pwned2 (id int)';
wwv_imp_workspace.create_flow(
 p_id=>wwv_flow.g_flow_id
,p_name=>'${EVIL} app'
,p_alias=>'SEC182'
);
wwv_flow_imp_page.create_page(p_id=>1, p_name=>'<img src=x onerror=alert(2)>');
wwv_flow_imp_page.create_page_plug(p_id=>wwv_flow_imp.id(11), p_plug_name=>'${EVIL}', p_plug_source_type=>'NATIVE_JET_CHART', p_plug_source=>'</pre>${EVIL}');
wwv_flow_imp_page.create_page_process(p_id=>wwv_flow_imp.id(12), p_process_name=>'Drop', p_process_type=>'NATIVE_PLSQL',
  p_process_sql_clob=>'begin execute immediate ''create table public.sec182_pwned3 (id int)''; end;');
wwv_flow_imp_page.create_page_validation(p_id=>wwv_flow_imp.id(13), p_validation_name=>'${EVIL}', p_validation_type=>'NATIVE_${EVIL}');
end;
/
`;
  const file = (data: string | Buffer, name = 'f1.sql') => ({ file: { name, type: 'application/sql', data: Buffer.isBuffer(data) ? data : Buffer.from(data) } });
  const builder = async (user = 'admin', password = 'admin') => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.submit('/builder/login', { username: user, password })).statusCode, 303);
    await b.get('/builder/import/apex');
    return b;
  };
  const tableExists = async (t: string) => (await owner.one<{ r: string | null }>('select to_regclass($1)::text as r', [t]))!.r !== null;
  const cleanup = async () => {
    await owner.query('delete from meta.app where alias = $1', [ALIAS]);
    await owner.query('delete from meta.developer where username = $1', [DEV2]);
    await owner.query(`delete from meta.temp_file where item_name = 'APEX_IMPORT'`);
  };
  before(async () => {
    await cleanup();
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false)`, [DEV2, DEV2_PW]);
  });
  after(cleanup);

  test('developers only, with the CSRF token', async () => {
    const king = new FileBrowser(app);
    await king.login('king');
    for (const b of [new FileBrowser(app), king]) {
      assert.equal((await b.get('/builder/import/apex')).statusCode, 302);
      assert.equal((await b.upload('/builder/import/apex', {}, file(EXPORT))).statusCode, 302);
    }
    const dev = await builder();
    dev.lastCsrf = 'forged';
    assert.equal((await dev.upload('/builder/import/apex', {}, file(EXPORT))).statusCode, 403);
    const ok = await builder();
    const up = await ok.upload('/builder/import/apex', {}, file(EXPORT));
    assert.equal(up.statusCode, 303);
    const url = up.headers.location as string;
    await ok.get(url);
    assert.equal((await ok.post(url, { __csrf: 'forged', action: 'import', alias: ALIAS, schema: '' })).statusCode, 403);
    assert.ok(!(await owner.one('select 1 from meta.app where alias = $1', [ALIAS])));
    // another developer does not get this developer's file
    const other = await builder(DEV2, DEV2_PW);
    assert.equal((await other.get(url)).statusCode, 303);
    assert.equal((await other.submit(url, { action: 'import', alias: ALIAS, schema: '' })).statusCode, 303);
    assert.ok(!(await owner.one('select 1 from meta.app where alias = $1', [ALIAS])));
  });

  test('the file is never run, and its names and markup are escaped in the report', async () => {
    const dev = await builder();
    const up = await dev.upload('/builder/import/apex', {}, file(EXPORT));
    const url = up.headers.location as string;
    const rep = await dev.get(url);
    assert.equal(rep.statusCode, 200);
    assert.doesNotMatch(rep.body, /<script>alert\(1\)/);
    assert.doesNotMatch(rep.body, /<img src=x/);
    assert.match(rep.body, /&lt;script&gt;alert\(1\)&lt;\/script&gt;/);
    const done = await dev.submit(url, { action: 'import', alias: ALIAS, schema: '' });
    assert.equal(done.statusCode, 303, done.body.slice(0, 300));
    for (const t of ['public.sec182_pwned', 'public.sec182_pwned2', 'public.sec182_pwned3']) assert.equal(await tableExists(t), false, t);
    // the placeholder of an unmapped region holds its source as text
    const src = (await owner.one<{ source: string }>(`select r.source from meta.region r join meta.page p on p.id = r.page_id join meta.app a on a.id = p.app_id where a.alias = $1`, [ALIAS]))!.source;
    assert.doesNotMatch(src, /<script>/);
    assert.match(src, /&lt;\/pre&gt;&lt;script&gt;/);
    // the PL/SQL is stored as text for porting, not run
    assert.ok(await owner.one(`select 1 from meta.process x join meta.page p on p.id = x.page_id join meta.app a on a.id = p.app_id where a.alias = $1 and x.code like '%sec182_pwned3%'`, [ALIAS]));
    assert.equal(await tableExists('public.sec182_pwned3'), false);
  });

  test('size limits: the upload, a zip that unpacks to too much, a broken file', async () => {
    const dev = await builder();
    const big = await dev.upload('/builder/import/apex', {}, file(Buffer.alloc(21 * 1024 * 1024, 0x20)));
    assert.equal(big.statusCode, 422);
    assert.match(big.body, /larger than 20 MB/);
    const { zipSync } = await import('fflate');
    const bomb = Buffer.from(zipSync({ 'f1/application/a.sql': new Uint8Array(101 * 1024 * 1024) }, { level: 1 }));
    assert.ok(bomb.length < 1024 * 1024);
    const z = await dev.upload('/builder/import/apex', {}, file(bomb, 'f1.zip'));
    assert.equal(z.statusCode, 422);
    assert.match(z.body, /holds too much/);
    const broken = await dev.upload('/builder/import/apex', {}, file("begin wwv_flow_imp_page.create_page(p_name=>'not closed); end;"));
    assert.equal(broken.statusCode, 422);
    assert.match(broken.body, /not closed/);
    assert.equal((await owner.one<{ n: number }>(`select count(*)::int as n from meta.temp_file where item_name = 'APEX_IMPORT'`))!.n <= 2, true);
  });
});

describe('sprint 184 code review of 0.94.0: OAuth clients limited to REST modules', () => {
  const ALIAS = 'sec184';
  let hr = 0;
  let appId = 0;
  let clientId = '';
  let secret = '';
  let bearer = '';
  const get = (url: string, token = bearer) => app.inject({ method: 'GET', url, headers: { authorization: `Bearer ${token}` } });
  const handlers = (m: string, auth?: string) => JSON.stringify([{ method: 'GET', path: 'who', type: 'sql', ...(auth ? { auth } : {}), source: `select meta.app_user() as who, meta.has_role('manager') as manager, '${m}' as module` }]);
  const limit = (modules: string[] | null, id = clientId) => owner.query('select meta.oauth_limit_client($1, $2)', [id, modules]);
  const token = async (id = clientId, s = secret) => (await (await import('../src/oauth.ts')).clientToken(id, s)).access_token;
  /** The data API's token check the way PostgREST runs it: SET ROLE to the token's role claim, pgkiln_anon without one. */
  const dataApi = async (t: string) => {
    const { decodeJwt } = await import('jose');
    const claims = decodeJwt(t);
    const c = await owner.pool.connect();
    try {
      await c.query('begin');
      await c.query(`select set_config('request.jwt.claims', $1, true)`, [JSON.stringify(claims)]);
      await c.query(`set local role ${typeof claims.role === 'string' ? claims.role : 'pgkiln_anon'}`);
      await c.query('select meta.api_check()');
      return 'ok';
    } catch (e) {
      return (e as Error).message;
    } finally {
      await c.query('rollback').catch(() => {});
      c.release();
    }
  };

  before(async () => {
    hr = (await owner.one(`select id from meta.app where alias = 'hr'`))!.id;
    await owner.query(`delete from meta.app where alias = $1`, [ALIAS]);
    await owner.query(`delete from meta.api_client where name like 'sec184%'`);
    await owner.query(`delete from meta.rest_module where app_id = $1 and name like 'sec184%'`, [hr]);
    await owner.query(`delete from meta.rest_object where app_id = $1 and alias = 'sec184-pub'`, [hr]);
    appId = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) select $1, 'Sec 184', 'none', db_role from meta.app where alias = 'hr' returning id`, [ALIAS]))!.id;
    for (const m of ['payroll', 'other'])
      await owner.query(`insert into meta.rest_module (app_id, name, title, handlers) values ($1, $2, $2, $3)`, [appId, m, handlers(m)]);
    await owner.query(`insert into meta.rest_module (app_id, name, title, handlers) values ($1, 'open', 'open', $2)`, [appId, handlers('open', 'public')]);
    const c = (await owner.one(`select * from meta.oauth_create_client($1, 'sec184-client', '{manager}', 'sprint 184', 15)`, [ALIAS]))!;
    [clientId, secret] = [c.client_id, c.client_secret];
    bearer = await token();
  });

  after(async () => {
    await owner.query(`delete from meta.app where alias = $1`, [ALIAS]);
    await owner.query(`delete from meta.api_client where name like 'sec184%'`);
    await owner.query(`delete from meta.rest_module where app_id = $1 and name like 'sec184%'`, [hr]);
    await owner.query(`delete from meta.rest_object where app_id = $1 and alias = 'sec184-pub'`, [hr]);
  });

  test('CR-1: the limit follows a renamed module, and a deleted module is never granted again by its name', async () => {
    await limit(['payroll']);
    assert.equal((await get(`/a/${ALIAS}/rest/payroll/who`)).statusCode, 200);
    // renamed: the client keeps it under its new name
    await owner.query(`update meta.rest_module set name = 'salaries' where app_id = $1 and name = 'payroll'`, [appId]);
    assert.equal((await get(`/a/${ALIAS}/rest/salaries/who`)).statusCode, 200, 'the renamed module');
    assert.equal((await get(`/a/${ALIAS}/rest/other/who`)).statusCode, 403);
    // deleted, and a new module takes the old name (and the new one): no access nobody gave
    await owner.query(`delete from meta.rest_module where app_id = $1 and name = 'salaries'`, [appId]);
    for (const m of ['payroll', 'salaries'])
      await owner.query(`insert into meta.rest_module (app_id, name, title, handlers) values ($1, $2, $2, $3)`, [appId, m, handlers(m)]);
    for (const m of ['payroll', 'salaries', 'other']) assert.equal((await get(`/a/${ALIAS}/rest/${m}/who`)).statusCode, 403, m);
    // the client stays limited with no module left: refused everywhere, also on the data API
    assert.equal((await owner.one('select module_limit from meta.api_client where client_id = $1', [clientId]))!.module_limit, true);
    assert.match(await dataApi(bearer), /limited to REST modules/);
    await owner.query(`delete from meta.rest_module where app_id = $1 and name = 'salaries'`, [appId]);
  });

  test('CR-1: importing over the application keeps the modules of the same name, and one it drops is not granted again', async () => {
    const { replaceApp } = await import('../src/cli/replace.ts');
    await limit(['payroll']);
    const doc = (await owner.one('select meta.export_app($1) as d', [ALIAS]))!.d;
    await owner.tx((c) => replaceApp(c, doc, ALIAS, { backup: null }));
    assert.equal((await get(`/a/${ALIAS}/rest/payroll/who`)).statusCode, 200, 'the same module after the import');
    assert.equal((await get(`/a/${ALIAS}/rest/other/who`)).statusCode, 403);
    // an import without payroll, then one with it again: the client is not given it back
    const without = { ...doc, rest_modules: doc.rest_modules.filter((m: { name: string }) => m.name !== 'payroll') };
    await owner.tx((c) => replaceApp(c, without, ALIAS, { backup: null }));
    assert.equal((await get(`/a/${ALIAS}/rest/payroll/who`)).statusCode, 404);
    await owner.tx((c) => replaceApp(c, doc, ALIAS, { backup: null }));
    assert.equal((await get(`/a/${ALIAS}/rest/payroll/who`)).statusCode, 403, 'a module of the old name is not granted');
    assert.equal((await owner.one('select count(*)::int as n from meta.api_client_module l join meta.api_client c on c.id = l.client_id where c.client_id = $1', [clientId]))!.n, 0);
  });

  test('CR-1: meta.oauth_limit_client takes modules of the client\'s own application only, and is for the owner', async () => {
    await assert.rejects(limit(['payroll', 'nope']), /no REST module named nope/);
    await owner.query(`insert into meta.rest_module (app_id, name, title, handlers) values ($1, 'sec184x', 'x', '[]')`, [hr]);
    await assert.rejects(limit(['sec184x']), /no REST module named sec184x/, 'a module of another application');
    await assert.rejects(limit([]), /at least one/);
    await limit(['PAYROLL', ' payroll ']);
    assert.equal((await get(`/a/${ALIAS}/rest/payroll/who`)).statusCode, 200);
    for (const role of ['pgkiln_runtime', 'pgkiln_anon', 'hr_api', 'hr_app']) {
      const ok = await owner.one(`select has_function_privilege($1, 'meta.oauth_limit_client(text, text[])', 'execute') as x, has_table_privilege($1, 'meta.api_client_module', 'select') as y`, [role]);
      assert.deepEqual([ok!.x, ok!.y], [false, false], role);
    }
  });

  test('CR-2: a limited client gets 403 on the data API, also with a token without a role claim; cleared, its token works there', async () => {
    const { decodeJwt, SignJWT } = await import('jose');
    const { jwtSecret } = await import('../src/api.ts');
    await owner.query(`update meta.app set api_role = null where id = $1`, [appId]);
    const hc = (await owner.one(`select * from meta.oauth_create_client('hr', 'sec184-hr', '{}', 'sprint 184', 15)`))!;
    await owner.query(`insert into meta.rest_module (app_id, name, title, handlers) values ($1, 'sec184m', 'm', $2) on conflict do nothing`, [hr, handlers('sec184m')]);
    await limit(['sec184m'], hc.client_id);
    const t = await token(hc.client_id, hc.client_secret);
    assert.equal(decodeJwt(t).role, 'hr_api', 'the API role, though limited');
    assert.match(await dataApi(t), /limited to REST modules/);
    // a token as 0.94.0 issued it to a limited client: no role claim, so PostgREST runs it as pgkiln_anon
    const old = await new SignJWT({ app: 'hr', app_user: 'client:sec184-hr', client_id: hc.client_id })
      .setProtectedHeader({ alg: 'HS256', typ: 'JWT' }).setIssuedAt().setExpirationTime('15m').sign(jwtSecret());
    assert.match(await dataApi(old), /limited to REST modules/, 'refused, not anonymous');
    await limit(null, hc.client_id);
    assert.equal(await dataApi(t), 'ok', 'the limit cleared: the same token works on the data API');
    // a client of an application without an API role, not limited: anonymous on the data API, as before
    await limit(null);
    assert.equal(await dataApi(await token()), 'ok');
  });

  test('CR-3: public endpoints stay public to a limited client, which is anonymous there', async () => {
    await limit(['payroll']);
    for (const t of [undefined, bearer]) {
      const res = await app.inject({ method: 'GET', url: `/a/${ALIAS}/rest/open/who`, headers: t ? { authorization: `Bearer ${t}` } : {} });
      assert.equal(res.statusCode, 200, res.body);
      assert.match(res.body, /"who":\s*"nobody"/, 'its identity does not reach the public handler');
      assert.match(res.body, /"manager":\s*false/, 'nor its roles');
    }
    // a public AutoREST object and the AutoREST OpenAPI document
    await owner.query(`insert into meta.rest_object (app_id, schema_name, object_name, alias, methods, auth) values ($1, 'hr', 'weather_station', 'sec184-pub', '{GET}', 'public') on conflict do nothing`, [hr]);
    const pub = (await owner.one(`select alias, auth from meta.rest_object where app_id = $1 and schema_name = 'hr' and object_name = 'weather_station'`, [hr]))!;
    const hc = (await owner.one(`select * from meta.oauth_create_client('hr', 'sec184-hr2', '{}', 'sprint 184', 15)`))!;
    await owner.query(`insert into meta.rest_module (app_id, name, title, handlers) values ($1, 'sec184m', 'm', $2) on conflict do nothing`, [hr, handlers('sec184m')]);
    await limit(['sec184m'], hc.client_id);
    const ht = await token(hc.client_id, hc.client_secret);
    if (pub.auth === 'public') {
      assert.equal((await app.inject({ method: 'GET', url: `/a/hr/autorest/${pub.alias}/` })).statusCode, 200);
      assert.equal((await get(`/a/hr/autorest/${pub.alias}/`, ht)).statusCode, 200, 'a public AutoREST object');
    }
    const doc = await get('/a/hr/autorest/openapi.json', ht);
    assert.equal(doc.statusCode, 200);
    const anon = await app.inject({ method: 'GET', url: '/a/hr/autorest/openapi.json' });
    assert.deepEqual(Object.keys(JSON.parse(doc.body).paths), Object.keys(JSON.parse(anon.body).paths), 'the public objects only');
    // a token endpoint stays refused
    assert.equal((await get(`/a/${ALIAS}/rest/other/who`)).statusCode, 403);
  });

  test('CR-4, CR-5, CR-9: the builder refuses a list with unknown names (never cuts it) and logs the new limit', async () => {
    await limit(null);
    const cid = (await owner.one('select id from meta.api_client where client_id = $1', [clientId]))!.id;
    const dev = new Browser();
    await dev.get('/builder/login');
    await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' });
    assert.equal((await dev.get(`/builder/apps/${appId}/api`)).statusCode, 200);
    const url = `/builder/apps/${appId}/api/clients/${cid}/modules`;
    const limited = async () => (await owner.one(`select c.module_limit, array(select m.name from meta.api_client_module l join meta.rest_module m on m.id = l.module_id where l.client_id = c.id order by m.name) as m
                                                   from meta.api_client c where c.id = $1`, [cid]))!;
    // 60 names, the 51st+ unknown: refused as a whole and reported, not cut at 50
    const many = [...Array.from({ length: 50 }, () => 'payroll'), ...Array.from({ length: 10 }, (_, i) => `zz${i}`)].join(', ');
    assert.equal((await dev.post(url, { __csrf: dev.lastCsrf, modules: many })).statusCode, 303);
    assert.deepEqual(await limited(), { module_limit: false, m: [] });
    assert.match((await dev.get(`/builder/apps/${appId}/api`)).body, /no REST module named zz0, zz1, zz2, zz3, zz4 \(\+5\)/);
    await dev.post(url, { __csrf: dev.lastCsrf, modules: 'payroll, OTHER' });
    assert.deepEqual(await limited(), { module_limit: true, m: ['other', 'payroll'] });
    const log = async () => (await owner.one(`select detail from meta.activity_log where app_id = $1 and event = 'oauth_client' order by id desc limit 1`, [appId]))!.detail;
    assert.equal(await log(), 'modules sec184-client: other, payroll');
    await dev.post(url, { __csrf: dev.lastCsrf, modules: '' });
    assert.deepEqual(await limited(), { module_limit: false, m: [] });
    assert.equal(await log(), 'modules sec184-client: none (the whole application)');
    // a limited client whose modules were all deleted: the page says so
    await limit(['payroll']);
    await owner.query(`delete from meta.rest_module where app_id = $1 and name = 'payroll'`, [appId]);
    assert.match((await dev.get(`/builder/apps/${appId}/api`)).body, /its REST modules were deleted: it is refused everywhere/);
    await owner.query(`insert into meta.rest_module (app_id, name, title, handlers) values ($1, 'payroll', 'payroll', $2)`, [appId, handlers('payroll')]);
  });
});

describe('sprint 185 the SQL Workshop runs as the workspace\'s developer login, not the owner (NX-S1)', async () => {
  const { ownerRoleCheck, instanceChecks } = await import('../src/instance-checks.ts');
  const DEV = 'sec185_dev';
  const PW = 'Sec185-dev-password!';
  const S = 'sec185';
  const login = async (username: string, password: string) => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.post('/builder/login', { __csrf: b.lastCsrf, username, password })).statusCode, 303);
    await b.get('/builder/sql/worksheet');
    return b;
  };
  const run = async (b: FileBrowser, sql: string, extra: Record<string, string> = {}) =>
    (await b.submit('/builder/sql/worksheet', { sql, mode: 'statement', ...extra })).body;
  const devLogin = async () => (await owner.one<{ dev_role: string }>('select dev_role from meta.workspace where id = 1'))!.dev_role;
  const metaOwner = async () => (await owner.one<{ o: string }>(`select nspowner::regrole::text as o from pg_namespace where nspname = 'meta'`))!.o;
  const audit = async (username: string) => (await owner.query(`select tool, reason, statement, rows, status from meta.owner_sql_audit where username = $1 order by id`, [username])).rows;
  const cleanup = async () => {
    await owner.query(`drop schema if exists ${S} cascade`);
    await owner.query(`drop table if exists public.sec185_script, public.sec185_escape`);
    await owner.query(`delete from meta.developer where username = $1`, [DEV]);
    await owner.query(`delete from meta.owner_sql_audit where username in ($1, 'admin') and reason like 'SEC185%'`, [DEV]);
  };
  before(async () => {
    await cleanup();
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false)`, [DEV, PW]);
    await owner.query(`insert into meta.workspace_member (workspace_id, username) values (1, $1) on conflict do nothing`, [DEV]);
    await owner.query(`create schema ${S}; create table ${S}.t (a int); insert into ${S}.t values (1), (2), (3)`);
  });
  after(cleanup);

  test('the owner\'s acceptance test: a developer who isn\'t an administrator can\'t drop pgkiln\'s tables, and Run as has no Owner connection', async () => {
    const d = await login(DEV, PW);
    const page = (await d.get('/builder/sql/worksheet')).body;
    const runAs = /<select name="as_app"[\s\S]*?<\/select>/.exec(page)![0];
    assert.doesNotMatch(runAs, /value="owner"|Owner connection/);
    assert.match(runAs, /<option value="">Developer login<\/option>/);
    assert.doesNotMatch(page, /name="owner_reason"/);
    const dropped = await run(d, 'drop table meta.setting');
    assert.match(dropped, /permission denied|must be owner/);
    assert.ok(await owner.one(`select to_regclass('meta.setting') as t`).then((r) => r!.t), 'meta.setting is still there');
    for (const sql of ['delete from meta.developer', 'update meta.app set name = name', 'create role sec185_evil', 'create schema sec185_evil', 'drop schema meta cascade'])
      assert.match(await run(d, sql), /permission denied|must be owner/, sql);
    assert.equal((await owner.query(`select 1 from pg_roles where rolname = 'sec185_evil'`)).rowCount, 0);
    // who it is: the workspace's developer login, which RESET ROLE can't leave
    const who = await run(d, `reset role; select session_user::text || '/' || current_user::text as who`, { mode: 'script' });
    const login0 = await devLogin();
    assert.match(who, new RegExp(`<td>${login0}/${login0}</td>`));
    assert.match(page, /Runs as this workspace&#39;s developer login/);
    assert.match((await d.get('/builder/sql')).body, /It runs as this workspace&#39;s developer login/);
  });

  test('a developer who isn\'t an administrator can\'t choose the Owner connection by forging the form or the URL', async () => {
    const d = await login(DEV, PW);
    assert.equal((await d.submit('/builder/sql/worksheet', { sql: 'select 1', mode: 'statement', as_app: 'owner', owner_reason: 'SEC185 forged' })).statusCode, 403);
    assert.equal((await d.submit('/builder/sql/run-as', { as: 'owner', reason: 'SEC185 forged' })).statusCode, 403);
    assert.equal((await d.submit('/builder/sql/commands', { sql: 'select 1', as_app: 'owner', owner_reason: 'SEC185 forged' })).statusCode, 403);
    assert.deepEqual(await audit(DEV), []);
    assert.match(await run(d, 'select session_user::text as who'), new RegExp(`<td>${await devLogin()}</td>`));
    // an administrator's Owner connection ends when they are no longer one
    await owner.query(`update meta.developer set is_admin = true where username = $1`, [DEV]);
    const d2 = await login(DEV, PW);
    assert.equal((await d2.submit('/builder/sql/run-as', { as: 'owner', reason: 'SEC185 then demoted' })).statusCode, 303);
    assert.match(await run(d2, 'select session_user::text as who'), new RegExp(`<td>${await metaOwner()}</td>`));
    await owner.query(`update meta.developer set is_admin = false where username = $1`, [DEV]);
    assert.match(await run(d2, 'select session_user::text as who'), new RegExp(`<td>${await devLogin()}</td>`));
    await owner.query(`delete from meta.owner_sql_audit where username = $1`, [DEV]);
  });

  test('an administrator\'s Owner connection needs a reason; it and every statement go to meta.owner_sql_audit; a red chip until they go back', async () => {
    const a = await login('admin', 'admin');
    let page = (await a.get('/builder/sql/worksheet')).body;
    assert.match(page, /<option value="owner">Owner connection<\/option>/);
    assert.match(page, /name="owner_reason"/);
    // the developer login by default, for administrators too
    assert.match(await run(a, 'select session_user::text as who'), new RegExp(`<td>${await devLogin()}</td>`));
    // no reason: nothing runs
    page = await run(a, `create table ${S}.no_reason (a int)`, { as_app: 'owner', owner_reason: '  ' });
    assert.match(page, /Give a reason for the Owner connection/);
    assert.equal((await owner.one(`select to_regclass('${S}.no_reason') as t`))!.t, null);
    assert.equal((await audit('admin')).filter((r) => r.reason.startsWith('SEC185')).length, 0);
    assert.equal((await a.submit('/builder/sql/run-as', { as: 'owner', reason: 'x'.repeat(501) })).statusCode, 303);
    assert.doesNotMatch((await a.get('/builder/sql')).body, /sw-owner-chip/, 'too long a reason: not chosen');
    // with a reason
    page = await run(a, `delete from ${S}.t where a > 1`, { as_app: 'owner', owner_reason: 'SEC185 fix rows' });
    assert.match(page, /ws-runas-chip ws-runas-owner/);
    assert.equal((await owner.one(`select count(*)::int as n from ${S}.t`))!.n, 1);
    page = await run(a, `select session_user::text as who`, { as_app: 'owner' });
    assert.match(page, new RegExp(`<td>${await metaOwner()}</td>`));
    assert.match((await a.get('/builder/sql/objects')).body, /class="sw-owner-chip"[\s\S]*Owner connection: every statement is recorded/, 'a red chip on every SQL Workshop page');
    // SQL Scripts on the Owner connection: each statement recorded too
    await a.get('/builder/sql/scripts/new');
    await a.submit('/builder/sql/scripts', { name: 'SEC185 script', content: `insert into ${S}.t values (7), (8);\nselect 1;`, action: 'run' });
    let rows = (await audit('admin')).filter((r) => r.reason === 'SEC185 fix rows');
    assert.deepEqual(rows.map((r) => [r.tool, r.status, r.statement, r.rows === null ? null : Number(r.rows)]), [
      ['worksheet', 'chosen', null, null],
      ['worksheet', 'ok', `delete from ${S}.t where a > 1`, 2],
      ['worksheet', 'ok', 'select session_user::text as who', 1],
      ['scripts', 'ok', `insert into ${S}.t values (7), (8)`, 2],
      ['scripts', 'ok', 'select 1', 1],
    ]);
    // back to the developer login (the chip's button)
    await a.get('/builder/sql');
    assert.equal((await a.submit('/builder/sql/run-as', { as: 'developer' })).statusCode, 303);
    assert.doesNotMatch((await a.get('/builder/sql')).body, /sw-owner-chip/);
    assert.match(await run(a, 'select session_user::text as who'), new RegExp(`<td>${await devLogin()}</td>`));
    rows = (await audit('admin')).filter((r) => r.reason === 'SEC185 fix rows');
    assert.equal(rows.at(-1)!.status, 'ended');
    // the audit table is not for anyone else
    assert.equal((await owner.one(`select has_table_privilege('pgkiln_runtime', 'meta.owner_sql_audit', 'select') as ok`))!.ok, false);
    assert.equal((await owner.one(`select has_table_privilege($1, 'meta.owner_sql_audit', 'select') as ok`, [await devLogin()]))!.ok, false);
    await owner.query(`delete from meta.sql_script where name = 'SEC185 script'`);
  });

  test('the converted tools run as the developer login: SQL Scripts, Unload Data, Object Browser, the code editor\'s check (RESET ROLE reaches the login only)', async () => {
    const d = await login(DEV, PW);
    const dev = await devLogin();
    // SQL Scripts
    await d.get('/builder/sql/scripts/new');
    await d.submit('/builder/sql/scripts', { name: 'SEC185 dev script', content: 'create table public.sec185_script as select session_user::text as u;', action: 'run' });
    assert.equal((await owner.one(`select u from public.sec185_script`))!.u, dev);
    assert.equal((await owner.one(`select tableowner from pg_tables where tablename = 'sec185_script'`))!.tableowner, dev);
    await owner.query(`delete from meta.sql_script where name = 'SEC185 dev script'`);
    // Unload Data
    const csv = await d.submit('/builder/sql/unload', { source: 'query', query: 'select session_user::text as u', format: 'csv' });
    assert.match(csv.body, new RegExp(dev));
    // the Object Browser doesn't offer the owner's schemas the workspace's roles don't use; pgkiln's own tables
    // (shown with the system objects, as the catalogue is) give no rows
    assert.doesNotMatch((await d.get('/builder/sql/objects')).body, new RegExp(`<option value="${S}"`));
    assert.doesNotMatch((await d.get('/builder/sql/objects?schema=meta&system=1&k=table&o=meta.developer&tab=data')).body, /admin<\/td>/);
    // the code editor's check of an application's SQL: a second statement that resets the role is still the login
    const hr = (await owner.one<{ id: number }>(`select id from meta.app where alias = 'hr'`))!;
    await d.get(`/builder/apps/${hr.id}`);
    await d.submit('/builder/code/check', { app: String(hr.id), shape: 'select', sql: 'select 1) x; reset role; create table public.sec185_escape as select session_user::text as u; select (1' });
    const esc = await owner.one(`select to_regclass('public.sec185_escape') as t`);
    if (esc!.t) assert.equal((await owner.one(`select u from public.sec185_escape`))!.u, dev, 'never the owner');
    assert.equal((await owner.one(`select to_regclass('meta.sec185_escape') as t`))!.t, null);
  });

  test('a Schema Import takes the default privileges of the dump\'s own schema only', async () => {
    const { checkStatement } = await import('../src/dumpscript.ts');
    assert.equal(checkStatement('ALTER DEFAULT PRIVILEGES FOR ROLE pgkiln_ws1_dev_ab12cd34 IN SCHEMA s GRANT SELECT,INSERT ON TABLES TO s_app;', 's'), null);
    assert.match(checkStatement('ALTER DEFAULT PRIVILEGES FOR ROLE x IN SCHEMA meta GRANT ALL ON TABLES TO x;', 's')!, /outside the dump's schema/);
    assert.match(checkStatement('ALTER DEFAULT PRIVILEGES GRANT ALL ON TABLES TO x;', 's')!, /not something pg_dump writes/, 'not without a schema');
  });

  test('a lockout check warns when DATABASE_URL is a superuser', async () => {
    assert.equal(ownerRoleCheck({ name: 'pgkiln', superuser: true }).level, 'warning');
    assert.match(ownerRoleCheck({ name: 'pgkiln', superuser: true }).title, /DATABASE_URL is a superuser/);
    assert.equal(ownerRoleCheck({ name: 'pgkiln_owner', superuser: false }).level, 'ok');
    const me = (await owner.one<{ s: boolean }>(`select rolsuper as s from pg_roles where rolname = session_user`))!.s;
    const check = (await instanceChecks(null)).find((c) => c.key === 'owner_role')!;
    assert.equal(check.level, me ? 'warning' : 'ok');
    const a = await login('admin', 'admin');
    if (me) assert.match((await a.get('/builder/instance')).body, /DATABASE_URL is a superuser/);
  });
});

describe('NX-S3 a default password on a public installation changes nothing until it is changed', () => {
  const USER = 'nxs3_sec';
  before(async () => {
    await owner.query(`delete from meta.developer where username = $1`, [USER]);
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($1), true)`, [USER]);
  });
  after(async () => {
    await owner.query(`delete from meta.developer where username = $1`, [USER]);
  });

  test('every other builder request, also a POST with a valid token, goes to the password form; after the change all is open', async () => {
    const keep = process.env.PUBLIC_URL;
    process.env.PUBLIC_URL = 'http://pgkiln.example.com';
    try {
      const b = new FileBrowser(app);
      await b.get('/builder/login');
      await b.post('/builder/login', { __csrf: b.lastCsrf, username: USER, password: USER });
      await b.get('/builder/developers');
      const before = (await owner.one('select name from meta.app where id = $1', [appId]))!.name;
      const res = await b.post(`/builder/apps/${appId}/settings`, { __csrf: b.lastCsrf, name: 'changed by nxs3' });
      assert.equal(res.statusCode, 302);
      assert.equal(res.headers.location, '/builder/developers');
      assert.equal((await owner.one('select name from meta.app where id = $1', [appId]))!.name, before, 'nothing changed');
      assert.equal((await b.get('/builder/instance')).statusCode, 302);
      // the password form itself is open, and changing the password lifts it
      await b.get('/builder/developers');
      const changed = await b.post('/builder/developers/password', { __csrf: b.lastCsrf, current: USER, password: 'Nxs3-a-much-longer-passphrase!' });
      assert.equal(changed.statusCode, 303);
      assert.equal((await b.get('/builder/instance')).statusCode, 200);
    } finally {
      if (keep === undefined) delete process.env.PUBLIC_URL;
      else process.env.PUBLIC_URL = keep;
    }
  });
});

describe('sprint 186 every application runs as a database role of its own (NX-S2)', async () => {
  const { AppRoleRefused, setAppRole, rolesChanged } = await import('../src/app-role.ts');
  const { importDoc } = await import('../src/cli/apps.ts');
  const { readFileSync } = await import('node:fs');
  const S = 'sec186';
  const ROLE = 'sec186_app';
  const BYPASS = 'sec186_bypass';
  const MEMBER = 'sec186_member';
  const LEGACY = 'sec186-legacy';
  const ROLES = [ROLE, BYPASS, MEMBER, 'app_sec186_imp', 'app_sec186_legacy', 'app_sec186_apx'];
  const ALIASES = [LEGACY, 'sec186-ok', 'sec186-imp', 'sec186-bad', 'sec186-apx'];
  const DEV = 'sec186_dev';
  const PW = 'Sec186-dev-password!';
  const dropRoles = async () => {
    for (const r of ROLES)
      if ((await owner.query('select 1 from pg_roles where rolname = $1', [r])).rowCount) await owner.query(`drop owned by ${r} cascade; drop role ${r}`);
  };
  const cleanup = async () => {
    await owner.query('delete from meta.app where alias = any($1)', [ALIASES]);
    await owner.query(`drop schema if exists ${S} cascade`);
    await owner.query('drop table if exists public.sec186_rls, public.sec186_nogrant');
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`delete from meta.sql_script where name like 'SEC186%'`);
    await dropRoles();
    rolesChanged();
  };
  const builder = async (username = 'admin', password = 'admin') => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.post('/builder/login', { __csrf: b.lastCsrf, username, password })).statusCode, 303);
    return b;
  };
  /** an application made before migration 167, without a role (the trigger is off for the insert only) */
  const legacyApp = async (role: string | null = null) => owner.tx(async (c) => {
    await c.query('alter table meta.app disable trigger app_role_check');
    const id = (await c.query(`insert into meta.app (alias, name, authentication, db_role) values ($1, 'SEC186 legacy', 'none', $2) returning id`, [LEGACY, role])).rows[0].id as number;
    await c.query('set constraints all immediate'); // the deferred workspace check first: ALTER TABLE refuses pending trigger events
    await c.query('alter table meta.app enable trigger app_role_check');
    const p = (await c.query(`insert into meta.page (app_id, page_no, name, title, requires_auth) values ($1, 1, 'Home', 'Home', false) returning id`, [id])).rows[0].id;
    await c.query(`insert into meta.region (page_id, seq, title, type, source) values ($1, 10, 'Who', 'static', '<p>SEC186 page</p>')`, [p]);
    return id;
  });
  before(async () => {
    await cleanup();
    await owner.query(`create role ${ROLE} nologin; create role ${BYPASS} nologin bypassrls; create role ${MEMBER} nologin; grant ${BYPASS} to ${MEMBER}`);
    // the runtime login may SET ROLE to an application's role, as for every application of a shared workspace
    await owner.query(`grant ${ROLE} to pgkiln_runtime`);
    await owner.query(`create schema ${S}; create table ${S}.t (a int); insert into ${S}.t values (1)`);
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false)`, [DEV, PW]);
    await owner.query(`insert into meta.workspace_member (workspace_id, username) values (1, $1) on conflict do nothing`, [DEV]);
  });
  after(cleanup);

  test('meta.role_is_powerful: superusers, BYPASSRLS, pgkiln\'s and PostgreSQL\'s roles, the owner and their members', async () => {
    const p = async (r: string) => (await owner.one<{ p: boolean }>('select meta.role_is_powerful($1) as p', [r]))!.p;
    assert.equal(await p(ROLE), false);
    assert.equal(await p('hr_app'), false);
    assert.equal(await p(BYPASS), true);
    assert.equal(await p(MEMBER), true, 'a member of a BYPASSRLS role can SET ROLE to it');
    for (const r of ['pgkiln_runtime', 'pgkiln_app_code', 'pg_read_all_data', 'pg_monitor']) assert.equal(await p(r), true, r);
    const metaOwner = (await owner.one<{ o: string }>(`select nspowner::regrole::text as o from pg_namespace where nspname = 'meta'`))!.o;
    assert.equal(await p(metaOwner), true);
    assert.equal(await p('sec186_does_not_exist'), false);
  });

  test('the owner\'s acceptance test: meta.app refuses an empty role and a BYPASSRLS, superuser or pgkiln role, made or set', async () => {
    const insert = (role: string | null) => owner.query(`insert into meta.app (alias, name, db_role) values ('sec186-bad', 'Bad', $1)`, [role]);
    await assert.rejects(insert(null), (e: Error & { code?: string }) => e.code === '23502' && /needs a database role of its own/.test(e.message));
    await assert.rejects(insert('  '), /needs a database role/);
    for (const r of [BYPASS, MEMBER, 'pgkiln_runtime', (await owner.one<{ u: string }>('select current_user as u'))!.u])
      await assert.rejects(insert(r), (e: Error & { code?: string }) => e.code === '42501', r);
    const ok = (await owner.one<{ id: number }>(`insert into meta.app (alias, name, db_role) values ('sec186-ok', 'Ok', $1) returning id`, [ROLE]))!.id;
    await assert.rejects(owner.query('update meta.app set db_role = null where id = $1', [ok]), /needs a database role/);
    await assert.rejects(owner.query('update meta.app set db_role = $2 where id = $1', [ok, BYPASS]), /can't run as/);
    await owner.query('delete from meta.app where id = $1', [ok]);
  });

  test('Settings → Security refuses an empty or powerful role, also from a forged post', async () => {
    const id = (await owner.one<{ id: number }>(`insert into meta.app (alias, name, authentication, db_role) values ('sec186-ok', 'SEC186 ok', 'none', $1) returning id`, [ROLE]))!.id;
    const a = await builder();
    const page = (await a.get(`/builder/apps/${id}/settings?tab=security`)).body;
    assert.match(page, /<li>✓ Runs as a dedicated database role \(<code>sec186_app<\/code>\)<\/li>/);
    assert.doesNotMatch(page, /id="make-role"/);
    const save = async (db_role: string) => {
      await a.get(`/builder/apps/${id}/settings?tab=security`);
      await a.submit(`/builder/apps/${id}/settings`, { name: 'SEC186 ok', alias: 'sec186-ok', authentication: 'none', db_role, tab: 'security' });
      return (await a.get(`/builder/apps/${id}/settings?tab=security`)).body;
    };
    assert.match(await save(''), /An application needs a database role of its own/);
    assert.match(await save('   '), /An application needs a database role of its own/);
    assert.match(await save(BYPASS), /The role sec186_bypass can&#39;t be an application&#39;s role/);
    assert.match(await save(MEMBER), /The role sec186_member can&#39;t be an application&#39;s role/);
    assert.match(await save('pgkiln'), /can&#39;t be an application&#39;s role/);
    assert.equal((await owner.one<{ r: string }>('select db_role as r from meta.app where id = $1', [id]))!.r, ROLE);
    assert.match(await save('hr_app'), /Settings saved|saved/i);
    assert.equal((await owner.one<{ r: string }>('select db_role as r from meta.app where id = $1', [id]))!.r, 'hr_app');
    // without the form's token: refused before anything is read
    const forged = await a.post(`/builder/apps/${id}/settings`, { name: 'x', alias: 'sec186-ok', db_role: '' });
    assert.equal(forged.statusCode, 403);
    assert.equal((await owner.one<{ r: string }>('select db_role as r from meta.app where id = $1', [id]))!.r, 'hr_app');
    await owner.query('delete from meta.app where id = $1', [id]);
  });

  test('an import without a role gets app_<alias> (or keeps the installed one); a powerful role is refused; never the owner', async () => {
    const doc = (await owner.one<{ d: Record<string, any> }>(`select meta.export_app('hr') as d`))!.d;
    delete doc.app.db_role;
    // the CLI's and MCP's import (importDoc)
    const { default: pg } = await import('pg');
    const db = new pg.Client({ connectionString: process.env.DATABASE_URL });
    await db.connect();
    try {
      const r = await importDoc(db as never, structuredClone(doc) as never, { alias: 'sec186-imp', replace: false });
      assert.match(r.roleNote!, /The file has no database role: the application runs as app_sec186_imp, a role pgkiln created without rights yet/);
      assert.equal((await owner.one<{ r: string }>(`select db_role as r from meta.app where alias = 'sec186-imp'`))!.r, 'app_sec186_imp');
      assert.equal((await owner.one<{ l: boolean; m: boolean }>(`select rolcanlogin as l, pg_has_role('pgkiln_runtime', 'app_sec186_imp', 'MEMBER') as m from pg_roles where rolname = 'app_sec186_imp'`))!.m, true);
      // a replacing import without a role keeps the installed one
      const r2 = await importDoc(db as never, structuredClone(doc) as never, { alias: 'sec186-imp', replace: true });
      assert.match(r2.roleNote!, /keeps its role app_sec186_imp/);
      // a file that names a powerful role
      await assert.rejects(importDoc(db as never, { ...structuredClone(doc), app: { ...doc.app, db_role: BYPASS } } as never, { alias: 'sec186-bad', replace: false }), /can't run as sec186_bypass/);
      assert.equal((await owner.query(`select 1 from meta.app where alias = 'sec186-bad'`)).rowCount, 0);
    } finally {
      await db.end();
    }
    await owner.query(`delete from meta.app where alias = 'sec186-imp'`);
    // the builder's import
    const a = await builder();
    await a.get('/builder/import');
    await a.submit('/builder/import', { doc: JSON.stringify({ ...doc, app: { ...doc.app, db_role: BYPASS } }), alias: 'sec186-bad' });
    assert.match((await a.get('/builder')).body, /Import failed: Application sec186-bad can&#39;t run as sec186_bypass/);
    await a.get('/builder/import');
    await a.submit('/builder/import', { doc: JSON.stringify(doc), alias: 'sec186-imp' });
    assert.match((await a.get('/builder')).body, /The file has no database role: the application runs as app_sec186_imp, an existing role/);
    assert.equal((await owner.one<{ r: string }>(`select db_role as r from meta.app where alias = 'sec186-imp'`))!.r, 'app_sec186_imp');
  });

  test('an application without a role: refused at runtime outside development mode (a clear page), an Advisor error, a red checklist line', async () => {
    const id = await legacyApp();
    // an unrelated change still saves (nothing about the role)
    await owner.query(`update meta.app set name = 'SEC186 legacy app' where id = $1`, [id]);
    const user = new Browser();
    const res = await user.get(`/a/${LEGACY}/1`);
    assert.equal(res.statusCode, 503);
    assert.match(res.body, /<h1>Not available<\/h1><p>This application can&#39;t run: it has no database role of its own/);
    assert.doesNotMatch(res.body, /SEC186 page/);
    // a JSON request too
    const json = await app.inject({ method: 'GET', url: `/a/${LEGACY}/1`, headers: { accept: 'application/json', 'x-requested-with': 'fetch' } });
    assert.equal(json.statusCode, 503);
    // background work and anything else that runs the application's SQL
    await assert.rejects(appTx({ appId: id, alias: LEGACY, dbRole: null, appUser: 'nobody', sessionId: '' }, async () => 1), (e) => e instanceof AppRoleRefused && e.problem === 'missing');
    // development mode: a developer of the application, signed in to the builder in the same browser
    const a = await builder();
    await a.get('/builder');
    const dev = await a.get(`/a/${LEGACY}/1`);
    assert.equal(dev.statusCode, 200);
    assert.match(dev.body, /SEC186 page/);
    assert.equal(await appTx({ appId: id, alias: LEGACY, dbRole: null, developer: true, appUser: 'nobody', sessionId: '' },
      async (c) => (await c.query('select current_user::text as u')).rows[0].u), 'pgkiln_runtime', 'the runtime login, never the owner');
    // the Advisor and the security checklist
    const { advise } = await import('../src/builder/advisor.ts');
    const f = (await advise(id)).findings.find((x) => x.field === 'database role');
    assert.equal(f?.severity, 'error');
    assert.match(f!.message, /no database role of its own/);
    const settings = (await a.get(`/builder/apps/${id}/settings?tab=security`)).body;
    assert.match(settings, /<li class="ck-error">✗ Runs as a dedicated database role <b>No database role: the application runs only for its developers from the builder<\/b><\/li>/);
    assert.match(settings, /<form method="post" action="\/builder\/apps\/\d+\/settings\/role" id="make-role">/);
    assert.match(settings, /Create app_sec186_legacy and use it/);
    // a working copy of it is refused until it has a role
    const { createCopy } = await import('../src/workingcopy.ts');
    await assert.rejects(createCopy(id, 'SEC186 copy', 'admin'), /needs a database role/);
    // Settings → Security: make app_<alias> with rights on a schema
    await a.get(`/builder/apps/${id}/settings?tab=security`);
    await a.submit(`/builder/apps/${id}/settings/role`, { schema: S });
    assert.match((await a.get(`/builder/apps/${id}/settings?tab=security`)).body, /The application now runs as app_sec186_legacy\./);
    assert.equal((await owner.one<{ r: string }>('select db_role as r from meta.app where id = $1', [id]))!.r, 'app_sec186_legacy');
    const rights = (await owner.one<{ u: boolean; s: boolean; l: boolean }>(
      `select has_schema_privilege('app_sec186_legacy', $1, 'USAGE') as u, has_table_privilege('app_sec186_legacy', $1 || '.t', 'SELECT') as s,
              (select rolcanlogin from pg_roles where rolname = 'app_sec186_legacy') as l`, [S]))!;
    assert.deepEqual(rights, { u: true, s: true, l: false });
    rolesChanged();
    const now = await new Browser().get(`/a/${LEGACY}/1`);
    assert.equal(now.statusCode, 200, 'end users again');
    assert.match(now.body, /SEC186 page/);
    // a reserved schema is refused
    await a.get(`/builder/apps/${id}/settings?tab=security`);
    await a.submit(`/builder/apps/${id}/settings/role`, { schema: 'meta' });
    assert.match((await a.get(`/builder/apps/${id}/settings?tab=security`)).body, /The schema meta can&#39;t be an application&#39;s parsing schema|exists and application/);
    assert.equal((await owner.one<{ c: boolean }>(`select has_schema_privilege('app_sec186_legacy', 'meta', 'CREATE') as c`))!.c, false);
  });

  test('a role made powerful after it was saved: refused when the application runs, in development mode too', async () => {
    await owner.query('delete from meta.app where alias = $1', [LEGACY]);
    const id = await legacyApp(ROLE);
    rolesChanged();
    assert.equal((await new Browser().get(`/a/${LEGACY}/1`)).statusCode, 200);
    await owner.query(`alter role ${ROLE} bypassrls`);
    try {
      rolesChanged();
      const res = await new Browser().get(`/a/${LEGACY}/1`);
      assert.equal(res.statusCode, 503);
      const a = await builder();
      await a.get('/builder');
      assert.equal((await a.get(`/a/${LEGACY}/1`)).statusCode, 503, 'development mode doesn\'t run a powerful role');
      await assert.rejects(setAppRole(owner as never, ROLE, { developer: true }), (e) => e instanceof AppRoleRefused && e.problem === 'powerful');
      assert.match((await a.get(`/builder/apps/${id}/settings?tab=security`)).body, /<li class="ck-error">✗ Runs as a dedicated database role \(<code>sec186_app<\/code>\) <b>This role is too powerful/);
    } finally {
      await owner.query(`alter role ${ROLE} nobypassrls`);
      rolesChanged();
    }
  });

  test('the upgrade (migration 167 again) changes no application and grants nothing', async () => {
    await owner.query('delete from meta.app where alias = $1', [LEGACY]);
    const id = await legacyApp();
    const sql = readFileSync('db/migrations/167_app_role_required.sql', 'utf8');
    const grants = `select coalesce(string_agg(m.roleid::regrole::text || '>' || m.member::regrole::text, ',' order by 1), '') as g from pg_auth_members m`;
    const before0 = (await owner.one<{ g: string }>(grants))!.g;
    const apps0 = (await owner.query('select id, alias, db_role, updated_at from meta.app order by id')).rows;
    await owner.tx(async (c) => {
      await c.query(sql);
      assert.equal((await c.query(grants)).rows[0].g, before0, 'no membership granted');
      assert.deepEqual((await c.query('select id, alias, db_role, updated_at from meta.app order by id')).rows, apps0);
      assert.equal((await c.query('select db_role from meta.app where id = $1', [id])).rows[0].db_role, null, 'the application without a role keeps its row');
      await c.query('rollback; begin'); // nothing of the second run stays
    });
    assert.equal((await new Browser().get(`/a/${LEGACY}/1`)).statusCode, 503);
    await owner.query('delete from meta.app where id = $1', [id]);
  });
});

describe('sprint 186 a clear message when row level security refuses the developer login', async () => {
  const DEV = 'sec186_rls';
  const PW = 'Sec186-rls-password!';
  const T = 'public.sec186_rls';
  const dev = async () => (await owner.one<{ d: string }>('select dev_role as d from meta.workspace where id = 1'))!.d;
  const login = async (username: string, password: string) => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    assert.equal((await b.post('/builder/login', { __csrf: b.lastCsrf, username, password })).statusCode, 303);
    return b;
  };
  const RLS = /new row violates row-level security policy for table &quot;sec186_rls&quot;/;
  const HINT = /class="alert alert-note rls-hint"[^>]*><p class="u-m0">Row level security or the table&#39;s privileges refused this: the SQL Workshop runs as the workspace&#39;s developer login/;
  const ASK = /Only an administrator can use the Owner connection/;
  const SWITCH = /<form method="post" action="\/builder\/sql\/run-as"[^>]*>[\s\S]*?name="to" value="\/builder\/sql\/[a-z-]+"[\s\S]*?Switch to the Owner connection/;
  const cleanup = async () => {
    await owner.query(`drop table if exists ${T}, public.sec186_nogrant`);
    await owner.query('delete from meta.developer where username = $1', [DEV]);
    await owner.query(`delete from meta.sql_script where name like 'SEC186%'`);
  };
  before(async () => {
    await cleanup();
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ($1, meta.hash_password($2), false)`, [DEV, PW]);
    await owner.query(`insert into meta.workspace_member (workspace_id, username) values (1, $1) on conflict do nothing`, [DEV]);
    // a table the owner made, with row level security: the developer login may insert, no policy lets it
    await owner.query(`create table ${T} (id int primary key, note text); alter table ${T} enable row level security;
      create policy sec186_read on ${T} for select using (true); grant select, insert on ${T} to ${await dev()}`);
    await owner.query('create table public.sec186_nogrant (id int)');
  });
  after(cleanup);

  test('SQL Commands (the worksheet): PostgreSQL\'s message, then the hint; administrators can switch to the Owner connection', async () => {
    const d = await login(DEV, PW);
    await d.get('/builder/sql/worksheet');
    const body = (await d.submit('/builder/sql/worksheet', { sql: `insert into ${T} values (1, 'x')`, mode: 'statement' })).body;
    assert.match(body, RLS);
    assert.match(body, HINT);
    assert.match(body, ASK);
    assert.doesNotMatch(body, SWITCH, 'not offered to a developer who isn\'t an administrator');
    // permission denied (no grant) gives the hint too; a plain error doesn't
    assert.match((await d.submit('/builder/sql/worksheet', { sql: 'insert into public.sec186_nogrant values (1)', mode: 'statement' })).body, HINT);
    assert.doesNotMatch((await d.submit('/builder/sql/worksheet', { sql: 'select 1/0', mode: 'statement' })).body, HINT);
    const a = await login('admin', 'admin');
    await a.get('/builder/sql/worksheet');
    const ab = (await a.submit('/builder/sql/worksheet', { sql: `insert into ${T} values (1, 'x')`, mode: 'statement' })).body;
    assert.match(ab, HINT);
    assert.match(ab, SWITCH);
    // the switch needs a reason and comes back to the tool; on the Owner connection the hint isn't shown
    const sw = await a.submit('/builder/sql/run-as', { as: 'owner', reason: 'SEC186 fix rls', to: '/builder/sql/worksheet' });
    assert.equal(sw.headers.location, '/builder/sql/worksheet');
    await a.get('/builder/sql/worksheet');
    const owned = (await a.submit('/builder/sql/worksheet', { sql: `insert into ${T} values (2, 'y')`, mode: 'statement', as_app: 'owner' })).body;
    assert.doesNotMatch(owned, HINT);
    assert.equal((await owner.one<{ n: number }>(`select count(*)::int as n from ${T}`))!.n, 1);
    await a.submit('/builder/sql/run-as', { as: 'developer' });
    await owner.query(`delete from meta.owner_sql_audit where reason = 'SEC186 fix rls'`);
  });

  test('SQL Scripts, Sample Data and Load Data show the hint after the refusal', async () => {
    const d = await login(DEV, PW);
    // SQL Scripts
    await d.get('/builder/sql/scripts/new');
    const script = await d.submit('/builder/sql/scripts', { name: 'SEC186 rls script', content: `insert into ${T} values (3, 'z');`, action: 'run' });
    const shown = script.statusCode === 303 ? (await d.get(String(script.headers.location))).body : script.body;
    assert.match(shown, RLS);
    assert.match(shown, HINT);
    // Sample Data: insert into the table
    const form = (await d.get(`/builder/sql/sample-data?schema=public&t=sec186_rls`)).body;
    const f: Record<string, string | string[]> = {};
    const fo = form.slice(form.indexOf('<form method="post" action="/builder/sql/sample-data">'));
    for (const m of fo.matchAll(/<input ([^>]*)>/g)) {
      const name = /name="([^"]+)"/.exec(m[1])?.[1];
      if (!name || name === '__csrf') continue;
      const v = (/value="([^"]*)"/.exec(m[1])?.[1] ?? '').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
      f[name] = f[name] === undefined ? v : [f[name]].flat().concat(v);
    }
    for (const m of fo.matchAll(/<select name="([^"]+)"[^>]*>([\s\S]*?)<\/select>/g)) f[m[1]] = /<option value="([^"]+)" selected>/.exec(m[2])?.[1] ?? '';
    const sd = await d.submit('/builder/sql/sample-data', { ...f, action: 'insert' });
    const sdBody = sd.statusCode === 303 ? (await d.get(String(sd.headers.location))).body : sd.body;
    assert.match(sdBody, /row-level security policy|permission denied/);
    assert.match(sdBody, HINT);
    // Load Data into the existing table
    await d.get('/builder/sql/load');
    const up = await d.upload('/builder/sql/load', { headers: 'true' }, { file: { name: 'x.csv', type: 'text/csv', data: Buffer.from('id,note\n5,a\n') } });
    assert.equal(up.statusCode, 303, up.body.slice(0, 300));
    const url = String(up.headers.location).split('?')[0];
    await d.get(url);
    const ld = await d.submit(url, { h: '1', target: 'existing', table: 'sec186_rls', map_0: 'id', map_1: 'note', mode: 'append' });
    assert.match(ld.body, /row-level security policy/);
    assert.match(ld.body, HINT);
    assert.equal((await owner.one<{ n: number }>(`select count(*)::int as n from ${T}`))!.n, 1, 'nothing more was inserted');
  });
});

describe('sprint 187 issues from an APEX import (NX-F1)', () => {
  test('made in the application\'s own workspace only; component names with markup are text', async () => {
    const { apexIssues } = await import('../src/apex-issues.ts');
    const ws = (await owner.one(`insert into meta.workspace (name) values ('SEC187 Other') returning id`))!.id;
    const appRow = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('sec187-apx', 'SEC187', 'none', (select db_role from meta.app where alias = 'hr')) returning id`))!.id;
    try {
      await owner.query('insert into meta.workspace_app (app_id, workspace_id) values ($1, $2) on conflict (app_id) do update set workspace_id = excluded.workspace_id', [appRow, ws]);
      const report = { application: { id: '1', name: 'x', alias: 'sec187-apx', release: null, schema: 'x' }, skipped: {}, counts: { mapped: 0, notes: 0, not_mapped: 1, port: 0 },
        entries: [{ kind: 'region' as const, page: 3, name: '<img src=x onerror=alert(1)>', apexType: 'PLUGIN_<b>X</b>', target: null, status: 'not_mapped' as const, port: false, notes: ['<script>alert(2)</script>'] }] };
      const n = await owner.tx((c) => apexIssues(c, report, { appId: appRow, alias: 'sec187-apx', by: 'admin' }));
      assert.equal(n, 1);
      const i = (await owner.one('select workspace_id, title, body from meta.team_issue where app_id = $1', [appRow]))!;
      assert.equal(i.workspace_id, ws, 'the application\'s workspace, not the default one');
      assert.match(i.title, /<img src=x onerror=alert\(1\)>/, 'stored as text');
      // shown escaped in Team Development of that workspace
      await owner.query(`insert into meta.workspace_member (workspace_id, username) values ($1, 'admin') on conflict do nothing`, [ws]);
      const b = new FileBrowser(app);
      await b.get('/builder/login');
      await b.post('/builder/login', { __csrf: b.lastCsrf, username: 'admin', password: 'admin' });
      await b.get('/builder');
      await b.post('/builder/workspace', { __csrf: b.lastCsrf, workspace: String(ws) });
      const team = (await b.get('/builder/team')).body;
      assert.ok(!team.includes('<img src=x onerror=alert(1)>'));
      assert.match(team, /&lt;img src=x onerror=alert\(1\)&gt;/);
    } finally {
      await owner.query('delete from meta.team_issue where app_id = $1', [appRow]);
      await owner.query('delete from meta.app where id = $1', [appRow]);
      await owner.query(`delete from meta.team_label where workspace_id = $1`, [ws]);
      await owner.query('delete from meta.workspace where id = $1', [ws]);
    }
  });
});

describe('sprint 188 browser security per application (NX-S4)', () => {
  const bsUrl = async () => `/builder/apps/${(await owner.one(`select id from meta.app where alias = 'hr'`))!.id}/settings/browser`;
  const setStored = async (v: unknown) => {
    const { browserSecurityChanged } = await import('../src/browser-security.ts');
    await owner.query(`update meta.app set browser_security = $1::jsonb where alias = 'hr'`, [JSON.stringify(v)]);
    browserSecurityChanged();
  };
  const devBrowser = async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username: 'admin', password: 'admin' });
    await b.get('/builder');
    return b;
  };
  let original: unknown = {};
  before(async () => { original = (await owner.one(`select browser_security from meta.app where alias = 'hr'`))!.browser_security; });
  after(() => setStored(original));

  test('the check refuses headers pgkiln sets, line breaks and origins that are not plain https origins', async () => {
    const { check, settingsOf } = await import('../src/browser-security.ts');
    for (const headers of ['Content-Security-Policy: default-src *', 'set-cookie: a=b', 'X-Frame-Options: ALLOWALL', 'Cache-Control: public', 'Access-Control-Allow-Origin: *', 'X-Robots-Tag: all', 'Bad Name: x', 'X-A: 1\nX-A: 2'])
      assert.ok(check({ headers }).problems.length, headers);
    assert.ok(check({ headers: [{ name: 'X-Team', value: 'a\r\nSet-Cookie: x=y' }] }).problems.length, 'CRLF in a value');
    for (const o of ['http://portal.example.com', 'https://portal.example.com/path', 'https://*.example.com', 'https://user@portal.example.com', "https://x.example.com 'unsafe-inline'", 'javascript:alert(1)', '*'])
      assert.ok(check({ embed: 'origins', embed_origins: o }).problems.length, o);
    assert.ok(check({ embed: 'origins', embed_origins: '' }).problems.length, 'origins without any origin');
    assert.ok(check({ embed: 'allowall' }).problems.length);
    assert.ok(check({ referrer: 'unsafe-url' }).problems.length, 'unsafe-url is not offered');
    const ok = check({ embed: 'origins', embed_origins: 'https://Portal.example.com/\nhttps://intra.example.org:8443', referrer: 'no-referrer', robots: 'index', headers: 'X-Team: sales' });
    assert.deepEqual(ok.problems, []);
    assert.deepEqual(ok.settings.embed_origins, ['https://portal.example.com', 'https://intra.example.org:8443']);
    // a stored value the check would refuse (an import, a hand edit) is left out, never sent
    const s = settingsOf({ embed: 'origins', embed_origins: ["https://a.example.com 'unsafe-inline'"], referrer: 'unsafe-url', headers: [{ name: 'Set-Cookie', value: 'x=y' }, { name: 'X-Ok', value: 'a\nb' }] });
    assert.deepEqual(s, { embed: 'same_origin', embed_origins: [], referrer: 'same-origin', robots: 'auto', headers: [] });
  });

  test('the application\'s pages send its choices; the builder keeps the defaults', async () => {
    await setStored({ embed: 'deny', referrer: 'no-referrer', robots: 'auto', headers: [{ name: 'X-Team', value: 'sales' }] });
    let res = await (await as('demo')).get('/a/hr/1');
    assert.equal(res.headers['x-frame-options'], 'DENY');
    assert.match(String(res.headers['content-security-policy']), /frame-ancestors 'none'/);
    assert.equal(res.headers['referrer-policy'], 'no-referrer');
    assert.equal(res.headers['x-team'], 'sales');
    assert.equal(res.headers['x-robots-tag'], 'noindex, nofollow', 'auto: HR needs a sign-in');
    assert.equal(res.headers['cache-control'], 'no-store', 'pages are never cached');
    const builder = await new FileBrowser(app).get('/builder/login');
    assert.equal(builder.headers['x-frame-options'], 'SAMEORIGIN');
    assert.equal(builder.headers['referrer-policy'], 'same-origin');
    assert.equal(builder.headers['x-team'], undefined);
    assert.match(String(builder.headers['content-security-policy']), /frame-ancestors 'self'/);

    await setStored({ embed: 'origins', embed_origins: ['https://portal.example.com'], robots: 'index' });
    res = await (await as('demo')).get('/a/hr/1');
    assert.equal(res.headers['x-frame-options'], undefined, 'X-Frame-Options cannot list origins');
    assert.match(String(res.headers['content-security-policy']), /frame-ancestors 'self' https:\/\/portal\.example\.com;/);
    assert.equal(res.headers['x-robots-tag'], undefined);
  });

  test('stored values the server must not send are left out (an import or a hand edit)', async () => {
    await setStored({ embed: 'origins', embed_origins: ["https://a.example.com; script-src *"], referrer: 'unsafe-url',
      headers: [{ name: 'Content-Security-Policy', value: 'default-src *' }, { name: 'Set-Cookie', value: 'pgkiln_sid=x' }, { name: 'X-Inject', value: 'a\r\nSet-Cookie: x=y' }] });
    const res = await (await as('demo')).get('/a/hr/1');
    assert.equal(res.headers['x-frame-options'], 'SAMEORIGIN');
    assert.match(String(res.headers['content-security-policy']), /script-src 'self'/);
    assert.doesNotMatch(String(res.headers['content-security-policy']), /a\.example\.com|default-src \*/);
    assert.equal(res.headers['referrer-policy'], 'same-origin');
    assert.equal(res.headers['x-inject'], undefined);
    assert.ok(![res.headers['set-cookie']].flat().some((c) => /pgkiln_sid=x|^x=y/.test(String(c))));
    // the Advisor says so
    const { advise } = await import('../src/builder/advisor.ts');
    const hrId = (await owner.one(`select id from meta.app where alias = 'hr'`))!.id;
    const { findings } = await advise(hrId);
    assert.ok(findings.some((f: { field?: string }) => f.field === 'browser security'));
  });

  test('a background prefetch without a session starts none (it would replace the sign-in page\'s cookie)', async () => {
    const res = await app.inject({ method: 'GET', url: '/a/hr/1', headers: { 'x-pgkiln-prefetch': '1' } });
    assert.equal(res.statusCode, 401);
    assert.equal(res.headers['set-cookie'], undefined, 'no session cookie');
    // with a session it is served as before
    const king = await as('king');
    const ok = await king.request('GET', '/a/hr/1');
    assert.equal(ok.statusCode, 200);
  });

  test('the builder form refuses what the server would not send, and needs a developer and the CSRF token', async () => {
    await setStored({});
    const url = await bsUrl();
    const dev = await devBrowser();
    await dev.get(url.replace('/browser', '?tab=security'));
    const stored = async () => (await owner.one(`select browser_security from meta.app where alias = 'hr'`))!.browser_security;
    await dev.post(url, { __csrf: dev.lastCsrf, embed: 'same_origin', referrer: 'same-origin', robots: 'auto', headers: 'Set-Cookie: pgkiln_sid=x', embed_origins: '' });
    assert.deepEqual(await stored(), {}, 'a reserved header is refused');
    await dev.post(url, { __csrf: dev.lastCsrf, embed: 'origins', referrer: 'same-origin', robots: 'auto', headers: '', embed_origins: "https://a.example.com 'unsafe-inline'" });
    assert.deepEqual(await stored(), {}, 'a CSP source that is not an origin is refused');
    await dev.post(url, { embed: 'deny', referrer: 'same-origin', robots: 'auto', headers: '', embed_origins: '' });
    assert.deepEqual(await stored(), {}, 'without the CSRF token');
    const anon = new FileBrowser(app);
    await anon.post(url, { embed: 'deny', referrer: 'same-origin', robots: 'auto', headers: '', embed_origins: '' });
    assert.deepEqual(await stored(), {}, 'not signed in');
    await dev.get(url.replace('/browser', '?tab=security'));
    await dev.post(url, { __csrf: dev.lastCsrf, embed: 'deny', referrer: 'strict-origin', robots: 'noindex', headers: 'X-Team: sales', embed_origins: '' });
    assert.deepEqual(await stored(), { embed: 'deny', embed_origins: [], referrer: 'strict-origin', robots: 'noindex', headers: [{ name: 'X-Team', value: 'sales' }] });
    // the checklist shows the headers the pages send, escaped
    const page = (await dev.get(url.replace('/browser', '?tab=security'))).body;
    assert.match(page, /X-Frame-Options: DENY/);
    assert.match(page, /X-Team: sales/);
  });
});

describe('sprint 189 session limits, deep linking and expiring bookmarks per application (NX-S5)', () => {
  let saved: Record<string, unknown>;
  const COLS = 'session_idle_minutes, session_max_hours, session_timeout_page, deep_linking';
  before(async () => { saved = (await owner.one(`select ${COLS} from meta.app where alias = 'hr'`))!; });
  const restore = () => owner.query(`update meta.app set session_idle_minutes = $1, session_max_hours = $2, session_timeout_page = $3, deep_linking = $4 where alias = 'hr'`,
    [saved.session_idle_minutes, saved.session_max_hours, saved.session_timeout_page, saved.deep_linking]);
  // every test puts HR back, also when it fails: later tests (and files) depend on deep linking and the limits
  afterEach(restore);
  after(restore);
  const age = (user: string, col: 'last_seen' | 'created_at', minutes: number) =>
    owner.query(`update meta.session set ${col} = now() - make_interval(mins => $3) where app_id = $1 and username = $2`, [appId, user, minutes]);
  const devBrowser = async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    await b.post('/builder/login', { __csrf: b.lastCsrf, username: 'admin', password: 'admin' });
    await b.get('/builder');
    return b;
  };

  test('an application\'s idle time and maximum length end its sessions, never later than the instance\'s', async () => {
    await owner.query(`update meta.app set session_idle_minutes = 5, session_max_hours = null, session_timeout_page = null where alias = 'hr'`);
    let allen = await as('allen');
    await age('allen', 'last_seen', 10);
    let res = await allen.get('/a/hr/1');
    assert.equal(res.statusCode, 302);
    assert.match(String(res.headers.location), /^\/a\/hr\/login/, 'idle 10 minutes > the application\'s 5');
    // longer than the instance's (60 minutes by default): the instance's still applies
    await owner.query(`update meta.app set session_idle_minutes = 1440 where alias = 'hr'`);
    allen = await as('allen');
    await age('allen', 'last_seen', 24 * 60 - 5);
    assert.match(String((await allen.get('/a/hr/1')).headers.location), /^\/a\/hr\/login/);
    // the maximum length
    await owner.query(`update meta.app set session_idle_minutes = null, session_max_hours = 1 where alias = 'hr'`);
    allen = await as('allen');
    await age('allen', 'created_at', 90);
    assert.match(String((await allen.get('/a/hr/1')).headers.location), /^\/a\/hr\/login/);
    allen = await as('allen');
    assert.equal((await allen.get('/a/hr/1')).statusCode, 200);
  });

  test('a session that has ended opens the timeout page, which must be a page without sign-in', async () => {
    const pid = (await owner.one(`insert into meta.page (app_id, page_no, name, title, requires_auth) values ($1, 9189, 'Ended', 'Ended', false) returning id`, [appId]))!.id;
    try {
      await owner.query(`update meta.app set session_idle_minutes = 5, session_timeout_page = 9189 where alias = 'hr'`);
      const allen = await as('allen');
      await age('allen', 'last_seen', 10);
      const res = await allen.get('/a/hr/3');
      assert.equal(res.headers.location, '/a/hr/9189');
      assert.equal((await allen.get('/a/hr/9189')).statusCode, 200);
      // once: the next request is an ordinary visit without a session
      assert.match(String((await allen.get('/a/hr/3')).headers.location), /^\/a\/hr\/login/);
      // a first visit (no cookie) goes to the sign-in page, not the timeout page
      assert.match(String((await new Browser().get('/a/hr/3')).headers.location), /^\/a\/hr\/login/);
      // the builder refuses a page that needs a sign-in
      const dev = await devBrowser();
      await dev.get(`/builder/apps/${appId}/settings?tab=errors`);
      await dev.post(`/builder/apps/${appId}/settings/behaviour`, { __csrf: dev.lastCsrf, session_settings: '1', session_warning_seconds: '120', session_timeout_page: '1', deep_linking: 'true' });
      assert.equal((await owner.one(`select session_timeout_page from meta.app where id = $1`, [appId]))!.session_timeout_page, 9189, 'page 1 needs a sign-in: refused');
      await dev.post(`/builder/apps/${appId}/settings/behaviour`, { __csrf: dev.lastCsrf, session_settings: '1', session_warning_seconds: '120', session_idle_minutes: '0', deep_linking: 'true' });
      assert.equal((await owner.one(`select session_idle_minutes from meta.app where id = $1`, [appId]))!.session_idle_minutes, 5, '0 minutes: refused');
    } finally {
      await owner.query(`update meta.app set session_timeout_page = null where alias = 'hr'`);
      await owner.query('delete from meta.page where id = $1', [pid]);
    }
  });

  test('a post of the form without the session fields (an older client) leaves them alone', async () => {
    await owner.query(`update meta.app set session_idle_minutes = 7, deep_linking = true where alias = 'hr'`);
    const dev = await devBrowser();
    await dev.get(`/builder/apps/${appId}/settings?tab=errors`);
    await dev.post(`/builder/apps/${appId}/settings/behaviour`, { __csrf: dev.lastCsrf, session_warning_seconds: '90' });
    const row = (await owner.one(`select session_warning_seconds, session_idle_minutes, deep_linking from meta.app where id = $1`, [appId]))!;
    assert.deepEqual(row, { session_warning_seconds: 90, session_idle_minutes: 7, deep_linking: true });
    await owner.query(`update meta.app set session_warning_seconds = 120 where id = $1`, [appId]);
  });

  test('deep linking off: the sign-in page gets no address, and a posted one is ignored', async () => {
    await owner.query(`update meta.app set session_idle_minutes = null, session_max_hours = null, deep_linking = false where alias = 'hr'`);
    const b = new Browser();
    assert.equal((await b.get('/a/hr/8')).headers.location, '/a/hr/login');
    await b.get('/a/hr/login?next=/a/hr/8');
    const res = await b.post('/a/hr/login', { __csrf: b.lastCsrf, username: 'allen', password: 'allen', next: '/a/hr/8' });
    assert.equal(res.statusCode, 303);
    const home = (await owner.one(`select home_page from meta.app where alias = 'hr'`))!.home_page;
    assert.equal(res.headers.location, `/a/hr/${home}`);
    await owner.query(`update meta.app set deep_linking = true where alias = 'hr'`);
    assert.match(String((await new Browser().get('/a/hr/8')).headers.location), /next=%2Fa%2Fhr%2F8/);
  });

  test('Expire bookmarks: links made before fail with "expired", new ones work, SQL and the server agree', async () => {
    const before = link('king', 3, { P3_EMPNO: '7839' });
    const king = await as('king');
    assert.equal((await king.get(before)).statusCode, 200);
    const dev = await devBrowser();
    await dev.get(`/builder/apps/${appId}/settings?tab=errors`);
    const epoch0 = (await owner.one('select url_epoch from meta.app where id = $1', [appId]))!.url_epoch;
    // a developer with the CSRF token only
    await dev.post(`/builder/apps/${appId}/settings/expire-bookmarks`, {});
    await new FileBrowser(app).post(`/builder/apps/${appId}/settings/expire-bookmarks`, {});
    assert.equal((await owner.one('select url_epoch from meta.app where id = $1', [appId]))!.url_epoch, epoch0, 'without the token, or signed out: nothing');
    await dev.post(`/builder/apps/${appId}/settings/expire-bookmarks`, { __csrf: dev.lastCsrf });
    assert.equal((await owner.one('select url_epoch from meta.app where id = $1', [appId]))!.url_epoch, epoch0 + 1);
    const old = await king.get(before);
    assert.equal(old.statusCode, 403);
    assert.match(old.body, /This link has expired/);
    // a tampered link is still a checksum error, not "expired"
    const forged = await king.get(before.replace('7839', '7934'));
    assert.equal(forged.statusCode, 403);
    assert.match(forged.body, /checksum error/);
    // links made now (the server remembered the new epoch on the page request above) work, and SQL makes the same
    const fresh = link('king', 3, { P3_EMPNO: '7839' });
    assert.notEqual(fresh, before);
    assert.equal((await king.get(fresh)).statusCode, 200);
    const sql = (await owner.one(`select meta.url_checksum($1, 3, 'king', '{"P3_EMPNO": "7839"}') as cs`, [appId]))!.cs;
    assert.equal(new URL(fresh, 'http://x').searchParams.get('cs'), sql);
    // the settings page says when
    assert.match((await dev.get(`/builder/apps/${appId}/settings?tab=errors`)).body, /Last expired: \d{4}-\d\d-\d\d \d\d:\d\d UTC/);
  });
});

// (sprint 193, NX-F3) page aliases: /a/<app>/<alias> opens a page as its number does, through the same checks
describe('page aliases (sprint 193)', () => {
  test('an alias is checked as its page number: sign-in, authorization schemes, checksums', async () => {
    const aliasOf = async (n: number) => (await owner.one<{ alias: string }>('select alias from meta.page where app_id = $1 and page_no = $2', [appId, n]))!.alias;
    const [employees, form, audit] = [await aliasOf(2), await aliasOf(3), await aliasOf(9)];
    // signed out: the sign-in page, as for the number
    const anon = await new Browser().get(`/a/hr/${employees}`);
    assert.equal(anon.statusCode, 302);
    assert.match(String(anon.headers.location), /^\/a\/hr\/login\?next=/);
    const allen = await as('allen');
    assert.equal((await allen.get(`/a/hr/${employees}`)).statusCode, 200);
    assert.equal((await allen.get(`/a/hr/${form}`)).statusCode, 403, 'the employee form needs MANAGER under its alias too');
    assert.equal((await allen.get(`/a/hr/${audit}`)).statusCode, 403, 'the audit trail needs ADMIN under its alias too');
    // a link with item values signed for page 3 works under the alias (checksums are made with the page number)
    const blake = await as('blake');
    const signed = link('blake', 3, { P3_EMPNO: '7499' });
    const byAlias = signed.replace('/a/hr/3?', `/a/hr/${form}?`);
    const ok = await blake.get(byAlias);
    assert.equal(ok.statusCode, 200);
    assert.match(ok.body, /value="7499"/);
    // tampered: a checksum error, as for the number
    const forged = await blake.get(byAlias.replace('7499', '7521'));
    assert.equal(forged.statusCode, 403);
    assert.match(forged.body, /checksum error/);
    // a link signed for another page: what its number gives
    assert.equal((await blake.get(signed.replace('/a/hr/3?', `/a/hr/${employees}?`))).statusCode, (await blake.get(signed.replace('/a/hr/3?', '/a/hr/2?'))).statusCode);
  });

  test("an alias only reaches its own application's pages; reserved words, odd and injected paths are 404 or the runtime's own", async () => {
    await owner.query(`delete from meta.app where alias = 's193-other'`);
    const other = (await owner.one(`insert into meta.app (alias, name, authentication, db_role) values ('s193-other', 'S193 other', 'none', 'hr_app') returning id`))!.id;
    try {
      await owner.query(`insert into meta.page (app_id, page_no, name, alias) values ($1, 1, 'Secret', 's193-secret')`, [other]);
      const king = await as('king');
      assert.equal((await king.get('/a/hr/s193-secret')).statusCode, 404, "another application's alias");
      assert.equal((await new Browser().get('/a/s193-other/s193-secret')).statusCode, 200, 'in its own application it opens');
      // reserved words never become an alias (the database refuses them; the runtime's routes keep theirs)
      await assert.rejects(owner.query(`update meta.page set alias = 'login' where app_id = $1`, [other]), /page_alias_check/);
      await assert.rejects(owner.query(`update meta.page set alias = '42' where app_id = $1`, [other]), /page_alias_check/);
      await assert.rejects(owner.query(`update meta.page set alias = 'a b' where app_id = $1`, [other]), /page_alias_check/);
      assert.equal((await owner.one(`insert into meta.page (app_id, page_no, name) values ($1, 2, 'Login') returning alias`, [other]))!.alias, 'login-page');
      assert.match((await new Browser().get('/a/hr/login')).body, /<form method="post" action="\/a\/hr\/login"/, '/login stays the sign-in page');
      for (const path of [`/a/hr/employees'%20or%20'1'='1`, '/a/hr/employees%00', '/a/hr/EMPLOYEES', '/a/hr/employees-', '/a/hr/-1', '/a/hr/0',
        '/a/hr/..%2Fs193-other%2Fs193-secret', `/a/hr/${'x'.repeat(65)}`, '/a/hr/%E2%80%AEemployees', '/a/hr/1e1', '/a/hr/0x2'])
        assert.equal((await king.get(path)).statusCode, 404, path);
      // the 404 page escapes what was asked for
      const res = await king.get('/a/hr/%3Cscript%3Ex');
      assert.equal(res.statusCode, 404);
      assert.doesNotMatch(res.body, /<script>x/);
    } finally {
      await owner.query('delete from meta.app where id = $1', [other]);
    }
  });

  test('the Page Designer refuses an alias that is malformed, numeric, reserved or taken, and needs the CSRF token', async () => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    await b.submit('/builder/login', { username: 'admin', password: 'admin' });
    const page = (await owner.one<{ id: number; alias: string; name: string; page_no: number }>('select id, alias, name, page_no from meta.page where app_id = $1 and page_no = 6', [appId]))!;
    const follow = async (url: string) => {
      let res = await b.get(url);
      for (let i = 0; i < 5 && res.statusCode >= 300 && res.statusCode < 400; i++) res = await b.get(String(res.headers.location));
      return res;
    };
    const form = async () => {
      const body = (await follow(`/builder/pages/${page.id}?c=page`)).body;
      const markup = new RegExp(`<form method="post" action="/builder/pages/${page.id}" class="component-form"[\\s\\S]*?</form>`).exec(body)?.[0];
      assert.ok(markup, 'the page form');
      return pageFormFields(markup);
    };
    try {
      for (const [alias, message] of [['Bad alias!', /only lower case letters/], ['1234', /not only digits/], ['rest', /a path the runtime uses itself/],
        ['employees', /already another page/], ['x'.repeat(70), /1 to 64 characters/]] as [string, RegExp][]) {
        const res = await b.submit(`/builder/pages/${page.id}`, { ...(await form()), page_alias: alias });
        assert.equal(res.statusCode, 303);
        assert.match((await follow(String(res.headers.location))).body, message, alias);
        assert.equal((await owner.one('select alias from meta.page where id = $1', [page.id]))!.alias, page.alias, `${alias}: unchanged`);
      }
      // without the token: refused
      const fields = await form();
      delete fields.__csrf;
      assert.equal((await b.post(`/builder/pages/${page.id}`, { ...fields, page_alias: 'no-token' })).statusCode, 403);
      // upper case and spaces around are made lower case; empty takes one from the name
      await b.submit(`/builder/pages/${page.id}`, { ...(await form()), page_alias: '  Time-Off ' });
      assert.equal((await owner.one('select alias from meta.page where id = $1', [page.id]))!.alias, 'time-off');
      await b.submit(`/builder/pages/${page.id}`, { ...(await form()), page_alias: '' });
      assert.equal((await owner.one('select alias from meta.page where id = $1', [page.id]))!.alias, page.alias);
    } finally {
      await owner.query('update meta.page set alias = $2 where id = $1', [page.id, page.alias]);
    }
  });

  test("the Pages report's column chooser: signed in, the CSRF token, known columns only, only the report's own query string back", async () => {
    const dev = new Browser();
    await dev.get('/builder/login');
    assert.equal((await dev.post('/builder/login', { __csrf: dev.lastCsrf, username: 'admin', password: 'admin' })).statusCode, 303);
    await dev.get(`/builder/apps/${appId}`);
    const cols = async () => (await owner.one<{ page_columns: string[] | null }>(`select page_columns from meta.developer where username = 'admin'`))!.page_columns;
    try {
      await owner.query(`update meta.developer set page_columns = null where username = 'admin'`);
      // signed out, or without the token: nothing changes
      const anon = await new Browser().post('/builder/page-columns', { app: String(appId), col: 'regions' });
      assert.ok([302, 303, 403].includes(anon.statusCode), String(anon.statusCode));
      assert.equal((await dev.post('/builder/page-columns', { app: String(appId), col: 'regions' })).statusCode, 403);
      assert.equal(await cols(), null);
      // unknown or injected column names are dropped; the stored list is the report's own names in their order
      await dev.get(`/builder/apps/${appId}`);
      const res = await dev.post('/builder/page-columns', { __csrf: dev.lastCsrf, app: String(appId), col: ['items', "x'); drop table meta.page; --", 'regions', '<script>', 'alias'],
        back: 'https://evil.example/' });
      assert.equal(res.statusCode, 303);
      assert.equal(res.headers.location, `/builder/apps/${appId}`, 'never another URL');
      assert.deepEqual(await cols(), ['alias', 'regions', 'items']);
      for (const back of ['//evil.example', '?a=1#x', '?q=<b>', '/\\evil.example', '?x=1\r\nSet-Cookie:a=b']) {
        await dev.get(`/builder/apps/${appId}`);
        const r = await dev.post('/builder/page-columns', { __csrf: dev.lastCsrf, app: String(appId), col: 'alias', back });
        assert.equal(r.headers.location, `/builder/apps/${appId}`, back);
      }
      await dev.get(`/builder/apps/${appId}`);
      const notApp = await dev.post('/builder/page-columns', { __csrf: dev.lastCsrf, app: 'x/../../evil', col: 'alias', back: '?sort=page' });
      assert.equal(notApp.headers.location, '/builder/apps');
      // the database refuses anything but column names too
      await assert.rejects(owner.query(`update meta.developer set page_columns = array['bad name'] where username = 'admin'`), /check/);
      // the filters' values are escaped where the report shows them back
      const body = (await dev.get(`/builder/apps/${appId}?type=%22%3E%3Cscript%3Ex&by=%3Cb%3Ey&group=%3Cimg%3E&q=%3Cb%3Ez`)).body;
      assert.doesNotMatch(body, /<script>x|<b>y|<img>|<b>z/);
    } finally {
      await owner.query(`update meta.developer set page_columns = null where username = 'admin'`);
    }
  });
});

describe('sprint 194 builder tokens for the command line and the MCP server (NX-F4, SEC-1)', () => {
  const DEV = 'sec194_dev';
  const SSO = 'sec194_sso';
  const MFA = 'sec194_mfa';
  const PW = 'Sec194-password!';
  const OTHER_APP = 'hr-sec194-ws';
  const WS = 'sec194 other ws';
  const SSO_WS = 'sec194 sso ws';
  const IP = '10.194.0.7';
  let wsId = 0;
  let tok: typeof import('../src/builder-tokens.ts');
  const api = (t: string | null, method: 'GET' | 'POST', path: string, body?: unknown, headers: Record<string, string> = {}, remoteAddress?: string) =>
    app.inject({ method, url: `/builder/api/v1/${path}`, headers: { ...(t ? { authorization: `Bearer ${t}` } : {}), ...headers }, ...(remoteAddress ? { remoteAddress } : {}), ...(body === undefined ? {} : { payload: body as object }) });
  const make = async (scopes: ('read' | 'write' | 'sql')[], username = DEV, workspaceId = 1) =>
    (await tok.createToken({ username, workspaceId, name: `sec ${Math.random().toString(36).slice(2, 9)}`, scopes, days: 30 })).token;
  const signIn = async (user: string) => {
    const b = new FileBrowser(app);
    await b.get('/builder/login');
    const r = await b.submit('/builder/login', { username: user, password: PW });
    assert.equal(r.statusCode, 303, `sign-in of ${user}`);
    return b;
  };
  /** the session's sign-in, minutes ago */
  const age = (user: string, minutes: number) =>
    owner.query(`update meta.session set state = jsonb_set(state, '{__AUTH}', to_jsonb(jsonb_set((state->>'__AUTH')::jsonb, '{at}', to_jsonb((extract(epoch from now()) * 1000)::bigint - $2::bigint * 60000))::text))
                  where app_id is null and username = $1 and state ? '__AUTH'`, [user, minutes]);
  const cleanup = async () => {
    await owner.query('delete from meta.session where app_id is null and username = any($1)', [[DEV, SSO, MFA]]);
    await owner.query('delete from meta.app where alias = $1', [OTHER_APP]);
    await owner.query('delete from meta.developer where username = any($1)', [[DEV, SSO, MFA]]);
    await owner.query('delete from meta.workspace where name = any($1)', [[WS, SSO_WS]]);
    await owner.query(`delete from meta.activity_log where app_id is null and event in ('login_failed', 'login_locked') and (ip = $1 or detail like 'builder API:%' or detail like 'builder token step-up%')`, [IP]);
  };
  before(async () => {
    tok = await import('../src/builder-tokens.ts');
    await cleanup();
    await owner.query('insert into meta.developer (username, password_hash, is_admin) select u, meta.hash_password($2), false from unnest($1::text[]) u', [[DEV, SSO, MFA], PW]);
    wsId = (await owner.one<{ id: number }>('insert into meta.workspace (name) values ($1) returning id', [WS]))!.id;
    // an application of another workspace
    const doc = (await owner.one(`select meta.export_app('hr') as d`))!.d;
    const id = (await owner.one<{ id: number }>('select meta.import_app($1::jsonb, $2) as id', [JSON.stringify(doc), OTHER_APP]))!.id;
    await owner.query('insert into meta.workspace_app (app_id, workspace_id) values ($1, $2) on conflict (app_id) do update set workspace_id = excluded.workspace_id', [id, wsId]);
  });
  after(cleanup);

  test('only a hash is stored; the token is a 256-bit random string', async () => {
    const { hashToken } = await import('../src/security.ts');
    const t = await make(['read']);
    assert.match(t, /^pgkb_[A-Za-z0-9_-]{43}$/);
    assert.equal((await owner.one('select count(*)::int as n from meta.builder_token where token_hash = $1', [hashToken(t)]))!.n, 1);
    const cols = (await owner.query(`select string_agg(t::text, '') as all from meta.builder_token t`)).rows[0].all;
    assert.ok(!cols.includes(t.slice(5)), 'the token itself is nowhere in the table');
    // the runtime role and workspace logins can't read the table
    assert.equal((await owner.one(`select has_table_privilege('pgkiln_runtime', 'meta.builder_token', 'SELECT') as ok`))!.ok, false);
    const dev = (await owner.one<{ r: string }>('select dev_role as r from meta.workspace where id = 1'))!.r;
    assert.equal((await owner.one(`select has_table_privilege($1, 'meta.builder_token', 'SELECT') as ok`, [dev]))!.ok, false);
  });

  test('the Authorization header only: no cookie, no query string, no other scheme; no CSRF token needed', async () => {
    const t = await make(['read']);
    const b = await signIn(DEV);
    const cookie = [...b.cookies].map(([k, v]) => `${k}=${v}`).join('; ');
    assert.equal((await api(null, 'GET', 'me', undefined, { cookie })).statusCode, 401, 'a signed-in browser is not a caller');
    assert.equal((await api(null, 'GET', `me?token=${t}`)).statusCode, 401);
    assert.equal((await api(null, 'GET', 'me', undefined, { authorization: `Basic ${Buffer.from(`x:${t}`).toString('base64')}` })).statusCode, 401);
    const r = await api(null, 'GET', 'me', undefined, { authorization: `Bearer ${t}` });
    assert.equal(r.statusCode, 200);
    assert.equal(r.headers['set-cookie'], undefined, 'no session is made');
    assert.equal(r.headers['access-control-allow-origin'], undefined, 'no CORS: a web page can\'t send the header');
    // a POST with the token and no CSRF field works (bearer requests aren't a browser's)
    assert.equal((await api(t, 'POST', 'tools/list_apps', {})).statusCode, 200);
    assert.match(String((await api(null, 'GET', 'me')).headers['www-authenticate']), /^Bearer/);
  });

  test('scopes: a read token can\'t write or run SQL; a 403 names the scope', async () => {
    const t = await make(['read']);
    const doc = (await api(t, 'GET', 'apps/hr/export')).json().doc;
    for (const [path, body] of [['apps/hr/import', { doc, replace: true }], ['advise', { doc }], ['tools/run_query', { sql: 'select 1' }], ['tools/lock_app', { alias: 'hr' }],
      ['tools/working_copy', { action: 'create', alias: 'hr', name: 'x' }]] as const) {
      const r = await api(t, 'POST', path, body);
      assert.equal(r.statusCode, 403, path);
      assert.match(r.json().error, /no (write|sql) scope/, path);
    }
    const w = await make(['write']);
    assert.equal((await api(w, 'POST', 'tools/list_apps', {})).statusCode, 403, 'write alone is not read');
  });

  test('expired and revoked tokens are refused at once (no cache that outlives a revoke)', async () => {
    const t = await make(['read']);
    assert.equal((await api(t, 'GET', 'me')).statusCode, 200);
    await owner.query(`update meta.builder_token set created_at = now() - interval '2 days', expires_at = now() - interval '1 second' where token_hash = encode(sha256($1::bytea), 'hex')`, [t]);
    const exp = await api(t, 'GET', 'me');
    assert.equal(exp.statusCode, 401);
    assert.match(exp.json().error, /expired/);
    const t2 = await make(['read']);
    assert.equal((await api(t2, 'POST', 'tools/list_apps', {})).statusCode, 200);
    await owner.query(`update meta.builder_token set revoked_at = now() where token_hash = encode(sha256($1::bytea), 'hex')`, [t2]);
    assert.equal((await api(t2, 'POST', 'tools/list_apps', {})).statusCode, 401);
  });

  test('a token never grants more than its developer has now: removed from the workspace, removed, held to set up two-factor sign-in', async () => {
    const t = await make(['read']);
    await owner.query('delete from meta.workspace_member where workspace_id = 1 and username = $1', [DEV]);
    try {
      const r = await api(t, 'GET', 'me');
      assert.equal(r.statusCode, 403);
      assert.match(r.json().error, /no longer a developer of workspace Default/);
    } finally {
      await owner.query('insert into meta.workspace_member (workspace_id, username) values (1, $1) on conflict do nothing', [DEV]);
    }
    assert.equal((await api(t, 'GET', 'me')).statusCode, 200);
    // a workspace requires a second factor and the grace period is over
    await owner.query(`update meta.workspace set mfa_required_since = now() - interval '60 days' where id = 1`);
    try {
      assert.equal((await api(t, 'GET', 'me')).statusCode, 403);
    } finally {
      await owner.query('update meta.workspace set mfa_required_since = null where id = 1');
    }
    // a removed developer: the token goes with them
    await owner.query(`insert into meta.developer (username, password_hash, is_admin) values ('sec194_gone', meta.hash_password('x'), false)`);
    const g = await make(['read'], 'sec194_gone');
    assert.equal((await api(g, 'GET', 'me')).statusCode, 200);
    await owner.query(`delete from meta.developer where username = 'sec194_gone'`);
    assert.equal((await api(g, 'GET', 'me')).statusCode, 401);
  });

  test('workspace boundaries: another workspace\'s application doesn\'t exist for the token', async () => {
    const t = await make(['read', 'write', 'sql']);
    assert.doesNotMatch((await api(t, 'POST', 'tools/list_apps', {})).json().text, new RegExp(OTHER_APP));
    for (const [name, args] of [['get_page', { alias: OTHER_APP, page: 1 }], ['app_overview', { alias: OTHER_APP }], ['read_app_files', { alias: OTHER_APP, prefix: 'shared/' }],
      ['run_query', { sql: 'select 1', alias: OTHER_APP }], ['lock_app', { alias: OTHER_APP }], ['working_copy', { action: 'list', alias: OTHER_APP }], ['advise_app', { alias: OTHER_APP }]] as const) {
      const r = await api(t, 'POST', `tools/${name}`, args);
      assert.equal(r.statusCode, 422, `${name}: ${r.body}`);
      assert.match(r.json().error, /no application/, name);
    }
    assert.equal((await api(t, 'GET', `apps/${OTHER_APP}/export`)).statusCode, 404);
    const doc = (await api(t, 'GET', 'apps/hr/export')).json().doc;
    const over = await api(t, 'POST', `apps/${OTHER_APP}/import`, { doc, replace: true, check: 'off' });
    assert.equal(over.statusCode, 409);
    assert.match(over.json().error, /another workspace/);
    assert.equal((await owner.one(`select meta.app_workspace(id) as ws from meta.app where alias = $1`, [OTHER_APP]))!.ws, wsId, 'not moved');
    // a token for a workspace the developer isn't in (administrators aren't either here) is refused at use
    const foreign = await make(['read'], DEV, wsId);
    assert.equal((await api(foreign, 'GET', 'me')).statusCode, 403);
    // recent_errors: only the workspace's applications
    const otherId = (await owner.one<{ id: number }>('select id from meta.app where alias = $1', [OTHER_APP]))!.id;
    await owner.query(`insert into meta.activity_log (app_id, event, detail) values ($1, 'error', 'sec194 secret of another workspace')`, [otherId]);
    assert.doesNotMatch((await api(t, 'POST', 'tools/recent_errors', { limit: 200 })).json().text, /sec194 secret/);
  });

  test('no Owner connection, also for an administrator\'s token; queries are read-only', async () => {
    await owner.query(`update meta.developer set is_admin = true where username = $1`, [DEV]);
    try {
      const t = await make(['read', 'sql']);
      const ownerRole = (await owner.one<{ u: string }>('select current_user as u'))!.u;
      const r = JSON.parse((await api(t, 'POST', 'tools/run_query', { sql: 'select current_user as u, session_user as s' })).json().text).rows[0];
      assert.notEqual(r.u, ownerRole);
      assert.notEqual(r.s, ownerRole);
      assert.match(r.s, /^pgkiln_ws1_dev_/);
      for (const sql of ['select * from meta.developer', 'set role pgkiln', `select pg_read_file('/etc/passwd')`, 'commit; delete from hr.emp', 'create table public.sec194 (id int)']) {
        const q = await api(t, 'POST', 'tools/run_query', { sql });
        assert.equal(q.statusCode, 422, sql);
      }
      // describe_schema / generate_ddl don't reach pgkiln's own schema
      assert.equal((await api(t, 'POST', 'tools/generate_ddl', { schema: 'meta' })).statusCode, 422);
      assert.equal((await api(t, 'POST', 'tools/describe_schema', { table: 'meta.builder_token' })).statusCode, 422);
    } finally {
      await owner.query(`update meta.developer set is_admin = false where username = $1`, [DEV]);
    }
  });

  test('failed token attempts are throttled per address, like sign-ins', async () => {
    const { loginMaxFailuresPerIp } = await import('../src/security.ts');
    const good = await make(['read']);
    for (let i = 0; i < loginMaxFailuresPerIp(); i++)
      assert.equal((await api(`pgkb_${'x'.repeat(43)}`, 'GET', 'me', undefined, {}, IP)).statusCode, 401);
    const r = await api(good, 'GET', 'me', undefined, {}, IP);
    assert.equal(r.statusCode, 429, 'even a valid token, from that address');
    assert.equal((await api(good, 'GET', 'me')).statusCode, 200, 'another address is not affected');
    const logged = await owner.one<{ n: number; users: number }>(`select count(*)::int as n, count(username)::int as users from meta.activity_log where ip = $1 and event = 'login_failed'`, [IP]);
    assert.equal(logged!.users, 0, 'a guessed token locks out no developer');
    await owner.query(`delete from meta.activity_log where ip = $1`, [IP]);
  });

  test('making a token needs a recent sign-in with the developer\'s factors (step-up)', async () => {
    const count = async (u: string) => (await owner.one<{ n: number }>('select count(*)::int as n from meta.builder_token where username = $1', [u]))!.n;
    const form = { name: 'step', days: '1', scopes: 'read', workspace: '1' };
    // just signed in with the password (no factor, none required): fine
    let b = await signIn(DEV);
    await b.get('/builder/security');
    const n0 = await count(DEV);
    assert.equal((await b.submit('/builder/security/tokens', { ...form, name: 'step 1' })).statusCode, 200);
    assert.equal(await count(DEV), n0 + 1);
    // eleven minutes later: the password again, a wrong one makes nothing and counts as a failed sign-in
    await age(DEV, 11);
    assert.match((await b.get('/builder/security')).body, /name="password"/);
    await b.submit('/builder/security/tokens', { ...form, name: 'step 2' });
    await b.get('/builder/security');
    await b.submit('/builder/security/tokens', { ...form, name: 'step 2', password: 'wrong' });
    assert.equal(await count(DEV), n0 + 1);
    assert.ok((await owner.one(`select 1 as ok from meta.activity_log where username = $1 and event = 'login_failed' and detail like 'builder token step-up%'`, [DEV])));
    await b.get('/builder/security');
    assert.equal((await b.submit('/builder/security/tokens', { ...form, name: 'step 2', password: PW })).statusCode, 200);
    assert.equal(await count(DEV), n0 + 2);
    // a session from before sprint 194 (no sign-in time): the same
    await owner.query(`update meta.session set state = state - '__AUTH' where app_id is null and username = $1`, [DEV]);
    await b.get('/builder/security');
    await b.submit('/builder/security/tokens', { ...form, name: 'step 3' });
    assert.equal(await count(DEV), n0 + 2);

    // a developer with an authenticator app: password and a code
    const { addTotp, newTotpSecret, totpAt, unbase32, stepNow } = await import('../src/mfa.ts');
    const secret = newTotpSecret();
    await addTotp(MFA, 'phone', secret, stepNow() - 5);
    b = new FileBrowser(app);
    await b.get('/builder/login');
    await b.submit('/builder/login', { username: MFA, password: PW });
    await b.get('/builder/login/2fa');
    assert.equal((await b.submit('/builder/login/2fa', { code: totpAt(unbase32(secret), stepNow()) })).statusCode, 303);
    await b.get('/builder/security');
    assert.equal((await b.submit('/builder/security/tokens', { ...form, name: 'mfa 1' })).statusCode, 200, 'just signed in with both');
    await age(MFA, 11);
    const page = (await b.get('/builder/security')).body;
    assert.match(page, /name="password"/);
    assert.match(page, /name="code"/);
    await b.submit('/builder/security/tokens', { ...form, name: 'mfa 2', password: PW });
    assert.equal(await count(MFA), 1, 'the password alone is not enough');
    await b.get('/builder/security');
    assert.equal((await b.submit('/builder/security/tokens', { ...form, name: 'mfa 2', password: PW, code: totpAt(unbase32(secret), stepNow() + 1) })).statusCode, 200);
    assert.equal(await count(MFA), 2);

    // a workspace that requires single sign-on: the password doesn't count, only signing in again through it
    b = await signIn(SSO);
    const ssoWs = (await owner.one<{ id: number }>('insert into meta.workspace (name, sso_only) values ($1, true) returning id', [SSO_WS]))!.id;
    await owner.query('insert into meta.workspace_member (workspace_id, username) values ($1, $2)', [ssoWs, SSO]);
    const sso = (await b.get('/builder/security')).body;
    assert.match(sso, /action="\/builder\/security\/tokens\/sign-in-again"/);
    assert.doesNotMatch(sso, /action="\/builder\/security\/tokens"/);
    await b.submit('/builder/security/tokens', { ...form, name: 'sso', password: PW });
    assert.equal(await count(SSO), 0);
    // two-factor sign-in required and none set up yet (grace period): no token
    await owner.query('delete from meta.workspace where id = $1', [ssoWs]);
    await owner.query('update meta.workspace set mfa_required_since = now() where id = 1');
    try {
      b = await signIn(SSO);
      assert.match((await b.get('/builder/security')).body, /Set up two-factor sign-in first/);
      await b.submit('/builder/security/tokens', { ...form, name: 'enrol' });
      assert.equal(await count(SSO), 0);
    } finally {
      await owner.query('update meta.workspace set mfa_required_since = null where id = 1');
    }
  });

  test('a developer revokes only their own; scopes and expiry from the form are checked on the server', async () => {
    const other = await tok.createToken({ username: MFA, workspaceId: 1, name: 'not yours', scopes: ['read'], days: 1 });
    const b = await signIn(DEV);
    await b.get('/builder/security');
    assert.equal((await b.submit(`/builder/security/tokens/${other.id}/revoke`, {})).statusCode, 404);
    assert.equal((await owner.one('select revoked_at from meta.builder_token where id = $1', [other.id]))!.revoked_at, null);
    // revoking needs the CSRF token
    assert.equal((await b.post(`/builder/security/tokens/${other.id}/revoke`, {})).statusCode, 403);
    const before = (await owner.one<{ n: number }>('select count(*)::int as n from meta.builder_token where username = $1', [DEV]))!.n;
    await b.submit('/builder/security/tokens', { name: 'bad scope', days: '1', scopes: 'admin', workspace: '1' });
    await b.get('/builder/security');
    await b.submit('/builder/security/tokens', { name: 'too long', days: '1000', scopes: 'read', workspace: '1' });
    await b.get('/builder/security');
    await b.submit('/builder/security/tokens', { name: 'not my workspace', days: '1', scopes: 'read', workspace: String(wsId) });
    assert.equal((await owner.one<{ n: number }>('select count(*)::int as n from meta.builder_token where username = $1', [DEV]))!.n, before);
  });
});
